      local kind, key = spec:match("^([%w_]+):(.*)$")
      local found = false
      if kind == "relation" then
        for _, p in ipairs(c.positive) do if p.kind == "relation" and p.relation == key then found = true end end
      elseif kind == "temporal" then
        for _, p in ipairs(c.positive) do if p.kind == "temporal" and p.relation == key then found = true end end
      elseif kind == "geo" then
        for _, g in ipairs(c.geographic or {}) do if (g.text or ""):lower():find(key:lower(), 1, true) then found = true end end
        for _, p in ipairs(c.positive) do if p.kind == "geographic" and p.value and (p.value.text or ""):lower():find(key:lower(), 1, true) then found = true end end
      elseif kind == "has" then
        for _, p in ipairs(c.positive) do if p.kind == "has" and p.value and (p.value.text or ""):lower():find(key:lower(), 1, true) then found = true end end
      elseif kind == "numeric" then
        -- numeric:relation or numeric:relation>1000000 (op symbols > >= < <= = ~ and a bound)
        local rel, sym, bound = key:match("^([%w_]+)([<>=~]*)([%d%.]*)$")
        local OPS = { [">"] = "gt", [">="] = "ge", ["<"] = "lt", ["<="] = "le", ["="] = "eq", ["~"] = "approx" }
        for _, p in ipairs(c.positive) do
          if p.kind == "numeric" and p.relation == rel and (sym == "" or OPS[sym] == p.op) and (bound == "" or tonumber(bound) == p.value) then found = true end
        end
      end
      if not found then ok = false end
    end
    for _, p in ipairs(c.positive) do got[#got + 1] = tostring(p.kind) .. ":" .. tostring(p.relation) end
    chk("pos", ok, table.concat(got, ","))
  end
  if gold.pref then
    local ok = true
    for _, s in ipairs(list_of(gold.pref)) do
      local found = false
      for _, p in ipairs(c.preferences or {}) do if (p.text or ""):lower():find(s:lower(), 1, true) then found = true end end
      if not found then ok = false end
    end
    chk("pref", ok, tostring(#(c.preferences or {})) .. " preference(s)")
  end
  if gold.src then
    local res_, label = gold.src:match("^([%w_]+):?(.*)$")
    local ok = false
    for _, s in ipairs(c.source or {}) do
      if s.resource == res_ and (label == "" or tostring(s.label or ""):find(label, 1, true)) then ok = true end
    end
    for _, s in ipairs(c.restrictions or {}) do
      if s.resource == res_ and (label == "" or tostring(s.text or ""):lower():find(label:lower(), 1, true)) then ok = true end
    end
    chk("src", ok, tostring(#(c.source or {})) .. " source constraint(s)")
  end
  if gold.amb then chk("amb", m.ambiguity and m.ambiguity.state == gold.amb, m.ambiguity and m.ambiguity.state) end
  if gold.alts then
    local want = {}
    for id in gold.alts:gmatch("[^|]+") do want[id] = true end
    local have = {}
    local function scan(r) if r and r.candidates then for _, cd in ipairs(r.candidates) do have[cd.id] = true end end end
    for _, r in pairs(m.roles or {}) do scan(r) end
    for _, k in ipairs({ "subject", "concept", "target", "focus", "object" }) do scan(m[k]) end
    for _, p in ipairs(m.ambiguity and m.ambiguity.points or {}) do for _, cd in ipairs(p.candidates or {}) do if cd.id then have[cd.id] = true end end end
    local ok = true
    for id in pairs(want) do if not have[id] then ok = false end end
    chk("alts", ok, table.concat(U.sorted_keys(have), "|"))
  end
  if gold.ctx then
    local want = list_of(gold.ctx)
    local have = {}
    for _, d in ipairs(m.dependencies or {}) do have[d.kind] = true end
    local ok = true
    if want[1] == "none" then ok = next(have) == nil else for _, w in ipairs(want) do if not have[w] then ok = false end end end
    chk("ctx", ok, table.concat(U.sorted_keys(have), ","))
  end
  if gold.items then
    local want = {}
    for x in gold.items:gmatch("[^|]+") do want[#want + 1] = norm_text(x) end
    local ok = m.items ~= nil and #m.items == #want
    if ok then for i, w in ipairs(want) do if norm_text(m.items[i].text) ~= w then ok = false end end end
    chk("items", ok, m.items and table.concat(U.map(m.items, function(r) return r.text end), "|") or "none")
  end
  if gold.inst then
    local ins = m.instruction
    local ok = ins ~= nil
    local got = {}
    if ins then
      for kv in (gold.inst .. ","):gmatch("(.-),") do
        local k, v = kv:match("^(%w+)=(.*)$")
        if k == "slot" then if ins.slot ~= v then ok = false end
        elseif k == "value" then
          local val = ins.value and (tostring(ins.value.year or ins.value.word or ins.value.label or "")) or ""
          if not val:lower():find(v:lower(), 1, true) then ok = false end
        elseif k == "corr" then if (ins.correction and "1" or "0") ~= v then ok = false end
        elseif k == "persist" then if (ins.persist and "1" or "0") ~= v then ok = false end
        elseif k == "verb" then if ins.verb ~= v then ok = false end end
      end
      got = { tostring(ins.slot), ins.value and tostring(ins.value.year or ins.value.word) or "-", tostring(ins.correction), tostring(ins.persist) }
    end
    chk("inst", ok, table.concat(got, "/"))
  end
  local cx = m.context or {}
  if gold.dep then
    local got = cx.dependency and cx.dependency.primary or "-"
    -- the format document calls the engine class `earlier_project_context` "earlier_context"
    chk("dep", got == gold.dep or (gold.dep == "earlier_context" and got == "earlier_project_context"), got)
  end
  if gold.ref then
    -- ref=<mention>><antecedent text | resolved | ambiguous | unresolved>, ...
    local ok, got = true, {}
    for _, spec in ipairs(list_of(gold.ref)) do
      local mention, want = spec:match("^(.-)>(.*)$")
      local found
      for _, r in ipairs(cx.references or {}) do if norm_text(r.mention) == norm_text(mention) then found = r end end
      if not found then ok = false; got[#got + 1] = mention .. ">(none)"
      else
        local w = norm_text(want)
        local have = found.status
        if w == "resolved" or w == "ambiguous" or w == "unresolved" then
          if have ~= w then ok = false end
        else
          if have ~= "resolved" or norm_text((found.antecedent and found.antecedent.text) or "") ~= w then ok = false end
        end
        got[#got + 1] = mention .. ">" .. have .. ((found.antecedent and found.antecedent.text) and (":" .. found.antecedent.text:sub(1, 30)) or "")
      end
    end
    chk("ref", ok, table.concat(got, ","))
  end
  if gold.active or gold.inactive then
    local act = {}
    for _, c in ipairs(cx.active_constraints or {}) do if c.slot then act[c.slot .. ":" .. tostring(c.value)] = true end end
    local ok = true
    for _, spec in ipairs(list_of(gold.active)) do if not act[spec] then ok = false end end
    for _, spec in ipairs(list_of(gold.inactive)) do if act[spec] then ok = false end end
    chk(gold.active and "active" or "inactive", ok, table.concat(U.sorted_keys(act), ","))
  end
  if gold.sel then
    -- sel=+fragment,-fragment : memory items whose text contains the fragment must (not) have been selected
    local ok, sel = true, (cx.memory and cx.memory.selected) or {}
    for _, spec in ipairs(list_of(gold.sel)) do
      local sign, frag = spec:sub(1, 1), spec:sub(2):lower()
      local hit = false
      for _, it in ipairs(sel) do if (it.text or ""):lower():find(frag, 1, true) then hit = true end end
      if (sign == "+" and not hit) or (sign == "-" and hit) then ok = false end
    end
    chk("sel", ok, tostring(#sel) .. " selected")
  end
  if gold.unres then chk("unres", #(cx.unresolved or {}) == tonumber(gold.unres), tostring(#(cx.unresolved or {}))) end
  if gold.chain then
    local got = m.query and m.query.chain and table.concat(m.query.chain, ">") or ""
    chk("chain", got == gold.chain, got)
  end
  if gold.pol then chk("pol", (m.polarity or "positive") == gold.pol, m.polarity) end
  if gold.evid then chk("evid", (m.requires_external_evidence and "1" or "0") == gold.evid, tostring(m.requires_external_evidence)) end
  return { ok = ok_all, fields = res }
end

---------------------------------------------------------------- semantic signature (metamorphic tests)
function E.signature(m)
  if not m then return "none" end
  -- the asked role's wh-noun ("Which city ...") is a type constraint on the answer, not an argument: it is not part of the signature
  local function r(x) if not x or x.asked then return "-" end return x.resolved_id or norm_text(x.text) end
  local negs = {}
  for _, n in ipairs(m.constraints and m.constraints.negative or {}) do negs[#negs + 1] = tostring(n.target and (n.target.type or n.target.text) or "?") end
  table.sort(negs)
  local tcs = {}
  for _, t in ipairs(all_temporal(m)) do
    if t.role ~= "derived" then tcs[#tcs + 1] = tostring(t.op) .. ":" .. tostring(t.year or t.text) end
  end
  table.sort(tcs)
  return table.concat({ m.intent or "?", m.relation and m.relation.id or "-", r(m.roles and m.roles.from), r(m.roles and m.roles.to), r(m.subject), r(m.concept),
    m.query and m.query.ask or "-", table.concat(negs, "+"), table.concat(tcs, "+"), m.ambiguity and m.ambiguity.state or "?", m.temporal_scope or "-" }, "|")
end

---------------------------------------------------------------- runner factory (shared by tools, tests and the CLI)
-- mode: "full" | "baseline" | "lexical_only" | comma-separated ablation flags (no_types,no_domain,no_hypotheses,no_coref,no_memory,...)
local MAIN_FALLBACK = { status = "no_interpretation", speech_act = "unknown", intent = "unknown",
  constraints = { positive = {}, negative = {}, temporal = {}, geographic = {}, source = {}, preferences = {}, restrictions = {} },
  ambiguity = { state = "unresolvable", points = {} }, roles = {}, dependencies = {} }

function E.make_runner(mode, lex, extra)
  mode = mode or "full"
  extra = extra or {}
  if mode == "baseline" then
    local B = require("asi.nlu.baseline")
    return function(t) return B.interpret(t, lex), 0 end
  elseif mode == "lexical_only" then
    local B = require("asi.nlu.baseline")
    return function(t) return B.lexical_only(t, lex), 0 end
  end
  local I = require("asi.nlu.interp")
  local Memory = require("asi.nlu.memory")
  local flags = {}
  if mode ~= "full" then for f in mode:gmatch("[^,]+") do flags[f] = true end end
  local interp = I.new({ flags = flags, lexicon = lex, budget = extra.budget })
  return function(t, cs)
    local turns = cs and cs.turns
    if not turns or flags.no_memory then
      local r = interp:interpret((turns and cs.final_text) or t, {})
      return r.main or MAIN_FALLBACK, r.work and r.work.total or 0
    end
    local mem = Memory.new({ ns = { user = "eval", project = "eval", conversation = cs.id } })
    local last, work = nil, 0
    for i, turn in ipairs(turns) do
      local r = interp:interpret(turn.text, { memory = mem, speaker = turn.speaker, light = (turn.speaker ~= "user") })
      work = work + (r.work and r.work.total or 0)
      if i == #turns then last = r end
    end
    return (last and last.main) or MAIN_FALLBACK, work
  end
end

---------------------------------------------------------------- running + aggregation
-- runner(text, case) -> interpretation table (the "main" sentence interpretation)
function E.run(cases, runner, lex, opts)
  opts = opts or {}
  local out = { results = {}, by_cat = {}, field_fail = {}, serious_fail = 0, any_fail = 0, n = #cases, work = 0, wall = 0 }
  local sigs = {}
  for _, cs in ipairs(cases) do
    local t0 = os.clock()
    local ok, m, work = pcall(runner, cs.text, cs)
    out.wall = out.wall + (os.clock() - t0)
    local cmp
    if not ok then
      cmp = { ok = false, fields = { crash = { ok = false, got = tostring(m) } } }
      m = nil
    else
      cmp = E.compare(lex, m, cs.gold)
      out.work = out.work + (work or 0)
    end
    local serious_bad = false
    for k, f in pairs(cmp.fields) do
      if not f.ok then
        out.field_fail[k] = (out.field_fail[k] or 0) + 1
        if E.SERIOUS[k] or k == "crash" then serious_bad = true end
      end
    end
    local cat = out.by_cat[cs.category]
    if not cat then cat = { n = 0, pass = 0, serious = 0 }; out.by_cat[cs.category] = cat end
    cat.n = cat.n + 1
    if cmp.ok then cat.pass = cat.pass + 1 else out.any_fail = out.any_fail + 1 end
    if serious_bad then cat.serious = cat.serious + 1; out.serious_fail = out.serious_fail + 1 end
    local r = { case = cs, ok = cmp.ok, serious = serious_bad, fields = cmp.fields, interp = m }
    out.results[#out.results + 1] = r
    if cs.gold.mm then
      local gid, rel_, other = cs.gold.mm:match("^([%w_]+):(%a+):?([%w_]*)$")
      if gid then sigs[#sigs + 1] = { id = cs.id, group = gid, kind = rel_, other = other, sig = E.signature(m), case = cs } end
    end
  end
  -- metamorphic checks: members of one class must share a signature; `ne` classes must differ from the class they name
  local classes = {}
  for _, s in ipairs(sigs) do classes[s.group] = classes[s.group] or {}; table.insert(classes[s.group], s) end
  out.metamorphic = { eq_total = 0, eq_ok = 0, ne_total = 0, ne_ok = 0, failures = {} }
  for gid, members in pairs(classes) do
    local base = members[1].sig
    for i = 2, #members do
      out.metamorphic.eq_total = out.metamorphic.eq_total + 1
      if members[i].sig == base then out.metamorphic.eq_ok = out.metamorphic.eq_ok + 1
      else table.insert(out.metamorphic.failures, { kind = "equivalence", group = gid, a = members[1].id, b = members[i].id, sig_a = base, sig_b = members[i].sig }) end
    end
    for _, m in ipairs(members) do
      if m.kind == "ne" and m.other ~= "" and classes[m.other] then
        out.metamorphic.ne_total = out.metamorphic.ne_total + 1
        if classes[m.other][1].sig ~= m.sig then out.metamorphic.ne_ok = out.metamorphic.ne_ok + 1
        else table.insert(out.metamorphic.failures, { kind = "distinction", group = gid, other = m.other, a = m.id, sig = m.sig }) end
      end
    end
  end
  return out
end

function E.summary(rep, label)
  local lines = {}
  local n = rep.n
  local lo, hi = U.wilson(n - rep.any_fail, n)
  local slo, shi = U.wilson(n - rep.serious_fail, n)
  lines[#lines + 1] = string.format("%s: n=%d  all-fields accuracy=%.3f [%.3f,%.3f]  serious-error rate=%.3f [%.3f,%.3f]  (any-error %.3f)",
    label or "eval", n, (n - rep.any_fail) / n, lo, hi, rep.serious_fail / n, 1 - shi, 1 - slo, rep.any_fail / n)
  for _, cat in ipairs(U.sorted_keys(rep.by_cat)) do
    local c = rep.by_cat[cat]
    local l, h = U.wilson(c.pass, c.n)
    lines[#lines + 1] = string.format("  %-28s n=%-3d pass=%-3d acc=%.2f [%.2f,%.2f] serious=%d", cat, c.n, c.pass, c.pass / c.n, l, h, c.serious)
  end
  local ff = {}
  for k, v in pairs(rep.field_fail) do ff[#ff + 1] = { k, v } end
  table.sort(ff, function(a, b) if a[2] ~= b[2] then return a[2] > b[2] end return a[1] < b[1] end)
  local parts = {}
  for _, x in ipairs(ff) do parts[#parts + 1] = x[1] .. "=" .. x[2] end
  lines[#lines + 1] = "  failing fields: " .. (#parts > 0 and table.concat(parts, " ") or "none")
  if rep.metamorphic and (rep.metamorphic.eq_total + rep.metamorphic.ne_total) > 0 then
    local m = rep.metamorphic
    lines[#lines + 1] = string.format("  metamorphic: equivalence %d/%d  distinction %d/%d", m.eq_ok, m.eq_total, m.ne_ok, m.ne_total)
  end
  return table.concat(lines, "\n")
end

function E.failures(rep, limit)
  local out = {}
  for _, r in ipairs(rep.results) do
    if not r.ok then
      local bad = {}
      for k, f in pairs(r.fields) do if not f.ok then bad[#bad + 1] = string.format("%s: got [%s] want [%s]", k, tostring(f.got), tostring(f.expected)) end end
      table.sort(bad)
      out[#out + 1] = string.format("%s [%s] %q%s\n    %s", r.case.id, r.case.category, r.case.text, r.serious and " (SERIOUS)" or "", table.concat(bad, "\n    "))
      if limit and #out >= limit then break end
    end
  end
  return table.concat(out, "\n")
end

---------------------------------------------------------------- manifests (dev / val / test integrity)
function E.read_file(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local s = f:read("*a")
  f:close()
  return s
end

function E.checksum(path)
  local s = E.read_file(path)
  return s and U.sha256(s) or nil
end

return E

end

package.preload["asi.nlu.frames"] = function(...)
-- asi.nlu.frames: construction-level semantics. Every frame turns parsed chunks into zero or more competing
-- hypotheses.  Roles are never guessed from word proximity: they come from (1) voice and wh-gap position,
-- (2) the relation lexicon's subj=to|from direction, and (3) type compatibility with the relation signature.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")

local F = {}

local cat = P.cat
local function C(S, k) return S.chunks[k] end
local function barrier(c) return c ~= nil and c.pre ~= nil end
local function other(role) return role == "to" and "from" or "to" end

---------------------------------------------------------------- hypothesis helpers
local function newh(S, frame, speech_act, intent, op)
  return { frame = frame, speech_act = speech_act, intent = intent, op = op, roles = {}, used = {}, factors = {}, notes = {}, constraints = {},
    polarity = "positive", S = S }
end
local function addf(h, name, v, note) h.factors[#h.factors + 1] = { name = name, v = v, note = note } end
local function use(h, a, b) for i = a, b or a do h.used[i] = true end end
local function use_np(h, np)
  if not np then return end
  for i = np.c1, np.c2 do h.used[i] = true end
  if np.of_arg then use_np(h, np.of_arg) end
  if np.possessor then use_np(h, np.possessor) end
  for _, m in ipairs(np.mods or {}) do if m.chunk then h.used[m.chunk.idx] = true end end
end
local function use_wh(h, wh)
  if not wh then return end
  for i = wh.c1, wh.c2 do h.used[i] = true end
  if wh.pied_adv then h.pied_consumed = true end   -- "In which city" read as "Where": the preposition is part of the wh-adverbial
end
local function use_vp(h, vp)
  for i = vp.c1, vp.c2 do h.used[i] = true end
end
F.newh, F.addf, F.use_np = newh, addf, use_np

local function is_be(c) return c and c.single and (cat(c, "aux_be") or cat(c, "clitic_s")) and not c.masked end
local function is_do(c) return c and c.single and cat(c, "aux_do") and not c.masked end
-- the auxiliary that licenses a subject-verb inversion with an object gap: do-support ("Which company did P found?") or the perfect ("Which company has P founded?")
local function is_have_aux(c) return c and c.single and cat(c, "aux_have") and not c.masked and not barrier(c) end
local function gap_aux(c) return (is_do(c) and "do") or (is_have_aux(c) and "have") or nil end
local function is_prep(c, form) return c and c.single and not c.masked and cat(c, "prep") and (form == nil or c.unit.form == form) end

-- a relational NP exposes (relation entry, argument NP, role of the known argument, role asked for)
local function relnp_options(S, np)
  local out = {}
  if np.head_kind ~= "relnoun" then return out end
  local arg = np.of_arg or np.possessor
  local compound = false
  if not arg then
    local last = np.mods[#np.mods]
    if last and last.kind == "entity_mod" and last.chunk.idx + 1 == np.hchunk_idx then
      arg = { head_kind = "entity", cands = last.cands, head = last.chunk, u1 = last.chunk.u1, u2 = last.chunk.u2, c1 = last.chunk.idx, c2 = last.chunk.idx,
        mods = {}, score = 0.2, compound = true, nxt = np.hchunk_idx, notes = {} }
      compound = true
    end
  end
  for _, e in ipairs(np.relnouns) do
    local rel = S.lex:get_rel(e.rel)
    if rel then
      local known_role = (e.role == "to") and "from" or "to"
      local base = { rel = rel, arg = arg, known_role = known_role, ask_role = e.role, compound = compound, entry = e, comma = np.comma_arg, fuzzy = e.fuzzy }
      -- kind modifiers ("financial capital of X": either a separate word or a lexicalised prefix) re-target the relation
      local kinds = {}
      if e.kind_prefix then kinds[#kinds + 1] = { form = e.kind_prefix } end
      for _, m in ipairs(np.mods) do kinds[#kinds + 1] = m end
      local derived_found = false
      for _, m in ipairs(kinds) do
        local derived = rel.kinds and rel.kinds[m.form]
        if derived and derived ~= rel.id and S.lex:get_rel(derived) then
          out[#out + 1] = { rel = S.lex:get_rel(derived), arg = arg, known_role = known_role, ask_role = e.role, kind_mod = m, compound = compound, entry = e,
            comma = np.comma_arg, fuzzy = e.fuzzy }
          derived_found = true
        elseif derived == rel.id then base.political_mod = m end
      end
      base.kind_ignored = derived_found -- the base relation silently ignores a kind word: strongly disfavoured
      out[#out + 1] = base
    end
  end
  return out
end
F.relnp_options = relnp_options

-- factors shared by every consumer of a relational-NP option
local function option_factors(h, o)
  if o.kind_mod then
    h.kind_mod = o.kind_mod.form
    if o.kind_mod.chunk then use(h, o.kind_mod.chunk.idx) end
    addf(h, "kind_modifier", 0.2, "kind modifier '" .. tostring(o.kind_mod.form) .. "' selects " .. o.rel.id)
  end
  if o.political_mod and o.political_mod.chunk then use(h, o.political_mod.chunk.idx) end
  if o.kind_ignored then addf(h, "kind_modifier_ignored", -0.9, "a kind word is present but this relation ignores it") end
  if o.comma then addf(h, "comma_apposition", -0.3, "argument attached across a comma") end
  if o.compound then addf(h, "compound_arg", -0.25, "entity+noun compound instead of 'of'/'s'") end
end
F.option_factors = option_factors

local function span_end_ok(S, k)
  -- true when nothing but sentence-final constraints can follow chunk k (used only for scoring, not as a hard gate)
  return k > S.last
end

-- A support verb ("use", "keep", "have", "call", "recognize") carries no relation by itself: the relation comes from the noun it supports.  In a plain
-- verb frame it is licensed only when the wh-phrase NAMES that noun ("WHICH CURRENCY does Sweden use?"); a bare "What does Acme keep?" is not a
-- headquarters question.  (The possessed-noun and "as"-complement frames below license it with their own noun.)
local function support_licensed(S, e, rel, wh, ask_role)
  if not e.support then return true end
  if e.as_only then return false end
  if wh and wh.relnoun and wh.np then
    for _, ne in ipairs(wh.np.relnouns or {}) do if ne.rel == rel.id then return true end end
  end
  -- the wh-phrase asks for the HOLDER and its type agrees with the relation's holder type: "WHICH COUNTRIES use the euro?"
  if ask_role == "from" and wh and wh.type and S.lex:compat(rel.from, wh.type) >= 0.9 then return true end
  return false
end
F.support_licensed = support_licensed

-- a relational wh-noun ("What CURRENCY does X use?") names the relation asked about: it must agree with the relation the rest of the clause expresses
local function wh_relnoun_agreement(h, wh, rel)
  if not (wh and wh.relnoun and wh.np) then return end
  local same = false
  for _, ne in ipairs(wh.np.relnouns or {}) do if ne.rel == rel.id then same = true end end
  if same then addf(h, "wh_noun_names_relation", 0.5, "the wh-noun '" .. tostring(wh.np.head and wh.np.head.form) .. "' names the relation " .. rel.id)
  else addf(h, "wh_noun_other_relation", -0.5, "the wh-noun names a different relation than " .. rel.id) end
end
F.wh_relnoun_agreement = wh_relnoun_agreement

-- record how a relation hypothesis binds its arguments (type fit is computed in hyp.lua)
local function set_lookup(h, rel, known_role, known_np, ask_role, wh)
  h.rel, h.rel_obj = rel.id, rel
  h.roles[known_role] = known_np
  h.known_role, h.ask = known_role, ask_role
  h.ask_type = rel[ask_role]
  if wh and wh.type then h.wh_type = wh.type end
  h.wh = wh
  h.op = "lookup"
  h.intent = "factual_lookup"
  h.requires_evidence = true
end

local function mark_unresolved_pron(h, np)
  if np and np.head_kind == "pronoun" then h.pronouns = h.pronouns or {}; h.pronouns[#h.pronouns + 1] = np end
  if np and np.of_arg then mark_unresolved_pron(h, np.of_arg) end
  if np and np.possessor then mark_unresolved_pron(h, np.possessor) end
end
F.mark_pron = mark_unresolved_pron

---------------------------------------------------------------- frame: wh + be + NP
function F.wh_copular(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial and wh.wh ~= "how_many" and wh.wh ~= "how_much" and wh.wh ~= "how_adj" then
      local bk = wh.nxt
      local be = C(S, bk)
      if is_be(be) and not barrier(be) then
        -- "Who is CURRENTLY the CEO of X?", "Who is NOW in charge of Y?": adverbs between the copula and the predicate carry no content here
        local nk, advs = bk + 1, {}
        while C(S, nk) and C(S, nk).single and not C(S, nk).masked and not barrier(C(S, nk)) and cat(C(S, nk), "adv") and not P.is_neg(C(S, nk)) do
          advs[#advs + 1] = nk; nk = nk + 1
        end
        for _, np in ipairs(P.parse_np(S, nk)) do
          local base = function(frame)
            local h = newh(S, frame, "question", nil, nil)
            use_wh(h, wh); use(h, bk); use_np(h, np)
            for _, a in ipairs(advs) do use(h, a) end
            -- "What is France's capital city CALLED?" -- the closing participle only asks for the name of the noun phrase
            local tail = C(S, np.nxt)
            if tail and tail.single and not tail.masked and np.nxt == S.last and (tail.unit.form == "called" or tail.unit.form == "named") then
              use(h, np.nxt)
              addf(h, "name_asking_participle", 0.1, "closing 'called' asks for the name of the noun phrase")
            end
            h.wh = wh; h.last_chunk = np.c2
            mark_unresolved_pron(h, np)
            return h
          end
          if np.head_kind == "relnoun" then
            local opts = relnp_options(S, np)
            for _, o in ipairs(opts) do
              local h = base("wh_copular:relnp")
              if o.arg then
                set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
                addf(h, "relnp_arg", 0.7, "relational noun with explicit argument")
                option_factors(h, o)
                mark_unresolved_pron(h, o.arg)
              else
                h.op, h.intent, h.rel, h.rel_obj = "define", "definition", o.rel.id, o.rel
                h.concept = np
                addf(h, "relnoun_no_arg", -1.0, "relational noun without its argument")
              end
              if np.temporal_scope then h.temporal_scope = np.temporal_scope end
              if np.superlative then h.ordering = { superlative = np.superlative } end
              out[#out + 1] = h
            end
          elseif np.head_kind == "entity" then
            local h = base("wh_copular:entity")
            h.op, h.intent = "describe", "entity_description"
            h.subject = np
            h.roles.subject = np
            h.requires_evidence = true
            if wh.wh == "who" then h.expect_type = "agent"; addf(h, "wh_who_expects_agent", 0.0, "who expects an agent") end
            if wh.type then h.expect_type = wh.type end
            out[#out + 1] = h
          elseif np.head_kind == "typenoun" or np.head_kind == "concept" or np.head_kind == "unknown" then
            local h = base("wh_copular:concept")
            h.op, h.intent = "define", "definition"
            h.concept = np
            h.requires_evidence = true
            if np.head_kind == "unknown" then addf(h, "unknown_term", -0.15, "term not in the lexicon: dataset-specific meaning must be learned from evidence") end
            if np.of_arg then addf(h, "concept_of_arg", -0.4, "a non-relational concept noun with an 'of' argument is a weaker structure than a relational noun") end
            out[#out + 1] = h
          elseif np.head_kind == "pronoun" then
            local h = base("wh_copular:pronoun")
            h.op, h.intent = "describe", "entity_description"
            h.subject = np
            out[#out + 1] = h
          elseif np.head_kind == "temporal" or np.head_kind == "number" or np.head_kind == "quote" or np.head_kind == "literal" then
            local h = base("wh_copular:literal")
            h.op, h.intent = "describe", "entity_description"
            h.subject = np
            out[#out + 1] = h
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: wh + VERB(active) + NP    ("Who founded X?")
-- also "Which company is based in Germany?" (stative prep verbs) and "Which claims are not supported by the documents?" (passive)
function F.wh_verb(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much" then
      local vk = wh.nxt
      for _, vp in ipairs(P.parse_vp(S, vk)) do
        for _, e in ipairs(vp.analysis.entries) do
          local rel = S.lex:get_rel(e.rel)
          if rel and support_licensed(S, e, rel, wh, (vp.voice == "active") and e.subj or other(e.subj)) then
            local function finish(h, known_np, known_role, ask_role)
              set_lookup(h, rel, known_role, known_np, ask_role, wh)
              h.wh = wh
              use_wh(h, wh); use_vp(h, vp); use_np(h, known_np)
              if vp.neg then h.polarity = "negative"; use(h, vp.neg_chunk.idx) end
              addf(h, "direction_explicit", 0.35, "role direction fixed by voice/lexicon (" .. vp.voice .. ", subj=" .. e.subj .. ")")
              if vp.analysis.guessed then addf(h, "guessed_verb", -0.3, "verb form guessed") end
              wh_relnoun_agreement(h, wh, rel)
              mark_unresolved_pron(h, known_np)
              out[#out + 1] = h
            end
            if vp.voice == "active" then
              if e.prep then
                -- "Which company invested in B?": prep object fills the other role
                local pk = vp.nxt
                if is_prep(C(S, pk), e.prep) then
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:active_prep", "question")
                    use(h, pk)
                    finish(h, np, other(e.subj), e.subj)
                  end
                end
              else
                for _, np in ipairs(P.parse_np(S, vp.nxt)) do
                  local h = newh(S, "wh_verb:active", "question")
                  finish(h, np, other(e.subj), e.subj)
                end
              end
            else -- passive / stative:  wh is the grammatical subject
              if e.prep then
                -- "Which company is based in Germany?": subject keeps e.subj role, PP object the other
                local pk = vp.nxt
                if is_prep(C(S, pk), e.prep) then
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:stative", "question")
                    use(h, pk)
                    finish(h, np, other(e.subj), e.subj)
                  end
                end
              else
                -- "Which claims are not supported by the documents?"  by-agent fills e.subj; wh is the other role
                local pk = vp.nxt
                if is_prep(C(S, pk), "by") then
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:passive_by", "question")
                    use(h, pk)
                    finish(h, np, e.subj, other(e.subj))
                  end
                elseif e.support and (is_prep(C(S, pk), "in") or is_prep(C(S, pk), "at") or is_prep(C(S, pk), "across") or is_prep(C(S, pk), "throughout")) then
                  -- locative passive of a support verb: "Which currency is used IN Sweden?" = the currency Sweden uses
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:locative_passive", "question")
                    use(h, pk)
                    finish(h, np, e.subj, other(e.subj))
                    addf(h, "locative_passive", 0.15, "support verb '" .. tostring(e.lemma) .. "' with a locative holder")
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: wh + do + NP(subject) + VERB(base)   ("Which company did P found?")
function F.wh_do(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial and wh.wh ~= "how_adj" then
      local dk = wh.nxt
      local embedded_no_aux = S.embedded and not gap_aux(C(S, dk)) and not is_be(C(S, dk))
      local aux = gap_aux(C(S, dk))
      if aux or embedded_no_aux then
        local nk = embedded_no_aux and dk or dk + 1
        local neg_chunk
        if P.is_neg(C(S, nk)) then neg_chunk = C(S, nk); nk = nk + 1 end
        for _, snp in ipairs(P.parse_np(S, nk, { no_of = false })) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = aux or "do", finite_ok = embedded_no_aux })) do
            for _, e in ipairs(vp.analysis.entries) do
              local rel = S.lex:get_rel(e.rel)
              if rel and support_licensed(S, e, rel, wh, other(e.subj)) then
                -- subject NP fills e.subj; the wh-gap is the object (other role). Stranded or absent preposition is fine.
                local h = newh(S, "wh_do:object_gap", "question")
                set_lookup(h, rel, e.subj, snp, other(e.subj), wh)
                use_wh(h, wh); use(h, dk); use_np(h, snp); use_vp(h, vp)
                if neg_chunk then h.polarity = "negative"; use(h, neg_chunk.idx) end
                local pk = vp.nxt
                if e.prep then
                  if is_prep(C(S, pk), e.prep) then use(h, pk)
                  elseif wh.pied == e.prep then h.pied_consumed = true
                  else addf(h, "prep_missing", -0.5, "expected stranded preposition '" .. e.prep .. "'") end
                elseif wh.pied then
                  -- "For which company does P work?": the fronted preposition belongs to the verb; a verb without one cannot absorb it
                  addf(h, "pied_prep_unused", -0.6, "fronted preposition '" .. wh.pied .. "' does not belong to this verb")
                end
                wh_relnoun_agreement(h, wh, rel)
                addf(h, "direction_explicit", 0.35, "role direction fixed by do-support gap (subject=" .. e.subj .. ")")
                mark_unresolved_pron(h, snp)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: wh + be + NP + VERB-ed (+ by)   ("Who was X founded by?")
function F.wh_passive(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial then
      local bk = wh.nxt
      if is_be(C(S, bk)) then
        for _, snp in ipairs(P.parse_np(S, bk + 1)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "be" })) do
            if vp.voice == "passive" then
              for _, e in ipairs(vp.analysis.entries) do
                local rel = S.lex:get_rel(e.rel)
                local lic_prep = rel and support_licensed(S, e, rel, wh, other(e.subj))
                local lic_by = rel and support_licensed(S, e, rel, wh, e.subj)
                if rel and lic_prep and e.prep and (is_prep(C(S, vp.nxt), e.prep) or wh.pied == e.prep) then
                  -- stative-prep verb: the grammatical subject keeps its own role, the wh-gap is the object of the (stranded or fronted) preposition
                  local h = newh(S, "wh_passive:stranded_prep", "question")
                  set_lookup(h, rel, e.subj, snp, other(e.subj), wh)
                  use_wh(h, wh); use(h, bk); use_np(h, snp); use_vp(h, vp)
                  if is_prep(C(S, vp.nxt), e.prep) then use(h, vp.nxt) else h.pied_consumed = true end
                  addf(h, "direction_explicit", 0.35, "stative verb with a preposition gap (subject=" .. e.subj .. ")")
                  mark_unresolved_pron(h, snp)
                  out[#out + 1] = h
                end
                if rel and lic_by and not e.prep then
                  local pk = vp.nxt
                  local pc = C(S, pk)
                  -- a passive followed by ANOTHER preposition ("is Java used for", "is X known for") is a different construction, not a stranded by-phrase
                  local other_prep = pc and pc.single and not pc.masked and cat(pc, "prep") and pc.unit.form ~= "by" and not barrier(pc)
                  -- a support verb ("is called", "is used") has no agentless passive: "What is X called?" asks about X itself, it does not gap an agent
                  if not other_prep and (not e.support or is_prep(pc, "by")) then
                    local h = newh(S, "wh_passive:stranded_by", "question")
                    -- X (grammatical subject) is the logical object; the wh-gap is the agent (e.subj role)
                    set_lookup(h, rel, other(e.subj), snp, e.subj, wh)
                    use_wh(h, wh); use(h, bk); use_np(h, snp); use_vp(h, vp)
                    if is_prep(pc, "by") then use(h, pk) else addf(h, "by_missing", -0.4, "passive without by-phrase") end
                    addf(h, "direction_explicit", 0.35, "agent gap of a passive")
                    mark_unresolved_pron(h, snp)
                    out[#out + 1] = h
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: when / where / how-many / how-old questions
function F.wh_adverbial(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    local f = wh.wh
    if f == "where" or f == "when" then
      local bk = wh.nxt
      -- "Where is X?"  /  "When was X founded?"  /  "When did X acquire Y?"
      if is_be(C(S, bk)) then
        for _, np in ipairs(P.parse_np(S, bk + 1)) do
          -- X followed by a participle:  "Where is X located?"  "When was X founded/born?"
          local vps = P.parse_vp(S, np.nxt, { aux_hint = "be" })
          for _, vp in ipairs(vps) do
            if vp.voice == "passive" then
              for _, e in ipairs(vp.analysis.entries) do
                local rel = S.lex:get_rel(e.rel)
                if rel then
                  local target_rel, known_role, ask_role
                  if f == "where" then
                    -- stative-prep verbs map directly ("located in", "based in", "born in"); others use rel.where
                    if e.prep then target_rel, known_role, ask_role = rel, e.subj, other(e.subj)
                    elseif rel.where and S.lex:get_rel(rel.where) then target_rel = S.lex:get_rel(rel.where); known_role, ask_role = "from", "to" end
                  else
                    if rel.when and S.lex:get_rel(rel.when) then target_rel = S.lex:get_rel(rel.when); known_role, ask_role = "from", "to" end
                  end
                  if target_rel then
                    local h = newh(S, "wh_adv:" .. f .. ":passive", "question")
                    set_lookup(h, target_rel, known_role, np, ask_role, wh)
                    h.derived_via = rel.id
                    use_wh(h, wh); use(h, bk); use_np(h, np); use_vp(h, vp)
                    addf(h, "direction_explicit", 0.3, f .. "-question on passive participle")
                    mark_unresolved_pron(h, np)
                    out[#out + 1] = h
                    -- "Where is the headquarters of X located?": 'located' adds nothing to a location-valued noun, which is answered by its own value
                    if f == "where" and target_rel.id == "located_in" and np.head_kind == "relnoun" then
                      for _, o in ipairs(relnp_options(S, np)) do
                        if o.arg and o.rel.locus and o.ask_role == "to" then
                          addf(h, "redundant_location_hop", -0.7, "the noun's own relation already gives a location; 'where ... located' needs no second hop")
                          local hl = newh(S, "wh_adv:where:locus_passive", "question")
                          set_lookup(hl, o.rel, o.known_role, o.arg, o.ask_role, wh)
                          use_wh(hl, wh); use(hl, bk); use_np(hl, np); use_vp(hl, vp)
                          addf(hl, "relnp_arg", 0.7, "relational noun with explicit argument")
                          addf(hl, "where_locus", 0.3, "'where' asks for the location this relation's value gives")
                          option_factors(hl, o)
                          mark_unresolved_pron(hl, o.arg)
                          out[#out + 1] = hl
                          break
                        end
                      end
                    end
                  end
                end
              end
            end
          end
          if f == "where" then
            -- "Where is the headquarters of X?": a noun whose relation value IS a location (rel.locus) is answered by that value directly;
            -- asking for the location of the location-valued attribute is a redundant extra hop
            local locus_opts = {}
            if np.head_kind == "relnoun" then
              for _, o in ipairs(relnp_options(S, np)) do if o.arg and o.rel.locus and o.ask_role == "to" then locus_opts[#locus_opts + 1] = o end end
            end
            local lrel = S.lex:get_rel("located_in")
            if lrel then
              local h = newh(S, "wh_adv:where:copula", "question")
              set_lookup(h, lrel, "from", np, "to", wh)
              use_wh(h, wh); use(h, bk); use_np(h, np)
              if #locus_opts > 0 then addf(h, "redundant_location_hop", -0.7, "the noun's own relation already gives a location; 'where' needs no second hop") end
              mark_unresolved_pron(h, np)
              out[#out + 1] = h
            end
            for _, o in ipairs(locus_opts) do
              local h = newh(S, "wh_adv:where:locus", "question")
              set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
              use_wh(h, wh); use(h, bk); use_np(h, np)
              addf(h, "relnp_arg", 0.7, "relational noun with explicit argument")
              addf(h, "where_locus", 0.3, "'where' asks for the location this relation's value gives")
              option_factors(h, o)
              mark_unresolved_pron(h, o.arg)
              out[#out + 1] = h
            end
          end
        end
      elseif is_do(C(S, bk)) then
        -- "When did X acquire Y?"  /  "When did X die?"
        for _, snp in ipairs(P.parse_np(S, bk + 1)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do" })) do
            for _, e in ipairs(vp.analysis.entries) do
              local rel = S.lex:get_rel(e.rel)
              local trel_id = rel and ((f == "when") and rel.when or rel.where)
              local trel = trel_id and S.lex:get_rel(trel_id)
              if trel then
                local obj_nps = P.parse_np(S, vp.nxt)
                local function build(onp)
                  local h = newh(S, "wh_adv:" .. f .. ":do", "question")
                  local known, kr
                  if onp then known, kr = onp, "from"; h.qualifier = { rel = rel.id, role = e.subj, np = snp }
                  else known, kr = snp, "from" end
                  set_lookup(h, trel, kr, known, "to", wh)
                  h.derived_via = rel.id
                  use_wh(h, wh); use(h, bk); use_np(h, snp); use_vp(h, vp)
                  if onp then use_np(h, onp) end
                  mark_unresolved_pron(h, snp); mark_unresolved_pron(h, onp)
                  addf(h, "direction_explicit", 0.3, f .. "-question on active verb")
                  out[#out + 1] = h
                end
                if e.subj == "from" then build(nil) end -- intransitive-like: "When did X die?"
                for _, onp in ipairs(obj_nps) do build(onp) end
                if e.subj == "to" and #obj_nps == 0 then build(nil) end
              end
            end
          end
        end
      end
    elseif f == "how_many" or f == "how_much" then
      -- "How many employees does X have?"  "How much revenue does X generate?"
      local np = wh.np
      local dk = wh.nxt
      if np and np.head_kind == "relnoun" and is_do(C(S, dk)) then
        for _, snp in ipairs(P.parse_np(S, dk + 1)) do
          local vk = snp.nxt
          local vc = C(S, vk)
          local consumed_verb = false
          if vc and vc.single and (cat(vc, "aux_have") or (vc.verbs or vc.relverbs[1])) and not barrier(vc) then consumed_verb = true end
          for _, e in ipairs(np.relnouns) do
            local rel = S.lex:get_rel(e.rel)
            if rel then
              local h = newh(S, "wh_adv:" .. f, "question")
              set_lookup(h, rel, other(e.role), snp, e.role, wh)
              h.answer_form = "number"
              use_wh(h, wh); use_np(h, np); use(h, dk); use_np(h, snp)
              if consumed_verb then use(h, vk) end
              addf(h, "relnp_arg", 0.6, "how-many over a relational noun")
              mark_unresolved_pron(h, snp)
              out[#out + 1] = h
            end
          end
        end
      elseif np and (np.head_kind == "typenoun" or np.head_kind == "unknown") then
        -- "How many cities are there in France?" -> count query over a type
        local h = newh(S, "wh_adv:count", "question", "count", "count")
        h.target = np
        h.wh = wh
        h.requires_evidence = true
        use_wh(h, wh); use_np(h, np)
        local k = wh.nxt
        while C(S, k) and is_be(C(S, k)) or (C(S, k) and C(S, k).single and (C(S, k).unit.form == "there")) do use(h, k); k = k + 1 end
        h.count_target = true
        addf(h, "count_query", 0.3, "how many <type>")
        out[#out + 1] = h
      end
    elseif f == "how_adj" then
      -- "How old is X?"  "How tall is Y?"
      local bk = wh.nxt
      if is_be(C(S, bk)) then
        for _, np in ipairs(P.parse_np(S, bk + 1)) do
          local dim = wh.dim and S.lex:dim(wh.dim)
          -- "How large is the workforce of X?": a relational noun with its argument names the relation itself (see F.how_adj_relnoun)
          if np.head_kind == "relnoun" and (np.of_arg or np.possessor) then dim = nil end
          for _, rid in ipairs(dim and dim.rels or {}) do
            local rel = S.lex:get_rel(rid)
            if rel then
              local h = newh(S, "wh_adv:how_adj", "question")
              set_lookup(h, rel, "from", np, "to", wh)
              h.answer_form = "number"
              h.dimension = wh.dim
              use_wh(h, wh); use(h, bk); use_np(h, np)
              mark_unresolved_pron(h, np)
              addf(h, "dimension_relation", 0.2, "how-" .. tostring(wh.adj) .. " via dimension " .. tostring(wh.dim))
              out[#out + 1] = h
            end
          end
        end
      end
    elseif f == "why" or f == "how" then
      local k = wh.nxt
      local h = newh(S, "wh_adv:" .. f, "question", f == "why" and "causal_explanation" or "explanation", "explain")
      h.wh = wh
      h.requires_evidence = true
      use_wh(h, wh)
      -- clause = [aux] NP VERB ...  captured generically
      local cl = F.parse_clause(S, k)
      if cl then
        h.clause = cl
        for i = k, cl.last do h.used[i] = true end
        addf(h, "clause_parsed", 0.4, "explanatory clause identified")
      else
        addf(h, "clause_missing", -0.6, "no clause to explain")
      end
      out[#out + 1] = h
    end
  end
end

-- Support verb + a POSSESSED relational noun, asked about:
--   "Where does Acme have/keep its headquarters?"   "In which city does France have its capital?"   "What does Sweden call its currency?"
--   embedded: "Tell me where Acme keeps its headquarters."
-- The holder is the verb's subject and the possessive pronoun is bound to it; the asked value is the relation's `to` side.
function F.where_support(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.wh == "where" or wh.wh == "what" or wh.wh == "which" then
      local dk = wh.nxt
      local embedded_no_aux = S.embedded and not is_do(C(S, dk))
      local gap = gap_aux(C(S, dk))      -- "Where DOES X keep ...", "Where HAS X established ..."
      if gap or embedded_no_aux then
        local nk = embedded_no_aux and dk or dk + 1
        for _, snp in ipairs(P.parse_np(S, nk)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = gap or "do", finite_ok = embedded_no_aux })) do
            for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
              local dc = C(S, onp.c1)
              if onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and (cat(dc, "poss_det") or cat(dc, "det")) and onp.c1 < onp.nxt - 1 then
                for _, o in ipairs(relnp_options(S, onp)) do
                  local rel = o.rel
                  local supported = (vp.lemma == "have" and rel.support_have) or false
                  for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then supported = true end end
                  local type_ok
                  if wh.wh == "where" then type_ok = rel.locus or (wh.type and S.lex:compat(rel.to, wh.type) >= 0.9)
                  else type_ok = (not wh.type) or S.lex:compat(rel.to, wh.type) >= 0.5 end
                  if supported and type_ok and o.ask_role == "to" then
                    local h = newh(S, "wh_adv:support_possessed", "question")
                    set_lookup(h, rel, "from", snp, "to", wh)
                    use_wh(h, wh); if not embedded_no_aux then use(h, dk) end; use_np(h, snp); use_vp(h, vp); use_np(h, onp)
                    addf(h, "support_construction", 0.8, "'" .. tostring(vp.lemma) .. "' + possessed '" .. rel.id .. "' noun")
                    if wh.wh == "where" then addf(h, "where_locus", 0.3, "'where' asks for the location this relation's value gives") end
                    mark_unresolved_pron(h, snp)
                    out[#out + 1] = h
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

-- Support verb with an "as" complement, the wh-phrase being the value:
--   "Who does Acme have as its CEO?"   "Whom did the board name as chief executive?"   "Which city does France recognize as its capital?"
--   "What does Sweden use as its currency?"   embedded: "Tell me who Acme has as its CEO."
-- The verb's subject is the holder, the (possessed or bare) relational noun after "as" names the relation, the wh-phrase is the relation's `to` side.
function F.wh_support_as(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much" and wh.wh ~= "where" and wh.wh ~= "when" then
      local dk = wh.nxt
      local embedded_no_aux = S.embedded and not is_do(C(S, dk))
      if is_do(C(S, dk)) or embedded_no_aux then
        local nk = embedded_no_aux and dk or dk + 1
        for _, snp in ipairs(P.parse_np(S, nk)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do", finite_ok = embedded_no_aux })) do
            if is_prep(C(S, vp.nxt), "as") then
              for _, onp in ipairs(P.parse_np(S, vp.nxt + 1)) do
                -- "name X as chief executive OF Acme" has its holder inside the noun phrase and an extra agent we cannot represent: not this frame
                if onp.head_kind == "relnoun" and not onp.of_arg and not onp.possessor and not is_prep(C(S, onp.nxt), "of") then
                  for _, o in ipairs(relnp_options(S, onp)) do
                    local rel = o.rel
                    local supported = (vp.lemma == "have" and rel.support_have) or false
                    for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then supported = true end end
                    local type_ok = (not wh.type) or S.lex:compat(rel.to, wh.type) >= 0.5
                    if supported and type_ok and o.ask_role == "to" then
                      local h = newh(S, "wh_do:support_as", "question")
                      set_lookup(h, rel, "from", snp, "to", wh)
                      use_wh(h, wh); if not embedded_no_aux then use(h, dk) end; use_np(h, snp); use_vp(h, vp); use(h, vp.nxt); use_np(h, onp)
                      addf(h, "support_construction", 0.8, "'" .. tostring(vp.lemma) .. "' + 'as' + '" .. rel.id .. "' noun")
                      wh_relnoun_agreement(h, wh, rel)
                      mark_unresolved_pron(h, snp)
                      out[#out + 1] = h
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

-- The wh-phrase is the HOLDER (subject) of a support verb:
--   "Which country has Paris as its capital?"   "Which companies have their headquarters in Oslo?"   "Which firm keeps its head office in Lyon?"
-- The value is the known side, the wh-phrase fills the relation's `from` role.
function F.wh_support_subject(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much" and wh.wh ~= "where" and wh.wh ~= "when" and wh.wh ~= "why" and wh.wh ~= "how" then
      for _, vp in ipairs(P.parse_vp(S, wh.nxt)) do
        if vp.voice == "active" then
          local function supported(rel)
            local ok = (vp.lemma == "have" and rel.support_have) or false
            for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then ok = true end end
            return ok
          end
          local function emit(rel, vnp, onp, frame, extra_used)
            if wh.type and S.lex:compat(rel.from, wh.type) < 0.5 then return end
            local h = newh(S, frame, "question")
            set_lookup(h, rel, "to", vnp, "from", wh)
            use_wh(h, wh); use_vp(h, vp); use_np(h, vnp); use_np(h, onp)
            if extra_used then use(h, extra_used) end
            addf(h, "support_construction", 0.8, "'" .. tostring(vp.lemma) .. "' + '" .. rel.id .. "' noun with the wh-phrase as holder")
            wh_relnoun_agreement(h, wh, rel)
            mark_unresolved_pron(h, vnp)
            out[#out + 1] = h
          end
          -- (a) VERB value as RELNOUN
          for _, vnp in ipairs(P.parse_np(S, vp.nxt)) do
            if is_prep(C(S, vnp.nxt), "as") then
              for _, onp in ipairs(P.parse_np(S, vnp.nxt + 1)) do
                if onp.head_kind == "relnoun" and not onp.of_arg and not onp.possessor and not is_prep(C(S, onp.nxt), "of") then
                  for _, o in ipairs(relnp_options(S, onp)) do
                    if o.ask_role == "to" and supported(o.rel) then emit(o.rel, vnp, onp, "wh_subject:support_as", vnp.nxt) end
                  end
                end
              end
            end
          end
          -- (b) VERB its RELNOUN in|at VALUE
          for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
            local dc = C(S, onp.c1)
            if onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and cat(dc, "poss_det") and onp.c1 < onp.nxt - 1 and (is_prep(C(S, onp.nxt), "in") or is_prep(C(S, onp.nxt), "at")) then
              for _, vnp in ipairs(P.parse_np(S, onp.nxt + 1)) do
                for _, o in ipairs(relnp_options(S, onp)) do
                  if o.ask_role == "to" and supported(o.rel) then emit(o.rel, vnp, onp, "wh_subject:support_possessed", onp.nxt) end
                end
              end
            end
          end
        end
      end
    end
  end
end

-- The wh-phrase is the HOLDER of a post that a role noun names:
--   "Who holds the CEO position at Acme?"   "Who currently occupies the prime minister role in Spain?"   "Who has the president's job in France?"
-- The role noun carries the relation, the verb only says that the wh-phrase holds the post: the answer is the relation's value for the argument.
local ROLE_HOLD = { hold = true, occupy = true, fill = true, have = true, assume = true }
function F.wh_role_holder(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and (wh.wh == "who" or wh.wh == "which" or wh.wh == "whom") then
      for _, vp in ipairs(P.parse_vp(S, wh.nxt)) do
        if vp.voice == "active" and ROLE_HOLD[vp.lemma] then
          for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
            if onp.head_kind == "relnoun" and (onp.of_arg or onp.possessor) then
              for _, o in ipairs(relnp_options(S, onp)) do
                if o.entry and o.entry.rolesuffix and o.ask_role == "to" and o.arg and ((not wh.type) or S.lex:compat(o.rel.to, wh.type) >= 0.5) then
                  local h = newh(S, "wh_role_holder", "question")
                  set_lookup(h, o.rel, "from", o.arg, "to", wh)
                  use_wh(h, wh); use_vp(h, vp); use_np(h, onp)
                  addf(h, "role_holder_construction", 1.3, "'" .. tostring(vp.lemma) .. "' + the post noun of " .. o.rel.id)
                  option_factors(h, o)
                  mark_unresolved_pron(h, o.arg)
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
    end
  end
end

-- helpers shared with asi.nlu.frames3
F.set_lookup, F.use_wh, F.use_vp, F.is_be, F.is_do, F.is_prep, F.gap_aux = set_lookup, use_wh, use_vp, is_be, is_do, is_prep, gap_aux

-- generic clause: [aux]* [NP-subject] [aux]* [not] VERB [NP-object] -> {subj, verb, obj, neg, last}
function F.parse_clause(S, k)
  local best
  for _, snp in ipairs(P.parse_np(S, k)) do
    for _, vp in ipairs(P.parse_vp(S, snp.nxt)) do
      local cl = { subj = snp, vp = vp, lemma = vp.lemma, neg = vp.neg, voice = vp.voice, last = vp.c2 }
      local objs = P.parse_np(S, vp.nxt)
      if objs[1] then cl.obj = objs[1]; cl.last = objs[1].c2 end
      best = best or cl
    end
  end
  if not best then
    -- inverted: aux NP VERB  ("did X fail", "does X work")
    local c = C(S, k)
    if c and c.single and (cat(c, "aux_do") or cat(c, "aux_be") or cat(c, "aux_have") or cat(c, "modal")) then
      for _, snp in ipairs(P.parse_np(S, k + 1)) do
        local neg
        local vk = snp.nxt
        if P.is_neg(C(S, vk)) then neg = true; vk = vk + 1 end
        for _, vp in ipairs(P.parse_vp(S, vk, { aux_hint = (cat(c, "aux_do") and "do") or (cat(c, "aux_be") and "be") or "have" })) do
          local cl = { subj = snp, vp = vp, lemma = vp.lemma, neg = neg or vp.neg, voice = vp.voice, last = vp.c2 }
          local objs = P.parse_np(S, vp.nxt)
          if objs[1] then cl.obj = objs[1]; cl.last = objs[1].c2 end
          best = best or cl
        end
      end
    end
  end
  return best
end

---------------------------------------------------------------- frame: yes/no verification
function F.yes_no(S, out)
  local k0 = S.first
  local c0 = C(S, k0)
  if not (c0 and c0.single and (cat(c0, "aux_be") or cat(c0, "aux_do") or cat(c0, "aux_have") or cat(c0, "modal") or c0.be_clitic or (cat(c0, "clitic_s") and S.inverted)) and not cat(c0, "wh")) then return end
  local akind = P.aux_kind(c0) or (cat(c0, "clitic_s") and "be") or nil
  -- "Isn't Canberra the capital of Australia?": a negated auxiliary asks for confirmation; the claim being checked is the positive one
  local nstart, neg_first = k0 + 1, nil
  if P.is_neg(C(S, nstart)) and not barrier(C(S, nstart)) then neg_first = nstart; nstart = nstart + 1 end
  for _, np1 in ipairs(P.parse_np(S, nstart)) do
    -- "Is Sydney NOT the capital of Australia?": the negation follows the subject
    local neg_mid
    if akind == "be" and np1.nxt <= S.last and P.is_neg(C(S, np1.nxt)) and not barrier(C(S, np1.nxt)) then neg_mid = np1.nxt end
    local function base(frame)
      local h = newh(S, frame, "question", "verification", "verify")
      use(h, k0); use_np(h, np1)
      if neg_first then use(h, neg_first); h.polarity = "negative"; addf(h, "confirmation_question", 0.0, "negated auxiliary: the question asks for confirmation; the claim checked is the positive one") end
      if neg_mid then use(h, neg_mid); h.polarity = "negative"; addf(h, "confirmation_question", 0.0, "negated question: asks for confirmation; the claim checked is the positive one") end
      h.requires_evidence = true
      mark_unresolved_pron(h, np1)
      return h
    end
    if akind == "be" then
      local nk = neg_mid and (np1.nxt + 1) or np1.nxt
      -- "Is Paris the capital of France?"  /  "Is the capital of France Paris?"
      for _, np2 in ipairs(P.parse_np(S, nk)) do
        for _, pair in ipairs({ { np1, np2 }, { np2, np1 } }) do
          local value, relnp = pair[1], pair[2]
          if relnp.head_kind == "relnoun" and value.head_kind ~= "relnoun" then
            for _, o in ipairs(relnp_options(S, relnp)) do
              if o.arg then
                local h = base("yes_no:be_rel")
                use_np(h, np2)
                h.rel, h.rel_obj = o.rel.id, o.rel
                h.roles[o.known_role] = o.arg
                h.roles[o.ask_role] = value
                h.verify = { rel = o.rel.id, from = h.roles.from, to = h.roles.to }
                h.items = (value.u1 or 0) < (o.arg.u1 or 0) and { value, o.arg } or { o.arg, value }
                h.known_role, h.ask = o.known_role, nil
                addf(h, "relnp_arg", 0.6, "verification of a relational statement")
                mark_unresolved_pron(h, o.arg); mark_unresolved_pron(h, value)
                out[#out + 1] = h
              end
            end
          end
        end
        if np2.head_kind == "typenoun" and np1.head_kind == "entity" then
          local h = base("yes_no:be_type")
          use_np(h, np2)
          h.verify = { type_assertion = np2.senses and np2.senses[1] and np2.senses[1].type, subject = np1 }
          h.roles.subject = np1
          out[#out + 1] = h
        end
      end
      -- "Is Paris in France?"  "Is X located in Y?"
      local pk = nk
      local vps = P.parse_vp(S, nk, { aux_hint = "be" })
      for _, vp in ipairs(vps) do
        if vp.voice == "passive" then
          for _, e in ipairs(vp.analysis.entries) do
            local rel = S.lex:get_rel(e.rel)
            if rel then
              if e.prep and is_prep(C(S, vp.nxt), e.prep) then
                for _, np2 in ipairs(P.parse_np(S, vp.nxt + 1)) do
                  local h = base("yes_no:be_stative")
                  use_vp(h, vp); use(h, vp.nxt); use_np(h, np2)
                  h.rel, h.rel_obj = rel.id, rel
                  h.roles[e.subj] = np1; h.roles[other(e.subj)] = np2
                  h.verify = { rel = rel.id, from = h.roles.from, to = h.roles.to }
                  h.items = { np1, np2 }
                  out[#out + 1] = h
                end
              elseif not e.prep and is_prep(C(S, vp.nxt), "by") then
                for _, np2 in ipairs(P.parse_np(S, vp.nxt + 1)) do
                  local h = base("yes_no:be_passive")
                  use_vp(h, vp); use(h, vp.nxt); use_np(h, np2)
                  h.rel, h.rel_obj = rel.id, rel
                  h.roles[other(e.subj)] = np1; h.roles[e.subj] = np2
                  h.verify = { rel = rel.id, from = h.roles.from, to = h.roles.to }
                  h.items = { np1, np2 }
                  if vp.neg then h.polarity = "negative" end
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
      if is_prep(C(S, pk), "in") then
        local lrel = S.lex:get_rel("located_in")
        for _, np2 in ipairs(P.parse_np(S, pk + 1)) do
          local h = base("yes_no:be_in")
          use(h, pk); use_np(h, np2)
          h.rel, h.rel_obj = "located_in", lrel
          h.roles.from, h.roles.to = np1, np2
          h.verify = { rel = "located_in", from = np1, to = np2 }
          h.items = { np1, np2 }
          out[#out + 1] = h
        end
      end
    elseif akind == "do" or akind == "have" or akind == "modal" then
      for _, vp in ipairs(P.parse_vp(S, np1.nxt, { aux_hint = (akind == "do" and "do") or (akind == "have" and "have") or "modal" })) do
        for _, e in ipairs(vp.analysis.entries) do
          local rel = S.lex:get_rel(e.rel)
          if rel then
            local pk = vp.nxt
            local has_prep = e.prep and is_prep(C(S, pk), e.prep)
            local ok_start = has_prep and pk + 1 or (not e.prep and pk)
            if ok_start then
              for _, np2 in ipairs(P.parse_np(S, ok_start)) do
                local h = base("yes_no:aux_verb")
                use_vp(h, vp); use_np(h, np2)
                if has_prep then use(h, pk) end
                h.rel, h.rel_obj = rel.id, rel
                h.roles[e.subj] = np1; h.roles[other(e.subj)] = np2
                h.verify = { rel = rel.id, from = h.roles.from, to = h.roles.to }
                h.items = { np1, np2 }
                if vp.neg then h.polarity = "negative" end
                addf(h, "direction_explicit", 0.3, "role direction fixed by active verb")
                mark_unresolved_pron(h, np2)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

return F

end

package.preload["asi.nlu.frames2"] = function(...)
-- asi.nlu.frames2: request-side constructions (imperatives, search with filters, comparison, definition/description,
-- statements, focus, instructions/corrections).  Extends asi.nlu.frames.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local F = require("asi.nlu.frames")

local cat = P.cat
local newh, addf, use_np = F.newh, F.addf, F.use_np
local function C(S, k) return S.chunks[k] end
local function barrier(c) return c ~= nil and c.pre ~= nil end
local function other(role) return role == "to" and "from" or "to" end
local function use(h, a, b) for i = a, b or a do h.used[i] = true end end

local WRAPPER_NOUNS = U.set({ "concept", "term", "notion", "idea", "meaning", "definition", "word", "phrase", "topic" })

-- "the concept of X" / "the meaning of X" -> X
local function unwrap(np)
  if np and np.of_arg and (np.head_kind == "typenoun" or np.head_kind == "concept" or np.head_kind == "unknown")
    and np.head and WRAPPER_NOUNS[np.head.form] then
    return np.of_arg, true
  end
  return np, false
end

local function skip_fillers(S, k)
  -- "me", "for", "about", "up", "out", "the following" style fillers after a request verb
  local used = {}
  while true do
    local c = C(S, k)
    local nx = C(S, k + 1)
    if c and c.single and not c.masked and (c.unit.form == "me" or c.unit.form == "for" or c.unit.form == "about" or c.unit.form == "up"
      or c.unit.form == "out" or c.unit.form == "regarding" or c.unit.form == "on" and false) then
      used[#used + 1] = k; k = k + 1
    -- "tell me MORE / MORE ABOUT / A BIT MORE ABOUT / EVERYTHING ABOUT X": the quantity word asks for more of the same
    elseif c and c.single and not c.masked and (c.unit.form == "more" or c.unit.form == "everything" or c.unit.form == "anything" or c.unit.form == "all") and nx and nx.single and nx.unit.form == "about" and not barrier(nx) then
      used[#used + 1] = k; used[#used + 1] = k + 1; k = k + 2
    else break end
  end
  return k, used
end

---------------------------------------------------------------- filters on a target set  (shared with constraints.lua)
-- parse modifiers that follow a target NP:  [that|which|who] [adv] V NP  |  V-ing NP  |  V-ed <temporal|by NP>  |  in/based in PLACE  |  with N X
-- returns list of filters and the next chunk index.  Every filter records exactly the chunks it consumed.
---------------------------------------------------------------- numeric restrictions on a relation's value
--   "with more than 500 employees"   "that have a population over one million"   "having at least 10 offices"   "with revenue of exactly 5 billion"
--   "between 100 and 200 employees"
-- The relation is named by a relational noun whose `to` role is a number (employees, population/inhabitants, revenue ...).
local CMP_CUES = { { "cmp_gt", "gt" }, { "cmp_ge", "ge" }, { "cmp_lt", "lt" }, { "cmp_le", "le" }, { "cmp_eq", "eq" }, { "cmp_approx", "approx" } }
local function cmp_at(S, k)
  local c = C(S, k)
  if not c or c.masked or not c.u1 then return nil end
  for _, ce in ipairs(CMP_CUES) do
    local n = S.lex:cue_at(ce[1], S.units, c.u1)
    if n then
      local consumed, kk = 0, k
      while C(S, kk) and consumed < n do consumed = consumed + (C(S, kk).u2 - C(S, kk).u1 + 1); kk = kk + 1 end
      if consumed == n then return ce[2], kk end
    end
  end
end
local function number_at(S, k)
  local c = C(S, k)
  if not c or c.masked or (c.pre and k > 1 and false) then return nil end
  if c.number and c.number.value then return c.number.value, k + 1 end
  if c.single and c.unit and c.unit.kind == "number" and c.unit.numval ~= nil and not c.temporal then return c.unit.numval, k + 1 end
end
local function numeric_noun_rel(S, c)
  if not c or c.masked then return nil end
  for _, e in ipairs(c.relnouns or {}) do
    local rel = S.lex:get_rel(e.rel)
    if rel and not rel.open and e.role == "to" and S.lex:compat(rel.to, "number") >= 0.9 then return rel end
  end
  -- a counted noun ("residents", "workers") counts the value of the relation that lists it
  if c.single and c.unit and c.unit.kind == "word" then
    local form = c.unit.form
    for _, rel in ipairs(S.lex:all_rels()) do
      if not rel.open then for _, n in ipairs(rel.count_nouns or {}) do if n == form then return rel end end end
    end
  end
end
local HAVE_WORDS = U.set({ "with", "having", "have", "has", "had" })

function F.numeric_filter(S, k)
  local start = k
  local lead = false
  local c = C(S, k)
  if c and c.single and not c.masked and HAVE_WORDS[c.unit.form] then lead = true; k = k + 1 end
  local function done(rel, op, v1, v2, nk)
    local first, last = C(S, start), C(S, nk - 1)
    local text = S.an.original:sub(S.units[first.u1].s, S.units[last.u2].e)
    return { kind = "numeric", rel = rel.id, op = op, value = v1, value2 = v2, text = text, chunks = { start }, span = { first = start, last = nk - 1 } }, nk
  end
  -- Form A:  [CMP] NUMBER NOUN      "more than 500 employees", "between 100 and 200 employees", (after with/have) "500 employees"
  do
    local op, k2 = cmp_at(S, k)
    local bc = C(S, k)
    if not op and bc and bc.single and not bc.masked and bc.unit.form == "between" then
      local v1, k3 = number_at(S, k + 1)
      local ac = v1 and C(S, k3)
      if ac and ac.single and not ac.masked and (ac.unit.form == "and" or ac.unit.form == "to") then
        local v2, k4 = number_at(S, k3 + 1)
        local rel = v2 and numeric_noun_rel(S, C(S, k4))
        if rel then return done(rel, "between", v1, v2, k4 + 1) end
      end
    end
    local v, k3 = number_at(S, k2 or k)
    if v and (op or lead) then
      local rel = numeric_noun_rel(S, C(S, k3))
      if rel then return done(rel, op or "eq", v, nil, k3 + 1) end
    end
  end
  -- Form B:  [DET] NOUN [of] [CMP] NUMBER       "a population over one million", "revenue of at least 5 billion", "a headcount of 200"
  do
    local nk = k
    local dc = C(S, nk)
    if dc and dc.single and not dc.masked and (cat(dc, "det") or cat(dc, "poss_det")) then nk = nk + 1 end
    local rel = numeric_noun_rel(S, C(S, nk))
    if rel then
      local pk, of = nk + 1, false
      local oc = C(S, pk)
      if oc and oc.single and not oc.masked and (oc.unit.form == "of" or oc.unit.form == "at" or oc.unit.form == "is" or oc.unit.form == "above" and false) then of = oc.unit.form == "of"; pk = pk + 1 end
      local op, k2 = cmp_at(S, pk)
      local v, k3 = number_at(S, k2 or pk)
      if v and (op or of) then return done(rel, op or "eq", v, nil, k3) end
      -- "between 1 and 2 million"
      local bc = C(S, pk)
      if bc and bc.single and not bc.masked and bc.unit.form == "between" then
        local v1, k4 = number_at(S, pk + 1)
        local ac = v1 and C(S, k4)
        if ac and ac.single and not ac.masked and ac.unit.form == "and" then
          local v2, k5 = number_at(S, k4 + 1)
          if v2 then return done(rel, "between", v1, v2, k5) end
        end
      end
    end
  end
  return nil
end

function F.parse_filters(S, k, target_np, limit_idx)
  local filters = {}
  local lex = S.lex
  limit_idx = limit_idx or S.last
  local function last_unmasked(i) return i <= limit_idx and C(S, i) and not C(S, i).masked end
  local guard = 0
  while last_unmasked(k) and guard < 8 do
    guard = guard + 1
    local c = C(S, k)
    local start = k
    local progressed = false
    -- optional list joiner
    if c.single and (cat(c, "conj") and (c.unit.form == "and" or c.unit.form == "or") ) and not (c.pre and c.pre:find("sent")) then
      k = k + 1; c = C(S, k)
      if not c or c.masked then break end
    end
    -- locative relative clause:  "the country where Mount Fuji is"  ->  located_in(from=Mount Fuji, to=<target>)
    if c.single and c.unit.form == "where" and lex:get_rel("located_in") then
      local done
      for _, np in ipairs(P.parse_np(S, k + 1)) do
        local bc = C(S, np.nxt)
        if bc and bc.single and not bc.masked and (cat(bc, "aux_be") or cat(bc, "clitic_s")) then
          -- "where O is headquartered" (stative verb with a preposition): the place plays the OTHER role of that relation
          for _, vp in ipairs(P.parse_vp(S, np.nxt, { aux_hint = nil })) do
            if vp.voice == "passive" then
              for _, e in ipairs(vp.analysis.entries) do
                local r = lex:get_rel(e.rel)
                if r and e.prep and not r.open then
                  filters[#filters + 1] = { kind = "relation", rel = r.id, target_role = other(e.subj), value = np, chunks = { k, vp.c2 },
                    span = { first = k, last = vp.c2 }, locative_clause = true }
                  k = vp.nxt
                  done = true
                  break
                end
              end
            end
            if done then break end
          end
          if done then break end
          filters[#filters + 1] = { kind = "relation", rel = "located_in", target_role = "to", value = np, chunks = { k, np.nxt },
            span = { first = k, last = np.nxt }, locative_clause = true }
          k = np.nxt + 1
          done = true
          break
        end
        -- "where O has its head office": a support verb + a possessed location-valued noun
        for _, vp in ipairs(P.parse_vp(S, np.nxt, {})) do
          for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
            local dc = C(S, onp.c1)
            if onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and (cat(dc, "poss_det") or cat(dc, "det")) and onp.c1 < onp.nxt - 1 then
              for _, o in ipairs(F.relnp_options(S, onp)) do
                local supported = (vp.lemma == "have" and o.rel.support_have) or false
                for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == o.rel.id then supported = true end end
                if supported and o.rel.locus and o.ask_role == "to" then
                  filters[#filters + 1] = { kind = "relation", rel = o.rel.id, target_role = "to", value = np, chunks = { k, onp.nxt - 1 },
                    span = { first = k, last = onp.nxt - 1 }, locative_clause = true }
                  k = onp.nxt
                  done = true
                  break
                end
              end
            end
            if done then break end
          end
          if done then break end
        end
        if done then break end
      end
      if done then goto continue_filters end
    end
    -- relativiser
    local rel_marker
    if c.single and (c.unit.form == "that" or c.unit.form == "which" or c.unit.form == "who") then rel_marker = true; k = k + 1 end
    -- numeric restriction: "with more than 500 employees", "that have a population over one million"
    do
      local nf, nk2 = F.numeric_filter(S, k)
      if nf and nk2 - 1 <= limit_idx then
        nf.span.first = start
        filters[#filters + 1] = nf
        k = nk2; progressed = true
        goto continue_filters
      end
    end
    -- copular relative clause: "the city that IS / FUNCTIONS AS the capital of K"
    if rel_marker and C(S, k) and C(S, k).single and cat(C(S, k), "aux_be") and not C(S, k).masked then
      local done
      for _, np in ipairs(P.parse_np(S, k + 1)) do
        if np.head_kind == "relnoun" then
          for _, o in ipairs(F.relnp_options(S, np)) do
            if o.arg and o.rel and not o.rel.open then
              filters[#filters + 1] = { kind = "relation", rel = o.rel.id, target_role = o.ask_role, value = o.arg, chunks = { start, np.c2 },
                span = { first = start, last = np.nxt - 1 }, copular_relative = true }
              k = np.nxt
              done = true
              break
            end
          end
        end
        if done then break end
      end
      if done then goto continue_filters end
    end
    -- object relative clause, with or without a relativiser:  "the companies (that) Google acquired",  "the startups Sequoia Capital has invested in"
    -- the subject is a proper name; the verb is followed only by (a stranded preposition and) the end of the clause, so the target set fills the gap
    if not (rel_marker and C(S, k) and C(S, k).single and cat(C(S, k), "aux_be")) then
      local done
      for _, snp in ipairs(P.parse_np(S, k, { no_of = true })) do
        if snp.head_kind == "entity" or (snp.head_kind == "unknown" and snp.head and snp.head.cap) then
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, {})) do
            if vp.voice == "active" then
              for _, e in ipairs(vp.analysis.entries) do
                local rel = lex:get_rel(e.rel)
                if rel and not e.support and not e.as_only and not rel.open then
                  local nxt, ok = vp.nxt, true
                  if e.prep then
                    local pc2 = C(S, nxt)
                    if pc2 and pc2.single and not pc2.masked and pc2.unit.form == e.prep then nxt = nxt + 1 else ok = false end
                  end
                  local fc = C(S, nxt)
                  local gap_end = (nxt > limit_idx) or (fc ~= nil and (fc.pre ~= nil or fc.temporal ~= nil or (fc.single and (cat(fc, "conj") or cat(fc, "prep")))))
                  if ok and gap_end then
                    filters[#filters + 1] = { kind = "relation", rel = rel.id, target_role = other(e.subj), value = snp, chunks = { start, nxt - 1 },
                      span = { first = start, last = nxt - 1 }, adv = vp.tscope, polarity = vp.neg and "negative" or "positive", object_relative = true }
                    k = nxt; done = true; progressed = true
                    break
                  end
                end
              end
            end
            if done then break end
          end
        end
        if done then break end
      end
      if done then goto continue_filters end
    end
    -- verb phrase (participial or relative)
    -- with a relativiser ("that currently offer ...") any finite form is fine; without one only participles can modify a noun
    local tmp = rel_marker and P.parse_vp(S, k, {}) or P.parse_vp(S, k, { participle_ok = true })
    for _, vp in ipairs(tmp) do
      for _, e in ipairs(vp.analysis.entries) do
        local rel = lex:get_rel(e.rel)
        if rel and not e.as_only then
          local f
          local nxt = vp.nxt
          local tc = C(S, nxt)
          -- (a) passive participle + temporal expression:  "established after 2020"  -> rel.when
          if (vp.vform == "pp" or vp.vform == "past") and tc and tc.temporal and tc.temporal.kind ~= "marker" and rel.when and lex:get_rel(rel.when) and not tc.masked then
            local trel = lex:get_rel(rel.when)
            f = { kind = "temporal_relation", rel = trel.id, via = rel.id, role = "from", expr = tc.temporal, chunks = { start, vp.c2, nxt }, adv = vp.tscope }
            nxt = nxt + 1
          elseif e.prep then
            if C(S, nxt) and C(S, nxt).single and cat(C(S, nxt), "prep") and C(S, nxt).unit.form == e.prep then
              for _, np in ipairs(P.parse_np(S, nxt + 1, { no_of = false })) do
                local t_role = e.subj
                f = { kind = "relation", rel = rel.id, target_role = t_role, value = np, chunks = { start, vp.c2, nxt }, adv = vp.tscope, polarity = vp.neg and "negative" or "positive" }
                nxt = np.nxt
                break
              end
            end
          else
            for _, np in ipairs(P.parse_np(S, nxt)) do
              local pass = vp.voice == "passive" or vp.vform == "pp"
              local t_role = pass and other(e.subj) or e.subj
              if pass and not (C(S, np.c1) and false) then
                -- passive with by-agent:  "founded by X"
              end
              f = { kind = "relation", rel = rel.id, target_role = t_role, value = np, chunks = { start, vp.c2 }, adv = vp.tscope, polarity = vp.neg and "negative" or "positive" }
              nxt = np.nxt
              break
            end
            if not f and (vp.vform == "pp" or vp.voice == "passive") and C(S, nxt) and C(S, nxt).single and C(S, nxt).unit.form == "by" then
              for _, np in ipairs(P.parse_np(S, nxt + 1)) do
                f = { kind = "relation", rel = rel.id, target_role = other(e.subj), value = np, chunks = { start, vp.c2, nxt }, adv = vp.tscope }
                nxt = np.nxt
                break
              end
            end
          end
          if f then
            f.span = { first = start, last = nxt - 1 }
            filters[#filters + 1] = f
            k = nxt
            progressed = true
            break
          end
        end
      end
      if progressed then break end
    end
    if not progressed then
      -- PP filters: geography ("in Germany"), attribute quantities ("with more than 100 employees")
      local pc = C(S, start)
      if rel_marker then pc = nil end
      if pc and pc.single and cat(pc, "prep") and not pc.masked then
        local f = pc.unit.form
        if f == "in" or f == "near" or f == "around" or f == "within" or f == "across" or f == "on" or f == "at" or f == "throughout" or f == "outside" or f == "inside" then
          for _, np in ipairs(P.parse_np(S, start + 1, { no_of = false })) do
            if np.head_kind == "entity" then
              filters[#filters + 1] = { kind = "geo", prep = f, value = np, chunks = { start }, span = { first = start, last = np.nxt - 1 } }
              k = np.nxt; progressed = true
              break
            end
          end
        elseif f == "with" then
          local nk = start + 1
          -- quantity comparator:  "with more than 100 employees"
          local cmp_n = lex:cue_at("quantifier_cmp", S.units, C(S, nk) and C(S, nk).u1 or 0)
          for _, np in ipairs(P.parse_np(S, nk, { no_of = false })) do
            f = { kind = "has", value = np, chunks = { start }, span = { first = start, last = np.nxt - 1 } }
            filters[#filters + 1] = f
            k = np.nxt; progressed = true
            break
          end
        end
      end
    end
    if not progressed then k = start; break end
    ::continue_filters::
  end
  return filters, k
end

---------------------------------------------------------------- multi-hop chains
-- A known argument that is itself a relational NP ("the founder of Example Labs") or a type noun modified by a relative clause
-- ("the country where Mount Fuji is", "the company that acquired Beta Systems") is expanded into ordered lookup steps with
-- typed intermediate variables:  steps[1] runs first; the hypothesis' own relation consumes the last variable.
local function lex_rel(S, id) return S.lex:get_rel(id) end

local function relativizer(c)
  return c and c.single and not c.masked and (c.unit.form == "that" or c.unit.form == "which" or c.unit.form == "who" or c.unit.form == "where")
end

function F.expand_chain(S, h)
  if h.chain_done or not h.known_role or not h.rel then return end
  h.chain_done = true
  local top_np = h.roles[h.known_role]
  if not top_np or top_np.head_kind == "pronoun" then return end
  local steps = {}
  local used_extra = {}
  local last_chunk = top_np.c2

  local function build(np, depth)
    if depth > 3 or not np then return nil end
    if np.head_kind == "relnoun" then
      for _, o in ipairs(F.relnp_options(S, np)) do
        if o.arg then
          local inner = build(o.arg, depth + 1)
          steps[#steps + 1] = { rel = o.rel.id, rel_obj = o.rel, known_role = o.known_role, known = inner and inner.var_np or o.arg, ask_role = o.ask_role,
            result_type = o.rel[o.ask_role], source_np = np }
          return { var_np = { head_kind = "var", var = "?" .. #steps, type = o.rel[o.ask_role], step = #steps, u1 = np.u1, u2 = np.u2, c1 = np.c1, c2 = np.c2,
            mods = {}, score = 0, notes = {} } }
        end
      end
    elseif (np.head_kind == "typenoun" or np.head_kind == "unknown") and relativizer(C(S, np.nxt)) then
      local filters, k = F.parse_filters(S, np.nxt, np)
      local made
      for _, f in ipairs(filters) do
        if f.kind == "relation" then
          local rel = lex_rel(S, f.rel)
          if rel then
            local ntype = np.senses and np.senses[1] and np.senses[1].type
            steps[#steps + 1] = { rel = rel.id, rel_obj = rel, known_role = other(f.target_role), known = f.value, ask_role = f.target_role,
              result_type = ntype or rel[f.target_role], source_np = np, via_clause = true }
            for i = f.span.first, f.span.last do used_extra[i] = true end
            last_chunk = math.max(last_chunk, f.span.last)
            made = #steps
          end
        end
      end
      if made then
        local ntype = np.senses and np.senses[1] and np.senses[1].type
        return { var_np = { head_kind = "var", var = "?" .. made, type = ntype or steps[made].result_type, step = made, u1 = np.u1, u2 = np.u2, c1 = np.c1,
          c2 = np.c2, mods = {}, score = 0, notes = {} } }
      end
    end
    return nil
  end

  local res = build(top_np, 0)
  if res and #steps > 0 then
    local var = res.var_np
    var.u1, var.c1 = top_np.u1, top_np.c1
    var.c2 = math.max(last_chunk, top_np.c2)
    var.u2 = S.chunks[var.c2].u2
    var.steps = steps
    h.chain = steps
    h.roles[h.known_role] = var
    for i = top_np.c1, var.c2 do h.used[i] = true end
    for i in pairs(used_extra) do h.used[i] = true end
    h.factors[#h.factors + 1] = { name = "multi_hop", v = 0.3, note = #steps .. "-step chain before " .. h.rel }
    -- "the location of X's headquarters": a location-valued noun is answered by its own value; a second 'located_in' hop is redundant unless the
    -- question asks for a narrower kind of place ("in which COUNTRY is ...")
    local top = steps[#steps]
    local wt = h.wh and h.wh.type
    if h.rel == "located_in" and top and top.rel_obj.locus and top.ask_role == "to" and (not wt or wt == "place" or wt == "location" or S.lex:compat(top.rel_obj.to, wt) >= 0.9) then
      h.factors[#h.factors + 1] = { name = "redundant_location_hop", v = -0.9, note = "the noun's own relation already gives a location; a second located_in hop is redundant" }
    end
  end
end

---------------------------------------------------------------- request frames
local ACT_INFORM_DEFINE = U.set({ "define" })

local function finish_target_h(S, h, np, k_after, filters)
  h.target = np
  h.filters = filters
  for _, f in ipairs(filters) do
    for i = f.span.first, f.span.last do h.used[i] = true end
  end
end

local DESCRIBES = U.set({ "overview", "summary", "profile", "rundown", "background", "introduction", "snapshot", "briefing", "primer", "description", "biography", "bio" })
-- build hypotheses from a request object NP (shared by imperatives, polite wrappers and "I want ...")
local function from_object_np(S, out, np, verb_info, speech_act, prefix_used, fprefix)
  local act = verb_info and verb_info.act
  local lemma = verb_info and verb_info.lemma
  local function base(frame)
    if fprefix then frame = frame:gsub("^request", fprefix) end
    local h = newh(S, frame, speech_act or "request")
    use_np(h, np)
    for _, u in ipairs(prefix_used or {}) do h.used[u] = true end
    if verb_info and verb_info.chunk_idx then h.used[verb_info.chunk_idx] = true end
    h.request_verb = lemma
    F.mark_pron(h, np)
    return h
  end
  local subj, unwrapped = unwrap(np)
  if unwrapped then np = subj end
  if np.head_kind == "relnoun" then
    for _, o in ipairs(F.relnp_options(S, np)) do
      local h = base("request:relnp")
      if o.arg then
        h.rel, h.rel_obj = o.rel.id, o.rel
        h.roles[o.known_role] = o.arg
        h.known_role, h.ask = o.known_role, o.ask_role
        h.ask_type = o.rel[o.ask_role]
        h.op, h.intent, h.requires_evidence = "lookup", "factual_lookup", true
        addf(h, "relnp_arg", 0.7, "relational noun with explicit argument")
        F.option_factors(h, o)
        if np.temporal_scope then h.temporal_scope = np.temporal_scope end
        if np.superlative then h.ordering = { superlative = np.superlative } end
        F.mark_pron(h, o.arg)
      else
        h.op, h.intent, h.rel, h.rel_obj, h.concept = "define", "definition", o.rel.id, o.rel, np
        addf(h, "relnoun_no_arg", -1.0, "relational noun without its argument")
      end
      out[#out + 1] = h
    end
  elseif np.head_kind == "entity" then
    local h = base("request:entity")
    h.op, h.intent, h.requires_evidence = "describe", "entity_description", true
    h.subject = np; h.roles.subject = np
    if act == "inform" and lemma == "define" then h.op, h.intent = "define", "definition"; h.concept = np end
    out[#out + 1] = h
  elseif np.head_kind == "typenoun" or np.head_kind == "concept" or np.head_kind == "unknown" then
    -- "Name the person who set up O." / "Give me the city where O keeps its head office.": a definite SINGULAR description with one relative clause asks
    -- for the one referent -- a lookup of the clause's relation, not a search for a set
    if np.head_kind == "typenoun" and not np.plural and np.det == "the" and (act == "retrieve" or act == "inform") then
      local filters, kf = F.parse_filters(S, np.nxt, np)
      local f = filters[1]
      if #filters == 1 and f.kind == "relation" and f.value and kf > S.last then
        local drel = S.lex:get_rel(f.rel)
        if drel and not drel.open then
          local h = base("request:description")
          h.rel, h.rel_obj = drel.id, drel
          h.roles[other(f.target_role)] = f.value
          h.known_role, h.ask = other(f.target_role), f.target_role
          h.ask_type = drel[f.target_role]
          h.op, h.intent, h.requires_evidence = "lookup", "factual_lookup", true
          h.wh_type = np.senses and np.senses[1] and np.senses[1].type or nil
          for i = f.span.first, f.span.last do h.used[i] = true end
          addf(h, "description_lookup", 0.9, "definite singular description with one relative clause names a single referent")
          F.mark_pron(h, f.value)
          out[#out + 1] = h
        end
      end
    end
    -- "give me a SUMMARY of the figures", "send me an overview of the results": a task noun requested through a retrieval verb is a task
    local hf = np.head and np.head.single and np.head.unit and np.head.unit.form
    -- "give me an OVERVIEW of Corvane Plastics", "a PROFILE of X": a description noun over a named entity asks for the description of that entity
    if hf and DESCRIBES[hf] and np.of_arg and np.of_arg.head_kind == "entity" and (act == "retrieve" or act == "inform" or act == "task") then
      local h = base("request:entity")
      h.op, h.intent, h.requires_evidence = "describe", "entity_description", true
      h.subject = np.of_arg; h.roles.subject = np.of_arg
      use_np(h, np.of_arg)
      addf(h, "description_noun", 0.9, "'" .. hf .. "' of a named entity asks for a description of it")
      out[#out + 1] = h
    end
    if hf and (S.lex:cats(hf) or {}).tasknoun and (act == "retrieve" or act == "inform" or act == "task") then
      local h = base("request:task_nominal")
      h.op, h.intent = "task", "task"
      h.task_verb, h.object, h.requires_context = hf, np.of_arg or np, true
      addf(h, "task_noun", 0.9, "'" .. hf .. "' names a task (summary, analysis, overview ...) requested through the verb '" .. tostring(lemma) .. "'")
      out[#out + 1] = h
    end
    -- plural typenoun => search for a set;  singular typenoun after find/list => search too;  concept/unknown => define/describe
    local plural = np.plural
    -- "Find/Show/List <noun>" requests items of that kind, also when the noun is not in the lexicon
    -- a bare plural noun phrase with a locative / relative filter and no verb ("Cinemas in Karsholm, please.") is a search as well
    local bare_filtered = false
    if not act and np.head_kind == "unknown" and plural then
      local fl, kf0 = F.parse_filters(S, np.nxt, np)
      local only_fillers = true
      for i = kf0, S.last do local ci = C(S, i); if not (ci and ci.single and (cat(ci, "polite") or cat(ci, "discourse") or cat(ci, "ignorable"))) then only_fillers = false end end
      bare_filtered = #fl > 0 and only_fillers
    end
    if ((np.head_kind == "typenoun") and (plural or act == "retrieve")) or (np.head_kind == "unknown" and act == "retrieve") or bare_filtered then
      local h = base("request:search")
      if np.head_kind == "unknown" then addf(h, "unknown_target_type", -0.1, "search target type is not in the lexicon") end
      -- a target that swallows a named entity plus a lowercase word ("the companies Google acquired") has swallowed a clause, not named a set
      if np.head_kind == "unknown" and np.head and np.head.single and not np.head.cap then
        for _, md in ipairs(np.mods or {}) do
          if md.kind == "entity_mod" then addf(h, "target_swallows_clause", -0.8, "the target phrase contains a named entity followed by a lowercase word: a clause, not a noun phrase"); break end
        end
      end
      h.op, h.intent, h.requires_evidence = "search", "search", true
      local filters, kf = F.parse_filters(S, np.nxt, np)
      finish_target_h(S, h, np, kf, filters)
      addf(h, "search_target", 0.5, "typed target set")
      if #filters > 0 then addf(h, "filters_parsed", 0.15 * #filters, #filters .. " filter(s) from relative/participial clauses") end
      out[#out + 1] = h
    end
    local h = base("request:concept")
    if act == "retrieve" and (np.head_kind == "unknown" or (np.head_kind == "typenoun" and plural)) then addf(h, "retrieval_verb_not_definition", -0.6, "a retrieval verb asks for items, not a definition") end
    if act == "inform" and lemma == "explain" then h.op, h.intent = "explain", "explanation"
    elseif act == "inform" and lemma == "describe" then h.op, h.intent = "describe", "entity_description"
    else h.op, h.intent = "define", "definition" end
    h.concept = np
    h.requires_evidence = true
    if np.head_kind == "unknown" then addf(h, "unknown_term", -0.15, "term not in the lexicon") end
    if np.of_arg then addf(h, "concept_of_arg", -0.4, "a non-relational concept noun with an 'of' argument is a weaker structure than a relational noun") end
    out[#out + 1] = h
  elseif np.head_kind == "pronoun" or np.head_kind == "ordinal_ref" then
    local h = base("request:pronoun")
    h.op, h.intent = "describe", "entity_description"
    h.subject = np
    out[#out + 1] = h
  elseif np.head_kind == "quote" or np.head_kind == "literal" then
    local h = base("request:literal")
    h.op, h.intent, h.requires_evidence = "describe", "entity_description", true
    h.subject = np
    out[#out + 1] = h
  end
end

function F.request(S, out)
  local k = S.first
  local c = C(S, k)
  if not c or c.masked then return end
  local w = S.wrapper or { kinds = {} }
  local wrapped = #w.kinds > 0
  -- 1. imperative verb at the start of the core
  local vana = (c.single or c.kind == "mwe") and P.verb_analyses(S, c) or {}
  for _, a in ipairs(vana) do
    if a.form == "base" and (a.act or #a.entries > 0) and not cat(c, "wh") then
      local act = a.act or "task"
      local nk, fill_used = skip_fillers(S, k + 1)
      local vinfo = { act = act, lemma = a.lemma, chunk_idx = k }
      if act == "inform" or act == "retrieve" or act == "task" or act == "focus" then
        -- explain why/how ...
        local wh = P.parse_wh(S, nk)
        local sub_h
        for _, wq in ipairs(wh) do
          if wq.adverbial and (wq.wh == "why" or wq.wh == "how") and a.lemma == "explain" then
            local h = newh(S, "request:explain_clause", "request", wq.wh == "why" and "causal_explanation" or "explanation", "explain")
            h.wh = wq; h.request_verb = a.lemma; h.requires_evidence = true
            use(h, k); for _, u in ipairs(fill_used) do h.used[u] = true end
            for i = wq.c1, wq.c2 do h.used[i] = true end
            local cl = F.parse_clause(S, wq.nxt)
            if cl then h.clause = cl; for i = wq.nxt, cl.last do h.used[i] = true end; addf(h, "clause_parsed", 0.4, "explanatory clause identified")
            else addf(h, "clause_missing", -0.6, "no clause to explain") end
            out[#out + 1] = h
          end
        end
        for _, np in ipairs(P.parse_np(S, nk)) do
          if act == "task" or act == "focus" then
            local h = newh(S, "request:task", "request", "task", "task")
            use(h, k); use_np(h, np); for _, u in ipairs(fill_used) do h.used[u] = true end
            h.task_verb = a.lemma; h.object = np; h.requires_context = true
            F.mark_pron(h, np)
            out[#out + 1] = h
          else
            from_object_np(S, out, np, vinfo, "request", fill_used)
          end
        end
      elseif act == "compare" then
        for _, np1 in ipairs(P.parse_np(S, nk)) do
          local items, endk = { np1 }, np1.nxt
          while true do
            local jc = C(S, endk)
            if jc and jc.single and (jc.unit.form == "and" or jc.unit.form == "with" or jc.unit.form == "to" or jc.unit.form == "versus" or jc.unit.form == "vs") then
              local nps = P.parse_np(S, endk + 1)
              if nps[1] then items[#items + 1] = nps[1]; endk = nps[1].nxt else break end
            elseif jc and not jc.masked and jc.pre and jc.pre:find("comma") and #items >= 1 then
              -- "Compare A, B and C": the next item follows the comma directly
              local nps = P.parse_np(S, endk)
              if nps[1] and nps[1].nxt > endk then items[#items + 1] = nps[1]; endk = nps[1].nxt else break end
            else break end
          end
          if #items >= 2 then
            local h = newh(S, "request:compare", "request", "comparison", "compare")
            use(h, k); for _, u in ipairs(fill_used) do h.used[u] = true end
            h.items = items
            for _, it in ipairs(items) do use_np(h, it) end
            for i = np1.nxt, endk - 1 do h.used[i] = true end
            h.requires_evidence = true
            addf(h, "comparison_items", 0.5, #items .. " items to compare")
            out[#out + 1] = h
          end
        end
      end
    end
  end
  -- 2. wrapper-led requests ("I want the capital of France", "Could you tell me about Mercury")
  if wrapped then
    local nk, fill_used = skip_fillers(S, k)
    local c0 = C(S, nk)
    local prefix = fill_used
    if c0 and c0.single and not c0.masked and (c0.unit.form == "about" or c0.unit.form == "regarding") then prefix = { nk }; nk = nk + 1 end
    for _, np in ipairs(P.parse_np(S, nk)) do
      from_object_np(S, out, np, { act = w.seek and "retrieve" or "inform", lemma = w.verb }, "request", prefix)
    end
  end
end

F.from_object_np = from_object_np
F.resource_slot = resource_slot

---------------------------------------------------------------- bare NP (fragment)  "capital of France"  "france capital?"  "Mercury"
function F.np_only(S, out)
  if S.wrapper and #S.wrapper.kinds > 0 then return end -- wrapper-led requests are handled by F.request
  for _, np in ipairs(P.parse_np(S, S.first)) do
    from_object_np(S, out, np, nil, "fragment", {}, "fragment")
    -- "Chile - capital" / "Egypt, capital?" : the argument comes first, the relational noun after a separator
    if np.head_kind == "entity" and not np.of_arg and not np.possessor then
      local nx = C(S, np.nxt)
      if nx and nx.pre and (nx.pre:find("comma") or nx.pre:find("dash") or nx.pre:find("colon")) and not nx.masked then
        for _, rn in ipairs(P.parse_np(S, np.nxt)) do
          if rn.head_kind == "relnoun" and not rn.of_arg and not rn.possessor then
            local cp = U.shallow(rn)
            cp.of_arg, cp.comma_arg = np, true
            cp.c1, cp.u1 = np.c1, np.u1
            from_object_np(S, out, cp, nil, "fragment", {}, "fragment")
            break
          end
        end
      end
    end
    -- "capital, France": a relational noun whose argument follows across a comma
    if np.head_kind == "relnoun" and not np.of_arg and not np.possessor then
      local nx = C(S, np.nxt)
      if nx and nx.pre and nx.pre:find("comma") and not nx.masked then
        for _, arg in ipairs(P.parse_np(S, np.nxt)) do
          if arg.head_kind == "entity" then
            local cp = U.shallow(np)
            cp.of_arg, cp.comma_arg, cp.nxt, cp.u2, cp.c2 = arg, true, arg.nxt, arg.u2, arg.c2
            from_object_np(S, out, cp, nil, "fragment", {}, "fragment")
            break
          end
        end
      end
    end
  end
end

-- a sentence that is nothing but an exclusion / preference / restriction clause ("Exclude universities.", "Don't include reposts.")
function F.segment_only(S, out)
  local segs = S.segs or {}
  if #segs == 0 then return end
  for k = S.first, S.last do
    local c = C(S, k)
    if not c.masked and not P.is_function_chunk(S, c) then return end
  end
  local sg = segs[1]
  local h = newh(S, "segment_only:" .. sg.kind, "instruction", "instruction_update", "instruct")
  h.instruction = { verb = sg.cue, act = (sg.kind == "exclusion") and "exclude" or "constraint", kind = sg.kind }
  h.polarity = (sg.kind == "exclusion") and "negative" or "positive"
  addf(h, "segment_only", 0.9, "the whole sentence is a " .. sg.kind .. " clause")
  out[#out + 1] = h
end

---------------------------------------------------------------- comparison questions
-- "What changed between the first version and the revised version?"
function F.wh_change(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial then
      for _, vp in ipairs(P.parse_vp(S, wh.nxt)) do
        if vp.lemma == "change" or vp.lemma == "differ" or vp.lemma == "vary" then
          local pk = vp.nxt
          local pc = C(S, pk)
          if pc and pc.single and (pc.unit.form == "between" or pc.unit.form == "from") then
            for _, np1 in ipairs(P.parse_np(S, pk + 1)) do
              local jc = C(S, np1.nxt)
              if jc and jc.single and (jc.unit.form == "and" or jc.unit.form == "to") then
                for _, np2 in ipairs(P.parse_np(S, np1.nxt + 1)) do
                  local h = newh(S, "wh_change:diff", "question", "comparison", "diff")
                  use(h, wh.c1, wh.c2); F.use_np(h, np1); F.use_np(h, np2)
                  for i = vp.c1, np2.c1 - 1 do h.used[i] = true end
                  h.items = { np1, np2 }
                  h.requires_evidence = true
                  F.mark_pron(h, np1); F.mark_pron(h, np2)
                  addf(h, "diff_between_two", 0.6, "what-changed between two items")
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
    end
  end
end

-- "Which one is older?"  "Which is larger, A or B?"  "Is A older than B?"
function F.compare_q(S, out)
  local lex = S.lex
  local function comp_adj(c)
    if not (c and c.single) then return nil end
    local f = c.unit.form
    for _, r in ipairs(lex:readings(f)) do
      if r.pos == "adj" and (r.feat == "comp" or r.feat == "sup") then return r end
    end
    return nil
  end
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial then
      local bk = wh.nxt
      local be = C(S, bk)
      if be and be.single and (cat(be, "aux_be") or cat(be, "clitic_s")) then
        local ac = C(S, bk + 1)
        local r = comp_adj(ac)
        if r then
          local h = newh(S, "compare_q:wh_adj", "question", "comparison", "rank_attribute")
          use(h, wh.c1, wh.c2); use(h, bk, bk + 1)
          h.wh = wh; h.dimension = r.dim; h.degree = r.feat; h.adj = r.lemma
          local drel = F.dim_unique_rel and F.dim_unique_rel(lex, r.dim)
          if drel then h.rel, h.rel_obj = drel.id, drel end
          h.requires_evidence = true
          addf(h, "comparative_adjective", 0.5, r.lemma .. " (" .. r.feat .. ") on dimension " .. tostring(r.dim))
          -- candidates "A or B"
          local nk = bk + 2
          local items = {}
          local c3 = C(S, nk)
          if c3 and c3.pre and c3.pre:find("comma") then nk = nk end
          for _, np in ipairs(P.parse_np(S, nk)) do
            items[#items + 1] = np; use_np(h, np)
            local oc = C(S, np.nxt)
            if oc and oc.single and oc.unit.form == "or" then
              local nps = P.parse_np(S, np.nxt + 1)
              if nps[1] then items[#items + 1] = nps[1]; use(h, np.nxt); use_np(h, nps[1]) end
            end
            break
          end
          if #items > 0 then h.items = items end
          out[#out + 1] = h
        end
      end
    end
  end
  -- "Is A older than B?"
  local c0 = C(S, k0)
  if c0 and c0.single and cat(c0, "aux_be") then
    for _, np1 in ipairs(P.parse_np(S, k0 + 1)) do
      local ac = C(S, np1.nxt)
      local r = comp_adj(ac)
      local tc = C(S, np1.nxt + 1)
      if r and tc and tc.single and tc.unit.form == "than" then
        for _, np2 in ipairs(P.parse_np(S, np1.nxt + 2)) do
          local h = newh(S, "compare_q:yes_no", "question", "verification", "verify_comparison")
          use(h, k0); use_np(h, np1); use(h, np1.nxt, np1.nxt + 1); use_np(h, np2)
          h.items = { np1, np2 }; h.dimension = r.dim; h.degree = r.feat; h.adj = r.lemma
          h.requires_evidence = true
          addf(h, "comparative_adjective", 0.5, r.lemma .. " on " .. tostring(r.dim))
          out[#out + 1] = h
        end
      end
    end
  end
end

---------------------------------------------------------------- "What does X mean?" / "What does X stand for?"
function F.what_means(S, out)
  local lex = S.lex
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.wh == "what" and not wh.np and not wh.adverbial then
      local ac = C(S, wh.nxt)
      local aux_ok = ac and ac.single and cat(ac, "aux_do") and not ac.masked
      if aux_ok or S.embedded then
        for _, np in ipairs(P.parse_np(S, aux_ok and wh.nxt + 1 or wh.nxt)) do
          local vc = C(S, np.nxt)
          local n = vc and lex:cue_at("definition_verb", S.units, vc.u1)
          if n then
            local h = newh(S, "what_means:definition", "question", "definition", "define")
            use(h, wh.c1, wh.c2); if aux_ok then use(h, wh.nxt) end; use_np(h, np)
            local consumed, k = 0, np.nxt
            while C(S, k) and consumed < n do consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1); h.used[k] = true; k = k + 1 end
            h.concept = np
            h.requires_evidence = true
            addf(h, "definition_question", 0.9, "'what does X mean' asks for the meaning of X")
            F.mark_pron(h, np)
            out[#out + 1] = h
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- recall questions about the conversation itself
-- "What did we decide about the inventory service?"  "Why did we pick that for billing?"  "Remind me what I said about X."
local RECALL_PREP = U.set({ "about", "on", "regarding", "for", "with", "to", "over", "around", "concerning" })
function F.recall(S, out)
  local lex = S.lex
  local c0 = C(S, S.first)
  if not c0 then return end
  local k = S.first
  local intro = lex:cue_at("recall_intro", S.units, c0.u1)
  local intro_used = {}
  if intro then
    local consumed = 0
    while C(S, k) and consumed < intro do consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1); intro_used[#intro_used + 1] = k; k = k + 1 end
  end
  for _, wh in ipairs(P.parse_wh(S, k)) do
    local nk = wh.nxt
    local aux = C(S, nk)
    local has_aux = aux and aux.single and (cat(aux, "aux_do") or cat(aux, "aux_have")) and not aux.masked
    if has_aux then nk = nk + 1 end
    local sc = C(S, nk)
    local pf = sc and sc.single and sc.unit.form
    if pf == "we" or pf == "i" or pf == "you" then
      for _, vp in ipairs(P.parse_vp(S, nk + 1, { aux_hint = has_aux and "do" or nil })) do
        local v = lex.verbs[vp.lemma]
        -- the construction itself (wh + do-support + first/second person subject) marks a question about the conversation; the verb only has to
        -- be one that people use about what was said, chosen, proposed or planned
        if v and (v.act == "discourse" or v.act == "inform" or v.act == "focus" or v.act == "constraint" or v.act == "task") then
          local topic, object
          local ek = vp.nxt
          local ec = C(S, ek)
          if ec and ec.single and RECALL_PREP[ec.unit.form] and not ec.masked then
            for _, np in ipairs(P.parse_np(S, ek + 1)) do topic = np break end
            if topic then ek = topic.nxt end
          else
            for _, np in ipairs(P.parse_np(S, ek)) do object = np break end
            if object then
              ek = object.nxt
              local pc = C(S, ek)
              if pc and pc.single and RECALL_PREP[pc.unit.form] and not pc.masked then
                for _, np in ipairs(P.parse_np(S, ek + 1)) do topic = np break end
                if topic then ek = topic.nxt end
              end
            end
          end
          local h = newh(S, "recall:wh", "question", "conversation_recall", "recall")
          for _, u in ipairs(intro_used) do h.used[u] = true end
          use(h, wh.c1, wh.c2)
          if has_aux then use(h, wh.nxt) end
          use(h, nk); for i = vp.c1, vp.c2 do h.used[i] = true end
          if wh.np then F.use_np(h, wh.np) end
          if topic then use_np(h, topic) end
          if object then use_np(h, object) end
          h.recall = { verb = vp.lemma, wh = wh.wh, participant = pf, topic = topic or object, object = object }
          h.subject = topic or object
          h.requires_context = true
          if h.subject then F.mark_pron(h, h.subject) end
          addf(h, "recall_construction", 0.9, "wh-question about what the participants said or decided ('" .. pf .. " " .. vp.lemma .. "')")
          out[#out + 1] = h
        end
      end
    end
  end
end

-- "What was my first question?"  "What was the last thing I asked?"  "What was my previous request?": a question about the user's own earlier turns
local TURN_NOUNS = U.set({ "question", "request", "message", "query", "prompt", "instruction", "command", "remark", "comment", "statement" })
function F.recall_turn(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.wh == "what" and not wh.np then
      local bc = C(S, wh.nxt)
      if bc and bc.single and not bc.masked and (cat(bc, "aux_be") or cat(bc, "clitic_s")) and not barrier(bc) then
        for _, np in ipairs(P.parse_np(S, wh.nxt + 1, { no_of = true })) do
          local hn = np.head and np.head.single and np.head.unit.form
          if hn and TURN_NOUNS[hn] and (np.poss_det == "my" or np.poss_det == "our" or np.det == "the") then
            local h = newh(S, "recall:turn", "question", "conversation_recall", "recall")
            use(h, wh.c1, wh.c2); use(h, wh.nxt); use_np(h, np)
            h.recall = { verb = "ask", wh = "what", participant = "i", topic = nil, ordinal = np.ordinal }
            h.requires_context = true
            addf(h, "recall_construction", 0.9, "'what was my <ordinal> " .. hn .. "' asks about the user's own earlier turns")
            out[#out + 1] = h
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- basis clause
-- "..., considering the correction I made earlier"  /  "... given the revised budget"  /  "... taking X into account"
-- The NP is an input the request must respect; it is kept as a (possibly context-dependent) argument, never dropped.
function F.attach_basis(S, h)
  if h.basis ~= nil or not h.speech_act or h.speech_act == "statement" then return end
  local lex = S.lex
  for k = S.first, S.last do
    local c = C(S, k)
    if c and not c.masked and not h.used[k] and c.single and lex:cue_at("basis", S.units, c.u1) == 1 then
      local form = c.unit.form
      local nxt = C(S, k + 1)
      if not (form == "given" and nxt and nxt.single and nxt.unit.form == "that") then
        for _, np in ipairs(P.parse_np(S, k + 1)) do
          local c1, c2 = C(S, np.nxt), C(S, np.nxt + 1)
          local closed = c1 and c2 and c1.single and c2.single and c1.unit.form == "into" and c2.unit.form == "account"
          if form ~= "taking" or closed then
            h.basis = { cue = form, np = np }
            h.used[k] = true; use_np(h, np)
            if closed then h.used[np.nxt] = true; h.used[np.nxt + 1] = true end
            addf(h, "basis_clause", 0.3, "'" .. form .. "' introduces a basis the request must take into account")
            F.mark_pron(h, np)
            return
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- statements, focus, instructions, corrections
local function resource_slot(S, np)
  if not np or not np.head then return nil end
  local canon = S.lex:resource(np.head.form)
  if not canon and np.head.single then canon = S.lex:resource(np.head.unit.form) end
  return canon
end

-- "version 3.2", "the file sales_q3_final.csv", "figure 12": a number / identifier / file name inside a resource phrase is its value
function F.literal_value(S, np)
  if not np then return nil end
  for ci = np.c1, np.c2 do
    local c = C(S, ci)
    if c and c.single and not c.masked and c ~= np.head then
      local u = c.unit
      if c.literal or u.kind == "ident" or (u.kind == "number" and u.numval ~= nil and not c.temporal and not u.ordinal) then return { word = c.text, label = c.text } end
    end
  end
  local hc = np.head
  if hc and hc.single then
    local u = hc.unit
    if hc.literal or u.kind == "ident" then return { word = hc.text, label = hc.text } end
    if u.kind == "number" and u.numval ~= nil and not hc.temporal and not u.ordinal then return { word = hc.text, label = hc.text } end
  end
  return nil
end

function F.instruction(S, out)
  local lex = S.lex
  local k = S.first
  local c = C(S, k)
  if not c or c.masked then return end
  -- correction / persistence cues at the start: "Actually, ...", "No, wait, ...", "From now on ..."
  local corr_n = lex:cue_at("correction", S.units, c.u1)
  local persist_n = lex:cue_at("persist", S.units, c.u1)
  local skipped = {}
  local correction, persist = false, false
  local function skip_units(n)
    local consumed = 0
    while C(S, k) and consumed < n do
      consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1)
      skipped[#skipped + 1] = k; k = k + 1
    end
  end
  if corr_n then
    correction = true; skip_units(corr_n)
    -- several markers may open one sentence: "Wait, no, I meant ...", "Correction: I meant ...", "Sorry, quick fix: ..."
    for _ = 1, 3 do
      local cn = C(S, k)
      local n2 = cn and not cn.masked and lex:cue_at("correction", S.units, cn.u1)
      if n2 then skip_units(n2)
      elseif cn and cn.single and not cn.masked and (cn.unit.form == "no" or cn.unit.form == "yes" or cn.unit.form == "okay" or cn.unit.form == "ok" or cn.unit.form == "well" or cn.unit.form == "so") then skipped[#skipped + 1] = k; k = k + 1
      else break end
    end
  end
  c = C(S, k)
  if c and lex:cue_at("persist", S.units, c.u1) then persist = true; skip_units(lex:cue_at("persist", S.units, c.u1)) end
  -- a correction / retraction clause anywhere before the instruction ("I got that wrong before, so please switch ...", "Disregard what I said, and go with ...")
  local preamble_to
  if not correction then
    for kk = S.first, S.last do
      local ck = C(S, kk)
      if ck and not ck.masked and (lex:cue_at("correction", S.units, ck.u1) or lex:cue_at("revoke", S.units, ck.u1)) then correction = true; preamble_to = kk break end
    end
  end
  c = C(S, k)
  -- temporal persist marker already lexed as a temporal chunk ("From now on", "Going forward")
  while c and c.temporal and (c.temporal.kind == "persist" or c.temporal.persist) do persist = true; skipped[#skipped + 1] = k; k = k + 1; c = C(S, k) end
  c = C(S, k)
  if not c or c.masked then return end
  -- a persistence marker anywhere in the sentence ("Use the 2025 dataset from now on.") makes the instruction standing
  for _, ch in ipairs(S.chunks) do
    if ch.temporal and (ch.temporal.kind == "persist" or ch.temporal.persist) then persist = true end
  end
  local REPLACE_VERBS = U.set({ "replace", "swap", "substitute", "change", "exchange" })
  local PARTICLE_EXCLUDERS = U.set({ "keep", "leave", "take", "filter", "screen", "weed", "cut", "strike", "rule", "block", "hide", "push", "sort" })
  -- one clause: [please|just|then|also]* VERB [to|with|over to] NP        (also "replace THAT with NP")
  local function try_clause(k0, prefix_used, allow_ing)
    local kk = k0
    local pre = {}
    while C(S, kk) and C(S, kk).single and not C(S, kk).masked and (cat(C(S, kk), "polite") or cat(C(S, kk), "adv") or (cat(C(S, kk), "conj") and kk > k0 - 1 and C(S, kk).unit.form ~= "if")) do
      pre[#pre + 1] = kk; kk = kk + 1
    end
    local cv = C(S, kk)
    if not (cv and cv.single and not cv.masked) then return end
    local analyses = P.verb_analyses(S, cv)
    -- "Actually, MAKE THAT the 2020 figures": a replacement phrased with "make that / it / this"
    local make_pron
    if cv.unit.form == "make" or cv.unit.form == "turn" then
      local pr = C(S, kk + 1)
      if pr and pr.single and not pr.masked and not barrier(pr) and (pr.unit.form == "that" or pr.unit.form == "it" or pr.unit.form == "this") then
        analyses = { { lemma = "make", form = "base", act = "constraint", entries = {} } }
        make_pron = kk + 1
      end
    end
    -- "Going forward, ONLY COUNT the audited figures": with "only", a retrieval verb restricts what is used
    local only_pre = false
    for _, pk in ipairs(pre) do if C(S, pk).unit.form == "only" then only_pre = true end end
    for _, a in ipairs(analyses) do
      local act_ok = a.act == "constraint" or a.act == "exclude" or a.act == "include" or (only_pre and (a.act == "retrieve" or a.act == "inform"))
      if (a.form == "base" or (allow_ing and a.form == "ing")) and act_ok then
        local nk = kk + 1
        local fill = {}
        if make_pron then fill[#fill + 1] = make_pron; nk = make_pron + 1 end
        local nc = C(S, nk)
        -- "switch to X" / "go with X" / "stick with X" / "switch over to X"
        if nc and nc.single and (nc.unit.form == "over") and C(S, nk + 1) and C(S, nk + 1).unit.form == "to" then fill[#fill + 1] = nk; nk = nk + 1; nc = C(S, nk) end
        if nc and nc.single and (nc.unit.form == "to" or nc.unit.form == "with" or nc.unit.form == "on" or nc.unit.form == "from") then fill[#fill + 1] = nk; nk = nk + 1 end
        local tries = {}
        if REPLACE_VERBS[a.lemma] then
          -- "replace THAT with the 2021 dataset": the replacement is the second noun phrase
          for _, np1 in ipairs(P.parse_np(S, nk)) do
            local wc = C(S, np1.nxt)
            if wc and wc.single and (wc.unit.form == "with" or wc.unit.form == "by") then
              for _, np2 in ipairs(P.parse_np(S, np1.nxt + 1)) do tries[#tries + 1] = { np = np2, extra = { np1 = np1, joiner = np1.nxt } } end
            end
          end
        end
        if #tries == 0 then for _, np in ipairs(P.parse_np(S, nk)) do tries[#tries + 1] = { np = np } end end
        for _, tr in ipairs(tries) do
          local np = tr.np
          if np.head_kind == "pronoun" then
            -- "I meant the 2024 dataset, so please switch to THAT": the pronoun stands for the resource named earlier in the same sentence
            for k2 = S.first, kk - 1 do
              local found
              for _, np2 in ipairs(P.parse_np(S, k2)) do
                if resource_slot(S, np2) and np2.nxt <= kk then found = np2 break end
              end
              if found then tr.antecedent_np = found; break end
            end
          end
          local act_eff = a.act
          if only_pre and (a.act == "retrieve" or a.act == "inform") then
            act_eff = "constraint"
            if not resource_slot(S, tr.antecedent_np or np) then goto next_try end   -- "Only list companies ..." is a request, not a restriction of a resource
          end
          local ptc = C(S, np.nxt)
          -- "swap the earlier dataset OUT": the object is what is being removed, not the new value
          if REPLACE_VERBS[a.lemma] and ptc and ptc.single and not ptc.masked and (ptc.unit.form == "out" or ptc.unit.form == "off") then goto next_try end
          -- "KEEP hospitals OUT of ...", "LEAVE X OUT", "FILTER X OUT": a particle after the object turns the verb into an exclusion
          if PARTICLE_EXCLUDERS[a.lemma] and ptc and ptc.single and not ptc.masked and (ptc.unit.form == "out" or ptc.unit.form == "off" or ptc.unit.form == "away") then
            act_eff = "exclude"
            tr.particle = np.nxt
          end
          local h = newh(S, "instruction:" .. act_eff, "instruction", "instruction_update", "instruct")
          if tr.particle then h.used[tr.particle] = true end
          for _, s_ in ipairs(skipped) do h.used[s_] = true end
          for _, s_ in ipairs(prefix_used or {}) do h.used[s_] = true end
          -- a retraction / correction clause that precedes the instruction is explained by the correction marker itself
          if preamble_to and kk > preamble_to then for i2 = S.first, kk - 1 do if i2 ~= kk then h.used[i2] = true end end end
          for _, s_ in ipairs(pre) do h.used[s_] = true end
          use(h, kk); for _, f in ipairs(fill) do h.used[f] = true end; use_np(h, np)
          if tr.extra then use_np(h, tr.extra.np1); h.used[tr.extra.joiner] = true end
          local vnp = tr.antecedent_np or np
          if tr.antecedent_np then use_np(h, vnp) end
          local slot = resource_slot(S, vnp)
          local value
          if vnp.temporal_mod then value = { year = vnp.temporal_mod.year, label = vnp.temporal_mod.text, expr = vnp.temporal_mod }
          else
            for _, m in ipairs(vnp.mods) do if m.kind == "mod" or m.kind == "ordinal" then value = value or { word = m.form, label = m.text } end end
          end
          value = value or F.literal_value(S, vnp)
          h.instruction = { verb = a.lemma, act = act_eff, np = vnp, slot = slot, value = value, correction = correction, persist = persist }
          if act_eff == "exclude" then h.polarity = "negative" end
          h.correction, h.persist = correction, persist
          if slot then addf(h, "resource_slot", 0.5, "instruction targets the '" .. slot .. "' slot") end
          if correction then addf(h, "correction_cue", 0.4, "explicit correction marker") end
          if persist then addf(h, "persist_cue", 0.3, "applies from now on") end
          F.mark_pron(h, np)
          out[#out + 1] = h
          ::next_try::
        end
      end
    end
  end
  try_clause(k, nil, S.wrapper and S.wrapper.progressive)
  -- later clauses: "..., and go with the 2022 dataset", "..., so please switch over to the 2021 dataset", "Sorry: use the 2020 dataset"
  for kk = k + 1, S.last do
    local ck = C(S, kk)
    if ck and not ck.masked then
      local pc = C(S, kk - 1)
      local after_conj = pc and pc.single and cat(pc, "conj") and not pc.masked
      if (ck.pre and (ck.pre:find("comma") or ck.pre:find("colon") or ck.pre:find("semi"))) or after_conj then
        if not (correction and false) then try_clause(kk, nil, false) end
      end
    end
  end
  -- "The 2023 dataset is the one I actually want you to use from now on." / "... is the one to use": a resource named as THE ONE to use
  if #out == 0 then
    for _, np in ipairs(P.parse_np(S, k)) do
      local slot = resource_slot(S, np)
      local cb = C(S, np.nxt)
      if slot and cb and cb.single and cat(cb, "aux_be") and not cb.masked then
        local one_k
        for j = np.nxt + 1, math.min(S.last, np.nxt + 4) do
          local cj = C(S, j)
          if cj and cj.single and (cj.unit.form == "one") then one_k = j break end
        end
        if one_k then
          for j = one_k + 1, S.last do
            local cj = C(S, j)
            local verb
            if cj and cj.single and not cj.masked then
              for _, a in ipairs(P.verb_analyses(S, cj)) do
                if a.form == "base" and (a.act == "constraint") then verb = a end
              end
            end
            if verb then
              local h = newh(S, "instruction:the_one_to_use", "instruction", "instruction_update", "instruct")
              for _, s_ in ipairs(skipped) do h.used[s_] = true end
              use_np(h, np); for i = np.nxt, S.last do if not (C(S, i).temporal and not (C(S, i).temporal.persist or C(S, i).temporal.kind == "persist")) then h.used[i] = true end end
              local value
              if np.temporal_mod then value = { year = np.temporal_mod.year, label = np.temporal_mod.text, expr = np.temporal_mod }
              else for _, m in ipairs(np.mods) do if m.kind == "mod" or m.kind == "ordinal" then value = value or { word = m.form, label = m.text } end end end
              h.instruction = { verb = verb.lemma, act = "constraint", np = np, slot = slot, value = value, correction = correction, persist = persist }
              h.correction, h.persist = correction, persist
              addf(h, "resource_slot", 0.5, "the sentence names a '" .. slot .. "' as the one to use")
              if correction then addf(h, "correction_cue", 0.4, "explicit correction marker") end
              if persist then addf(h, "persist_cue", 0.3, "applies from now on") end
              out[#out + 1] = h
              break
            end
          end
        end
      end
    end
  end
  -- A resource value stated as a fact about the resource, not as an imperative:
  --   "The 2025 dataset replaces the one I named before."        (the subject is the NEW value)
  --   "The right dataset is 2026."  "The dataset should be 2026 not what I said before."  "The one you should be using from now on is 2026."
  do
    local REPLACERS = U.set({ "replace", "replaces", "replacing", "supersede", "supersedes", "override", "overrides", "overrule", "overrules", "supplant", "supplants", "trump", "trumps" })
    local CORRECT_ADJ = U.set({ "right", "correct", "proper", "actual", "real", "true", "intended", "new", "updated", "current" })
    local function value_of_np(np)
      if np.temporal_mod then return { year = np.temporal_mod.year, label = np.temporal_mod.text, expr = np.temporal_mod } end
      if np.head_kind == "temporal" and np.head.temporal then return { year = np.head.temporal.year, label = np.head.temporal.text or P.span_text(S, np) } end
      if np.head_kind == "number" then return { word = P.span_text(S, np), label = P.span_text(S, np) } end
      if np.count then return { word = tostring(np.count), label = tostring(np.count) } end
      return nil
    end
    local any_resource
    for kk = S.first, S.last do
      local ck = C(S, kk)
      if ck and ck.single and S.lex:resource(ck.unit.form) then any_resource = S.lex:resource(ck.unit.form) end
    end
    -- candidate clause starts: the sentence start and every position after a comma / semicolon / colon / conjunction
    local starts = { k }
    for kk = k + 1, S.last do
      local ck, pc = C(S, kk), C(S, kk - 1)
      if ck and not ck.masked and ((ck.pre and (ck.pre:find("comma") or ck.pre:find("semi") or ck.pre:find("colon"))) or (pc and pc.single and cat(pc, "conj") and not pc.masked)) then starts[#starts + 1] = kk end
    end
    local np_list = {}
    for _, st in ipairs(starts) do for _, np in ipairs(P.parse_np(S, st)) do np_list[#np_list + 1] = np end end
    for _, np in ipairs(np_list) do
      local slot = resource_slot(S, np) or ((np.head and np.head.single and np.head.unit.form == "one") and any_resource) or nil
      local cb = C(S, np.nxt)
      -- (a) "the 2025 dataset replaces the one I named before"
      if slot and cb and cb.single and not cb.masked and REPLACERS[cb.unit.form] then
        local val = value_of_np(np)
        if val then
          local h = newh(S, "instruction:subject_replaces", "instruction", "instruction_update", "instruct")
          for _, s_ in ipairs(skipped) do h.used[s_] = true end
          use_np(h, np); h.used[np.nxt] = true
          for i = np.nxt + 1, S.last do if not C(S, i).masked then h.used[i] = true end end
          h.instruction = { verb = "replace", act = "constraint", np = np, slot = slot, value = val, correction = true, persist = persist }
          h.correction, h.persist = true, persist
          addf(h, "resource_slot", 0.5, "the sentence says which '" .. slot .. "' replaces the earlier one")
          addf(h, "replacement_statement", 0.5, "'" .. cb.unit.form .. "' marks the subject as the new value")
          out[#out + 1] = h
        end
      end
      -- (b) "the right dataset is 2026", "the dataset should be 2026 not what I said before", "the one you should be using from now on is 2026"
      if slot then
        local bk = np.nxt
        -- skip a relative clause after "the one": "... you should be using from now on"
        if np.head and np.head.single and np.head.unit.form == "one" then
          local jj = bk
          while C(S, jj) and not (C(S, jj).single and cat(C(S, jj), "aux_be") and C(S, jj + 1) and value_of_np((P.parse_np(S, jj + 1))[1] or {}) ) and jj < S.last do jj = jj + 1 end
          bk = jj
        end
        local bc = C(S, bk)
        -- optional modal: "should be", "must be", "needs to be", "will be"
        local mk = bk
        while C(S, mk) and C(S, mk).single and not C(S, mk).masked and (cat(C(S, mk), "modal") or cat(C(S, mk), "adv") or C(S, mk).unit.form == "to" or C(S, mk).unit.form == "need" or C(S, mk).unit.form == "needs") and mk < S.last do mk = mk + 1 end
        local bc2 = C(S, mk)
        if bc2 and bc2.single and not bc2.masked and cat(bc2, "aux_be") then
          for _, vnp in ipairs(P.parse_np(S, mk + 1)) do
            local val = value_of_np(vnp)
            if val then
              local adj_correct = false
              for _, md in ipairs(np.mods) do if md.form and CORRECT_ADJ[md.form:lower()] then adj_correct = true end end
              local h = newh(S, "instruction:resource_is_value", "instruction", "instruction_update", "instruct")
              for _, s_ in ipairs(skipped) do h.used[s_] = true end
              use_np(h, np); use_np(h, vnp)
              for i = np.nxt, vnp.c1 do h.used[i] = true end
              for i = vnp.nxt, S.last do if not C(S, i).masked then h.used[i] = true end end
              h.instruction = { verb = "be", act = "constraint", np = np, slot = slot, value = val, correction = correction or adj_correct, persist = persist }
              h.correction, h.persist = correction or adj_correct, persist
              addf(h, "resource_slot", 0.5, "the sentence states which '" .. slot .. "' is the right one")
              addf(h, "resource_is_value", 0.5, "a resource noun is equated with a value")
              out[#out + 1] = h
              break
            end
          end
        end
      end
    end
  end
  -- bare correction followed by a plain fragment: "Actually, the 2025 one."  handled as statement with correction flag
  if correction and #out == 0 then
    local nk = k
    local mem = S.ctx and S.ctx.discourse and S.ctx.discourse.mem
    for _, np in ipairs(P.parse_np(S, nk)) do
      local h = newh(S, "instruction:correction_fragment", "correction", "correction", "instruct")
      for _, s in ipairs(skipped) do h.used[s] = true end
      use_np(h, np)
      local slot, value = resource_slot(S, np), nil
      -- a bare value with no resource noun ("Sorry, I meant 2023.", "No, the 2025 one."): it replaces the value of the standing instruction it corrects
      if not slot and np.nxt > S.last and mem and mem.recent_slot then
        local tm = np.temporal_mod or (np.head and np.head.temporal and np.head.temporal.kind == "year" and np.head.temporal) or nil
        if tm and tm.year then value = { year = tm.year, label = tm.text or (np.head and np.head.text), expr = tm }
        else
          value = F.literal_value(S, np)
          -- a bare four-digit number is a year
          local y = value and value.word and value.word:match("^(%d%d%d%d)$")
          if y and tonumber(y) >= 1000 and tonumber(y) <= 2999 then value = { year = tonumber(y), label = value.label } end
        end
        local rs = value and mem:recent_slot(value.year and "year" or "word")
        if rs then
          slot = rs
          h.speech_act, h.intent = "instruction", "instruction_update"
          addf(h, "slot_from_memory", 0.6, "a bare corrected value replaces the value of the standing '" .. rs .. "' instruction")
        else value = nil end
      end
      h.instruction = { verb = nil, np = np, slot = slot, value = value, correction = true, persist = persist }
      h.correction = true
      F.mark_pron(h, np)
      out[#out + 1] = h
      break
    end
  end
end

-- Exclusions and prohibitions that are NOT plain imperatives (F.instruction handles "Leave out X.", "Do not include X.", "Keep X out of ..."):
--   passive / deontic   "Universities need to be excluded."  "Reposts should be left out."  "X are not to be included."  "make sure X are left out of the list"
--   modal active        "The results should exclude X."  "Results must not contain any X."  "My brief says to exclude X."
--   progressive         "We are ruling out X for this exercise."  "I'm leaving out X."
--   wishes              "I don't want any X in the results."  "I'd rather not see any X."  "I'd really like X excluded."  "I'd rather you skipped X."
--   states of affairs   "Anything involving X is off limits."  "No X in the output, please."
--   a pronoun object    "If you come across any X, just drop them from the results."
-- Each yields an instruction_update hypothesis shaped like the imperative ones, so memory treats it identically (a standing prohibition).
local DEONTIC_WORDS = U.set({ "should", "must", "shall", "ought", "need", "needs", "needed", "supposed", "required", "expected" })
local DIRECTIVE_WORDS = U.set({ "please", "ensure", "sure", "remember", "mind", "must", "should", "shall", "ought", "need", "needs", "needed", "want", "wants", "wanted", "prefer",
  "rather", "always", "never", "require", "required", "requirement", "rule", "insist", "important", "essential", "crucial", "necessary", "wish" })
local CHAIN_WORDS = U.set({ "to", "get", "gets", "got", "be", "been", "being", "is", "are", "was", "were", "am", "do", "does", "did", "rather", "just", "really", "please", "kindly",
  "also", "then", "still", "actually", "simply", "now", "not", "never", "n't", "should", "must", "shall", "ought", "need", "needs", "needed", "supposed", "required", "expected",
  "have", "has", "had", "will", "would", "can", "could", "may", "might", "going", "'d", "'ll", "'re", "'m", "'s", "'ve", "gotta", "always", "definitely", "absolutely", "all" })
local OFF_LIMITS = { { "off", "limits" }, { "off", "the", "table" }, { "out", "of", "scope" }, { "out", "of", "bounds" }, { "banned" }, { "forbidden" }, { "prohibited" },
  { "taboo" }, { "unwanted" }, { "not", "wanted" }, { "irrelevant" }, { "not", "relevant" }, { "excluded" }, { "out" }, { "off", "limit" } }
local INDEF_LINK = U.set({ "involving", "with", "about", "from", "containing", "concerning", "featuring", "mentioning", "regarding", "on", "of", "by", "related", "relating" })
local OUTPUT_NOUNS = U.set({ "results", "result", "output", "outputs", "list", "lists", "answer", "answers", "response", "responses", "report", "summary", "table", "search", "findings" })
local WISH_VERBS = U.set({ "want", "wants", "wanted", "need", "needs", "needed", "like", "likes", "prefer", "prefers", "wish", "expect", "require", "requires", "insist" })
local PERCEPTION_VERBS = U.set({ "see", "have", "get", "receive", "hear", "find", "want", "need", "like", "include", "use", "show", "contain", "list", "return", "mention", "feature",
  "display", "give", "output", "surface", "produce", "present", "report", "read", "spot", "notice", "add", "incorporate" })
local INSTRUCT_VERBS = U.set({ "says", "said", "say", "asks", "asked", "ask", "tells", "told", "tell", "requires", "required", "instructs", "instructed", "decided", "agreed", "wants", "wanted",
  "needs", "needed", "want", "need", "prefer", "prefers", "wish", "plan", "plans", "idea", "goal", "aim" })

function F.exclusion_clause(S, out)
  if S.sentence and S.sentence.question_mark then return end
  -- the constraint-segment masks (set because exclusion cue words such as "exclude" / "rule out" are in the sentence) hide exactly the words this frame reads:
  -- lift them while scanning, restore them afterwards
  local saved
  for i, ch in ipairs(S.chunks) do if ch.masked then saved = saved or {}; saved[i] = ch.mask_kind or true end end
  if saved then
    for i in pairs(saved) do S.chunks[i].masked = nil end
    S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
  end
  local ok, err = pcall(F.exclusion_clause_scan, S, out)
  if saved then
    for i, kind in pairs(saved) do S.chunks[i].masked = true; S.chunks[i].mask_kind = kind ~= true and kind or nil end
    S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
  end
  if not ok then error(err, 0) end
end

function F.exclusion_clause_scan(S, out)
  local function form_of(c) return c and c.single and c.unit and c.unit.form or nil end
  local directive, persist = false, false
  for k = S.first, S.last do
    local c = C(S, k)
    if c and not c.masked then
      local f = form_of(c)
      if f and DIRECTIVE_WORDS[f] then directive = true end
      if c.temporal and (c.temporal.kind == "persist" or c.temporal.persist) then directive, persist = true, true end
    end
  end
  -- "Someone asked whether universities should be excluded": a REPORTED question or a third party's debate is not an instruction to the system
  local QUESTION_REPORT = U.set({ "whether", "asked", "asks", "asking", "wondered", "wonders", "wondering", "debated", "debating", "argued", "arguing", "questioned", "discussed", "discussing", "unclear", "unsure" })
  local reported_question_at = {}
  do
    local seen_q = false
    for k = S.first, S.last do
      local c = C(S, k)
      local f = c and c.single and c.unit and c.unit.form
      if f and QUESTION_REPORT[f] then seen_q = true end
      if f == "if" and k > S.first then seen_q = true end
      reported_question_at[k] = seen_q
    end
  end
  local seen = {}
  local function emit(frame, np, used_from, used_to, verb, more_used)
    local key = np.c1 .. ":" .. np.c2 .. ":" .. frame
    if seen[key] then return end
    -- the construction must not sit inside a reported question / conditional (the imperative-with-pronoun case below is the one place "if" is expected)
    if frame ~= "pronoun_object" and reported_question_at[used_from] then return end
    seen[key] = true
    local h = newh(S, "instruction:" .. frame, "instruction", "instruction_update", "instruct")
    for i = used_from, used_to do if C(S, i) then h.used[i] = true end end
    for _, u in ipairs(more_used or {}) do h.used[u] = true end
    use_np(h, np)
    h.instruction = { verb = verb, act = "exclude", np = np, correction = false, persist = persist }
    h.polarity = "negative"
    h.persist = persist
    addf(h, "exclusion_clause", 0.9, "an exclusion is stated (" .. frame .. ")")
    if directive then addf(h, "directive_context", 0.2, "the sentence carries a directive marker") end
    if persist then addf(h, "persist_cue", 0.3, "applies from now on") end
    F.mark_pron(h, np)
    out[#out + 1] = h
  end
  -- the NP that ends right before chunk `e` (longest first)
  local function np_ending_before(e)
    for i = S.first, e - 1 do
      for _, np in ipairs(P.parse_np(S, i)) do if np.nxt == e then return np end end
    end
  end
  -- "any X", "all X": the quantifier is part of the determiner; the target is the NP after it
  for kv = S.first, S.last do
    local c = C(S, kv)
    if c and not c.masked and (c.single or c.kind == "mwe") then
      for _, a in ipairs(P.verb_analyses(S, c)) do
        local is_excl = a.act == "exclude"
        local is_percep = a.act == "include" or PERCEPTION_VERBS[a.lemma] == true
        if is_excl or is_percep then
          -- the verb group in front of the verb
          local j = kv - 1
          local forms, has_neg, has_be, deontic, rather = {}, false, false, false, false
          while j >= S.first and C(S, j) and C(S, j).single and not C(S, j).masked and not barrier(C(S, j)) and CHAIN_WORDS[form_of(C(S, j))] and kv - j <= 6 do
            local f = form_of(C(S, j))
            if f == "do" and forms[1] == "do" then break end      -- "whatever you DO don't include X": two do's are two clauses
            table.insert(forms, 1, f)
            if P.is_neg(C(S, j)) or f == "never" then has_neg = true end
            if f == "be" or f == "been" or f == "being" or f == "is" or f == "are" or f == "was" or f == "were" or f == "am" or f == "get" or f == "gets" or f == "got" or f == "'re" or f == "'m" then has_be = true end
            if DEONTIC_WORDS[f] then deontic = true end
            if f == "rather" then rather = true end
            j = j - 1
          end
          local chain_first = j + 1
          for i, f in ipairs(forms) do
            if f == "to" and i > 1 and (forms[i - 1] == "have" or forms[i - 1] == "has" or forms[i - 1] == "had" or forms[i - 1] == "going" or forms[i - 1] == "ought") then deontic = true end
          end
          local subj_form = j >= S.first and form_of(C(S, j)) or nil
          local subj_pron = subj_form == "we" or subj_form == "i" or subj_form == "you"
          local after, verb_end = kv + 1, kv
          local nc = C(S, after)
          if is_excl and c.kind ~= "mwe" and nc and nc.single and not nc.masked and not barrier(nc) and (nc.unit.form == "out" or nc.unit.form == "off") then after = after + 1; verb_end = after - 1 end
          local to_before = forms[#forms] == "to"
          local imperative_chain = true       -- nothing but do / not / please-like words in front: a plain imperative, F.instruction's business
          for _, f in ipairs(forms) do
            if not (f == "do" or f == "does" or f == "did" or f == "not" or f == "n't" or f == "never" or f == "please" or f == "just" or f == "kindly" or f == "also" or f == "then" or f == "always" or f == "really" or f == "definitely" or f == "absolutely" or f == "now") then imperative_chain = false end
          end
          if subj_pron then imperative_chain = false end

          -- (1) passive: NP be/get ... excluded
          if is_excl and (a.form == "pp" or a.form == "past") and has_be and not has_neg then
            local np = np_ending_before(chain_first)
            if np and (deontic or directive or rather or persist) then emit("passive", np, np.c1, verb_end) end
          end
          -- (1b) a negated passive of an include-like verb: "X are not to be included", "X should not be shown", "X must not appear"
          if is_percep and not is_excl and (a.form == "pp" or a.form == "past") and has_be and has_neg and (deontic or to_before or directive) then
            local np = np_ending_before(chain_first)
            if np then emit("negated_passive", np, np.c1, verb_end) end
          end
          -- (2) modal / infinitive active: "the results should exclude X", "my brief says to exclude X"
          if is_excl and a.form == "base" and not has_neg and not imperative_chain then
            local pv = j >= S.first and C(S, j)
            local instruct_prev = pv and pv.single and INSTRUCT_VERBS[form_of(pv)] or false
            if deontic or (to_before and (instruct_prev or directive)) then
              -- "My brief says to exclude X": the introducing clause is part of the directive
              for _, np in ipairs(P.parse_np(S, after)) do emit("modal", np, instruct_prev and S.first or chain_first, np.c2, a.lemma); break end
            end
          end
          -- (3) progressive with a first/second-person subject: "We are ruling out X"
          if is_excl and a.form == "ing" and has_be and subj_pron and not has_neg then
            for _, np in ipairs(P.parse_np(S, after)) do emit("progressive", np, j, np.c2, a.lemma); break end
          end
          -- (4) subjunctive wish: "I'd rather you skipped X"
          if is_excl and (a.form == "past" or a.form == "base") and subj_form == "you" then
            local before1, before2 = form_of(C(S, j - 1)), form_of(C(S, j - 2))
            if before1 == "rather" or before2 == "rather" or before1 == "prefer" or before1 == "wish" then
              for _, np in ipairs(P.parse_np(S, after)) do emit("subjunctive", np, j - 1, np.c2, a.lemma); break end
            end
          end
          -- (5) negated include-like verbs: "Results must not contain any X", "I don't want any X", "I'd rather not see any X"
          if is_percep and not is_excl and a.form == "base" and has_neg and not imperative_chain then
            if deontic or rather or (subj_pron and WISH_VERBS[a.lemma]) or (subj_pron and rather) then
              for _, np in ipairs(P.parse_np(S, after)) do emit("negated_wish", np, chain_first, np.c2, a.lemma); break end
            end
          end
          -- (5b) a negated imperative that is not the first clause: "..., but whatever you do don't include X"
          if is_percep and not is_excl and a.form == "base" and has_neg and imperative_chain and chain_first > S.first then
            for _, np in ipairs(P.parse_np(S, after)) do emit("negated_imperative", np, chain_first, np.c2, a.lemma); break end
          end
          -- (6) wish + participle: "I'd really like X excluded", "we need X left out"
          if WISH_VERBS[a.lemma] and not has_neg then
            for _, np in ipairs(P.parse_np(S, kv + 1)) do
              local k2 = np.nxt
              local tc, bc = C(S, k2), C(S, k2 + 1)
              if tc and tc.single and form_of(tc) == "to" and bc and bc.single and cat(bc, "aux_be") then k2 = k2 + 2 end
              local vc = C(S, k2)
              if vc and (vc.single or vc.kind == "mwe") and not vc.masked then
                for _, a2 in ipairs(P.verb_analyses(S, vc)) do
                  if a2.act == "exclude" and (a2.form == "pp" or a2.form == "past") then emit("wish_participle", np, kv, k2, a2.lemma) end
                end
              end
            end
          end
          -- (7) imperative exclusion whose object is a pronoun: "If you come across any X, just drop THEM from the results"
          if is_excl and a.form == "base" and imperative_chain and not has_neg then
            for _, np in ipairs(P.parse_np(S, after)) do
              if np.head_kind == "pronoun" and np.pron and (np.pron.form == "them" or np.pron.form == "those" or np.pron.form == "it") then
                -- the antecedent: the nearest earlier noun phrase (not a pronoun) before this clause
                local ante
                for e = kv - 1, S.first, -1 do
                  for i = e, S.first, -1 do
                    for _, np2 in ipairs(P.parse_np(S, i)) do
                      if np2.nxt == e + 1 and np2.head_kind ~= "pronoun" and (np2.head_kind == "typenoun" or np2.head_kind == "unknown" or np2.head_kind == "entity") then ante = ante or np2 end
                    end
                    if ante then break end
                  end
                  if ante then break end
                end
                if ante then emit("pronoun_object", ante, kv, np.c2, a.lemma, { np.c1 }) end
              end
              break
            end
          end
        end
      end
    end
  end
  -- (8) states of affairs: "Anything involving X is off limits."
  for kb = S.first + 1, S.last do
    local bc = C(S, kb)
    if bc and bc.single and not bc.masked and cat(bc, "aux_be") then
      for _, pat in ipairs(OFF_LIMITS) do
        local ok = true
        for i, w in ipairs(pat) do
          local ck = C(S, kb + i)
          if not (ck and ck.single and not ck.masked and form_of(ck) == w) then ok = false break end
        end
        if ok then
          local np = np_ending_before(kb)
          local target = np
          -- "anything involving X": the indefinite only introduces the target
          for i = S.first, kb - 1 do
            local ci = C(S, i)
            local fi = form_of(ci)
            if fi == "anything" or fi == "everything" or fi == "anyone" or fi == "all" then
              local link = C(S, i + 1)
              if link and link.single and INDEF_LINK[form_of(link)] then
                local k3 = i + 2
                if form_of(link) == "related" or form_of(link) == "relating" then if form_of(C(S, i + 2)) == "to" then k3 = i + 3 end end
                for _, np2 in ipairs(P.parse_np(S, k3)) do if np2.nxt == kb then target = np2; break end end
              end
            end
          end
          if target then emit("off_limits", target, target.c1, kb + #pat) end
          break
        end
      end
    end
  end
  -- (9) "No X in the output, please."
  do
    local c0 = C(S, S.first)
    if c0 and c0.single and not c0.masked and form_of(c0) == "no" then
      for _, np in ipairs(P.parse_np(S, S.first + 1)) do
        local pc = C(S, np.nxt)
        if pc and pc.single and cat(pc, "prep") and not pc.masked then
          for _, np2 in ipairs(P.parse_np(S, np.nxt + 1)) do
            if np2.head and OUTPUT_NOUNS[np2.head.single and np2.head.unit.form or ""] then emit("no_x_in_output", np, S.first, np2.c2) end
          end
        end
      end
    end
  end
end

-- "I'm researching Company A." / "Let's talk about X." / "We are looking at Y."
function F.focus(S, out)
  local lex = S.lex
  local c = C(S, S.first)
  if not c then return end
  local n = lex:cue_at("focus_intro", S.units, c.u1)
  if n then
    local k = S.first
    local consumed = 0
    while C(S, k) and consumed < n do consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1); k = k + 1 end
    for _, np in ipairs(P.parse_np(S, k)) do
      local h = newh(S, "statement:focus", "statement", "statement", "focus")
      for i = S.first, k - 1 do h.used[i] = true end
      use_np(h, np)
      h.focus = np
      F.mark_pron(h, np)
      addf(h, "focus_cue", 0.6, "explicit topic-focus statement")
      out[#out + 1] = h
    end
  end
end

-- declarative statements: NP + VP + NP  /  NP be NP  (used for memory and for extracting assertions)
function F.statement(S, out)
  local k = S.first
  for _, snp in ipairs(P.parse_np(S, k)) do
    for _, vp in ipairs(P.parse_vp(S, snp.nxt)) do
      local objs = P.parse_np(S, vp.nxt)
      local h = newh(S, "statement:svo", "statement", "statement", "assert")
      use_np(h, snp); for i = vp.c1, vp.c2 do h.used[i] = true end
      -- "Results must not contain X", "universities should be excluded": a deontic verb group is a directive, not an assertion of fact
      for i = snp.nxt, vp.c2 do
        local ci = C(S, i)
        local fi = ci and ci.single and ci.unit and ci.unit.form
        if fi == "must" or fi == "should" or fi == "shall" or fi == "ought" then addf(h, "deontic_not_assertion", -0.9, "a verb group with '" .. fi .. "' is a directive, not a statement of fact"); break end
      end
      h.statement = { subj = snp, vp = vp, lemma = vp.lemma, neg = vp.neg }
      if objs[1] then use_np(h, objs[1]); h.statement.obj = objs[1] end
      for _, e in ipairs(vp.analysis.entries) do
        local rel = S.lex:get_rel(e.rel)
        if rel and objs[1] and not rel.open then
          h.rel, h.rel_obj = rel.id, rel
          h.roles[vp.voice == "passive" and other(e.subj) or e.subj] = snp
          h.roles[vp.voice == "passive" and e.subj or other(e.subj)] = objs[1]
          addf(h, "relation_verb", 0.4, "statement over relation verb")
          break
        end
      end
      F.mark_pron(h, snp)
      out[#out + 1] = h
    end
  end
end

return F

end

package.preload["asi.nlu.frames3"] = function(...)
-- asi.nlu.frames3: question constructions beyond the wh-first core frames (extends asi.nlu.frames / frames2; every function adds competing hypotheses).
--   wh_relnoun_stranded  "Which continent is Kenya IN?"  "What industry does X operate in?"  "In which industry does X operate?"    the wh-noun names the relation
--   wh_pred_stranded     "What is France a member OF?"  "Which company is Jane the CEO OF?"  "What is Normandy part OF?"            a predicate noun names the relation
--   wh_adj_predicate     "Which language is OFFICIAL in Brazil?"                                                                 adjective + wh-noun is a relational noun phrase
--   quantity_q           "How many people live in X?"  "How much does X cost?"  "How much is X?"  "How many people work at X?"   counted nouns / quantity verbs
--   how_adj_relnoun      "How large is the workforce of X?"                                                                     degree adjective over a relational noun
--   list_relative        "Name the startups X has invested in."  "List the countries that use the euro."                         imperative + noun phrase with a relative clause
--   yes_no_support       "Does X have its headquarters in Y?"                                                                    support verb + possessed relational noun, yes/no
-- Roles are never guessed from proximity: they come from the relation lexicon (the role a noun denotes, the subject role of a verb) and from type fit.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local F = require("asi.nlu.frames2")

local cat = P.cat
local newh, addf, use_np = F.newh, F.addf, F.use_np
local set_lookup, use_wh, use_vp = F.set_lookup, F.use_wh, F.use_vp
local is_be, is_do, is_prep = F.is_be, F.is_do, F.is_prep
local relnp_options, wh_relnoun_agreement, mark_unresolved_pron = F.relnp_options, F.wh_relnoun_agreement, F.mark_pron

local function C(S, k) return S.chunks[k] end
local function barrier(c) return c ~= nil and c.pre ~= nil end
local function other(role) return role == "to" and "from" or "to" end
local function use(h, a, b) for i = a, b or a do h.used[i] = true end end

-- words that may stand between the subject and a stranded preposition without adding a relation ("What sector is X ACTIVE in?", "Which industry does X OPERATE in?")
local FILLERS = U.set({ "active", "based", "located", "situated", "found", "operating", "working", "present", "listed", "registered", "classified", "categorised",
  "categorized", "placed", "positioned", "specialised", "specialized", "operate", "operates", "work", "works", "lie", "lies", "sit", "sits", "exist", "exists",
  "compete", "competes", "trade", "trades", "belong", "belongs", "fall", "falls", "rank", "ranks", "reside", "resides" })

-- relation noun phrases ("official language", "workforce", "chief executive officer") -> { {rel=, role=}, ... }
local function phrase_index(lex)
  if lex._phrase_index and lex._phrase_rev == lex.revision then return lex._phrase_index end
  local idx = {}
  for _, rel in ipairs(lex:all_rels()) do
    if not rel.open then
      for _, n in ipairs(rel.nouns_to or {}) do local k = n:lower(); idx[k] = idx[k] or {}; idx[k][#idx[k] + 1] = { rel = rel, role = "to" } end
      for _, n in ipairs(rel.nouns_from or {}) do local k = n:lower(); idx[k] = idx[k] or {}; idx[k][#idx[k] + 1] = { rel = rel, role = "from" } end
    end
  end
  lex._phrase_index, lex._phrase_rev = idx, lex.revision
  return idx
end

local PARTICIPLES = U.set({ "spoken", "used", "recognised", "recognized", "adopted", "designated", "declared", "accepted", "established", "named" })

local function wh_ok(wh)
  return not wh.adverbial and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much"
end

---------------------------------------------------------------- the wh-noun names the relation; the preposition is stranded or fronted
function F.wh_relnoun_stranded(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.relnoun and wh.np and wh_ok(wh) then
      local ac = C(S, wh.nxt)
      local mode = ac and not barrier(ac) and ((is_be(ac) and "be") or (is_do(ac) and "do")) or nil
      if mode then
        for _, snp in ipairs(P.parse_np(S, wh.nxt + 1)) do
          local pk, filler = snp.nxt, nil
          local fc = C(S, pk)
          if fc and fc.single and not fc.masked and not barrier(fc) and FILLERS[fc.unit.form] then filler = pk; pk = pk + 1 end
          local pc = C(S, pk)
          local stranded = pc and pc.single and not pc.masked and not barrier(pc) and cat(pc, "prep") and pk == S.last
          local fronted = wh.pied and pk > S.last
          if (stranded or fronted) and (mode == "be" or filler) then
            for _, e in ipairs(wh.np.relnouns) do
              local rel = S.lex:get_rel(e.rel)
              if rel then
                local h = newh(S, "wh_relnoun_stranded", "question")
                set_lookup(h, rel, other(e.role), snp, e.role, wh)
                use_wh(h, wh); use(h, wh.nxt); use_np(h, snp)
                if filler then use(h, filler) end
                if stranded then use(h, pk) elseif wh.pied then h.pied_consumed = true end
                addf(h, "stranded_relnoun", 0.7, "the wh-noun '" .. tostring(wh.np.head and wh.np.head.form) .. "' names " .. rel.id .. "; the preposition is stranded or fronted")
                wh_relnoun_agreement(h, wh, rel)
                mark_unresolved_pron(h, snp)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- a predicate noun names the relation: "What is France a member of?"
function F.wh_pred_stranded(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh_ok(wh) and not wh.relnoun then
      local bc = C(S, wh.nxt)
      if is_be(bc) and not barrier(bc) then
        for _, snp in ipairs(P.parse_np(S, wh.nxt + 1)) do
          for _, rnp in ipairs(P.parse_np(S, snp.nxt)) do
            if rnp.head_kind == "relnoun" and not rnp.of_arg and not rnp.possessor then
              local pc = C(S, rnp.nxt)
              -- the preposition is stranded ("Which country is Bamako the capital OF?") or fronted with the wh-phrase ("OF which country is Bamako the capital?")
              local stranded = pc and pc.single and not pc.masked and not barrier(pc) and cat(pc, "prep") and rnp.nxt == S.last
              local fronted = wh.pied and rnp.nxt > S.last
              if stranded or fronted then
                for _, e in ipairs(rnp.relnouns) do
                  local rel = S.lex:get_rel(e.rel)
                  -- the predicate noun denotes role e.role of the SUBJECT ("France is a member of ..." / "Jane is the CEO of ..."); the preposition's object is the other role
                  local ask = other(e.role)
                  if rel and ((not wh.type) or S.lex:compat(rel[ask], wh.type) >= 0.5) then
                    local h = newh(S, "wh_pred_stranded", "question")
                    set_lookup(h, rel, e.role, snp, ask, wh)
                    use_wh(h, wh); use(h, wh.nxt); use_np(h, snp); use_np(h, rnp)
                    if stranded then use(h, rnp.nxt) else h.pied_consumed = true end
                    addf(h, "pred_noun_relation", 0.7, "the predicate noun '" .. tostring(rnp.head and rnp.head.form) .. "' names " .. rel.id .. " for the subject")
                    mark_unresolved_pron(h, snp)
                    out[#out + 1] = h
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- adjective + wh-noun is a relational noun phrase: "Which language is official in Brazil?"
function F.wh_adj_predicate(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh_ok(wh) and wh.np and not wh.relnoun and wh.np.head and wh.np.head.single and (wh.np.head_kind == "typenoun" or wh.np.head_kind == "concept") then
      local bc = C(S, wh.nxt)
      local ac = C(S, wh.nxt + 1)
      if is_be(bc) and not barrier(bc) and ac and ac.single and not ac.masked and not barrier(ac) then
        local adj, shift = ac.unit.form, 0
        -- "officially spoken" / "nationally recognised": the adverb stands for the adjective of the relational noun phrase
        local vc = C(S, wh.nxt + 2)
        if adj:match("ly$") and #adj > 4 and vc and vc.single and not vc.masked and not barrier(vc) and PARTICIPLES[vc.unit.form] then adj = adj:gsub("ly$", ""); shift = 1 end
        local phrase = adj .. " " .. wh.np.head.unit.form
        local pc = C(S, wh.nxt + 2 + shift)
        if pc and pc.single and not pc.masked and not barrier(pc) and cat(pc, "prep") then
          for _, ent in ipairs(phrase_index(S.lex)[phrase] or {}) do
            for _, np in ipairs(P.parse_np(S, wh.nxt + 3 + shift)) do
              local h = newh(S, "wh_adj_predicate", "question")
              set_lookup(h, ent.rel, other(ent.role), np, ent.role, wh)
              use_wh(h, wh); use(h, wh.nxt, wh.nxt + 2 + shift); use_np(h, np)
              addf(h, "adjective_noun_relation", 0.7, "'" .. phrase .. "' is a relational noun phrase of " .. ent.rel.id)
              mark_unresolved_pron(h, np)
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- impersonal subject: "What currency do THEY use in Zembrova?"  "Which currency do people use in Peru?"
local IMPERSONAL = U.set({ "they", "people", "folks", "locals", "residents", "citizens", "everyone", "you" })
function F.wh_impersonal(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh_ok(wh) and (wh.wh == "what" or wh.wh == "which") then
      local ac = C(S, wh.nxt)
      if is_do(ac) and not barrier(ac) then
        local pc = C(S, wh.nxt + 1)
        if pc and pc.single and not pc.masked and not barrier(pc) and IMPERSONAL[pc.unit.form] then
          for _, vp in ipairs(P.parse_vp(S, wh.nxt + 2, { aux_hint = "do" })) do
            local lp = C(S, vp.nxt)
            if lp and lp.single and not lp.masked and not barrier(lp) and cat(lp, "prep") and (lp.unit.form == "in" or lp.unit.form == "at" or lp.unit.form == "across" or lp.unit.form == "throughout") then
              for _, np in ipairs(P.parse_np(S, vp.nxt + 1)) do
                for _, e in ipairs(vp.analysis.entries or {}) do
                  local rel = S.lex:get_rel(e.rel)
                  -- the place is the holder of the relation the support verb carries ("use ... in Zembrova" = Zembrova's currency)
                  if rel and e.support and e.subj == "from" and F.support_licensed(S, e, rel, wh, "to") then
                    local h = newh(S, "wh_impersonal", "question")
                    set_lookup(h, rel, "from", np, "to", wh)
                    use_wh(h, wh); use(h, wh.nxt, wh.nxt + 1); use_vp(h, vp); use(h, vp.nxt); use_np(h, np)
                    addf(h, "impersonal_subject", 0.8, "'" .. pc.unit.form .. " " .. tostring(vp.lemma) .. " in X' is the generic 'what X uses'")
                    wh_relnoun_agreement(h, wh, rel)
                    mark_unresolved_pron(h, np)
                    out[#out + 1] = h
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- "Which country is Elena Vasquez from?" / "What does Ithari Foundry do?"
function F.wh_origin(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh_ok(wh) and wh.np and not wh.relnoun and wh.type and (wh.np.head_kind == "typenoun") then
      local bc = C(S, wh.nxt)
      if is_be(bc) and not barrier(bc) then
        for _, snp in ipairs(P.parse_np(S, wh.nxt + 1)) do
          local pc = C(S, snp.nxt)
          if pc and pc.single and not pc.masked and not barrier(pc) and pc.unit.form == "from" and snp.nxt == S.last then
            local rid = S.lex:isa(wh.type, "country") and "nationality" or ((S.lex:isa(wh.type, "city") or wh.type == "place") and "birth_place" or nil)
            local rel = rid and S.lex:get_rel(rid)
            if rel then
              local h = newh(S, "wh_origin", "question")
              set_lookup(h, rel, "from", snp, "to", wh)
              use_wh(h, wh); use(h, wh.nxt); use_np(h, snp); use(h, snp.nxt)
              addf(h, "origin_from", 0.7, "'" .. tostring(wh.np.head and wh.np.head.form) .. " ... from' asks for the origin (" .. rel.id .. ") of a person")
              mark_unresolved_pron(h, snp)
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

function F.what_does_do(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.wh == "what" and not wh.np and not wh.adverbial then
      local ac, k = C(S, wh.nxt), wh.nxt
      if is_do(ac) and not barrier(ac) then
        for _, snp in ipairs(P.parse_np(S, k + 1)) do
          local vc = C(S, snp.nxt)
          if vc and vc.single and not vc.masked and not barrier(vc) and vc.unit.form == "do" and snp.nxt == S.last and (snp.head_kind == "entity" or snp.head_kind == "unknown") then
            local rel = S.lex:get_rel("industry")
            if rel then
              local h = newh(S, "what_does_do", "question")
              set_lookup(h, rel, "from", snp, "to", wh)
              use_wh(h, wh); use(h, k); use_np(h, snp); use(h, snp.nxt)
              addf(h, "what_does_x_do", 0.6, "'What does X do?' asks for the business X is in")
              mark_unresolved_pron(h, snp)
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- quantities: counted nouns, "how much", degree adjectives over relational nouns
local function count_rels(lex, noun)
  local out = {}
  for _, rel in ipairs(lex:all_rels()) do
    for _, n in ipairs(rel.count_nouns or {}) do if n == noun then out[#out + 1] = rel end end
  end
  return out
end

-- the lemmas a chunk can be a form of (the lexicon's verbs, the inflection guesser, and the surface form itself as a base form)
local Morph = require("asi.nlu.morph")
local function lemma_set(S, c)
  local set = {}
  if not c or not c.single or c.masked then return set end
  for _, a in ipairs(P.verb_analyses(S, c)) do set[a.lemma] = true end
  for _, g in ipairs(Morph.guess(c.unit.form)) do if g.pos == "verb" then set[g.lemma] = true end end
  set[c.unit.form] = true
  return set
end

local function verb_entry(rel, lemma)
  local out = {}
  for _, cv in ipairs(rel.count_verbs or {}) do if cv.lemma == lemma then out[#out + 1] = cv end end
  return out
end

function F.quantity_q(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    -- "How many PEOPLE live in X?" / "How many residents are there in X?" / "How many people does X employ?"
    if wh.wh == "how_many" and wh.np and wh.np.head and wh.np.head.single and wh.np.head_kind ~= "relnoun" then
      local noun = wh.np.head.unit.form
      for _, rel in ipairs(count_rels(S.lex, noun)) do
        local function emit(frame, known, vp_or_k, extra)
          local h = newh(S, frame, "question")
          set_lookup(h, rel, "from", known, "to", wh)
          h.answer_form = "number"
          use_wh(h, wh); use_np(h, known)
          if extra then extra(h) end
          addf(h, "counted_noun", 0.7, "'how many " .. noun .. "' counts the value of " .. rel.id)
          mark_unresolved_pron(h, known)
          out[#out + 1] = h
        end
        local nk = wh.nxt
        local c1 = C(S, nk)
        -- (a) subject = the counted people:  live in X / work at X / are living in X
        do
          local vk = nk
          local progressive = false
          if is_be(c1) and not barrier(c1) and not (C(S, nk + 1) and C(S, nk + 1).single and C(S, nk + 1).unit.form == "there") then vk = nk + 1; progressive = true end
          local vc = C(S, vk)
          if vc and vc.single and not vc.masked and not barrier(vc) then
            for lemma in pairs(lemma_set(S, vc)) do
              for _, ce in ipairs(verb_entry(rel, lemma)) do
                local function mark(h) if progressive then use(h, nk) end; use(h, vk) end
                if ce.prep then
                  local pk = vk + 1
                  if is_prep(C(S, pk), ce.prep) then
                    for _, np in ipairs(P.parse_np(S, pk + 1)) do emit("quantity:count_verb", np, nil, function(h) mark(h); use(h, pk) end) end
                  else
                    -- "How many people live THERE?": the locative pro-form carries the preposition and the place
                    for _, np in ipairs(P.parse_np(S, pk)) do
                      if np.head_kind == "pronoun" and np.pron and np.pron.cats and np.pron.cats.pron_loc then emit("quantity:count_verb", np, nil, mark) end
                    end
                  end
                elseif ce.lemma ~= "have" then
                  for _, np in ipairs(P.parse_np(S, vk + 1)) do emit("quantity:count_verb", np, nil, mark) end
                end
              end
            end
          end
        end
        for _, vp in ipairs(P.parse_vp(S, nk)) do
          -- passive:  "How many people are employed by X?"
          if vp.voice == "passive" and (vp.lemma == "employ") and rel.id == "employees" then
            local pk = vp.nxt
            if is_prep(C(S, pk), "by") or is_prep(C(S, pk), "at") then
              for _, np in ipairs(P.parse_np(S, pk + 1)) do emit("quantity:count_passive", np, nil, function(h) use_vp(h, vp); use(h, pk) end) end
            end
          end
        end
        -- (b) "are there in X" / "are there at X"
        if is_be(c1) and not barrier(c1) then
          local c2, c3 = C(S, nk + 1), C(S, nk + 2)
          if c2 and c2.single and c2.unit.form == "there" and c3 and c3.single and cat(c3, "prep") and not barrier(c3) and (c3.unit.form == "in" or c3.unit.form == "at") then
            for _, np in ipairs(P.parse_np(S, nk + 3)) do emit("quantity:there_are", np, nil, function(h) use(h, nk, nk + 2) end) end
          end
        end
        -- (c) do-support:  "How many people does X have / employ?"
        if is_do(c1) and not barrier(c1) then
          for _, snp in ipairs(P.parse_np(S, nk + 1)) do
            for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do" })) do
              for _, ce in ipairs(verb_entry(rel, vp.lemma)) do
                if not ce.prep then emit("quantity:do_count", snp, nil, function(h) use(h, nk); use_vp(h, vp) end) end
              end
            end
          end
        end
      end
    end
    -- bare "How much does X cost?" / "How much is X?"
    if (wh.wh == "how_much" or wh.wh == "how_many") and wh.bare then
      local ac = C(S, wh.nxt)
      if is_do(ac) then
        for _, snp in ipairs(P.parse_np(S, wh.nxt + 1)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do" })) do
            for _, e in ipairs(vp.analysis.entries or {}) do
              local rel = S.lex:get_rel(e.rel)
              if rel and not e.support and not e.prep and S.lex:compat(rel.to, "number") >= 0.9 then
                local h = newh(S, "quantity:how_much_verb", "question")
                set_lookup(h, rel, e.subj, snp, other(e.subj), wh)
                h.answer_form = "number"
                use_wh(h, wh); use(h, wh.nxt); use_np(h, snp); use_vp(h, vp)
                addf(h, "quantity_verb", 0.7, "'how much' asks for the numeric value of " .. rel.id .. " (verb '" .. tostring(vp.lemma) .. "')")
                mark_unresolved_pron(h, snp)
                out[#out + 1] = h
              end
            end
          end
        end
      elseif is_be(ac) and wh.wh == "how_much" then
        for _, np in ipairs(P.parse_np(S, wh.nxt + 1)) do
          for _, rel in ipairs(S.lex:all_rels()) do
            if rel.howmuch and (np.head_kind == "entity" or np.head_kind == "typenoun" or np.head_kind == "unknown") then
              local h = newh(S, "quantity:how_much_is", "question")
              set_lookup(h, rel, "from", np, "to", wh)
              h.answer_form = "number"
              use_wh(h, wh); use(h, wh.nxt); use_np(h, np)
              addf(h, "how_much_default", 0.4, "'how much is X' asks for the " .. rel.id .. " of a product-like thing")
              mark_unresolved_pron(h, np)
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

-- "How large is the workforce of X?"  "How big is the population of Chad?"  "How high is the revenue of X?"
function F.how_adj_relnoun(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.wh == "how_adj" then
      local bc = C(S, wh.nxt)
      if is_be(bc) and not barrier(bc) then
        for _, np in ipairs(P.parse_np(S, wh.nxt + 1)) do
          if np.head_kind == "relnoun" and (np.of_arg or np.possessor) then
            for _, o in ipairs(relnp_options(S, np)) do
              if o.arg and S.lex:compat(o.rel.to, "number") >= 0.9 then
                local h = newh(S, "how_adj_relnoun", "question")
                set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
                h.answer_form = "number"
                use_wh(h, wh); use(h, wh.nxt); use_np(h, np)
                addf(h, "relnp_arg", 0.7, "relational noun with explicit argument")
                addf(h, "degree_over_relnoun", 0.2, "'how " .. tostring(wh.adj) .. "' over a numeric relational noun")
                F.option_factors(h, o)
                mark_unresolved_pron(h, o.arg)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- elliptical follow-ups: "What about Jupiter?"  "Same question for Sundrel Energy."  "Sorry, I meant Nokian Tyres."
-- The previous relational question of the conversation is re-asked about the new argument (the memory keeps it as `last_query`).
function F.ellipsis(S, out)
  local view = S.ctx and S.ctx.discourse
  local mem = view and view.mem
  if not mem then return end
  local lq, cmp = mem.last_query, mem.comparison
  if lq and lq.turn >= (mem.turn or 0) then lq = nil end
  if cmp and cmp.turn >= (mem.turn or 0) then cmp = nil end
  if not lq and not cmp then return end
  -- the more recent of the two earlier requests is the one that is continued ("And what about Tanzania?" after a comparison adds an item to it)
  local continue_cmp = cmp ~= nil and (lq == nil or cmp.turn > lq.turn)
  local c0 = C(S, S.first)
  local n = c0 and not c0.masked and S.lex:cue_at("ellipsis_open", S.units, c0.u1)
  if not n then
    -- "And Bosch?", "Also of Bosch?": the sentence-initial conjunction was stripped as a lead-in; it is the whole cue
    local lc = S.wrapper and S.wrapper.lead_in and S.first > 1 and C(S, S.first - 1)
    if lc and lc.single and (lc.unit.form == "and" or lc.unit.form == "also") then n = 0 else return end
  end
  local k, consumed = S.first, 0
  while k <= S.last and consumed < n do consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1); k = k + 1 end
  if consumed ~= n or k > S.last then return end
  -- "And of Bosch?": the preposition that introduces the new argument of a relational noun belongs to the cue
  local pc = C(S, k)
  if pc and pc.single and not pc.masked and not barrier(pc) and pc.unit.form == "of" and k < S.last then k = k + 1 end
  local rel = S.lex:get_rel(continue_cmp and cmp.rel or (lq and lq.rel))
  if not rel and not continue_cmp then return end
  for _, np in ipairs(P.parse_np(S, k)) do
    -- the whole remainder is the new argument (a name, an unknown noun phrase or a pronoun)
    if np.nxt > S.last and (np.head_kind == "entity" or np.head_kind == "unknown" or np.head_kind == "typenoun" or np.head_kind == "pronoun") and not np.of_arg then
      local h
      if continue_cmp then
        h = newh(S, "ellipsis:comparison", "question", "comparison", "compare")
        h.items = { np }
        if rel then h.rel, h.rel_obj = rel.id, rel end
        h.dimension = cmp.dimension
        h.requires_evidence = true
        h.ellipsis = { turn = cmp.turn, text = "" }
        addf(h, "elliptical_comparison", 0.9, "adds an item to the comparison of the previous request (turn " .. tostring(cmp.turn) .. ")")
      else
        h = newh(S, "ellipsis:requery", "question")
        set_lookup(h, rel, lq.known_role, np, lq.ask, nil)
        h.ellipsis = { turn = lq.turn, text = lq.text }
        addf(h, "elliptical_requery", 0.9, "re-asks the previous question (" .. rel.id .. ", turn " .. tostring(lq.turn) .. ") about a new argument")
      end
      use(h, S.first, k - 1); use_np(h, np)
      mark_unresolved_pron(h, np)
      out[#out + 1] = h
    end
  end
end

---------------------------------------------------------------- comparisons
local DIFF_NOUNS = U.set({ "difference", "differences", "similarity", "similarities", "contrast", "contrasts", "distinction", "distinctions", "comparison" })

-- "What are the main differences between X and Y?"  "How do X and Y differ?"  "How does X compare to Y?"
function F.compare_differences(S, out)
  local function between(k, wh, base_used)
    for _, np1 in ipairs(P.parse_np(S, k)) do
      local jc = C(S, np1.nxt)
      if jc and jc.single and not jc.masked and not barrier(jc) and jc.unit.form == "and" then
        for _, np2 in ipairs(P.parse_np(S, np1.nxt + 1)) do
          if np2.nxt > S.last then
            local h = newh(S, "compare_differences", "question", "comparison", "diff")
            use_wh(h, wh); use(h, np1.nxt); use_np(h, np1); use_np(h, np2)
            for i = base_used, np1.c1 - 1 do h.used[i] = true end
            h.items = { np1, np2 }
            h.requires_evidence = true
            mark_unresolved_pron(h, np1); mark_unresolved_pron(h, np2)
            addf(h, "differences_between_two", 0.8, "a request for the differences between two items")
            out[#out + 1] = h
          end
        end
      end
    end
  end
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.wh == "what" and not wh.adverbial and not wh.np then
      local bc = C(S, wh.nxt)
      if is_be(bc) and not barrier(bc) then
        for _, dnp in ipairs(P.parse_np(S, wh.nxt + 1)) do
          if dnp.head and dnp.head.single and DIFF_NOUNS[dnp.head.unit.form] then
            local pc = C(S, dnp.nxt)
            if pc and pc.single and not pc.masked and not barrier(pc) and pc.unit.form == "between" then between(dnp.nxt + 1, wh, wh.nxt) end
          end
        end
      end
    elseif wh.wh == "how" and wh.adverbial then
      local ac = C(S, wh.nxt)
      if ac and ac.single and not ac.masked and not barrier(ac) and (cat(ac, "aux_do") or cat(ac, "aux_be")) then
        -- "How do X and Y differ?" / "How are X and Y different?"
        for _, np1 in ipairs(P.parse_np(S, wh.nxt + 1)) do
          local jc = C(S, np1.nxt)
          if jc and jc.single and not jc.masked and not barrier(jc) and jc.unit.form == "and" then
            for _, np2 in ipairs(P.parse_np(S, np1.nxt + 1)) do
              local vc = C(S, np2.nxt)
              if vc and vc.single and not vc.masked and not barrier(vc) and np2.nxt == S.last and (vc.unit.form == "differ" or vc.unit.form == "different" or vc.unit.form == "similar" or vc.unit.form == "compare" or vc.unit.form == "alike") then
                local h = newh(S, "compare_differences:how_differ", "question", "comparison", "diff")
                use_wh(h, wh); use(h, wh.nxt); use_np(h, np1); use(h, np1.nxt); use_np(h, np2); use(h, np2.nxt)
                h.items = { np1, np2 }
                h.requires_evidence = true
                mark_unresolved_pron(h, np1); mark_unresolved_pron(h, np2)
                addf(h, "differences_between_two", 0.8, "how two items differ")
                out[#out + 1] = h
              end
            end
          end
          -- "How does X differ from Y?" / "How does X compare to Y?"
          local vc = C(S, np1.nxt)
          if vc and vc.single and not vc.masked and not barrier(vc) and (vc.unit.form == "differ" or vc.unit.form == "compare" or vc.unit.form == "stack") then
            local pc = C(S, np1.nxt + 1)
            if pc and pc.single and not pc.masked and not barrier(pc) and (pc.unit.form == "from" or pc.unit.form == "to" or pc.unit.form == "with" or pc.unit.form == "against" or pc.unit.form == "up") then
              local qk = np1.nxt + 2
              local q = C(S, qk)
              if q and q.single and q.unit.form == "to" and pc.unit.form == "up" then qk = qk + 1 end
              for _, np2 in ipairs(P.parse_np(S, qk)) do
                if np2.nxt > S.last then
                  local h = newh(S, "compare_differences:how_compare", "question", "comparison", "diff")
                  use_wh(h, wh); use(h, wh.nxt); use_np(h, np1); use(h, np1.nxt, qk - 1); use_np(h, np2)
                  h.items = { np1, np2 }
                  h.requires_evidence = true
                  mark_unresolved_pron(h, np1); mark_unresolved_pron(h, np2)
                  addf(h, "differences_between_two", 0.8, "how one item differs from / compares with another")
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
    end
  end
end

-- "Which of the two firms, A or B, has more employees?"  "Which has more employees, A or B?"  "Which of the two has more employees?"
local MORE_WORDS = { more = "more", greater = "more", larger = "more", bigger = "more", fewer = "fewer", less = "fewer", smaller = "fewer" }
function F.compare_which_of_two(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if (wh.wh == "which" or wh.wh == "who") and not wh.adverbial and not wh.np then
      local k = wh.nxt
      local items = {}
      local oc = C(S, k)
      -- "of the two firms," / "of the two," / "of A and B"
      if oc and oc.single and not oc.masked and not barrier(oc) and oc.unit.form == "of" then
        k = k + 1
        local dc, tc = C(S, k), C(S, k + 1)
        if dc and tc and dc.single and tc.single and dc.unit.form == "the" and (tc.unit.form == "two" or tc.unit.form == "both") then
          k = k + 2
          local nn = C(S, k)
          if nn and not barrier(nn) and not nn.pre and (nn.senses and #nn.senses > 0) then k = k + 1 end   -- "the two FIRMS"
        elseif dc and dc.single and (dc.unit.form == "them" or dc.unit.form == "these" or dc.unit.form == "those") then k = k + 1 end
        -- optional listed items:  ", A or B,"
        local lc = C(S, k)
        if lc and lc.pre and lc.pre:find("comma") then
          for _, np1 in ipairs(P.parse_np(S, k)) do
            local jc = C(S, np1.nxt)
            if jc and jc.single and (jc.unit.form == "or" or jc.unit.form == "and") then
              for _, np2 in ipairs(P.parse_np(S, np1.nxt + 1)) do
                items = { np1, np2 }
                k = np2.nxt
                break
              end
            end
            break
          end
        end
      end
      -- verb: has / have + more|fewer N
      local hv = C(S, k)
      if hv and hv.single and not hv.masked and cat(hv, "aux_have") then
        local mw = C(S, k + 1)
        local deg = mw and mw.single and MORE_WORDS[mw.unit.form]
        if deg then
          for _, np in ipairs(P.parse_np(S, k + 2)) do
            if np.head_kind == "relnoun" and (np.nxt > S.last or true) then
              for _, e in ipairs(np.relnouns) do
                local rel = S.lex:get_rel(e.rel)
                if rel and S.lex:compat(rel.to, "number") >= 0.9 then
                  -- items may also follow:  "..., A or B"
                  local its = items
                  local nk = np.nxt
                  if #its == 0 then
                    local lc = C(S, nk)
                    if lc and lc.pre and lc.pre:find("comma") then
                      for _, n1 in ipairs(P.parse_np(S, nk)) do
                        local jc = C(S, n1.nxt)
                        if jc and jc.single and (jc.unit.form == "or" or jc.unit.form == "and") then
                          for _, n2 in ipairs(P.parse_np(S, n1.nxt + 1)) do if n2.nxt > S.last then its = { n1, n2 } end; break end
                        end
                        break
                      end
                    end
                  end
                  if #its == 0 and S.vs_items then its = S.vs_items end      -- "Siemens vs Bosch: who has more employees?"
                  local h = newh(S, "compare_which_of_two", "question", "comparison", "rank_attribute")
                  h.wh = wh
                  h.rel, h.rel_obj = rel.id, rel
                  use_wh(h, wh); use(h, wh.nxt, k + 1); use_np(h, np)
                  for _, it in ipairs(its) do use_np(h, it) end
                  if #its == 2 then h.items = its; use(h, its[1].nxt) end
                  h.degree = deg == "more" and "comp_more" or "comp_less"
                  h.dimension = "size"
                  h.requires_evidence = true
                  addf(h, "comparison_over_attribute", 0.9, "'" .. tostring(mw.unit.form) .. " " .. tostring(np.head and np.head.form) .. "' ranks two items on " .. rel.id)
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- imperative + noun phrase with a relative clause
local LIST_VERBS = U.set({ "name", "list", "enumerate", "give", "show", "tell", "find", "get", "provide", "identify", "mention", "state", "fetch", "retrieve", "display", "cite" })

function F.list_relative(S, out)
  local k = S.first
  local vc = C(S, k)
  local head
  if vc and vc.single and not vc.masked and LIST_VERBS[vc.unit.form] and not barrier(vc) then
    head = k
    k = k + 1
    local mc = C(S, k)
    if mc and mc.single and not mc.masked and (mc.unit.form == "me" or mc.unit.form == "us") and not barrier(mc) then k = k + 1 end
  else
    -- "Give me the firms ...": the request wrapper already took the verb and "me"
    local w = S.wrapper
    local wk = w and w.chunks and w.chunks[1]
    local wc = wk and C(S, wk)
    if not (wc and wc.single and LIST_VERBS[wc.unit.form]) then return end
    head = wk
  end
  for _, nnp in ipairs(P.parse_np(S, k, { no_of = true })) do
    local t = nnp.senses and nnp.senses[1] and nnp.senses[1].type
    if (nnp.head_kind == "typenoun" or nnp.head_kind == "unknown") and nnp.head and not nnp.of_arg then
      local rk = nnp.nxt
      local rc = C(S, rk)
      local relativizer = rc and rc.single and not rc.masked and not barrier(rc) and (rc.unit.form == "that" or rc.unit.form == "which" or rc.unit.form == "who")
      if relativizer then rk = rk + 1 end
      local wh = { wh = "which", type = t, np = nnp, nxt = rk, c1 = nnp.c1, c2 = nnp.c2, u1 = nnp.u1, u2 = nnp.u2, plural = true, synthetic = true }
      -- the known side of a LOOKUP is a named thing ("Sequoia Capital", "the euro"); a descriptive phrase ("Series A funding") makes the clause a FILTER of a search
      local function named(np)
        return np.head_kind == "entity" or (np.head_kind == "unknown" and np.head and np.head.cap)
          or ((np.head_kind == "typenoun" or np.head_kind == "unknown") and not np.plural and np.det == "the")   -- "the euro": one definite thing
      end
      local function finish(h, rel, known_role, known_np, ask_role, vp, prep_k)
        if not named(known_np) then return end
        set_lookup(h, rel, known_role, known_np, ask_role, wh)
        use(h, head, k - 1); use_np(h, nnp); use_np(h, known_np); use_vp(h, vp)
        if relativizer then use(h, nnp.nxt) end
        if prep_k then use(h, prep_k) end
        mark_unresolved_pron(h, known_np)
        out[#out + 1] = h
      end
      -- (a) object gap:  the startups [that] SEQUOIA CAPITAL HAS INVESTED IN        subject NP, then a verb group, a stranded preposition is allowed
      for _, snp in ipairs(P.parse_np(S, rk)) do
        for _, vp in ipairs(P.parse_vp(S, snp.nxt)) do
          for _, e in ipairs(vp.analysis.entries or {}) do
            local rel = S.lex:get_rel(e.rel)
            if rel and vp.voice == "active" and F.support_licensed(S, e, rel, wh, other(e.subj)) then
              local pk = vp.nxt
              local prep_ok = (not e.prep and pk > S.last) or (e.prep and is_prep(C(S, pk), e.prep) and pk == S.last)
              if prep_ok then
                local h = newh(S, "list_relative:object_gap", "request")
                finish(h, rel, e.subj, snp, other(e.subj), vp, e.prep and pk or nil)
                addf(h, "direction_explicit", 0.35, "role direction fixed by the relative clause's object gap (subject=" .. e.subj .. ")")
                addf(h, "list_request", 0.3, "imperative + noun phrase + relative clause")
              end
            end
          end
        end
      end
      -- (c) agent phrase:  all books BY Imelda Strand
      do
        local bc = C(S, nnp.nxt)
        if bc and bc.single and not bc.masked and not barrier(bc) and bc.unit.form == "by" and t then
          for _, anp in ipairs(P.parse_np(S, nnp.nxt + 1)) do
            if anp.nxt > S.last then
              for _, rel in ipairs(S.lex:all_rels()) do
                if not rel.open and (rel.id == "author" or rel.id == "creator" or rel.id == "developer") and S.lex:compat(t, rel.from) >= 0.9 then
                  local h = newh(S, "list_relative:by_agent", "request")
                  set_lookup(h, rel, "to", anp, "from", wh)
                  use(h, head, k - 1); use_np(h, nnp); use(h, nnp.nxt); use_np(h, anp)
                  addf(h, "by_agent", 0.6, "'" .. tostring(nnp.head and nnp.head.form) .. " by X' lists works whose " .. rel.id .. " is X")
                  if rel.id == "author" and S.lex:isa(t, "publication") then addf(h, "literary_work", 0.15, "a book/article has an author") end
                  mark_unresolved_pron(h, anp)
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
      -- (b) subject gap:  the countries [that] USE THE EURO
      if relativizer or true then
        for _, vp in ipairs(P.parse_vp(S, rk)) do
          if vp.voice == "active" then
            for _, e in ipairs(vp.analysis.entries or {}) do
              local rel = S.lex:get_rel(e.rel)
              if rel and F.support_licensed(S, e, rel, wh, e.subj) then
                local pk = vp.nxt
                local ok_prep = (not e.prep) or is_prep(C(S, pk), e.prep)
                if ok_prep then
                  local ok = pk + (e.prep and 1 or 0)
                  for _, onp in ipairs(P.parse_np(S, ok)) do
                    if onp.nxt > S.last then
                      local h = newh(S, "list_relative:subject_gap", "request")
                      finish(h, rel, other(e.subj), onp, e.subj, vp, e.prep and pk or nil)
                      addf(h, "direction_explicit", 0.35, "role direction fixed by voice/lexicon (subject gap, subj=" .. e.subj .. ")")
                      addf(h, "list_request", 0.3, "imperative + noun phrase + relative clause")
                      if not relativizer then addf(h, "no_relativizer", -0.25, "a reduced relative clause without 'that'") end
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- a resource named with a value in a directive sentence: "the analysis should now run on dataset 2025 rather than the one I mentioned before"
-- "Scrap the earlier dataset, I want dataset 2026 used from here on."  "Whenever you run the analysis, pull from the 2020 dataset and nothing else."
-- Any sentence that frames a resource phrase WITH A VALUE (the 2021 dataset, dataset 2019, the dataset named 2026, version 3.2, the file a.csv) as what to use is an instruction
-- about that resource's slot -- whatever the verb ("lean on", "run on", "pull from", "built on", "carried out on", "go with").  Questions and reported speech are not.
local DIR_WORDS = U.set({ "use", "using", "run", "running", "pull", "pulling", "build", "built", "base", "based", "carry", "carried", "lean", "rely", "relying", "work", "working",
  "analyse", "analyze", "analysed", "analyzed", "go", "going", "switch", "switching", "stick", "sticking", "draw", "drawing", "take", "taking", "apply", "applied", "operate",
  "compute", "computed", "calculate", "calculated", "process", "load", "read", "query", "select", "choose", "pick", "prefer", "adopt", "default", "point", "restrict", "limit",
  "stay", "remain", "keep", "set", "need", "want", "wish", "should", "must", "ensure", "replace", "replaces", "swap", "change", "update", "upgrade", "move", "refer", "consult", "feed", "fall" })
local REPORT_MARKERS = U.set({ "she", "he", "they", "someone", "somebody", "friend", "colleague", "teacher", "professor", "boss", "manager", "said", "says", "told", "tells", "asked", "asks",
  "suggested", "suggests", "recommended", "recommends", "mentioned", "claimed", "thinks", "thought", "reckons", "reckoned", "heard", "read" })
local FIRST_PERSON_DIRECTIVE = U.set({ "i", "we", "let's", "lets", "please", "kindly" })
local NAMING = U.set({ "named", "called", "titled", "labelled", "labeled", "dubbed", "number", "no", "id", "version" })
local REPLACE_VERBS = U.set({ "use", "switch", "go", "pick", "choose", "take", "try", "prefer", "adopt", "select", "rely", "stick", "move" })
function F.resource_directive(S, out)
  if S.sentence and S.sentence.question_mark then return end
  if #P.parse_wh(S, S.first) > 0 then return end
  local lex = S.lex
  local has_dir, reported, first_person = false, false, false
  for i = S.first, S.last do
    local c = C(S, i)
    local f = c and not c.masked and ((c.single and c.unit.form) or (c.form and c.form:match("^(%S+)")))   -- a multiword verb ("set up") counts by its first word
    if f then
      if DIR_WORDS[f] then has_dir = true end
      -- "On second thought, ...": the idiom is not a report of someone's thinking
      local prevc = C(S, i - 1)
      local idiom = f == "thought" and prevc and prevc.single and (prevc.unit.form == "second" or prevc.unit.form == "first" or prevc.unit.form == "after")
      if REPORT_MARKERS[f] and not idiom then reported = true end
      if FIRST_PERSON_DIRECTIVE[f] then first_person = true end
      if f == "let" then
        local nx = C(S, i + 1)
        if nx and nx.single and (nx.unit.form == "us" or nx.unit.form == "'s" or cat(nx, "clitic_s")) then first_person = true end
      end
    end
  end
  if not has_dir then return end
  -- "My friend said to use the 2021 dataset in her statistics class.": reported, no directive of the speaker's own
  if reported and not first_person then return end
  local function emit(c, slot, value)
    -- a retraction or replacement marker anywhere makes it a correction; a standing marker makes it persist
    local correction, persist = false, false
    for k = S.first, S.last do
      local ck = C(S, k)
      if ck and not ck.masked then
        if lex:cue_at("correction", S.units, ck.u1) or lex:cue_at("revoke", S.units, ck.u1) then correction = true end
        if ck.temporal and (ck.temporal.kind == "persist" or ck.temporal.persist) then persist = true end
        if ck.single and (ck.unit.form == "instead" or ck.unit.form == "replace" or ck.unit.form == "replaces" or ck.unit.form == "scrap" or ck.unit.form == "disregard") then correction = true end
        if ck.single and (ck.unit.form == "whenever" or ck.unit.form == "always" or ck.unit.form == "everytime") then persist = true end
      end
    end
    local h = newh(S, "instruction:resource_directive", "instruction", "instruction_update", "instruct")
    for k = S.first, S.last do if C(S, k) and not C(S, k).masked then h.used[k] = true end end
    h.instruction = { verb = "use", act = "constraint", np = { head = c, head_kind = "concept", mods = {}, u1 = c.u1, u2 = c.u2, c1 = c.idx, c2 = c.idx, nxt = c.idx + 1, notes = {}, score = 0 },
      slot = slot, value = value, correction = correction, persist = persist }
    h.correction, h.persist = correction, persist
    addf(h, "resource_slot", 0.5, "the sentence names a '" .. slot .. "' with a value as what to use")
    addf(h, "directive_framing", 0.4, "directive wording around the resource phrase")
    if correction then addf(h, "correction_cue", 0.4, "explicit correction / replacement marker") end
    if persist then addf(h, "persist_cue", 0.3, "applies to every later request") end
    out[#out + 1] = h
  end
  local retracted    -- { chunk, slot } of a resource phrase that an exclusion verb retracts ("Forget the 2022 dataset ...")
  -- a value written at chunk k: a year, a number or an identifier ("2021", "v3.2", "a.csv"); "the ONE" is a pronoun, not the number one
  local function value_at(k)
    local vc = C(S, k)
    if not vc or vc.masked or barrier(vc) and false then return nil end
    if vc.temporal and vc.temporal.year then return { year = vc.temporal.year, label = vc.text, expr = vc.temporal } end
    if vc.single and (vc.literal or vc.unit.kind == "ident" or (vc.unit.kind == "number" and vc.unit.numval and not vc.unit.ordinal)) then
      local prev = C(S, k - 1)
      if vc.unit.form == "one" and prev and prev.single and (cat(prev, "det") or prev.unit.form == "which") then return nil end
      return { word = vc.text, label = vc.text }
    end
  end
  local COPULA_FORMS = U.set({ "is", "was", "are", "be", "'s", "will", "should", "must" })
  -- words that may stand between a resource noun and its value: "dataset WITH THE ONE FROM 2026", "dataset FOR THE YEAR 2020", "dataset NAMED 2021"
  local VALUE_FILL = U.set({ "one", "ones", "year", "version", "number", "no", "id", "named", "called", "titled", "labelled", "labeled", "dubbed", "edition", "release", "from", "for", "of",
    "with", "to", "by", "using", "as", "in", "at", "covering", "dated", "marked", "tagged" })
  for i = S.first, S.last do
    local c = C(S, i)
    local slot = c and not c.masked and lex:resource(c.single and c.unit.form or c.form)
    if slot and not (slot == "solution") then
      local value
      local pc = C(S, i - 1)
      if pc and not pc.masked and not barrier(c) then value = value_at(i - 1) end
      if value and pc.single and pc.unit.kind == "number" and pc.unit.form == "one" then value = nil end
      if not value then
        -- a value after the noun, over at most six function words
        local k = i + 1
        for _ = 1, 6 do
          local cn = C(S, k)
          if not cn or cn.masked or (barrier(cn) and k > i + 1) then break end
          value = value_at(k)
          if value then break end
          if cn.single and (cat(cn, "det") or cat(cn, "prep") or VALUE_FILL[cn.unit.form]) then k = k + 1 else break end
        end
        -- predicate value: "the dataset I need IS the one for 2026", "the right dataset should be 2026"
        if not value then
          for jk = i + 1, math.min(S.last, i + 9) do
            local cj = C(S, jk)
            if cj and cj.single and not cj.masked and COPULA_FORMS[cj.unit.form] then
              local vk = jk + 1
              for _ = 1, 6 do
                local cn = C(S, vk)
                if not cn then break end
                value = value_at(vk)
                if value then break end
                if cn.single and (cat(cn, "det") or cat(cn, "prep") or cn.unit.form == "be" or VALUE_FILL[cn.unit.form]) then vk = vk + 1 else break end
              end
              break
            end
          end
        end
      end
      if value then
        -- the object of an exclusion verb ("Forget / Ignore / Drop the 2022 dataset") is retracted, not adopted
        local excluded = false
        for b = i - 1, math.max(S.first, i - 5), -1 do
          local bc = C(S, b)
          if bc and not bc.masked then
            for _, v in ipairs(bc.verbs or {}) do if v.act == "exclude" then excluded = true end end
            if excluded or (b < i - 1 and barrier(bc)) then break end
          end
        end
        if excluded then retracted = retracted or { chunk = c, slot = slot }
        else emit(c, slot, value); return end
      end
    end
  end
  -- "Forget the 2022 dataset and use 2024 instead.": the retracted phrase names the slot, the replacement is a bare value after a choosing verb
  if retracted then
    for k = S.first, S.last do
      local ck = C(S, k)
      if ck and ck.single and not ck.masked and REPLACE_VERBS[ck.unit.form] then
        local nk = k + 1
        local tc = C(S, nk)
        if tc and tc.single and not tc.masked and (tc.unit.form == "to" or tc.unit.form == "with") then nk = nk + 1 end
        local vc = C(S, nk)
        if vc and not vc.masked and not barrier(vc) then
          local value
          if vc.temporal and vc.temporal.year then value = { year = vc.temporal.year, label = vc.text, expr = vc.temporal }
          elseif vc.single and (vc.unit.kind == "ident" or (vc.unit.kind == "number" and vc.unit.numval and not vc.unit.ordinal)) then value = { word = vc.text, label = vc.text } end
          if value then emit(retracted.chunk, retracted.slot, value); return end
        end
      end
    end
  end
end

---------------------------------------------------------------- standing style / format instructions: "Always answer in metric units from now on."  "Reply in formal English."
-- A persistence marker (always, never, from now on, going forward) with a verb of communication and a manner phrase is a standing instruction about HOW to answer.
local STYLE_VERBS = U.set({ "answer", "respond", "reply", "write", "format", "present", "explain", "speak", "talk", "summarize", "summarise", "keep", "report", "express", "phrase", "address" })
local PERSIST_WORDS = U.set({ "always", "never", "henceforth", "hereafter" })
function F.style_instruction(S, out)
  local persist = false
  for _, ch in ipairs(S.chunks) do
    if ch.temporal and (ch.temporal.kind == "persist" or ch.temporal.persist) then persist = true end
    if ch.single and PERSIST_WORDS[ch.unit.form] then persist = true end
  end
  if not persist then return end
  for k = S.first, S.last do
    local c = C(S, k)
    if c and c.single and not c.masked and STYLE_VERBS[c.unit.form] then
      local pk = k + 1
      local ac = C(S, pk)
      -- "answer ONLY in French": a restricting adverb carries no content of its own here
      if ac and ac.single and not ac.masked and not barrier(ac) and (ac.unit.form == "only" or ac.unit.form == "just" or ac.unit.form == "exclusively" or ac.unit.form == "strictly" or ac.unit.form == "solely") then pk = pk + 1 end
      local pc = C(S, pk)
      -- the manner phrase:  in / with / using / as  X
      if pc and pc.single and not pc.masked and not barrier(pc) and (pc.unit.form == "in" or pc.unit.form == "with" or pc.unit.form == "using" or pc.unit.form == "as" or pc.unit.form == "like") then
        for _, np in ipairs(P.parse_np(S, pk + 1)) do
          local h = newh(S, "instruction:style", "instruction", "instruction_update", "instruct")
          for i = S.first, np.nxt - 1 do
            local ci = C(S, i)
            if ci and not ci.masked and (i >= k or (ci.single and (PERSIST_WORDS[ci.unit.form] or ci.temporal or cat(ci, "polite") or cat(ci, "adv") or cat(ci, "discourse")))) then h.used[i] = true end
          end
          -- trailing persistence marker ("... from now on")
          for i = np.nxt, S.last do local ci = C(S, i); if ci and ci.temporal and (ci.temporal.kind == "persist" or ci.temporal.persist) then h.used[i] = true end end
          h.instruction = { verb = c.unit.form, act = "constraint", np = np, slot = "style", value = { word = np.head and np.head.form or "", label = P.span_text(S, np) }, persist = true }
          h.persist = true
          addf(h, "style_instruction", 0.9, "a standing instruction about how to answer ('" .. c.unit.form .. " " .. pc.unit.form .. " ...')")
          addf(h, "persist_cue", 0.3, "applies from now on")
          out[#out + 1] = h
        end
      end
    end
  end
end

---------------------------------------------------------------- existential questions: "Is there a bakery in Wexmoor?"  "Are there any hospitals in Finland?"  -> a search for such things
local EXIST_FILLERS = U.set({ "anywhere", "somewhere", "around", "nearby", "locally" })
function F.existential_search(S, out)
  local c0, c1 = C(S, S.first), C(S, S.first + 1)
  if not (c0 and c1 and c0.single and c1.single and not c0.masked and not c1.masked and cat(c0, "aux_be") and c1.unit.form == "there" and not barrier(c1)) then return end
  local k = S.first + 2
  local qc = C(S, k)
  local lead = { S.first, S.first + 1 }
  if qc and qc.single and not qc.masked and not barrier(qc) and (qc.unit.form == "any" or qc.unit.form == "a" or qc.unit.form == "an" or qc.unit.form == "some") then
    lead[#lead + 1] = k; k = k + 1
  end
  for _, np in ipairs(P.parse_np(S, k, { no_of = false })) do
    -- "a decent plumber ANYWHERE around X": a place adverb before the locative phrase carries nothing
    local sk = np.nxt
    local ac = C(S, sk)
    local skipped = {}
    while ac and ac.single and not ac.masked and not barrier(ac) and EXIST_FILLERS[ac.unit.form] and not cat(ac, "prep") do skipped[#skipped + 1] = sk; sk = sk + 1; ac = C(S, sk) end
    if np.head_kind == "typenoun" or np.head_kind == "unknown" or np.head_kind == "concept" then
      local hs = {}
      F.from_object_np(S, hs, np, { act = "retrieve", lemma = "find" }, "question", lead)
      for _, h in ipairs(hs) do
        if h.intent == "search" then
          for _, i in ipairs(skipped) do h.used[i] = true end
          addf(h, "existential_question", 0.4, "'is there ...?' asks for such things")
          out[#out + 1] = h
        end
      end
    end
  end
end

---------------------------------------------------------------- yes/no with a support verb and a possessed relational noun: "Does X have its headquarters in Y?"
function F.yes_no_support(S, out)
  local c0 = C(S, S.first)
  if not (c0 and c0.single and not c0.masked and cat(c0, "aux_do") and not cat(c0, "wh")) then return end
  for _, snp in ipairs(P.parse_np(S, S.first + 1)) do
    for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do" })) do
      for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
        local dc = C(S, onp.c1)
        if onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and cat(dc, "poss_det") and onp.c1 < onp.nxt - 1 and (is_prep(C(S, onp.nxt), "in") or is_prep(C(S, onp.nxt), "at")) then
          for _, vnp in ipairs(P.parse_np(S, onp.nxt + 1)) do
            for _, o in ipairs(relnp_options(S, onp)) do
              local rel = o.rel
              local supported = (vp.lemma == "have" and rel.support_have) or false
              for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then supported = true end end
              if supported and o.ask_role == "to" then
                local h = newh(S, "yes_no:support_possessed", "question", "verification", "verify")
                use(h, S.first); use_np(h, snp); use_vp(h, vp); use_np(h, onp); use(h, onp.nxt); use_np(h, vnp)
                h.requires_evidence = true
                h.rel, h.rel_obj = rel.id, rel
                h.roles.from, h.roles.to = snp, vnp
                h.verify = { rel = rel.id, from = snp, to = vnp }
                h.items = { snp, vnp }
                addf(h, "support_construction", 0.8, "'" .. tostring(vp.lemma) .. "' + possessed '" .. rel.id .. "' noun, yes/no")
                mark_unresolved_pron(h, snp)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

return F

end

package.preload["asi.nlu.frames4"] = function(...)
-- asi.nlu.frames4: attribution and placement constructions (extends asi.nlu.frames / frames2 / frames3 on the same table; every function adds competing hypotheses).
--   wh_identity_person   "Who is the person serving as CEO of X?"                                   a reduced relative clause naming the post
--   wh_credit            "Who was behind the founding of X?"  "Who is credited with founding X?"     attribution idioms: the agent of the event named by a verb / derived noun
--                        "Who gets the credit for starting X?"  "Whom do we have to thank for founding X?"
--   wh_locus_host        "Which city hosts the headquarters of X?"  "Which city is home to X's head office?"
--   where_find           "Where can I find the headquarters of X?"  "In which city will I find the head office of X?"
--   wh_relnoun_same_pred "Which currency is legal tender in K?"                                       the predicate noun is another name of the relation the wh-noun names
--   generic_holder       "What currency do the locals use when they shop in K?"                      a generic subject is not the holder: the place named in the locative phrase is
-- Roles come from the relation lexicon (the subject role of the relation's verbs, the role a noun denotes) and from type fit, never from word proximity.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local F = require("asi.nlu.frames2")
require("asi.nlu.frames3")

local cat = P.cat
local newh, addf, use_np = F.newh, F.addf, F.use_np
local set_lookup, use_wh, use_vp = F.set_lookup, F.use_wh, F.use_vp
local is_be = F.is_be
local relnp_options, mark_unresolved_pron = F.relnp_options, F.mark_pron

local function C(S, k) return S.chunks[k] end
local function barrier(c) return c ~= nil and c.pre ~= nil end
local function other(role) return role == "to" and "from" or "to" end
local function use(h, a, b) for i = a, b or a do h.used[i] = true end end
-- the lower-case form of an ordinary (unmasked, unbroken) chunk
local function form_of(c) return c and not c.masked and not barrier(c) and (c.form or (c.unit and c.unit.form)) or nil end

-- does the phrase (space-separated words) start at chunk k, either as one chunk per word or as one multiword chunk?  -> index after it
local function phrase_at(S, k, phrase)
  local one = form_of(C(S, k))
  if one and one == phrase then return k + 1 end
  local j = k
  for w in phrase:gmatch("%S+") do
    local f = form_of(C(S, j))
    local c = C(S, j)
    if not (f and c.single and f == w) then return nil end
    j = j + 1
  end
  return j
end
local function first_phrase(S, k, phrases)
  for _, ph in ipairs(phrases) do
    local n = phrase_at(S, k, ph)
    if n then return n, ph end
  end
end

-- derived event nouns of the relations' verbs:  "founding" -> { founder (agent role "to") }
local function deverbal_index(lex)
  if lex._deverbal_index and lex._deverbal_rev == lex.revision then return lex._deverbal_index end
  local idx = {}
  for _, rel in ipairs(lex:all_rels()) do
    if not rel.open and rel.deverbals and #rel.deverbals > 0 then
      local agent
      for _, v in ipairs(rel.verbs or {}) do if not v.support and v.subj and not v.prep then agent = agent or v.subj end end
      for _, n in ipairs(rel.deverbals) do
        local k = n:lower()
        idx[k] = idx[k] or {}
        idx[k][#idx[k] + 1] = { rel = rel, agent = agent or "to" }
      end
    end
  end
  lex._deverbal_index, lex._deverbal_rev = idx, lex.revision
  return idx
end

---------------------------------------------------------------- "Who is the person serving as CEO of X?"
local PERSONISH = U.set({ "person", "one", "individual", "man", "woman", "executive", "guy", "gentleman", "lady", "official", "someone" })
local SERVING = U.set({ "serving as", "acting as", "working as", "functioning as", "operating as", "employed as", "sitting as" })
function F.wh_identity_person(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and (wh.wh == "who" or wh.wh == "whom") and not wh.np then
      local bk = wh.nxt
      local bc = C(S, bk)
      if is_be(bc) and not barrier(bc) then
        for _, tnp in ipairs(P.parse_np(S, bk + 1, { no_of = true })) do
          local th = tnp.head
          local sc = C(S, tnp.nxt)
          if th and th.single and PERSONISH[th.unit.form] and sc and SERVING[form_of(sc) or ""] then
            for _, rnp in ipairs(P.parse_np(S, tnp.nxt + 1)) do
              if rnp.head_kind == "relnoun" and (rnp.of_arg or rnp.possessor) then
                for _, o in ipairs(relnp_options(S, rnp)) do
                  if o.arg and o.rel and not o.rel.open then
                    local h = newh(S, "wh_identity_person", "question")
                    set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
                    use_wh(h, wh); use(h, bk); use_np(h, tnp); use(h, tnp.nxt); use_np(h, rnp)
                    addf(h, "serving_as_construction", 0.9, "'the person serving as <post noun> of X' asks who fills the post")
                    F.option_factors(h, o)
                    mark_unresolved_pron(h, o.arg)
                    out[#out + 1] = h
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- attribution idioms
-- cue phrases that follow the wh-word and introduce the attributed event
local CREDIT_NOUNS = U.set({ "credit", "recognition", "honour", "honor", "praise", "glory", "kudos", "thanks", "blame" })
local CREDIT_VERBS = U.set({ "get", "gets", "got", "getting", "deserve", "deserves", "deserved", "take", "takes", "took", "earn", "earns", "earned", "claim", "claims", "claimed",
  "receive", "receives", "received", "merit", "merits", "merited" })
local DET_SET = U.set({ "the", "a", "an", "some", "any", "due", "all", "full", "most", "much" })
local SKIP_AUX = U.set({ "do", "does", "did", "should", "would", "could", "can", "will", "must", "shall", "might", "may", "has", "have", "had", "ought", "really", "actually", "ultimately", "finally", "rightly" })
local SKIP_SUBJ = U.set({ "we", "i", "you", "people", "one", "they", "everyone", "anyone", "somebody", "someone" })
local SKIP_NEED = U.set({ "have", "has", "need", "needs", "ought", "must", "should", "got", "to", "always", "really", "ultimately" })

-- positions (chunk index after the cue) at which an attributed event may start; each entry also carries the chunk range of the cue
local function credit_cues(S, k)
  local res = {}
  local function add(n, from, to) if n then res[#res + 1] = { nxt = n, c1 = from, c2 = to } end end
  local c = C(S, k)
  if not c or c.masked then return res end
  -- "was behind ...", "was the driving force behind ...", "was responsible for ...", "is credited with ...", "is to thank for ..."
  if is_be(c) and not barrier(c) then
    local j = k + 1
    local cj = C(S, j)
    -- "have been" style perfect chains are tolerated by the parser upstream; here only the simple copula
    local n = phrase_at(S, j, "behind")
    add(n, k, j)
    -- "the driving force behind", "the brains behind", "the man behind": one to four ordinary chunks, then "behind"
    for m = j, math.min(j + 4, S.last) do
      local cm = C(S, m)
      if not cm or cm.masked or (m > j and barrier(cm)) then break end
      local nb = phrase_at(S, m + 1, "behind")
      if nb and m >= j then add(nb, k, m + 1) end
    end
    add(phrase_at(S, j, "responsible for"), k, j)
    add(phrase_at(S, j, "credited with"), k, j)
    add(phrase_at(S, j, "to thank for"), k, j)
    add(phrase_at(S, j, "the one to thank for"), k, j)
    add(phrase_at(S, j, "the person to thank for"), k, j)
    add(phrase_at(S, j, "the one responsible for"), k, j)
    add(phrase_at(S, j, "the person responsible for"), k, j)
    add(phrase_at(S, j, "the one behind"), k, j)
    add(phrase_at(S, j, "the person behind"), k, j)
    add(phrase_at(S, j, "accountable for"), k, j)
    add(phrase_at(S, j, "in charge of creating"), k, j)
  end
  -- "gets the credit for ...", "should get credit for ...", "deserves the credit for ...", "takes credit for ..."
  do
    local j = k
    while C(S, j) and not C(S, j).masked and not barrier(C(S, j)) and C(S, j).single and SKIP_AUX[C(S, j).unit.form] do j = j + 1 end
    local vc = C(S, j)
    if vc and vc.single and not vc.masked and not barrier(vc) and CREDIT_VERBS[vc.unit.form] then
      local m = j + 1
      while C(S, m) and C(S, m).single and not C(S, m).masked and not barrier(C(S, m)) and DET_SET[C(S, m).unit.form] do m = m + 1 end
      local nc = C(S, m)
      if nc and nc.single and not nc.masked and CREDIT_NOUNS[nc.unit.form] then
        local fc = C(S, m + 1)
        if fc and fc.single and not fc.masked and not barrier(fc) and fc.unit.form == "for" then add(m + 2, k, m + 1) end
      end
    end
  end
  -- "do we have to thank for ...", "should we thank for ...", "do I owe thanks to"  (the wh-word is the object of "thank")
  do
    local j = k
    local aux_seen = false
    while C(S, j) and not C(S, j).masked and not barrier(C(S, j)) and C(S, j).single and SKIP_AUX[C(S, j).unit.form] do j = j + 1; aux_seen = true end
    local sc = C(S, j)
    if aux_seen and sc and sc.single and not sc.masked and not barrier(sc) and SKIP_SUBJ[sc.unit.form] then
      local m = j + 1
      while C(S, m) and not C(S, m).masked and not barrier(C(S, m)) and C(S, m).single and SKIP_NEED[C(S, m).unit.form] do m = m + 1 end
      local tc, fc = C(S, m), C(S, m + 1)
      if tc and fc and tc.single and fc.single and not tc.masked and not fc.masked and not barrier(tc) and not barrier(fc) and tc.unit.form == "thank" and fc.unit.form == "for" then
        add(m + 2, k, m + 1)
      end
    end
  end
  return res
end

-- the attributed event: a gerund with its object ("founding X", "setting up X") or a derived noun with "of" ("the founding of X", "the creation of X")
local function credit_targets(S, t)
  local res = {}
  local c = C(S, t)
  if not c or c.masked or barrier(c) then return res end
  -- "credited with HAVING established O": a perfect gerund names the same event
  local perfect = false
  if c.single and c.unit.form == "having" then
    local nc = C(S, t + 1)
    if nc and not nc.masked and not barrier(nc) then perfect = true; t = t + 1; c = nc end
  end
  if c.single or c.kind == "mwe" then
    for _, a in ipairs(P.verb_analyses(S, c)) do
      if (not perfect and a.form == "ing") or (perfect and (a.form == "pp" or a.form == "past")) then
        for _, e in ipairs(a.entries or {}) do
          local rel = S.lex:get_rel(e.rel)
          if rel and not rel.open and not e.prep and not e.support and not e.as_only then
            for _, onp in ipairs(P.parse_np(S, t + 1)) do
              res[#res + 1] = { rel = rel, agent = e.subj, obj = onp, c1 = t, c2 = t, kind = "gerund" }
            end
          end
        end
      end
    end
  end
  local idx = deverbal_index(S.lex)
  for _, np in ipairs(P.parse_np(S, t)) do
    local hf = np.head and np.head.single and np.head.unit.form
    if hf and idx[hf] and np.of_arg then
      for _, d in ipairs(idx[hf]) do
        res[#res + 1] = { rel = d.rel, agent = d.agent, obj = np.of_arg, np = np, kind = "noun" }
      end
    end
  end
  return res
end

F.credit_cues, F.credit_targets, F.phrase_at, F.first_phrase, F.deverbal_index = credit_cues, credit_targets, phrase_at, first_phrase, deverbal_index

function F.wh_credit(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and (wh.wh == "who" or wh.wh == "whom" or wh.wh == "whose") and not wh.np and wh.wh ~= "whose" then
      for _, cue in ipairs(credit_cues(S, wh.nxt)) do
        for _, tg in ipairs(credit_targets(S, cue.nxt)) do
          local h = newh(S, "wh_credit", "question")
          set_lookup(h, tg.rel, other(tg.agent), tg.obj, tg.agent, wh)
          use_wh(h, wh); use(h, cue.c1, cue.nxt - 1)
          if tg.kind == "gerund" then use(h, tg.c1) else use_np(h, tg.np) end
          use_np(h, tg.obj)
          addf(h, "credit_construction", 0.9, "attribution idiom: the wh-word asks for the agent of the event '" .. tostring(tg.rel.id) .. "'")
          mark_unresolved_pron(h, tg.obj)
          out[#out + 1] = h
        end
      end
    end
  end
end

---------------------------------------------------------------- locus relations: which place hosts / is home to the thing
local HOST_LEMMAS = U.set({ "host", "house", "contain", "hold", "shelter", "accommodate", "harbour", "harbor", "have", "boast" })
local HOME_PHRASES = { "home to", "the home of", "the site of", "the seat of", "the base of", "the location of", "the location for", "the venue for", "the setting for", "host to", "the host of" }

F.HOME_PHRASES, F.HOST_LEMMAS = HOME_PHRASES, HOST_LEMMAS
local function locus_options(S, np)
  local opts = {}
  for _, o in ipairs(relnp_options(S, np)) do
    if o.arg and o.rel and not o.rel.open and o.rel.locus and o.ask_role == "to" then opts[#opts + 1] = o end
  end
  return opts
end

F.locus_options = locus_options

function F.wh_locus_host(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.np and wh.type then
      local function emit(onp, frame_note, k_after, extra_use)
        for _, o in ipairs(locus_options(S, onp)) do
          local h = newh(S, "wh_locus_host", "question")
          set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
          use_wh(h, wh); use_np(h, onp)
          for _, i in ipairs(extra_use) do use(h, i) end
          addf(h, "locus_host_construction", 0.9, frame_note)
          F.option_factors(h, o)
          mark_unresolved_pron(h, o.arg)
          out[#out + 1] = h
        end
      end
      -- (a) "Which city HOSTS the headquarters of X?"
      for _, vp in ipairs(P.parse_vp(S, wh.nxt)) do
        if vp.voice == "active" and HOST_LEMMAS[vp.lemma] then
          for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
            if onp.head_kind == "relnoun" then
              local used = {}
              for i = vp.c1, vp.c2 do used[#used + 1] = i end
              emit(onp, "'" .. tostring(vp.lemma) .. "' + a locus noun: the wh-place is the value of the relation", vp.nxt, used)
            end
          end
        end
      end
      -- (b) "Which city IS HOME TO the headquarters of X?"
      local bc = C(S, wh.nxt)
      if is_be(bc) and not barrier(bc) then
        local n, ph = first_phrase(S, wh.nxt + 1, HOME_PHRASES)
        if n then
          for _, onp in ipairs(P.parse_np(S, n)) do
            if onp.head_kind == "relnoun" then
              local used = { wh.nxt }
              for i = wh.nxt + 1, n - 1 do used[#used + 1] = i end
              emit(onp, "'" .. ph .. "' + a locus noun: the wh-place is the value of the relation", n, used)
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- "Where can I find the headquarters of X?"
local FIND_VERBS = U.set({ "find", "locate", "see", "spot", "discover", "reach" })
local FINDER = U.set({ "i", "we", "you", "one", "someone", "anyone", "somebody", "anybody", "people", "tourists", "visitors", "travellers", "travelers", "customers", "clients" })
function F.where_find(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    local where = wh.adverbial and wh.wh == "where"
    local pied = (not wh.adverbial) and wh.pied and wh.np and wh.type
    if where or pied then
      local ac = C(S, wh.nxt)
      if ac and ac.single and not ac.masked and not barrier(ac) and (cat(ac, "modal") or cat(ac, "aux_do")) then
        local sc = C(S, wh.nxt + 1)
        local vc = C(S, wh.nxt + 2)
        if sc and vc and sc.single and vc.single and not sc.masked and not vc.masked and not barrier(sc) and not barrier(vc)
          and FINDER[sc.unit.form] and FIND_VERBS[vc.unit.form] then
          for _, onp in ipairs(P.parse_np(S, wh.nxt + 3)) do
            if onp.head_kind == "relnoun" then
              for _, o in ipairs(locus_options(S, onp)) do
                local h = newh(S, "where_find", "question")
                set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
                use_wh(h, wh); use(h, wh.nxt, wh.nxt + 2); use_np(h, onp)
                if pied then h.pied_consumed = true end
                addf(h, "where_find_construction", 0.9, "'where can one find <locus noun>' asks for the value of " .. o.rel.id)
                F.option_factors(h, o)
                mark_unresolved_pron(h, o.arg)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- "Which currency is legal tender in K?"
local PLACE_PREPS = U.set({ "in", "of", "for", "at", "across", "throughout", "within" })
function F.wh_relnoun_same_pred(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.relnoun and wh.np and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much" then
      local bc = C(S, wh.nxt)
      if is_be(bc) and not barrier(bc) then
        local nk = wh.nxt + 1
        for _, pnp in ipairs(P.parse_np(S, nk, { no_of = true })) do
          if pnp.head_kind == "relnoun" and not pnp.of_arg and not pnp.possessor then
            local pc = C(S, pnp.nxt)
            if pc and pc.single and not pc.masked and not barrier(pc) and PLACE_PREPS[pc.unit.form] then
              for _, anp in ipairs(P.parse_np(S, pnp.nxt + 1)) do
                for _, we in ipairs(wh.np.relnouns or {}) do
                  for _, pe in ipairs(pnp.relnouns or {}) do
                    if pe.rel == we.rel and pe.role == we.role then
                      local rel = S.lex:get_rel(we.rel)
                      if rel and not rel.open then
                        local h = newh(S, "wh_relnoun_same_pred", "question")
                        set_lookup(h, rel, other(we.role), anp, we.role, wh)
                        use_wh(h, wh); use(h, wh.nxt); use_np(h, pnp); use(h, pnp.nxt); use_np(h, anp)
                        addf(h, "same_relation_predicate", 0.7, "the predicate noun '" .. tostring(pnp.head and pnp.head.form) .. "' is another name of " .. rel.id .. ", the relation the wh-noun names")
                        F.wh_relnoun_agreement(h, wh, rel)
                        mark_unresolved_pron(h, anp)
                        out[#out + 1] = h
                      end
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- generic subjects: "What currency do the locals use when they shop in K?"
-- A generic subject (they, people, the locals) cannot hold a country-level relation: the place named in a locative phrase of the sentence is the holder.
local GENERIC_NOUN = U.set({ "locals", "people", "residents", "citizens", "inhabitants", "natives", "folks", "visitors", "tourists", "travellers", "travelers", "shoppers",
  "customers", "everyone", "everybody", "nationals", "countrymen", "population", "public", "workers", "students", "shopkeepers", "merchants", "traders", "farmers" })
local GENERIC_PRON = U.set({ "they", "you", "one", "we", "everyone", "everybody", "people" })
local LOC_PREPS = U.set({ "in", "at", "across", "throughout", "within", "around", "inside", "to", "for", "from", "into", "of" })

local function generic_np(np)
  if not np then return false end
  if np.head_kind == "pronoun" then return GENERIC_PRON[np.pron and np.pron.form or ""] == true end
  if np.head and np.head.single and GENERIC_NOUN[np.head.unit.form] and not np.of_arg then return true end
  return false
end

function F.generic_holder(S, out)
  local n0 = #out
  for hi = 1, n0 do
    local h = out[hi]
    if h.op == "lookup" and h.rel_obj and not h.rel_obj.open and h.known_role and h.roles and h.roles[h.known_role] and not h.generic_rebound then
      local gnp = h.roles[h.known_role]
      local role_type = h.rel_obj[h.known_role]
      if generic_np(gnp) then
        -- candidate holders: a name in a locative phrase that this hypothesis leaves unused, of a type the relation's holder accepts
        local found, count = nil, 0
        for k = S.first, S.last do
          local pc = C(S, k)
          if pc and pc.single and not pc.masked and LOC_PREPS[pc.unit.form] and not h.used[k] then
            for _, np in ipairs(P.parse_np(S, k + 1)) do
              if (np.head_kind == "entity" or (np.head_kind == "unknown" and np.head and np.head.cap)) and not np.det and not np.poss_det then
                local ty
                for _, cd in ipairs(np.cands or {}) do ty = ty or cd.type end
                if np.head and np.head.names and np.head.names[1] then ty = ty or np.head.names[1].type_guess end
                if S.lex:compat(ty, role_type) > -1.0 then found = found or { prep = k, np = np }; count = count + 1 end
                break
              end
            end
          end
        end
        if found and count == 1 then
          local h2 = U.shallow(h)
          h2.roles, h2.used, h2.factors = U.shallow(h.roles), U.shallow(h.used), U.shallow(h.factors)
          h2.pronouns = nil
          h2.roles[h.known_role] = found.np
          use(h2, found.prep); use_np(h2, found.np)
          h2.generic_rebound = true
          addf(h2, "generic_subject_holder", 0.9, "the generic subject '" .. P.span_text(S, gnp) .. "' is not the holder; the place named in the locative phrase is")
          out[#out + 1] = h2
        end
      end
    end
  end
end

---------------------------------------------------------------- "Which country is Kyoto in?"   (a typed place wh-noun + copula + subject + stranded "in")
function F.wh_place_stranded_in(S, out)
  local lrel = S.lex:get_rel("located_in")
  if not lrel then return end
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.np and wh.type and S.lex:compat(wh.type, "place") >= 0.9 and not wh.pied then
      local bc = C(S, wh.nxt)
      if is_be(bc) and not barrier(bc) then
        for _, snp in ipairs(P.parse_np(S, wh.nxt + 1)) do
          local pc = C(S, snp.nxt)
          if pc and pc.single and not pc.masked and not barrier(pc) and pc.unit.form == "in" and snp.nxt == S.last then
            local h = newh(S, "wh_place_stranded_in", "question")
            set_lookup(h, lrel, "from", snp, "to", wh)
            use_wh(h, wh); use(h, wh.nxt); use_np(h, snp); use(h, snp.nxt)
            addf(h, "stranded_in_place", 0.7, "'Which " .. tostring(wh.type) .. " is X in?' asks for the place that contains X")
            mark_unresolved_pron(h, snp)
            out[#out + 1] = h
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- comparisons with an explicit dimension
--   "Compare the populations of Chile and Peru."   "Compare Tesla and Toyota by revenue."   "How does Norway compare with Sweden and Denmark in terms of area?"
--   "Rank Mount Everest, K2 and Kangchenjunga by height."
-- The dimension is a number-valued relation named by a relational noun; the items are the things compared.
local function numeric_rel(S, np)
  if not np or np.head_kind ~= "relnoun" then return nil end
  for _, e in ipairs(np.relnouns or {}) do
    local rel = S.lex:get_rel(e.rel)
    if rel and not rel.open and e.role == "to" and S.lex:compat(rel.to, "number") >= 0.9 then return rel end
  end
end

-- the unique defined relation of a measurable dimension ("height" -> height); nil when the dimension spans several ("age", "size")
function F.dim_unique_rel(lex, dim)
  local d = lex.dims and lex.dims[dim] or (lex.parent and lex.parent.dims and lex.parent.dims[dim])
  if not d then return nil end
  local found
  for _, rid in ipairs(d.rels or {}) do
    local r = lex:get_rel(rid)
    if r and not r.open then
      if found then return nil end
      found = r
    end
  end
  return found
end

local DIM_CUES = { "in terms of", "by", "on", "regarding", "with respect to", "as to", "according to", "based on", "using", "for" }
-- "(by|in terms of|on ...) [the] DIM"  ->  rel, np, next chunk
local function trailing_dimension(S, k)
  local n = first_phrase(S, k, DIM_CUES)
  if not n then return nil end
  local dc = C(S, n)
  if dc and dc.single and not dc.masked and cat(dc, "det") then n = n + 1 end
  for _, np in ipairs(P.parse_np(S, n, { no_of = true })) do
    local rel = numeric_rel(S, np)
    if rel then return rel, np, np.nxt end
  end
end

local ITEM_JOINERS = U.set({ "and", "or", "versus", "vs", "vs.", "against", "with", "to", "&", "and/or" })
-- items "A, B and C" / "A with B": returns the NPs and the chunk after the last
local function item_list(S, k, limit)
  local items = {}
  local cur = k
  for _ = 1, 8 do
    local np
    for _, cand_np in ipairs(P.parse_np(S, cur, { no_of = true })) do
      if cand_np.head_kind ~= "relnoun" or #items == 0 then np = cand_np; break end
    end
    if not np then break end
    items[#items + 1] = np
    cur = np.nxt
    local nx = C(S, cur)
    if not nx or nx.masked then break end
    if nx.single and ITEM_JOINERS[nx.unit.form] and not (nx.pre and false) then cur = cur + 1
    elseif nx.pre and nx.pre:find("comma") then
      -- ", and C" or ", C"
      local c2 = C(S, cur + 1)
      if nx.single and ITEM_JOINERS[nx.unit.form] then cur = cur + 1 elseif nx.single and cat(nx, "prep") then break end
    else break end
    if limit and cur > limit then break end
  end
  return items, cur
end

F.item_list = item_list

local COMPARE_VERBS = U.set({ "compare", "contrast", "benchmark", "weigh" })
local RANK_VERBS = U.set({ "rank", "sort", "order", "arrange", "list" })
function F.compare_dimension(S, out)
  local vc = C(S, S.first)
  -- (1) imperative "Compare ..."   (2) imperative "Rank ... by DIM"
  if vc and vc.single and not vc.masked and (COMPARE_VERBS[vc.unit.form] or RANK_VERBS[vc.unit.form]) then
    local ranking = RANK_VERBS[vc.unit.form] and not COMPARE_VERBS[vc.unit.form]
    local k = S.first + 1
    local first_np
    -- "the populations of Chile and Peru": the dimension noun with the first item as its argument
    for _, np in ipairs(P.parse_np(S, k)) do
      local rel = numeric_rel(S, np)
      if rel and np.of_arg and not ranking then
        local items, endk = { np.of_arg }, np.nxt
        local jc = C(S, endk)
        if jc and not jc.masked then
          -- "of A and B" / "of A, B and C": a joiner or a comma follows the first item
          local joiner = jc.single and ITEM_JOINERS[jc.unit.form]
          if joiner or (jc.pre and jc.pre:find("comma")) then
            local rest, e2 = item_list(S, joiner and endk + 1 or endk)
            for _, it in ipairs(rest) do items[#items + 1] = it end
            endk = e2
          end
        end
        if #items >= 2 then
          local h = newh(S, "compare_dimension:noun", "request", "comparison", "compare")
          use(h, S.first); use_np(h, np)
          for _, it in ipairs(items) do use_np(h, it) end
          for i = np.nxt, endk - 1 do h.used[i] = true end
          h.items, h.rel, h.rel_obj, h.dimension = items, rel.id, rel, "size"
          h.requires_evidence = true
          addf(h, "comparison_items", 0.5, #items .. " items to compare on " .. rel.id)
          addf(h, "dimension_noun", 0.5, "'" .. tostring(np.head and np.head.form) .. "' names the compared dimension")
          out[#out + 1] = h
        end
      end
    end
    -- plain item list + trailing dimension
    local items, endk = item_list(S, k)
    if #items >= (ranking and 2 or 2) then
      local rel, dnp, after = trailing_dimension(S, endk)
      if rel then
        local h = newh(S, ranking and "compare_dimension:rank" or "compare_dimension:by", "request", "comparison", ranking and "rank" or "compare")
        use(h, S.first)
        for _, it in ipairs(items) do use_np(h, it) end
        for i = items[#items].nxt, after - 1 do h.used[i] = true end
        h.items, h.rel, h.rel_obj, h.dimension = items, rel.id, rel, "size"
        h.requires_evidence = true
        addf(h, "comparison_items", 0.5, #items .. " items on " .. rel.id)
        addf(h, "dimension_noun", 0.5, "'" .. tostring(dnp.head and dnp.head.form) .. "' names the compared dimension")
        out[#out + 1] = h
      end
    end
  end
  -- (3) "How does A compare with B and C in terms of DIM?"
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.adverbial and wh.wh == "how" then
      local dc = C(S, wh.nxt)
      if dc and dc.single and not dc.masked and cat(dc, "aux_do") then
        for _, snp in ipairs(P.parse_np(S, wh.nxt + 1, { no_of = true })) do
          local cvc = C(S, snp.nxt)
          local pc = C(S, snp.nxt + 1)
          if cvc and cvc.single and not cvc.masked and COMPARE_VERBS[cvc.unit.form] and pc and pc.single and ITEM_JOINERS[pc.unit.form] then
            local rest, endk = item_list(S, snp.nxt + 2)
            if #rest >= 1 then
              local items = { snp }
              for _, it in ipairs(rest) do items[#items + 1] = it end
              local rel, dnp, after = trailing_dimension(S, endk)
              local h = newh(S, "compare_dimension:how", "question", "comparison", "compare")
              use_wh(h, wh); use(h, wh.nxt); use_np(h, snp); use(h, snp.nxt, snp.nxt + 1)
              for _, it in ipairs(rest) do use_np(h, it) end
              if rel then
                for i = endk, after - 1 do h.used[i] = true end
                h.rel, h.rel_obj = rel.id, rel
              end
              h.items, h.dimension = items, "size"
              h.requires_evidence = true
              addf(h, "comparison_items", 0.5, #items .. " items compared")
              if rel then addf(h, "dimension_noun", 0.5, "'" .. tostring(dnp.head and dnp.head.form) .. "' names the compared dimension") end
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- wh-questions whose answer is the set defined by filters
--   "Which cities in Germany have more than a million inhabitants?"   "Which cities are in Germany?"   "Which companies have more than 500 employees?"
--   "What companies were founded after 1990?"
-- The wh-noun is the target set; the rest of the sentence is the same chain of filters a "Find ..." request would carry.
function F.which_filtered(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    local nnp = wh.np
    if nnp and not wh.adverbial and not wh.relnoun and (wh.wh == "which" or wh.wh == "what") and nnp.plural and not nnp.of_arg
      and (nnp.head_kind == "typenoun" or nnp.head_kind == "unknown") then
      local k = wh.nxt
      local cop = C(S, k)
      local used_cop
      -- "Which cities ARE in Germany?": the copula joins the target to its filters
      if cop and cop.single and not cop.masked and not barrier(cop) and (cat(cop, "aux_be") or cat(cop, "aux_have") and false) then used_cop = k; k = k + 1 end
      local filters, kf = F.parse_filters(S, k, nnp)
      if #filters > 0 and kf > S.last then
        local h = newh(S, "wh_which:filtered", "question", "search", "search")
        use_wh(h, wh); use_np(h, nnp)
        if used_cop then use(h, used_cop) end
        h.target, h.filters = nnp, filters
        for _, f in ipairs(filters) do for i = f.span.first, f.span.last do h.used[i] = true end end
        h.requires_evidence = true
        h.wh = wh
        addf(h, "search_target", 0.5, "typed target set")
        addf(h, "filters_parsed", 0.15 * #filters, #filters .. " filter(s) from the clause")
        -- a lookup of a known relation reads the same words more exactly; the set reading is the fallback for questions no relation covers
        addf(h, "filtered_set_fallback", -0.6, "the question asks for the members of a set defined by filters")
        if nnp.head_kind == "unknown" then addf(h, "unknown_target_type", -0.1, "search target type is not in the lexicon") end
        out[#out + 1] = h
      end
    end
  end
end

---------------------------------------------------------------- superlative questions over a typed set
--   "What is the biggest city in Canada?"   "Which is the largest country in Africa?"   "What's the tallest mountain in Peru?"
-- The answer is the member of the type that is extreme on the superlative's dimension: a search with an ordering, not a definition.
function F.wh_superlative(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.np and not wh.adverbial and not wh.one and (wh.wh == "what" or wh.wh == "which") then
      local bc = C(S, wh.nxt)
      if bc and bc.single and not bc.masked and not barrier(bc) and (cat(bc, "aux_be") or cat(bc, "clitic_s")) then
        for _, np in ipairs(P.parse_np(S, wh.nxt + 1, { no_of = true })) do
          if np.superlative and (np.head_kind == "typenoun" or np.head_kind == "unknown") and not np.of_arg then
            local filters, kf = F.parse_filters(S, np.nxt, np)
            if kf > S.last then
              local h = newh(S, "wh_superlative:search", "question", "search", "search")
              use_wh(h, wh); use(h, wh.nxt); use_np(h, np)
              h.target, h.filters = np, filters
              for _, f in ipairs(filters) do for i = f.span.first, f.span.last do h.used[i] = true end end
              h.requires_evidence = true
              h.ordering = { superlative = np.superlative }
              addf(h, "superlative_target", 0.9, "'" .. tostring(np.superlative) .. "' over a typed set asks for its extreme member")
              if #filters > 0 then addf(h, "filters_parsed", 0.15 * #filters, #filters .. " filter(s) from the clause") end
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- passive yes/no questions without an agent, and dated ones
--   "Was Nokia acquired?"   "Has Nokia ever been acquired?"   "Was Instagram founded in 2010?"   "Was Napoleon born before 1800?"
-- Without a qualifier the question asks whether the relation holds for the subject at all; with a date it asks about the date relation the verb links to (founded -> founding date).
function F.yes_no_passive(S, out)
  local k0 = S.first
  local c0 = C(S, k0)
  if not (c0 and c0.single and not c0.masked and (cat(c0, "aux_be") or cat(c0, "aux_have"))) then return end
  local hint = cat(c0, "aux_be") and "be" or "have"
  local nstart, neg_first = k0 + 1, nil
  if P.is_neg(C(S, nstart)) and not barrier(C(S, nstart)) then neg_first = nstart; nstart = nstart + 1 end
  for _, np1 in ipairs(P.parse_np(S, nstart)) do
    for _, vp in ipairs(P.parse_vp(S, np1.nxt, { aux_hint = hint })) do
      if vp.voice == "passive" then
        for _, e in ipairs(vp.analysis.entries or {}) do
          local rel = S.lex:get_rel(e.rel)
          if rel and not rel.open and not e.support and not e.as_only then
            local tc = C(S, vp.nxt)
            local frame, vrel, np2
            if vp.nxt > S.last then
              frame, vrel = "yes_no:passive_any", rel
            elseif tc and not tc.masked and tc.temporal and tc.temporal.kind ~= "marker" and tc.temporal.kind ~= "relative" then
              local trel = rel.when and S.lex:get_rel(rel.when) or nil
              if not trel and S.lex:compat(rel.to, "date") >= 0.9 then trel = rel end
              if trel then
                for _, dnp in ipairs(P.parse_np(S, vp.nxt)) do
                  if dnp.nxt > S.last and dnp.head_kind ~= "relnoun" then np2 = dnp; frame, vrel = "yes_no:passive_dated", trel; break end
                end
              end
            end
            if frame then
              local h = newh(S, frame, "question", "verification", "verify")
              use(h, k0); use_np(h, np1); use_vp(h, vp)
              if neg_first then use(h, neg_first); h.polarity = "negative" end
              h.rel, h.rel_obj = vrel.id, vrel
              if np2 then
                use_np(h, np2)
                h.roles.from, h.roles.to = np1, np2
                h.items = { np1, np2 }
              else
                h.roles[other(e.subj)] = np1
                h.items = { np1 }
              end
              h.verify = { rel = vrel.id, from = h.roles.from, to = h.roles.to }
              h.requires_evidence = true
              addf(h, "passive_verification", 0.6, np2 and "a passive verb with a date asks about the date relation of the subject" or "a passive verb without an agent asks whether the relation holds at all")
              mark_unresolved_pron(h, np1)
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- comparison verified through a relation's value
--   "Does Apple have more employees than Google?"   "Does Tokyo have a larger population than Osaka?"   "Is Tokyo more populous than Osaka?"
local CMP_MORE = U.set({ "more", "larger", "bigger", "greater", "higher", "longer", "taller" })
local CMP_LESS = U.set({ "fewer", "less", "smaller", "lower", "shorter" })
function F.verify_comparison(S, out)
  local k0 = S.first
  local c0 = C(S, k0)
  if not (c0 and c0.single and not c0.masked and cat(c0, "aux_do")) then return end
  for _, np1 in ipairs(P.parse_np(S, k0 + 1, { no_of = true })) do
    local hc = C(S, np1.nxt)
    if hc and hc.single and not hc.masked and not barrier(hc) and hc.unit.form == "have" then
      local k = np1.nxt + 1
      local dc = C(S, k)
      if dc and dc.single and not dc.masked and cat(dc, "det") then k = k + 1 end
      local cw = C(S, k)
      local dir = cw and cw.single and not cw.masked and (CMP_MORE[cw.unit.form] and "gt" or CMP_LESS[cw.unit.form] and "lt") or nil
      if dir then
        local nc = C(S, k + 1)
        local rel
        for _, ee in ipairs(nc and nc.relnouns or {}) do
          local r = S.lex:get_rel(ee.rel)
          if r and not r.open and ee.role == "to" and S.lex:compat(r.to, "number") >= 0.9 then rel = r; break end
        end
        local tcnk = C(S, k + 2)
        if rel and tcnk and tcnk.single and not tcnk.masked and tcnk.unit.form == "than" then
          for _, np2 in ipairs(P.parse_np(S, k + 3, { no_of = true })) do
            -- an optional trailing "have" repeats the verb: "... than Google has"
            local endk = np2.nxt
            local tl = C(S, endk)
            if tl and tl.single and not tl.masked and (tl.unit.form == "have" or tl.unit.form == "has") then endk = endk + 1 end
            if endk > S.last then
              local h = newh(S, "compare_q:have_more", "question", "verification", "verify_comparison")
              use(h, k0); use_np(h, np1); use(h, np1.nxt, k + 2); use_np(h, np2)
              for i = np2.nxt, endk - 1 do h.used[i] = true end
              h.items = { np1, np2 }
              h.rel, h.rel_obj = rel.id, rel
              h.dimension, h.degree, h.adj = "size", "comp", cw.unit.form
              h.cmp = { op = dir, rel = rel.id }
              h.requires_evidence = true
              addf(h, "comparative_relnoun", 0.7, "'" .. cw.unit.form .. " " .. tostring(nc.unit.form) .. " than' compares the values of " .. rel.id)
              mark_unresolved_pron(h, np1); mark_unresolved_pron(h, np2)
              out[#out + 1] = h
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- bans stated as what must (not) appear
--   "Agencies should never appear in your answers."   "Make sure agencies never show up in your answers."   "Don't let agencies show up in your answers."
--   "Please make sure there are no agencies in the results."   "Leave agencies out of the results."   "Take agencies off the list."
-- All of them exclude the noun phrase from the results; the particle verbs put the object BETWEEN verb and particle, which the cue-led exclusion segments do not see.
local APPEAR_PHRASES = { "show up", "shows up", "showing up", "appear", "appears", "appearing", "come up", "comes up", "turn up", "turns up", "pop up", "pops up", "surface", "surfaces",
  "occur", "occurs", "feature", "features", "be included", "be listed", "be shown", "be returned", "be displayed", "be present", "be there", "be in", "be among", "creep in", "slip in", "get in",
  "get through", "make it in", "make it into", "end up in" }
local PARTICLE_VERBS = U.set({ "leave", "keep", "take", "cut", "weed", "filter", "strike", "screen", "throw", "kick", "drop", "rule", "block", "shut", "sort", "leave" })
local PARTICLES = U.set({ "out", "off", "away" })
local MODALS_BAN = U.set({ "should", "must", "shall", "will", "can", "may", "might", "ought", "could", "would" })
local NEG_WORDS_BAN = U.set({ "never", "not", "no longer", "n't" })
local MAKE_SURE = { "make sure that", "make sure", "ensure that", "ensure", "see to it that", "be sure that", "be sure", "check that", "just make sure", "please make sure", "do make sure" }

local MAKE_SURE_WORDS = U.set({ "make", "sure", "ensure", "check", "see", "to", "it", "that", "be", "careful", "just", "do", "also", "and", "so", "please", "kindly", "always", "okay", "ok", "yes", "oh" })
local function ban_hyp(S, frame, np, from, to, verb)
  local persist = false
  for _, ch in ipairs(S.chunks) do
    if ch.temporal and (ch.temporal.kind == "persist" or ch.temporal.persist) then persist = true end
    if ch.single and ch.unit and (ch.unit.form == "always" or ch.unit.form == "never") then persist = true end
  end
  local h = newh(S, "instruction:" .. frame, "instruction", "instruction_update", "instruct")
  for i = from, to do if C(S, i) then h.used[i] = true end end
  use_np(h, np)
  -- the frame words in front of the clause ("make sure", "ensure that", "see to it that", "be careful that") belong to the instruction too
  for i = S.first, from - 1 do
    local ci = C(S, i)
    if ci and ci.single and ci.unit and MAKE_SURE_WORDS[ci.unit.form] then h.used[i] = true end
  end
  -- a persistence marker or a polite word around the clause belongs to the instruction too
  for i = S.first, S.last do
    local ci = C(S, i)
    if ci and ((ci.temporal and (ci.temporal.kind == "persist" or ci.temporal.persist)) or (ci.single and ci.unit and (cat(ci, "polite") or cat(ci, "discourse")))) then h.used[i] = true end
  end
  h.instruction = { verb = verb, act = "exclude", np = np, correction = false, persist = persist }
  h.polarity = "negative"
  h.persist = persist
  addf(h, "exclusion_clause", 0.9, "an exclusion is stated (" .. frame .. ")")
  if persist then addf(h, "persist_cue", 0.3, "applies from now on") end
  mark_unresolved_pron(h, np)
  return h
end

local function ban_scan(S, out)
  if S.sentence and S.sentence.question_mark then return end
  local function neg_at(k)
    local c = C(S, k)
    if not (c and c.single and c.unit and not barrier(c)) then return nil end
    if c.unit.form == "never" or P.is_neg(c) then return k + 1 end
  end
  local function appear_at(k)
    for _, ph in ipairs(APPEAR_PHRASES) do
      local n = phrase_at(S, k, ph)
      if n then return n end
    end
  end
  for k = S.first, math.min(S.last, S.first + 199) do      -- a request is short; longer inputs are not scanned for bans here
    -- (A) NP [modal] never|not APPEAR: find the negation first, then the noun phrase that ends right before it (a bounded look-back keeps this linear)
    local nk0 = neg_at(k)
    if nk0 then
      local e = appear_at(nk0)
      if e then
        local end_before = k
        local pm = C(S, k - 1)
        if pm and pm.single and pm.unit and MODALS_BAN[pm.unit.form] and k - 1 > S.first then end_before = k - 1 end
        local made = false
        for kstart = math.max(S.first, end_before - 6), end_before - 1 do
          if made then break end
          for _, np in ipairs(P.parse_np(S, kstart, { no_of = false })) do
            if np.c1 == kstart and np.nxt == end_before and (np.head_kind == "typenoun" or np.head_kind == "unknown" or np.head_kind == "concept" or np.head_kind == "entity" or np.head_kind == "relnoun") then
              out[#out + 1] = ban_hyp(S, "appearance", np, kstart, e - 1, "appear")
              made = true
              break
            end
          end
        end
      end
    end
    -- (C) don't let|allow|have NP APPEAR
    local c = C(S, k)
    if c and c.single and (cat(c, "aux_do") or cat(c, "modal")) and not c.masked then
      local nk = neg_at(k + 1)
      if nk then
        local lc = C(S, nk)
        if lc and lc.single and (lc.unit.form == "let" or lc.unit.form == "allow" or lc.unit.form == "have" or lc.unit.form == "permit") then
          for _, np in ipairs(P.parse_np(S, nk + 1)) do
            local e = appear_at(np.nxt)
            if e then out[#out + 1] = ban_hyp(S, "let_appear", np, k, e - 1, "let") end
          end
        end
      end
    end
    -- (D) make sure there are no NP in the results / there should be no NP
    local tc = C(S, k)
    if tc and tc.single and tc.unit and tc.unit.form == "there" and not tc.masked then
      local bk = k + 1
      local bc = C(S, bk)
      if bc and bc.single and MODALS_BAN[bc.unit.form] then bk = bk + 1; bc = C(S, bk) end
      if bc and bc.single and (cat(bc, "aux_be") or bc.unit.form == "be") then
        local nc = C(S, bk + 1)
        if nc and nc.single and nc.unit.form == "no" then
          for _, np in ipairs(P.parse_np(S, bk + 2)) do
            out[#out + 1] = ban_hyp(S, "no_existential", np, k, np.nxt - 1, "exclude")
          end
        end
      end
    end
    -- (E) leave|keep|take NP out|off (of|from X)
    if c and c.single and PARTICLE_VERBS[c.unit.form] and not c.masked then
      for _, np in ipairs(P.parse_np(S, k + 1, { no_of = false })) do
        local pc = C(S, np.nxt)
        if pc and pc.single and PARTICLES[pc.unit.form] and not barrier(pc) then
          local e = np.nxt
          local oc = C(S, e + 1)
          if oc and oc.single and (oc.unit.form == "of" or oc.unit.form == "from") then
            local nps = P.parse_np(S, e + 2)
            e = nps[1] and (nps[1].nxt - 1) or (e + 1)
          end
          out[#out + 1] = ban_hyp(S, "particle_out", np, k, e, c.unit.form)
        end
      end
    end
  end
end

function F.appearance_ban(S, out)
  -- the exclusion cue words of the sentence mask exactly what this frame reads: lift the masks while scanning
  local saved
  for i, ch in ipairs(S.chunks) do if ch.masked then saved = saved or {}; saved[i] = ch.mask_kind or true end end
  if saved then
    for i in pairs(saved) do S.chunks[i].masked = nil end
    S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
  end
  local ok, err = pcall(ban_scan, S, out)
  if saved then
    for i, kind in pairs(saved) do S.chunks[i].masked = true; S.chunks[i].mask_kind = kind ~= true and kind or nil end
    S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
  end
  if not ok then error(err, 0) end
end

---------------------------------------------------------------- relational statements
--   "Paris is the capital of France."   "The capital of France is Paris."   "Acme was founded by Jane Doe."   "Acme is headquartered in Oslo."
-- With a negated copula ("Paris is not the capital of France.") the polarity is negative.  A statement that is asked for confirmation (", right?", "Is it true that ...")
-- becomes a verification in asi.nlu.sem.
local function is_prep_chunk(c, form) return c and c.single and not c.masked and cat(c, "prep") and (form == nil or c.unit.form == form) end
function F.statement_relational(S, out)
  if S.sentence and S.sentence.question_mark and not S.polar then return end
  for _, np1 in ipairs(P.parse_np(S, S.first)) do
    local bk = np1.nxt
    local bc = C(S, bk)
    if is_be(bc) and not barrier(bc) then
      local nk, neg_chunk = bk + 1, nil
      local nc = C(S, nk)
      if nc and P.is_neg(nc) and not barrier(nc) then neg_chunk = nk; nk = nk + 1 end
      local function base(frame)
        local h = newh(S, frame, "statement", "statement", "assert")
        use_np(h, np1); use(h, bk)
        if neg_chunk then use(h, neg_chunk); h.polarity = "negative" end
        mark_unresolved_pron(h, np1)
        return h
      end
      for _, np2 in ipairs(P.parse_np(S, nk)) do
        for _, pair in ipairs({ { np1, np2 }, { np2, np1 } }) do
          local value, relnp = pair[1], pair[2]
          if relnp.head_kind == "relnoun" and value.head_kind ~= "relnoun" and value.head_kind ~= "pronoun" then
            for _, o in ipairs(relnp_options(S, relnp)) do
              if o.arg and o.rel and not o.rel.open then
                local h = base("statement:be_rel")
                use_np(h, np2)
                h.rel, h.rel_obj = o.rel.id, o.rel
                h.roles[o.known_role] = o.arg
                h.roles[o.ask_role] = value
                h.known_role = o.known_role
                addf(h, "relnp_statement", 0.5, "statement of a relational fact")
                F.option_factors(h, o)
                mark_unresolved_pron(h, o.arg); mark_unresolved_pron(h, value)
                out[#out + 1] = h
              end
            end
          end
        end
      end
      for _, vp in ipairs(P.parse_vp(S, bk)) do
        if vp.voice == "passive" then
          for _, e in ipairs(vp.analysis.entries or {}) do
            local rel = S.lex:get_rel(e.rel)
            if rel and not rel.open and not e.support and not e.as_only then
              local pc = C(S, vp.nxt)
              local frame, ok_prep
              if e.prep and is_prep_chunk(pc, e.prep) then frame, ok_prep = "statement:be_stative", true
              elseif not e.prep and is_prep_chunk(pc, "by") then frame, ok_prep = "statement:be_passive", true end
              if ok_prep then
                for _, np2 in ipairs(P.parse_np(S, vp.nxt + 1)) do
                  local h = base(frame)
                  use_vp(h, vp); use(h, vp.nxt); use_np(h, np2)
                  h.rel, h.rel_obj = rel.id, rel
                  if e.prep then h.roles[e.subj] = np1; h.roles[other(e.subj)] = np2
                  else h.roles[other(e.subj)] = np1; h.roles[e.subj] = np2 end
                  if vp.neg then h.polarity = "negative" end
                  addf(h, "relation_statement", 0.5, "statement over a relation verb (" .. tostring(vp.voice) .. ")")
                  mark_unresolved_pron(h, np2)
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
    elseif bc and not bc.masked and not (S.wrapper and #S.wrapper.kinds > 0) then
      -- active voice with a prepositional relation verb: "I work at Ithari Foundry.", "Acme operates in Germany."
      -- (not after a request wrapper: "I need solar installers based in X" is a request whose object carries a participial clause)
      for _, vp in ipairs(P.parse_vp(S, bk)) do
        if vp.voice ~= "passive" and not vp.neg then
          for _, e in ipairs(vp.analysis.entries or {}) do
            local rel = S.lex:get_rel(e.rel)
            if rel and not rel.open and not e.support and not e.as_only and e.prep and is_prep_chunk(C(S, vp.nxt), e.prep) then
              for _, np2 in ipairs(P.parse_np(S, vp.nxt + 1)) do
                local h = newh(S, "statement:active_prep", "statement", "statement", "assert")
                use_np(h, np1); use_vp(h, vp); use(h, vp.nxt); use_np(h, np2)
                h.rel, h.rel_obj = rel.id, rel
                h.roles[e.subj] = np1; h.roles[other(e.subj)] = np2
                addf(h, "relation_statement", 0.5, "statement over a relation verb with a preposition (active)")
                mark_unresolved_pron(h, np1); mark_unresolved_pron(h, np2)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

return F

end

package.preload["asi.nlu.frames5"] = function(...)
-- asi.nlu.frames5: instructions about HOW a dataset is read and HOW the assistant sounds, and questions about the engine's own reading
-- (extends asi.nlu.frames / frames2 / frames3 / frames4 on the same table; every function adds competing hypotheses).
--   voice_instruction   "Use a calmer tone."  "No caps."  "Ignore the personality."  "Treat the examples as facts."  "Play Bob instead."   a standing instruction (slot tone / persona / dataset_role)
--   voice_query         "What tone will you use?"  "How did you read the dataset?"                                                          a question about the engine itself (intent interpretation_query)
-- The wording is recognised by asi.nlu.override (word classes and clause structure); this module only turns what it found into hypotheses with named factors.
local P = require("asi.nlu.parse")
local F = require("asi.nlu.frames4")
local Override = require("asi.nlu.override")

local newh, addf = F.newh, F.addf

local SLOT = { tone = "tone", persona = "persona", dataset_role = "dataset_role" }

local function sentence_text(S)
  local s = S.sentence
  if not (s and s.s and s.e) then return nil end
  return S.an.original:sub(s.s, s.e)
end

local function parse_sentence(S)
  if S.override_parse ~= nil then return S.override_parse or nil end
  local text = sentence_text(S)
  S.override_parse = false
  if text and text ~= "" then
    local res = Override.parse(text, { names = S.ctx and S.ctx.persona_names })
    if #res.items > 0 then S.override_parse = res end
  end
  return S.override_parse or nil
end

local function use_all(S, h)
  for k = S.first, S.last do
    local c = S.chunks[k]
    if c and not c.masked then h.used[k] = true end
  end
end

function F.voice_instruction(S, out)
  local res = parse_sentence(S)
  if not res then return end
  for _, item in ipairs(res.items) do
    if SLOT[item.kind] and #item.ops > 0 then
      local c1 = S.chunks[S.first]
      if c1 then
        local h = newh(S, "instruction:" .. item.kind, "instruction", "instruction_update", "instruct")
        use_all(S, h)
        local np = { head = c1, head_kind = "concept", mods = {}, u1 = c1.u1, u2 = c1.u2, c1 = c1.idx, c2 = c1.idx, nxt = c1.idx + 1, notes = {}, score = 0 }
        h.instruction = { verb = "adjust", act = "constraint", np = np, slot = SLOT[item.kind], value = { word = table.concat(item.ops, ";"), label = item.label }, persist = true,
          ops = item.ops }
        h.persist = true
        h.voice_ops = item.ops
        addf(h, "voice_override", 1.8, "wording about the " .. item.kind:gsub("_", " ") .. ": " .. table.concat(item.evidence or {}, "; "))
        addf(h, "persist_cue", 0.3, "a standing instruction about the voice / the reading of the dataset")
        out[#out + 1] = h
      end
    end
  end
end

function F.voice_query(S, out)
  local res = parse_sentence(S)
  if not res then return end
  for _, item in ipairs(res.items) do
    if item.kind == "query_tone" or item.kind == "query_reading" then
      local h = newh(S, "voice_query", "question", "interpretation_query", "report")
      use_all(S, h)
      h.voice_query = item.kind
      h.requires_evidence = false
      addf(h, "voice_query", 1.8, "the question is about the engine's own reading of the dataset / the voice it will use ('" .. tostring(item.label) .. "')")
      out[#out + 1] = h
    end
  end
end

return F

end

package.preload["asi.nlu.hook"] = function(...)
-- asi.nlu.hook: the ONE integration point for a host program (for example the user's exec_eval bundle).
--   local Hook = require("asi.nlu.hook")
--   local out  = Hook.prepare("Which company acquired the business I mentioned earlier?", { memory = Hook.memory("session-1", "alice") })
--   -- out.prompt  : the LM Input Package text (authority boundaries, verified evidence, ambiguity and unresolved requirements)
--   -- out.record  : the versioned Interpretation Record (inspectable without any language model)
-- The hook never calls a language model, a network service or a clock; it never routes text into any other interface of the host.  Natural-language
-- text goes in, a structured interpretation and a bounded, authority-labelled input package come out.
local Hook = {}

local engine

-- datasets: optional list of { text = <file contents>, name = "world_2020.jsonl", dataset = "w2020", label = { year = 2020 }, version = "2020" }
function Hook.configure(opts)
  opts = opts or {}
  local Resources = require("asi.nlu.resources")
  local K = require("asi.nlu.knowledge")
  local Engine = require("asi.nlu.engine")
  local Cal = require("asi.nlu.calibration")
  local kb
  if opts.datasets and #opts.datasets > 0 then
    kb = K.new(Resources.core())
    for _, d in ipairs(opts.datasets) do kb:ingest(d.text, { name = d.name, dataset = d.dataset or d.name, label = d.label, version = d.version }) end
  end
  local model = opts.calibration or Cal.default_model()
  engine = Engine.new({ knowledge = kb, flags = opts.flags, budget = opts.budget, package_chars = opts.package_chars,
    calibration = (model and not opts.no_calibration) and Cal.record_adapter(model) or nil })
  return engine
end

function Hook.engine()
  return engine or Hook.configure({})
end

-- a conversation memory owned by `principal` (another principal is refused access to the namespace)
function Hook.memory(namespace, principal)
  return Hook.engine():memory(namespace, principal)
end

-- text -> { record, package, prompt, result, evidence }.  call = { memory = , speaker = , include_prompt = , package_chars = , budget = }
function Hook.prepare(text, call)
  call = call or {}
  if call.include_prompt == nil then call.include_prompt = true end
  local out = Hook.engine():process(text, call)
  return { record = out.record, package = out.package, prompt = out.package and out.package.prompt, result = out.result, evidence = out.evidence,
    valid = out.valid, light = out.light }
end

function Hook.version()
  local Engine = require("asi.nlu.engine")
  local Record = require("asi.nlu.record")
  return { engine = Engine.VERSION, record_schema = Record.SCHEMA }
end

return Hook

end

package.preload["asi.nlu.hyp"] = function(...)
-- asi.nlu.hyp: competing interpretation hypotheses.
-- Scores are sums of NAMED, bounded factors (so provenance is real: it lists the computations that produced the score).
-- Hard constraints (type clash on a required role) VETO a hypothesis; soft evidence only ranks.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local Cons = require("asi.nlu.constraints")

local H = {}

-- weights are fixed constants; they were only ever adjusted against the DEV split (see reports/)
H.W = {
  type_fit = 1.1,       -- multiplier on compat(-1..1) per bound role
  coverage = 1.6,       -- fraction of content chunks explained
  unexplained = -0.30,  -- per unexplained content chunk
  lex_entity = 0.15,    -- attested entity span used
  lex_mwe = 0.20,       -- attested multiword unit used
  domain = 0.35,
  discourse = 0.30,
  support = 0.25,
  fuzzy = -0.45,
  unseen = -0.05,
  exact_case = 0.15,
  temperature = 0.55,
  entity_temperature = 0.30,
  resolve_p = 0.60, resolve_margin = 0.30,
}

local FRAME_PRIOR = {
  ["wh_copular:relnp"] = 0.12, ["wh_verb:active"] = 0.10, ["wh_do:object_gap"] = 0.10, ["wh_passive:stranded_by"] = 0.10,
  ["request:relnp"] = 0.08, ["request:search"] = 0.05, ["request:entity"] = 0.0, ["request:concept"] = 0.0,
}

local function softmax(scores, T)
  local m = -math.huge
  for _, s in ipairs(scores) do if s > m then m = s end end
  local sum, ex = 0, {}
  for i, s in ipairs(scores) do ex[i] = math.exp((s - m) / T); sum = sum + ex[i] end
  for i = 1, #ex do ex[i] = ex[i] / sum end
  return ex
end
H.softmax = softmax

---------------------------------------------------------------- context domains (see parse.lua: P.domain_hits / P.domain_gain)
-- best domain support among an NP's candidate senses (used to rank typenoun/concept readings such as program.academic vs software)
local function sense_domain(S, ctx, np)
  local best_hits, best_sense = 0, nil
  for _, s in ipairs(np.senses or {}) do
    local h = P.domain_hits(S, ctx, s.domain, np.u1, np.u2)
    if h > best_hits then best_hits, best_sense = h, s end
  end
  return best_hits, best_sense
end
H.sense_domain = sense_domain

---------------------------------------------------------------- binding an NP argument to candidates + types
-- expected: type name (or union) or nil.  Returns bound table and the best type-fit in [-1, 1]
function H.bind_np(S, ctx, np, expected, h, role)
  if np.bound and np.bound_for == expected and (np.head_kind ~= "pronoun" or np.bound_h == h) then return np.bound, np.bound.fit end
  local lex = S.lex
  local W = H.W
  local b = { cands = {}, status = "unresolved", expected = expected }
  if np.head_kind == "entity" then
    local scored = {}
    -- "the country Georgia", "the company Apple": a type noun in front of a name tells which kind of thing the name denotes
    local cls_types = {}
    for _, md in ipairs(np.mods or {}) do
      if md.kind == "mod" and md.chunk then
        for _, sn in ipairs(md.chunk.senses or {}) do
          if sn.sense and sn.sense.kind == "typenoun" and sn.sense.type then cls_types[#cls_types + 1] = sn.sense.type end
        end
      end
    end
    for _, cd in ipairs(np.cands or {}) do
      local s, reasons = 0, {}
      local ty = cd.type
      if ty and #cls_types > 0 then
        local best = -1.0
        for _, ct in ipairs(cls_types) do best = math.max(best, lex:compat(ty, ct)) end
        if best >= 0.9 then s = s + 0.8; reasons[#reasons + 1] = "agrees with the type noun in front of the name"
        elseif best == -1.0 then s = s - 0.8; reasons[#reasons + 1] = "contradicts the type noun in front of the name" end
      end
      local fit
      if cd.unseen then
        s = s + W.unseen
        if ty then fit = lex:compat(ty, expected) else fit = 0.25; reasons[#reasons + 1] = "type inferred from relation signature" end
        reasons[#reasons + 1] = "not in any loaded entity table (open-set mention)"
      else
        fit = lex:compat(ty, expected)
      end
      if ctx.flags and ctx.flags.no_types then fit = 0.25 end
      s = s + 0.6 * fit
      if fit == -1.0 and expected then reasons[#reasons + 1] = "type " .. tostring(ty) .. " incompatible with expected " .. tostring(expected) end
      if cd.exact_case then s = s + W.exact_case; reasons[#reasons + 1] = "exact-case name match" end
      if cd.fuzzy then s = s + W.fuzzy * (1 - cd.fuzzy) - 0.15; reasons[#reasons + 1] = "fuzzy match from '" .. tostring(cd.fuzzy_from) .. "'" end
      if not (ctx.flags and ctx.flags.no_domain) then
        local dh = P.domain_hits(S, ctx, cd.domain, np.u1, np.u2)
        local gain = P.domain_gain(dh)
        if gain > 0 then s = s + gain; reasons[#reasons + 1] = dh .. " domain cue(s) in context" end
      end
      if ctx.mentioned and ctx.mentioned[cd.id] then s = s + W.discourse * ctx.mentioned[cd.id]; reasons[#reasons + 1] = "previously mentioned in the conversation" end
      if ctx.support then
        local n = ctx.support(cd.id) or 0
        if n > 0 then
          s = s + (n >= 3 and 0.6 or 0.3)
          reasons[#reasons + 1] = n .. (cd.unseen and " dataset mention(s)" or " supporting dataset record(s)")
        end
      end
      s = s + 0.1 * ((cd.prior or 0.5) - 0.5)
      scored[#scored + 1] = { id = cd.id, type = ty, name = cd.name, score = s, fit = fit, vetoed = (fit == -1.0 and expected ~= nil),
        reasons = reasons, unseen = cd.unseen, weak = cd.weak, fuzzy = cd.fuzzy, source = cd.source, domain = cd.domain }
    end
    local live = {}
    for _, c in ipairs(scored) do if not c.vetoed then live[#live + 1] = c end end
    table.sort(live, function(a, b) if a.score ~= b.score then return a.score > b.score end return a.id < b.id end)
    local rejected = {}
    for _, c in ipairs(scored) do if c.vetoed then rejected[#rejected + 1] = c end end
    if #live > 0 then
      local ps = softmax(U.map(live, function(c) return c.score end), W.entity_temperature)
      for i, c in ipairs(live) do c.p = ps[i] end
      b.cands = live
      b.top = live[1]
      b.rejected = rejected
      local margin = live[1].p - (live[2] and live[2].p or 0)
      if #live == 1 or (live[1].p >= W.resolve_p and margin >= W.resolve_margin) then
        b.status = live[1].unseen and "unseen" or "resolved"
      else b.status = "ambiguous" end
      b.margin = margin
      b.fit = live[1].fit
      -- an open-set mention that fills a typed role is probably of that type ("Ninefold" as the work of 'author'); kept apart from attested types
      if live[1].unseen and expected and not expected:find("|", 1, true) then b.itype = expected end
    else
      b.rejected = rejected
      b.status = "unresolved"
      b.fit = (#rejected > 0) and -1.0 or 0.25
    end
  elseif np.head_kind == "typenoun" or np.head_kind == "concept" then
    -- rank the NP's senses by domain support; the best one defines the type
    local senses = U.copy(np.senses or {})
    local hits, best = sense_domain(S, ctx, np)
    if best then
      for i, s in ipairs(senses) do if s.id == best.id then table.remove(senses, i); table.insert(senses, 1, s) break end end
      if not (ctx.flags and ctx.flags.no_domain) then b.domain_gain = P.domain_gain(hits) end
    end
    local ty = senses[1] and senses[1].type
    b.type, b.fit = ty, lex:compat(ty, expected)
    if ctx.flags and ctx.flags.no_types then b.fit = 0.25 end
    b.status = "resolved"
    b.senses = senses
    np.senses = senses
  elseif np.head_kind == "relnoun" then
    local e = np.relnouns and np.relnouns[1]
    local rel = e and lex:get_rel(e.rel)
    b.type = rel and rel[e.role] or nil
    b.fit = lex:compat(b.type, expected)
    b.status = "resolved"
  elseif np.head_kind == "var" then
    -- intermediate result of an earlier step of a multi-hop chain: its type comes from that step
    b.type, b.fit, b.status, b.chain_var = np.type, lex:compat(np.type, expected), "resolved", np.var
  elseif np.head_kind == "pronoun" then
    if ctx.discourse and not (ctx.flags and ctx.flags.no_coref) then
      ctx.discourse:pronoun_binding(S, ctx, np, expected, h, role, b)
    else
      b.status, b.fit, b.pending = "pending", 0.25, true
    end
  elseif np.head_kind == "ordinal_ref" then
    -- "the second one": the member of the latest enumeration of entities
    local dm = ctx.discourse and ctx.discourse.mem
    local a, size = nil, 0
    if dm then a, size = dm:find_entity_ordinal(np.ordinal) end
    if a then
      b.status = "resolved"
      b.antecedent = { key = a.key, text = a.text, type = a.etype, turn = a.turn, via = "ordinal_enumeration", ordinal = np.ordinal, p = 1.0 }
      b.top = { id = a.key, type = a.etype, name = a.text }
      b.type, b.fit = a.etype, lex:compat(a.etype, expected)
      b.cands = { { id = a.key, type = a.etype, name = a.text, p = 1.0, score = 1.0, reasons = { "member " .. tostring(np.ordinal) .. " of the latest list (" .. tostring(size) .. " members)" } } }
    else
      b.status, b.fit = "unresolved", 0.25
    end
  elseif np.head_kind == "temporal" then b.type, b.fit, b.status = "date", lex:compat("date", expected), "resolved"
  elseif np.head_kind == "number" then b.type, b.fit, b.status = "number", lex:compat("number", expected), "resolved"
  elseif np.head_kind == "quote" or np.head_kind == "literal" then b.type, b.fit, b.status = "text", 0.25, "resolved"
  else
    b.fit, b.status = 0.25, "unknown_term"
  end
  np.bound, np.bound_for, np.bound_h = b, expected, h
  return b, b.fit
end

---------------------------------------------------------------- per-hypothesis finalisation
local function content_chunks(S)
  if S.content_count then return S.content_count end
  local n = 0
  for k = S.first, S.last do
    local c = S.chunks[k]
    if not c.masked and not P.is_function_chunk(S, c) then n = n + 1 end
  end
  S.content_count = n
  return n
end

local function bind_all(S, ctx, h)
  local W = H.W
  local function fit_factor(name, fit, note)
    if fit == nil then return end
    h.factors[#h.factors + 1] = { name = name, v = W.type_fit * fit * 0.5, note = note }
    if fit == -1.0 then h.veto = h.veto or note end
  end
  -- a fronted preposition ("In which city ...", "By whom ...") must be accounted for by the construction
  if h.wh and h.wh.pied and not h.pied_consumed then
    h.factors[#h.factors + 1] = { name = "pied_prep_unused", v = -0.8, note = "the fronted preposition '" .. tostring(h.wh.pied) .. "' is not accounted for" }
  end
  if h.rel_obj and h.rel_obj.open then
    -- the relation word is not in the lexicon: it is kept under its own name, at a cost, so any lexicon reading of the same words wins
    h.factors[#h.factors + 1] = { name = "open_relation", v = -0.35, note = "relation inferred from a word the lexicon does not know ('" .. tostring(h.rel_obj.id) .. "'); not mapped onto any known relation" }
  end
  if h.rel_obj then
    for _, role in ipairs({ "from", "to" }) do
      local np = h.roles[role]
      if np then
        -- an open relation has no type signature: its arguments are neither rewarded nor vetoed
        local b, fit = H.bind_np(S, ctx, np, (not h.rel_obj.open) and h.rel_obj[role] or nil, h, role)
        local what = (b.top and b.top.name) or P.span_text(S, np)
        if b.status == "unresolved" and fit == -1.0 then
          fit_factor("type_fit:" .. role, -1.0, "'" .. P.span_text(S, np) .. "' cannot be a " .. tostring(h.rel_obj[role]) .. " (role '" .. role .. "' of " .. h.rel_obj.id .. ")")
        else
          fit_factor("type_fit:" .. role, fit, string.format("'%s' as %s of %s (fit %.2f)", what, role, h.rel_obj.id, fit))
        end
        if b.top and b.top.fuzzy then h.factors[#h.factors + 1] = { name = "fuzzy", v = W.fuzzy, note = "entity matched through a spelling variant" } end
      end
    end
    if h.wh_type and h.ask then
      local fit = S.lex:compat(h.wh_type, h.rel_obj[h.ask])
      if ctx.flags and ctx.flags.no_types then fit = 0.25 end
      fit_factor("answer_type_fit", fit, string.format("wh-type '%s' vs %s of %s (fit %.2f)", h.wh_type, h.ask, h.rel_obj.id, fit))
    end
  end
  -- every step of a multi-hop chain is typed against its own relation signature
  for si, st in ipairs(h.chain or {}) do
    local b, fit = H.bind_np(S, ctx, st.known, st.rel_obj[st.known_role], h, "chain" .. si)
    local what = (b.top and b.top.name) or P.span_text(S, st.known)
    fit_factor("chain_fit:" .. si, fit, string.format("step %d: '%s' as %s of %s (fit %.2f)", si, what, st.known_role, st.rel, fit))
  end
  -- a noun phrase already bound against a relation signature of this hypothesis keeps that typed binding (an untyped second binding would
  -- discard the type evidence: "Is Canbera the capital of Australia?" lists the same noun phrase as a role and as an item)
  local function bind_untyped(np, role)
    if np.bound and np.bound_h == h and np.bound_for ~= nil then return end
    H.bind_np(S, ctx, np, nil, h, role)
  end
  if h.subject then H.bind_np(S, ctx, h.subject, h.expect_type, h, "subject") end
  if h.concept then bind_untyped(h.concept, "concept") end
  if h.target then bind_untyped(h.target, "target") end
  for _, it in ipairs(h.items or {}) do bind_untyped(it, "item") end
  if h.focus then bind_untyped(h.focus, "focus") end
  if h.object then bind_untyped(h.object, "object") end
  if h.basis then bind_untyped(h.basis.np, "basis") end
  if h.statement then
    if h.statement.subj then bind_untyped(h.statement.subj, "subject") end
    if h.statement.obj then bind_untyped(h.statement.obj, "object") end
  end
  -- sense-level domain evidence for typenoun/concept readings (competing readings of a word such as "program")
  for _, np in ipairs({ h.concept, h.target, h.object, h.focus }) do
    if np and np.bound and np.bound.domain_gain and np.bound.domain_gain > 0 then
      h.factors[#h.factors + 1] = { name = "sense_domain", v = np.bound.domain_gain, note = "context domain supports the chosen sense of '" .. P.span_text(S, np) .. "'" }
    end
  end
  -- unaided fuzzy lexemes (typos of relation words / senses) cost confidence once per chunk
  for k in pairs(h.used) do
    local c = S.chunks[k]
    if c and c.fuzzy and #c.entities == 0 then
      h.factors[#h.factors + 1] = { name = "fuzzy_lexeme", v = W.fuzzy * (1 - c.fuzzy) - 0.15, note = "'" .. tostring(c.fuzzy_from) .. "' matched through a spelling variant" }
    end
  end

end

function H.finalize(S, ctx, h)
  local W = H.W
  local F2 = require("asi.nlu.frames2")
  F2.expand_chain(S, h)   -- turn nested relational NPs / relative clauses into ordered lookup steps
  F2.attach_basis(S, h)   -- "considering X" / "given X" arguments
  Cons.attach(S, h)
  bind_all(S, ctx, h)

  -- lexical attestation of the spans actually used
  local lex_bonus = 0
  for k in pairs(h.used) do
    local c = S.chunks[k]
    if c then
      if c.kind == "entity" and #c.entities > 0 then lex_bonus = lex_bonus + W.lex_entity
      elseif c.kind == "mwe" then lex_bonus = lex_bonus + W.lex_mwe end
    end
  end
  if lex_bonus > 0 then h.factors[#h.factors + 1] = { name = "lexical_attestation", v = lex_bonus, note = "attested multiword/entity spans used" } end

  -- coverage
  local total = math.max(1, content_chunks(S) + #(S.prefix_chunks or {}))
  local unexplained = Cons.unexplained(S, h)
  local explained = total - #unexplained
  local cov = explained / total
  h.coverage = cov
  h.unexplained = unexplained
  h.factors[#h.factors + 1] = { name = "coverage", v = W.coverage * cov, note = string.format("%d of %d content chunks explained", explained, total) }
  if #unexplained > 0 then
    h.factors[#h.factors + 1] = { name = "unexplained", v = W.unexplained * #unexplained, note = #unexplained .. " content chunk(s) not accounted for" }
  end
  local prior = FRAME_PRIOR[h.frame]
  if prior then h.factors[#h.factors + 1] = { name = "frame_prior", v = prior, note = "construction prior for " .. h.frame } end
  local s = 0
  for _, f in ipairs(h.factors) do s = s + f.v end
  h.score = s
  return h
end

-- NP objects are shared between competing hypotheses, so np.bound can belong to the last hypothesis finalised.  Rebinding the
-- winner restores its own bindings before anything is rendered or audited; factors added again are discarded (scores unchanged).
function H.rebind(S, ctx, h)
  local n = #h.factors
  local veto = h.veto
  bind_all(S, ctx, h)
  for i = #h.factors, n + 1, -1 do h.factors[i] = nil end
  h.veto = veto
end

---------------------------------------------------------------- selection
local function hyp_signature(S, h)
  local parts = { h.intent or "?", h.op or "?", h.rel or "-", h.ask or "-", h.polarity or "+" }
  for _, role in ipairs({ "from", "to", "subject" }) do
    local np = h.roles[role]
    if np then
      -- resolved entities compare by id; open-set mentions by their normalised text (the same name under two segmentations is one reading)
      local id = np.bound and np.bound.top and np.bound.top.id
      if not id or id:sub(1, 8) == "mention:" then id = P.core_text(S, np) end
      parts[#parts + 1] = role .. "=" .. id
    end
  end
  local obj = h.concept or h.target or h.focus or h.object
  if obj then
    -- same words + same semantic type == same reading, regardless of how the lattice segmented them
    local ty = obj.bound and (obj.bound.type or (obj.bound.senses and obj.bound.senses[1] and obj.bound.senses[1].type))
    parts[#parts + 1] = "obj=" .. P.core_text(S, obj) .. ":" .. tostring(ty)
  end
  for _, it in ipairs(h.items or {}) do parts[#parts + 1] = "item=" .. (it.head and it.head.form or "?") end
  if h.instruction then parts[#parts + 1] = "inst=" .. tostring(h.instruction.verb) .. ":" .. tostring(h.instruction.slot) end
  if h.clause then parts[#parts + 1] = "clause=" .. tostring(h.clause.lemma) end
  if h.statement then parts[#parts + 1] = "stmt=" .. tostring(h.statement.lemma) end
  return table.concat(parts, "|")
end

local function summarize(S, h)
  local function np_text(np) return np and P.span_text(S, np) or nil end
  local t = {}
  if h.rel then t[#t + 1] = h.rel end
  if h.known_role and h.roles[h.known_role] then t[#t + 1] = h.known_role .. "=" .. np_text(h.roles[h.known_role]) end
  if h.ask then t[#t + 1] = "ask=" .. h.ask end
  local obj = h.concept or h.target or h.focus or h.object or h.subject
  if obj then t[#t + 1] = "obj=" .. np_text(obj) end
  return (h.intent or "?") .. ": " .. table.concat(t, " ")
end
H.summarize = summarize

-- ranks finalised hypotheses; returns {ranked, rejected, top, posterior...}
function H.select(S, ctx, hyps)
  local W = H.W
  local live, rejected = {}, {}
  for _, h in ipairs(hyps) do
    if h.veto then rejected[#rejected + 1] = h else live[#live + 1] = h end
  end
  -- merge duplicates by signature, keep the best score and remember the other frames that agreed
  table.sort(live, function(a, b)
    if a.score ~= b.score then return a.score > b.score end
    return (a.frame or "") < (b.frame or "")
  end)
  local merged, seen = {}, {}
  for _, h in ipairs(live) do
    h.sig = hyp_signature(S, h)
    -- readings that are indistinguishable once summarised (same intent, relation, arguments, constraints) are ONE reading however many frames produced them
    local key = h.sig .. "\1" .. summarize(S, h)
    local m = seen[key]
    if m then m.agreeing_frames[#m.agreeing_frames + 1] = h.frame
    else h.agreeing_frames = {}; seen[key] = h; merged[#merged + 1] = h end
  end
  local ps = softmax(U.map(merged, function(h) return h.score end), (ctx.temperature or W.temperature))
  for i, h in ipairs(merged) do h.p = ps[i]; h.summary = summarize(S, h) end
  return { ranked = merged, rejected = rejected }
end

-- ambiguity points between the top hypothesis and its serious competitors + unresolved entity bindings inside the top hypothesis
function H.ambiguity(S, ctx, sel)
  local W = H.W
  local points = {}
  local top = sel.ranked[1]
  if not top then return { state = "unresolvable", points = points } end
  local function np_roles(h)
    local out = {}
    for _, role in ipairs({ "from", "to", "subject" }) do if h.roles[role] then out[role] = h.roles[role] end end
    if h.concept then out.concept = h.concept end
    if h.focus then out.focus = h.focus end
    if h.target then out.target = h.target end
    return out
  end
  -- (1) unresolved entity candidates inside the winning hypothesis
  for role, np in pairs(np_roles(top)) do
    local b = np.bound
    if b and b.status == "ambiguous" then
      local cands = {}
      for _, c in ipairs(b.cands) do if c.p >= 0.08 then cands[#cands + 1] = { id = c.id, type = c.type, p = c.p, reasons = c.reasons } end end
      points[#points + 1] = { id = "entity:" .. P.span_text(S, np), kind = "entity", role = role, mention = P.span_text(S, np), material = true, resolved = false,
        candidates = cands, rejected = U.map(b.rejected or {}, function(r) return { id = r.id, reason = r.reasons[#r.reasons] } end) }
    elseif b and b.status == "resolved" and b.top and #b.cands > 1 then
      points[#points + 1] = { id = "entity:" .. P.span_text(S, np), kind = "entity", role = role, mention = P.span_text(S, np), material = true, resolved = true,
        chosen = b.top.id, candidates = U.map(b.cands, function(c) return { id = c.id, type = c.type, p = c.p } end),
        rejected = U.map(b.rejected or {}, function(r) return { id = r.id, reason = r.reasons[#r.reasons] } end) }
    end
  end
  -- (2) competing hypotheses that differ in relation / intent / sense
  local function obj_type(h)
    local obj = h.concept or h.target or h.focus or h.object
    return obj and obj.bound and (obj.bound.type or (obj.bound.senses and obj.bound.senses[1] and obj.bound.senses[1].type)) or nil
  end
  for i = 2, #sel.ranked do
    local alt = sel.ranked[i]
    -- the same reading with a weaker lexical grounding (e.g. the word read as untyped instead of as the typed noun) is not a competing MEANING
    local same_reading = alt.summary == top.summary and alt.intent == top.intent and alt.rel == top.rel
    if same_reading then
      local ta, tb = obj_type(top), obj_type(alt)
      same_reading = (ta == nil or tb == nil or ta == tb)
    end
    if alt.p >= 0.12 and not same_reading then
      local kind
      if alt.rel ~= top.rel then kind = "relation"
      elseif alt.intent ~= top.intent then kind = "intent"
      elseif alt.ask ~= top.ask then kind = "role_direction"
      else kind = "sense" end
      points[#points + 1] = { id = "hyp:" .. i, kind = kind, material = true, resolved = (top.p >= W.resolve_p and (top.p - alt.p) >= W.resolve_margin),
        chosen = top.summary, candidates = { { summary = top.summary, p = top.p }, { summary = alt.summary, p = alt.p } } }
    end
  end
  local state = "resolved"
  for _, pt in ipairs(points) do if pt.material and not pt.resolved then state = "ambiguous" end end
  if (top.p < W.resolve_p or (sel.ranked[2] and top.p - sel.ranked[2].p < W.resolve_margin)) and sel.ranked[2] and sel.ranked[2].p >= 0.2 then
    local hasHyp = false
    for _, pt in ipairs(points) do if pt.kind ~= "entity" and not pt.resolved then hasHyp = true end end
    if hasHyp then state = "ambiguous" end
  end
  return { state = state, points = points }
end

return H

end

package.preload["asi.nlu.index"] = function(...)
-- asi.nlu.index: layered, incrementally updatable retrieval index.
--   1. exact entity postings         entity key -> records that MENTION it (identity, not substring)
--   2. phrase-aware field-weighted lexical postings (BM25F) with positions
--   3. typed assertion store         (relation, subject key) / (relation, object key) -> assertions extracted from records
--   4. metadata / time filters
-- BM25F is ONE component; semantic verification (asi.nlu.verify) decides whether a candidate actually supports the interpreted request.
local U = require("asi.nlu.util")
local TU = require("asi.nlu.textutil")

local X = {}
X.__index = X

X.FIELD_WEIGHT = { title = 2.2, name = 2.2, headline = 2.2, heading = 2.0, section = 1.4, text = 1.0, body = 1.0, summary = 1.2, abstract = 1.2, tags = 1.3 }
local K1, B = 1.2, 0.75

function X.new(opts)
  opts = opts or {}
  local self = setmetatable({}, X)
  self.docs, self.doc_of, self.n, self.live = {}, {}, 0, 0
  self.terms = {}                -- term -> { [doc] = { [field] = tf } }
  self.positions = {}            -- term -> { [doc] = { pos... } }  (field offsets baked into the position)
  self.df = {}
  self.len = {}                  -- field -> { [doc] = length }
  self.total_len, self.field_count = {}, {}
  self.entity_post = {}          -- key -> { [doc] = n }
  self.assertions = {}           -- list (index = assertion id)
  self.by_from, self.by_to, self.by_any = {}, {}, {}
  self.classes = {}              -- subject key -> list of classification assertion ids
  self.meta = {}                 -- field -> value -> { [doc] = true }
  self.revision = 0
  self.weights = opts.field_weight or X.FIELD_WEIGHT
  return self
end

local function fw(self, field) return self.weights[field] or self.weights[field:lower()] or 1.0 end

---------------------------------------------------------------- adding / removing documents
-- doc: the dataset record; analysis: result of assertions:extract (may be nil for metadata-only records)
function X:add(rec, analysis)
  if self.doc_of[rec.id] then self:remove(rec.id) end
  self.n = self.n + 1
  local d = self.n
  self.docs[d] = { id = rec.id, rec = rec, terms = {}, entities = {}, assertions = {}, meta = {} }
  self.doc_of[rec.id] = d
  self.live = self.live + 1
  local offset = 0
  local fields = rec.text_fields
  if not fields or #fields == 0 then fields = {} end
  for fi, f in ipairs(fields) do
    local text = rec.field_text and rec.field_text[f] or ""
    local toks = TU.tokens(text)
    -- text that is not knowledge (examples of a voice, instructions, questions) is not retrievable as evidence either
    local skip = analysis and analysis.skip and analysis.skip[f]
    if skip then
      local kept = {}
      for _, t in ipairs(toks) do
        local inside = false
        for _, r in ipairs(skip) do if t.s >= r.s and t.s <= r.e then inside = true break end end
        if not inside then kept[#kept + 1] = t end
      end
      toks = kept
    end
    local per = {}
    for _, t in ipairs(toks) do
      local term = t.t
      local ft = self.terms[term]
      if not ft then ft = {}; self.terms[term] = ft end
      local dt = ft[d]
      if not dt then dt = {}; ft[d] = dt; self.df[term] = (self.df[term] or 0) + 1; self.docs[d].terms[#self.docs[d].terms + 1] = term end
      dt[f] = (dt[f] or 0) + 1
      local pt = self.positions[term]
      if not pt then pt = {}; self.positions[term] = pt end
      local pl = pt[d]
      if not pl then pl = {}; pt[d] = pl end
      pl[#pl + 1] = offset + t.pos
      per[#per + 1] = t
    end
    offset = offset + 10000
    self.len[f] = self.len[f] or {}
    self.len[f][d] = #toks
    self.total_len[f] = (self.total_len[f] or 0) + #toks
    self.field_count[f] = (self.field_count[f] or 0) + 1
  end
  for k, v in pairs(rec.meta or {}) do
    local sv = tostring(v):lower()
    self.meta[k] = self.meta[k] or {}
    self.meta[k][sv] = self.meta[k][sv] or {}
    self.meta[k][sv][d] = true
    self.docs[d].meta[#self.docs[d].meta + 1] = { k, sv }
  end
  if analysis then
    local seen = {}
    for _, m in ipairs(analysis.mentions) do
      local key = m.key
      if not seen[key] then
        seen[key] = true
        local ep = self.entity_post[key]
        if not ep then ep = {}; self.entity_post[key] = ep end
        ep[d] = (ep[d] or 0) + 1
        self.docs[d].entities[#self.docs[d].entities + 1] = key
      end
    end
    for _, a in ipairs(analysis.assertions) do self:add_assertion(d, a) end
    self.docs[d].reader_directed = analysis.reader_directed
    self.docs[d].aliases = analysis.aliases
  end
  self.revision = self.revision + 1
  return d
end

function X:add_assertion(d, a)
  a.doc = d
  a.record = self.docs[d].id
  local id = #self.assertions + 1
  a.id = id
  self.assertions[id] = a
  self.docs[d].assertions[#self.docs[d].assertions + 1] = id
  local function post(map, key)
    if not key then return end
    local l = map[key]
    if not l then l = {}; map[key] = l end
    l[#l + 1] = id
  end
  if a.is_class then
    if a.from and a.from.key then post(self.classes, a.from.key) end
    return
  end
  local from_keys, to_keys = {}, {}
  if a.from then
    if a.from.key then from_keys[1] = a.from.key end
    for _, c in ipairs(a.from.cands or {}) do from_keys[#from_keys + 1] = c.id end
  end
  if a.to and not a.to.literal then
    if a.to.key then to_keys[1] = a.to.key end
    for _, c in ipairs(a.to.cands or {}) do to_keys[#to_keys + 1] = c.id end
  end
  for _, k in ipairs(from_keys) do post(self.by_from, a.rel .. "|" .. k); post(self.by_any, k) end
  for _, k in ipairs(to_keys) do post(self.by_to, a.rel .. "|" .. k); post(self.by_any, k) end
end

function X:remove(id)
  local d = self.doc_of[id]
  if not d then return false end
  local doc = self.docs[d]
  for _, term in ipairs(doc.terms) do
    if self.terms[term] then
      self.terms[term][d] = nil
      self.positions[term][d] = nil
      self.df[term] = math.max(0, (self.df[term] or 1) - 1)
    end
  end
  for f, lens in pairs(self.len) do
    if lens[d] then
      self.total_len[f] = self.total_len[f] - lens[d]
      self.field_count[f] = self.field_count[f] - 1
      lens[d] = nil
    end
  end
  for _, key in ipairs(doc.entities) do if self.entity_post[key] then self.entity_post[key][d] = nil end end
  for _, m in ipairs(doc.meta) do if self.meta[m[1]] and self.meta[m[1]][m[2]] then self.meta[m[1]][m[2]][d] = nil end end
  for _, aid in ipairs(doc.assertions) do self.assertions[aid].removed = true end
  doc.removed = true
  self.doc_of[id] = nil
  self.live = self.live - 1
  self.revision = self.revision + 1
  return true
end

---------------------------------------------------------------- lookups
function X:record(d) return self.docs[d] and self.docs[d].rec end

-- live assertions of a list of ids
local function live(self, ids)
  local out = {}
  for _, id in ipairs(ids or {}) do
    local a = self.assertions[id]
    if a and not a.removed then out[#out + 1] = a end
  end
  return out
end

function X:assertions_from(rel, key) return live(self, self.by_from[rel .. "|" .. key]) end
function X:assertions_to(rel, key) return live(self, self.by_to[rel .. "|" .. key]) end
function X:assertions_about(key) return live(self, self.by_any[key]) end
function X:classifications(key) return live(self, self.classes[key]) end

function X:docs_mentioning(key)
  local out = {}
  for d in pairs(self.entity_post[key] or {}) do if self.docs[d] and not self.docs[d].removed then out[#out + 1] = d end end
  table.sort(out)
  return out
end

---------------------------------------------------------------- BM25F with optional phrase constraint
local function idf(self, term)
  local df = self.df[term] or 0
  return math.log(1 + (self.live - df + 0.5) / (df + 0.5))
end

-- do the stemmed terms occur consecutively in document d?  (positions carry a field offset, so a phrase never spans two fields)
function X:phrase_in(d, terms)
  if #terms == 0 then return false end
  local first = self.positions[terms[1]] and self.positions[terms[1]][d]
  if not first then return false end
  for _, p in ipairs(first) do
    local ok = true
    for i = 2, #terms do
      local pl = self.positions[terms[i]] and self.positions[terms[i]][d]
      local found = false
      if pl then for _, q in ipairs(pl) do if q == p + i - 1 then found = true break end end end
      if not found then ok = false break end
    end
    if ok then return true end
  end
  return false
end

-- query = { terms = {t...}, phrases = { {t1,t2}, ... } }; returns list {doc, score, matched_terms, phrases} sorted by score desc
function X:search(query, limit)
  local scores, hits = {}, {}
  for _, term in ipairs(query.terms or {}) do
    local postings = self.terms[term]
    if postings then
      local w = idf(self, term)
      for d, per_field in pairs(postings) do
        if not self.docs[d].removed then
          local tfn = 0
          for f, tf in pairs(per_field) do
            local avg = (self.total_len[f] or 1) / math.max(1, self.field_count[f] or 1)
            local len = (self.len[f] and self.len[f][d]) or avg
            tfn = tfn + fw(self, f) * tf / (1 - B + B * len / math.max(avg, 1e-9))
          end
          scores[d] = (scores[d] or 0) + w * tfn / (K1 + tfn)
          hits[d] = hits[d] or {}
          hits[d][#hits[d] + 1] = term
        end
      end
    end
  end
  local out = {}
  for d, s in pairs(scores) do
    local ph = {}
    for _, p in ipairs(query.phrases or {}) do if self:phrase_in(d, p) then ph[#ph + 1] = table.concat(p, " ") end end
    out[#out + 1] = { doc = d, score = s + 1.5 * #ph, lexical = s, matched = hits[d], phrases = ph }
  end
  table.sort(out, function(a, b) if a.score ~= b.score then return a.score > b.score end return a.doc < b.doc end)
  if limit and #out > limit then for i = #out, limit + 1, -1 do out[i] = nil end end
  return out
end

function X:stats()
  return { documents = self.live, terms = (function() local c = 0; for _ in pairs(self.terms) do c = c + 1 end return c end)(),
    assertions = (function() local c = 0; for _, a in ipairs(self.assertions) do if not a.removed then c = c + 1 end end return c end)(),
    entities = (function() local c = 0; for _ in pairs(self.entity_post) do c = c + 1 end return c end)(), revision = self.revision }
end

return X

end

package.preload["asi.nlu.interp"] = function(...)
-- asi.nlu.interp: the interpreter facade.  text -> lexical analysis -> lattice -> semantic hypotheses -> interpretation.
-- LM-independent, deterministic (no clock/randomness), metered (explicit `limited` status instead of silent guessing).
local U = require("asi.nlu.util")
local Lex = require("asi.nlu.lex")
local Lattice = require("asi.nlu.lattice")
local Sem = require("asi.nlu.sem")
local Resources = require("asi.nlu.resources")
local Memory = require("asi.nlu.memory")
local Coref = require("asi.nlu.coref")
local P = require("asi.nlu.parse")

local I = {}
I.__index = I
I.VERSION = "0.1.0"

function I.new(opts)
  opts = opts or {}
  local self = setmetatable({}, I)
  self.lex = opts.lexicon or Resources.core()
  self.flags = opts.flags or {}           -- ablation switches: no_types, no_domain, no_hypotheses, no_semantics, ...
  self.budget = opts.budget or 2000000    -- integer work units per call
  self.temperature = opts.temperature
  self.max_covers = opts.max_covers or 3
  self.calibration = opts.calibration
  return self
end

-- main sentence: the last question/request, else the last sentence
local function pick_main(rendered)
  local main
  for i, r in ipairs(rendered) do
    if r.speech_act == "question" or r.speech_act == "request" or r.speech_act == "instruction" or r.speech_act == "correction" then main = i end
  end
  return main or #rendered
end

-- scan a sentence's units for discourse cues that change how it is remembered
-- A stated decision is a decision VERB (decided, agreed, settled on, resolved, chose, picked, voted ...) with a collective or first-person subject nearby, or the
-- noun "decision" introducing the outcome ("Team decision: X for Y").  Closed word lists, no phrase templates.
local DECISION_VERBS = U.set({ "decided", "agreed", "settled", "resolved", "concluded", "determined", "opted", "committed", "chose", "chosen", "picked", "selected", "voted", "went" })
-- verbs that are also ordinary actions ("I picked up the kids", "we went to the lake"): they count only with a collective subject and without a particle
local WEAK_DECISION_VERBS = U.set({ "chose", "chosen", "picked", "selected", "voted", "went" })
local DECISION_PARTICLES = U.set({ "up", "out", "off", "over", "on", "through", "back", "down", "away", "around", "in" })
local DECISION_SUBJECTS = U.set({ "we", "our", "i", "us", "team", "group", "everyone", "engineers", "engineer", "committee", "board", "management", "company", "they", "squad", "staff",
  "leadership", "council", "all", "crew", "department", "organisation", "organization" })
local function decision_statement(an, ua, ub)
  for i = ua, ub do
    local f = an.units[i].form
    if DECISION_VERBS[f] then
      -- "went"/"go" only count as "went with" / "go with"; the others need a collective / first-person subject within the six words before
      if f == "went" then
        local nx = an.units[i + 1]
        if not (nx and nx.form == "with") then goto continue end
      end
      if WEAK_DECISION_VERBS[f] then
        local nx = an.units[i + 1]
        if nx and DECISION_PARTICLES[nx.form] then goto continue end
        for j = math.max(ua, i - 5), i - 1 do
          local sf = an.units[j].form
          if sf ~= "i" and DECISION_SUBJECTS[sf] then return true end
        end
        goto continue
      end
      for j = math.max(ua, i - 6), i - 1 do if DECISION_SUBJECTS[an.units[j].form] then return true end end
      -- "It was decided by the whole team that ...", "The decision was made ..."
      for j = math.max(ua, i - 3), i - 1 do if an.units[j].form == "was" or an.units[j].form == "been" or an.units[j].form == "is" then return true end end
    elseif f == "decision" then
      local nx, nx2 = an.units[i + 1], an.units[i + 2]
      if i > ua and an.units[i - 1].form ~= "the" and nx and nx.pre and (nx.pre:find("colon") or nx.pre:find("dash")) then return true end       -- "Team decision: ..."
      if nx and (nx.form == "is" or nx.form == "was") and nx2 and (nx2.form == "to" or (nx2.pre and nx2.pre:find("colon"))) then return true end
    end
    ::continue::
  end
  return false
end

local function sentence_cues(an, sent, lex)
  local cues = {}
  local ua, ub = Sem.sentence_unit_range(an, sent.id)
  if not ua then return cues end
  -- a question about a decision is not a decision
  if not sent.question_mark and decision_statement(an, ua, ub) then cues.decision = true end
  for i = ua, ub do
    local u = an.units[i]
    do
      if lex:cue_at("hedge", an.units, i) then cues.hedged = true end
      if lex:cue_at("exact_mention", an.units, i) then cues.exact = true end
      local rn = lex:cue_at("revoke", an.units, i)
      if rn and not cues.revoke then
        -- a revocation needs a TARGET: a slot noun ("the dataset instruction"), an instruction-class noun ("my last constraint"), or nothing but
        -- anaphora ("never mind." / "scratch that").  "Never mind the noise outside" revokes nothing.
        local rv = { bare = true }
        for k = i + rn, #an.units do
          local u = an.units[k]
          if u.sent ~= sent.id then break end
          local cats = lex:cats(u.form) or {}
          local closed = cats.det or cats.pron or cats.prep or cats.aux_be or cats.aux_do or cats.adv or cats.polite or cats.conj or cats.particle or u.kind ~= "word"
          local slot = lex:resource(u.form)
          if slot and slot ~= "year" then rv.slot = rv.slot or slot; rv.bare = false
          elseif lex:refclasses(u.form).correction then rv.class = true; rv.bare = false
          elseif not closed then rv.bare = false end
        end
        cues.revoke = rv
      end
      if lex:cue_at("additive", an.units, i) then cues.additive = true end
      if lex:cue_at("scoped", an.units, i) then cues.scoped = true end
      if lex:cue_at("decision", an.units, i) then cues.decision = true end
      if lex:cue_at("decision_ref", an.units, i) then cues.decision_ref = true end
    end
  end
  return cues
end

local function trim_selection(sel, max_excluded)
  local out = { selected = {}, excluded = {}, n_selected = #sel.selected, n_excluded = #sel.excluded }
  for _, c in ipairs(sel.selected) do
    local it = c.item
    out.selected[#out.selected + 1] = { id = it.id, kind = it.kind, layer = it.layer, turn = it.turn, speaker = it.speaker, status = it.status, slot = it.slot,
      value = it.value, text = (it.text or ""):sub(1, 200), score = U.round(c.score, 3), factors = c.factors, reliability = it.reliability }
  end
  for i, x in ipairs(sel.excluded) do
    if i > (max_excluded or 8) then break end
    out.excluded[#out.excluded + 1] = { id = x.item.id, kind = x.item.kind, turn = x.item.turn, reason = x.reason, text = (x.item.text or ""):sub(1, 120) }
  end
  return out
end

-- Interpret `text`.  call = { memory = <asi.nlu.memory>, speaker = "user"|"assistant"|"doc", now = <date>, budget = n, domains = {}, support = fn }
-- With a memory, pronouns / back-references / corrections resolve against it and every sentence is observed into it.
-- Without one, a transient memory covers references inside this single message.
function I:interpret(text, call)
  call = call or {}
  local meter = U.meter(call.budget or self.budget)
  local an = Lex.analyze(text, { spell = self.lex.spell, now = call.now, meter = meter, max_bytes = call.max_bytes })
  local result = { original = an.original, analysis = an, status = an.status, sentences = {} }
  if an.status == "rejected" then return result end
  local lat = Lattice.build(an, self.lex, { meter = meter })
  result.lattice = lat
  local flags = self.flags
  local mem = call.memory
  if not mem and not flags.no_memory then mem = Memory.new({ transient = true }) end
  local speaker = call.speaker or "user"
  local view
  if mem then
    if not mem.refclasses then local lx = self.lex; mem.refclasses = function(w) return lx:refclasses(w) end end
    mem:begin_turn(speaker)
    view = Coref.view(mem, self.lex)
    result.memory = mem
  end
  if call.light and mem then
    -- light observation (assistant / document turns): attested entity mentions only, no semantic parse and no standing instructions
    local turn_items = {}
    for _, sent in ipairs(an.sentences) do
      local ua, ub = Sem.sentence_unit_range(an, sent.id)
      local cover = ua and lat:covers(1, ua, ub)[1]
      local found = {}
      for si, sp in ipairs(cover and cover.spans or {}) do
        local ids, name_r = {}, nil
        for _, r in ipairs(sp.readings) do
          if r.kind == "entity" and not r.fuzzy and r.entry then ids[r.entry.id] = r.entry.etype
          elseif r.kind == "name" and not name_r then name_r = r end
        end
        local text = an.original:sub(an.units[sp.i].s, an.units[sp.j].e)
        local n, only = 0, nil
        for id in pairs(ids) do n = n + 1; only = id end
        local ustart, uend = an.units[sp.i].s, an.units[sp.j].e
        if n == 1 then
          mem:mention(only, { type = ids[only], name = text, w = 0.2, role = "mention", speaker = speaker, loc = Coref.locative_before(an.units, sp.i) or nil })
          found[#found + 1] = { key = only, c1 = si, c2 = si }
          turn_items[#turn_items + 1] = { key = only, text = text, type = ids[only], s = ustart, e = uend }
        elseif n == 0 and name_r then
          local key = "mention:" .. text:lower()
          mem:mention(key, { type = name_r.type_guess, name = text, w = 0.2, role = "mention", speaker = speaker, weak = name_r.weak,
            pname = name_r.multiword and not name_r.head_cue and not name_r.type_guess or nil, loc = Coref.locative_before(an.units, sp.i) or nil })
          found[#found + 1] = { key = key, c1 = si, c2 = si }
          turn_items[#turn_items + 1] = { key = key, text = text, type = name_r.type_guess, s = ustart, e = uend }
        end
      end
      if #found > 0 then
        local S = P.new_state(an, self.lex, lat, cover, { flags = flags, meter = meter })
        Coref.describe_entities(view, S, found, speaker)
      end
    end
    -- a list the assistant gave ("1. Oslo 2. Stockholm 3. Helsinki"): later "the second one" / "the last" refer to its members
    if #turn_items >= 2 and speaker ~= "user" then
      local members = Memory.detect_enumeration(text, turn_items)
      if members then mem:note_enumeration(members) end
    end
    if not call.skip_utterance then mem:note_utterance(text, speaker) end
    result.light, result.work = true, meter:snapshot()
    return result
  end
  local ctx = { flags = flags, temperature = self.temperature, max_covers = self.max_covers, meter = meter, domains = call.domains,
    mentioned = call.mentioned, support = call.support, persona_names = call.persona_names }
  if view and not flags.no_coref then ctx.discourse = view end
  for si, sent in ipairs(an.sentences) do
    if view then
      ctx.mentioned = view:mention_weights()
      if not flags.no_domain then
        local dp = view:domain_profile()
        for d, n in pairs(call.domains or {}) do dp[d] = math.max(dp[d] or 0, n) end
        ctx.domains = dp
      end
    end
    local res = Sem.analyze_sentence(an, lat, self.lex, sent, ctx)
    if res then
      local interp = Sem.render(res, ctx)
      local cues = view and sentence_cues(an, sent, self.lex) or {}
      -- a stated decision is remembered even when the sentence has no parsable relational structure
      if view and cues.decision and speaker == "user" then mem:note_decision(interp.sentence.text, { sent = si }) end
      if view then
        -- references that only memory can resolve (back-references, ordinal artifacts, corrections, comparison sets)
        local rr = (flags.no_coref or interp.status ~= "ok") and { references = {}, by_text = {}, unresolved = {} } or Coref.resolve_references(view, interp)
        local ctxinfo = { references = rr.references, unresolved = rr.unresolved }
        if interp.speech_act ~= "statement" and not flags.no_memory_select then
          local sel = mem:select(interp, { max_items = 12, decision_ref = cues.decision_ref })
          ctxinfo.memory = trim_selection(sel, 8)
          ctxinfo.memory.namespace, ctxinfo.memory.revision, ctxinfo.memory.turn = mem:ns_key(), mem.revision, mem.turn
          ctxinfo.memory.n_candidates, ctxinfo.memory.n_items = sel.n_candidates, sel.n_items
          ctxinfo.active_constraints = mem:active_constraints(interp)
          if interp.intent == "conversation_recall" then
            rr.recall_found = #sel.selected > 0
            ctxinfo.recall = { found = rr.recall_found }
            if not rr.recall_found then
              rr.unresolved[#rr.unresolved + 1] = { kind = "conversation_recall", mention = interp.sentence.text, requirement = "nothing in the conversation matches what is being recalled (none is invented)" }
            end
          end
        end
        ctxinfo.dependency = mem:classify_dependency(interp, rr)
        if interp.status ~= "ok" then ctxinfo.note = "no semantic interpretation; only lexical memory selection was possible" end
        interp.context = ctxinfo
        if interp.status == "ok" and (speaker == "user" or call.observe_all) then
          mem:observe_sentence(interp, { speaker = speaker, sent = si, hedged = cues.hedged, revoke = cues.revoke, additive = cues.additive, scoped = cues.scoped })
          -- an instruction turn reports the standing state AFTER it took effect (all slots, whatever kind of request would use them)
          if interp.intent == "instruction_update" and not flags.no_memory_select then ctxinfo.active_constraints = mem:active_constraints(interp, { all = true }) end
          -- a long message can carry a directive in one of its clauses ("..., and yes, drop retailers from your results before I forget"): the clause reading
          -- that is an instruction / exclusion is remembered too, although the sentence as a whole read as a statement
          if speaker == "user" and interp.intent ~= "instruction_update" and interp.speech_act ~= "instruction" and res.ranked and not flags.no_suffix then
            for _, h in ipairs(res.ranked) do
              local is_suffix = false
              for _, f in ipairs(h.factors or {}) do if f.name == "clause_suffix" then is_suffix = true end end
              if is_suffix and h ~= res.top and (h.intent == "instruction_update" or h.instruction) and not h.veto then
                local st2 = res.states and res.states[h.cover_index]
                if st2 then
                  local H = require("asi.nlu.hyp")
                  H.rebind(st2, ctx, h)
                  local res2 = U.shallow(res)
                  res2.top, res2.S, res2.seg_cons = h, st2, st2.seg_cons
                  local ok2, interp2 = pcall(Sem.render, res2, ctx)
                  if ok2 and interp2 and interp2.status == "ok" and (interp2.intent == "instruction_update" or interp2.speech_act == "instruction") then
                    interp2.sentence = interp.sentence
                    mem:observe_sentence(interp2, { speaker = speaker, sent = si, hedged = cues.hedged, additive = cues.additive, scoped = cues.scoped })
                    break
                  end
                end
              end
            end
          end
          local items = {}
          Coref.walk(interp, function(r)
            local key = r.antecedent and r.antecedent.key or r.resolved_id
            if key and r.chunk_range and not r.deictic and not r.pronoun and not r.backref then items[#items + 1] = { key = key, c1 = r.chunk_range[1], c2 = r.chunk_range[2] } end
          end)
          if #items > 0 then Coref.describe_entities(view, res.S, items, speaker) end
        end
        -- every entity / name in a user sentence is remembered (weakly), also when the sentence has no semantic reading: a business that is only DESCRIBED
        -- ("... is the small business I'm assessing") is not a role of the winning reading but is exactly what "the company I mentioned earlier" later refers to
        if (speaker == "user" or call.observe_all) and res.S and not flags.no_mentions then
          local have = {}
          for key in pairs(mem.entities) do have[key] = true end
          local extra = {}
          for _, m in ipairs(Coref.mentions_from_state(res.S)) do
            mem:mention(m.key, { type = m.type, name = m.name, w = have[m.key] and 0.05 or 0.2, role = "mention", speaker = speaker, weak = m.weak, pname = m.pname, exact = cues.exact, loc = m.loc })
            extra[#extra + 1] = { key = m.key, c1 = m.c1, c2 = m.c2 }
          end
          if #extra > 0 then Coref.describe_entities(view, res.S, extra, speaker) end
        end
      end
      result.sentences[#result.sentences + 1] = { res = res, interp = interp }
    end
    if meter.over then
      result.status = "limited"
      break
    end
  end
  if mem and not call.skip_utterance then mem:note_utterance(text, speaker) end
  local rendered = {}
  for i, s in ipairs(result.sentences) do rendered[i] = s.interp end
  result.main_index = pick_main(rendered)
  result.main = rendered[result.main_index]
  result.work = meter:snapshot()
  return result
end

return I

end

package.preload["asi.nlu.knowledge"] = function(...)
-- asi.nlu.knowledge: a searchable knowledge base built from supplied datasets.
--   datasets (asi.nlu.dataset)  ->  assertion extraction (asi.nlu.assertions)  ->  index (asi.nlu.index)  +  a lexicon OVERLAY.
-- The overlay is how unseen terminology becomes usable without rewriting the interpreter: entities discovered in the data are registered with
-- the same keys the interpreter produces for open-set mentions, relations named by structured columns are induced from their names, and every
-- overlay item records the records that justified it.  Nothing is learned from the interpreter's own outputs (no self-reinforcement).
local U = require("asi.nlu.util")
local Lex = require("asi.nlu.lex")
local Lattice = require("asi.nlu.lattice")
local P = require("asi.nlu.parse")
local Lexicon = require("asi.nlu.lexicon")
local Dataset = require("asi.nlu.dataset")
local Index = require("asi.nlu.index")
local Assertions = require("asi.nlu.assertions")
local UC = require("asi.nlu.unicode")
local Profile = require("asi.nlu.profile")
local QA = require("asi.nlu.qa")

local K = {}
K.__index = K
K.SCHEMA = "nlu.knowledge/1"

function K.new(base_lex, opts)
  opts = opts or {}
  local self = setmetatable({}, K)
  self.base = base_lex
  self.lex = Lexicon.new(base_lex)
  self.lex.spell = self.lex:build_spell(base_lex.spell)
  self.datasets, self.dataset_order = {}, {}
  self.index = Index.new()
  self.meter_budget = opts.record_budget or 400000
  self.vocab = {}            -- mention key -> { text, count, records = {id...}, types = {type -> n}, class_votes = {...} }
  self.aliases = {}          -- folded alias -> { key, evidence = {record ids} }  (an alias is accepted only when the data itself states it)
  self.alias_keys = {}       -- canonical key -> { mention keys that denote it }
  self.rel_induced = {}      -- relation id -> { name, records }
  self.reader_directed = {}  -- record id -> list of flagged sentences
  self.profiles = {}         -- dataset id -> asi.nlu.profile (what the segments of the dataset ARE: facts, persona statements, examples, turns ...)
  self.policy = {}           -- dataset id -> the user's reading of the dataset (see K:set_policy); empty = the dataset's own structure decides
  self.qa_report = {}        -- record id -> { converted = n, skipped = { reason ... } } for question / answer pairs
  self.revision = 0
  self.errors = {}
  return self
end

---------------------------------------------------------------- linking short strings (titles, triple cells)
local function fold(s) return UC.fold(s):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "") end

function K:link_text(text, expected)
  local an = Lex.analyze(text, {})
  if an.status == "rejected" or #an.units == 0 then return { text = text, key = "mention:" .. fold(text), status = "unseen", unverified_link = true } end
  local lat = Lattice.build(an, self.lex, {})
  local cover = lat:covers(1, 1, #an.units)[1]
  if cover then
    local S = P.new_state(an, self.lex, lat, cover, { flags = {} })
    S.sentence = an.sentences[1]
    for _, np in ipairs(P.parse_np(S, 1)) do
      if np.nxt > #S.chunks then
        local d = Assertions.describe_np(S, { flags = {} }, np, expected, "link")
        if d.key or d.literal or d.cands then return d end
      end
    end
  end
  return { text = text, key = "mention:" .. fold(text), status = "unseen", unverified_link = true }
end

---------------------------------------------------------------- per-record indexing
local function topic_of(self, rec)
  for _, f in ipairs(rec.text_fields or {}) do
    local lf = f:lower()
    if lf == "title" or lf == "name" or lf == "headline" or lf == "heading" then
      local d = self:link_text(rec.field_text[f])
      if d.key and not d.unverified_link then return d end
    end
  end
end

---------------------------------------------------------------- how the dataset is read: profile + the user's policy
function K:has_turns(profile, rec_id)
  local ra = profile.recs[rec_id]
  if not ra then return false end
  for _, sg in ipairs(ra.segs) do
    local r = Profile.role_of(profile, sg)
    if r == "turn_user" or r == "turn_assistant" then return true end
  end
  return false
end

function K:qa_interp()
  if not self.qa_interpreter or self.qa_interpreter.lex ~= self.lex then
    self.qa_interpreter = require("asi.nlu.interp").new({ lexicon = self.lex })
  end
  return self.qa_interpreter
end

local ALL_ROLES = { "style_spec", "style_example", "anti_example", "persona_declaration", "meta", "turn_user", "turn_other", "turn_system" }
-- policy: { reading = "facts" | nil, include = { role = true }, exclude = { role = true }, records = { [record id] = "knowledge" | "ignore" }, qa = false, persona = { ... } }
function K:effective_policy(did)
  local p = self.policy[did] or {}
  local inc, exc = {}, {}
  if p.reading == "facts" then for _, r in ipairs(ALL_ROLES) do inc[r] = true end end
  for r in pairs(p.include or {}) do inc[r] = true end
  for r in pairs(p.exclude or {}) do exc[r] = true end
  -- record overrides: a reference ("n=2", "about=Germany") names records of any dataset; only the records of this one count here
  local recmap = {}
  for _, rr in ipairs(p.records or {}) do
    for _, id in ipairs(self:resolve_record_ref(rr.ref)) do
      if id:sub(1, #did + 1) == did .. ":" then recmap[id] = rr.action end
    end
  end
  -- a pair is read through its question: when the user excludes either side of the conversation there are no pairs
  local qa = p.qa
  if exc.turn_assistant or exc.turn_user then qa = false end
  return { reading = p.reading, include = inc, exclude = exc, records = recmap, qa = qa, persona = p.persona or {} }
end

-- "n=2" the second record (in the order of the datasets; negative counts from the end), "about=Germany" the records whose text mentions it
function K:resolve_record_ref(ref)
  local ids = {}
  for _, did in ipairs(self.dataset_order) do
    local ds = self.datasets[did]
    for _, id in ipairs(ds.order) do if ds.records[id] then ids[#ids + 1] = id end end
  end
  local n = ref:match("^n=(%-?%d+)$")
  if n then
    n = tonumber(n)
    if n < 0 then n = #ids + 1 + n end
    return ids[n] and { ids[n] } or {}
  end
  local about = ref:match("^about=(.+)$")
  local out = {}
  if about then
    local needle = about:lower()
    for _, id in ipairs(ids) do
      local rec = self:record(id)
      if rec and (rec.text or ""):lower():find(needle, 1, true) then out[#out + 1] = id end
    end
  end
  return out
end

function K:profile(did) return self.profiles[did] end

-- the voice the dataset's OWN text is written in (the knowledge parts only): descriptors that most of its records show, for "talk like the dataset".
-- Reported, never adopted by itself: a loud encyclopedia is still an encyclopedia.
function K:data_style(did)
  local profile = self.profiles[did]
  local ds = self.datasets[did]
  if not (profile and ds) then return nil end
  local pol = self:effective_policy(did)
  local samples = {}
  for _, id in ipairs(ds.order) do
    local rec = ds.records[id]
    if rec and not rec.duplicate_of and #samples < 300 then
      for _, f in ipairs(rec.text_fields or {}) do
        local text = rec.field_text[f]
        if text and text ~= "" then
          local skip = Profile.skip_ranges(profile, rec.id, f, { include = pol.include, exclude = pol.exclude })
          if skip then
            local parts, pos = {}, 1
            for _, r in ipairs(skip) do
              if r.s > pos then parts[#parts + 1] = text:sub(pos, r.s - 1) end
              pos = r.e + 1
            end
            if pos <= #text then parts[#parts + 1] = text:sub(pos) end
            text = table.concat(parts, " ")
          end
          text = text:gsub("^%s+", ""):gsub("%s+$", "")
          if #text >= 8 then samples[#samples + 1] = text end
        end
      end
    end
  end
  if #samples < 3 then return nil end
  local descs, features = Profile.measure_samples(samples, true)
  if #descs == 0 then return nil end
  for _, d in ipairs(descs) do d.basis = "dataset_text" end
  return { dataset = did, descriptors = descs, n_samples = #samples, features = features }
end

function K:index_record(rec)
  local analysis = { assertions = {}, mentions = {}, aliases = {}, reader_directed = {}, sentences = 0 }
  if rec.duplicate_of then
    -- duplicates stay searchable but never corroborate: no assertions, flagged
    self.index:add(rec, analysis)
    return analysis
  end
  local meter = U.meter(self.meter_budget)
  local ex = Assertions.new(self.lex, { meter = meter })
  local topic = topic_of(self, rec)
  local profile = self.profiles[rec.dataset]
  local pol = self:effective_policy(rec.dataset)
  local rec_override = pol.records[rec.id]
  for _, f in ipairs(rec.text_fields or {}) do
    local text = rec.field_text[f]
    if text and text ~= "" then
      -- the parts of the field that are not knowledge: style specifications, example utterances, questions, instructions, descriptions of the dataset
      local skip
      if profile and rec_override ~= "knowledge" then
        skip = Profile.skip_ranges(profile, rec.id, f, { include = pol.include, exclude = pol.exclude })
        if rec_override == "ignore" then skip = { { s = 1, e = #text, role = "ignored" } } end
      end
      if skip then analysis.skip = analysis.skip or {}; analysis.skip[f] = skip end
      local r = ex:extract(text, { topic = topic, skip = skip })
      analysis.skipped_sentences = (analysis.skipped_sentences or 0) + (r.skipped or 0)
      for _, a in ipairs(r.assertions) do a.field = f; a.reliability = rec.reliability; analysis.assertions[#analysis.assertions + 1] = a end
      for _, m in ipairs(r.mentions) do m.field = f; analysis.mentions[#analysis.mentions + 1] = m end
      for _, al in ipairs(r.aliases) do analysis.aliases[#analysis.aliases + 1] = al end
      for _, rd in ipairs(r.reader_directed) do rd.field = f; analysis.reader_directed[#analysis.reader_directed + 1] = rd end
      analysis.sentences = analysis.sentences + r.sentences
      if r.limited then analysis.limited = true end
    end
  end
  if topic and topic.key then analysis.mentions[#analysis.mentions + 1] = { key = topic.key, type = topic.type, text = topic.text, field = "title", topic = true } end
  -- instructions the dataset aims at its reader are flagged as such whether or not they were also recognised as a style statement
  if profile then
    local ra = profile.recs[rec.id]
    for _, sg in ipairs(ra and ra.segs or {}) do
      if sg.role == "behavior_directive" then
        local flagged = false
        for _, rd in ipairs(analysis.reader_directed) do if rd.field == sg.field and rd.s <= sg.e and rd.e >= sg.s then flagged = true break end end
        if not flagged then
          analysis.reader_directed[#analysis.reader_directed + 1] = { text = sg.text, reasons = { sg.via }, s = sg.s, e = sg.e, field = sg.field, sent = 0, source = "profile" }
        end
      end
    end
    -- question / answer pairs: the answer is read through the question
    if pol.qa ~= false and (profile.pair_fields or self:has_turns(profile, rec.id)) then
      local pairs_ = Profile.pairs(profile, rec.id)
      if #pairs_ > 0 then
        local interp = self:qa_interp()
        local rep = { converted = 0, skipped = {} }
        for _, pr in ipairs(pairs_) do
          local qt = (rec.field_text[pr.q.field] or ""):sub(pr.q.s, pr.q.e)
          local at = (rec.field_text[pr.a.field] or ""):sub(pr.a.s, pr.a.e)
          local a, why = QA.convert(self, interp, qt, at)
          if a then
            a.field, a.reliability = pr.a.field, rec.reliability
            analysis.assertions[#analysis.assertions + 1] = a
            for _, d in ipairs({ a.from, a.to }) do
              if d and d.key and not d.literal then analysis.mentions[#analysis.mentions + 1] = { key = d.key, type = d.type, text = d.text, field = pr.a.field } end
            end
            rep.converted = rep.converted + 1
          else rep.skipped[#rep.skipped + 1] = why end
        end
        self.qa_report[rec.id] = rep
      end
    end
  end
  -- structured triple rows are explicit assertions (highest precision, still tagged with their provenance)
  if rec.triple then
    local t = rec.triple
    local rel = self.lex:rel_by_name(t.relation)
    local induced = false
    if not rel then
      local norm = t.relation:lower():gsub("[%s%-]+", "_"):gsub("[^%w_]", "")
      -- a relation named only by the data lives in the same "open:" namespace as relations inferred from unknown words in text or questions
      rel = self.lex:induce_relation(norm, { id = "open:" .. norm:gsub("e$", ""), source = "induced" })
      induced = true
      self.rel_induced[rel.id] = self.rel_induced[rel.id] or { name = t.relation, records = {} }
      table.insert(self.rel_induced[rel.id].records, rec.id)
    end
    local from = self:link_text(t.subject, rel.from)
    local to = self:link_text(t.object, rel.to)
    analysis.assertions[#analysis.assertions + 1] = { rel = rel.id, from = from, to = to, polarity = t.polarity or "positive", modality = "asserted", tense = "present",
      pattern = "structured_triple", structured = true, induced_relation = induced or nil, text = rec.text, sent = 0, s = 1, e = #rec.text, reliability = rec.reliability }
    for _, d in ipairs({ from, to }) do
      if d.key and not d.literal then analysis.mentions[#analysis.mentions + 1] = { key = d.key, type = d.type, text = d.text, field = "triple" } end
    end
  end
  -- wide table rows: the column name is the relation, the row's entity the subject, the cell the value
  if rec.wide then
    local subj_text = rec.wide.subject
    for _, cell in ipairs(rec.wide.cells) do
      local norm = cell.col:lower():gsub("[%s%-]+", "_"):gsub("[^%w_]", "")
      local rel = self.lex:rel_by_name(norm) or self.lex:rel_by_name((norm:gsub("s$", "")))
      local induced = false
      if not rel and norm ~= "" then
        rel = self.lex:induce_relation(norm, { id = "open:" .. norm:gsub("e$", ""), source = "induced" })
        induced = true
        self.rel_induced[rel.id] = self.rel_induced[rel.id] or { name = cell.col, records = {} }
        table.insert(self.rel_induced[rel.id].records, rec.id)
      end
      if rel then
        local from = self:link_text(subj_text, rel.from)
        local to = self:link_text(tostring(cell.value), rel.to)
        -- the row's entity is the subject unless its type fits the relation's other end better
        if from.type and rel.to and rel.from and self.lex:compat(from.type, rel.to) > self.lex:compat(from.type, rel.from) then from, to = to, from end
        analysis.assertions[#analysis.assertions + 1] = { rel = rel.id, from = from, to = to, polarity = "positive", modality = "asserted", tense = "present", pattern = "wide_table",
          structured = true, induced_relation = induced or nil, text = rec.text, sent = 0, s = 1, e = #rec.text, reliability = rec.reliability, field = cell.col }
        for _, d in ipairs({ from, to }) do
          if d.key and not d.literal then analysis.mentions[#analysis.mentions + 1] = { key = d.key, type = d.type, text = d.text, field = "wide" } end
        end
      end
    end
  end
  -- vocabulary + alias evidence
  for _, m in ipairs(analysis.mentions) do
    if m.key and m.key:sub(1, 8) == "mention:" and not m.weak then
      local v = self.vocab[m.key]
      if not v then v = { text = m.text, count = 0, records = {}, seen = {}, types = {}, class_votes = {} }; self.vocab[m.key] = v end
      v.count = v.count + 1
      if not v.seen[rec.id] then v.seen[rec.id] = true; v.records[#v.records + 1] = rec.id end
      if m.type then v.types[m.type] = (v.types[m.type] or 0) + 1 end
    end
  end
  for _, a in ipairs(analysis.assertions) do
    if a.is_class and a.from and a.from.key and self.vocab[a.from.key] and a.class_type then
      local v = self.vocab[a.from.key]
      v.class_votes[a.class_type] = (v.class_votes[a.class_type] or 0) + 1
    end
    -- role-signature type evidence for unseen participants
    if not a.is_class and a.rel then
      local rel = self.lex:get_rel(a.rel)
      for _, role in ipairs({ "from", "to" }) do
        local d = a[role]
        if rel and d and d.key and d.key:sub(1, 8) == "mention:" and self.vocab[d.key] and not d.literal then
          local v = self.vocab[d.key]
          v.sig_votes = v.sig_votes or {}
          v.sig_votes[rel[role]] = (v.sig_votes[rel[role]] or 0) + 1
        end
      end
    end
  end
  for _, al in ipairs(analysis.aliases) do
    local fa = fold(al.alias)
    local e = self.aliases[fa]
    if not e then e = { key = al.key, evidence = {} }; self.aliases[fa] = e end
    if e.key == al.key then
      e.evidence[#e.evidence + 1] = rec.id
      local list = self.alias_keys[al.key]
      if not list then list = {}; self.alias_keys[al.key] = list end
      local mk = "mention:" .. fa
      local dup = false
      for _, x in ipairs(list) do if x == mk then dup = true end end
      if not dup then list[#list + 1] = mk end
    else e.conflict = true end
  end
  if #analysis.reader_directed > 0 then self.reader_directed[rec.id] = analysis.reader_directed end
  self.index:add(rec, analysis)
  return analysis
end

---------------------------------------------------------------- overlay: dataset-discovered entities
local function best_vote(votes)
  local best, bn
  for t, n in pairs(votes or {}) do if not bn or n > bn or (n == bn and t < best) then best, bn = t, n end end
  return best, bn
end

function K:refresh_overlay()
  local added = 0
  for key, v in pairs(self.vocab) do
    if not self.lex.entities[key] and not self.base:get_entity(key) then
      local ty = best_vote(v.class_votes) or best_vote(v.types) or best_vote(v.sig_votes) or "entity"
      if not self.lex:has_type(ty) then ty = "entity" end
      local names = { { text = v.text, cs = false } }
      self.lex:add_entity({ id = key, type = ty, names = names, domain = {}, prior = 0.4, attr = {}, source = "dataset",
        evidence = { records = #v.records, mentions = v.count } })
      added = added + 1
    end
  end
  for fa, al in pairs(self.aliases) do
    if not al.conflict and not al.registered then
      local target = self.lex:get_entity(al.key)
      if target then
        self.lex:add_entity({ id = "alias:" .. fa, type = target.type, names = { { text = fa, cs = false } }, domain = target.domain, prior = 0.4, attr = {}, source = "dataset_alias",
          alias_of = al.key, evidence = al.evidence })
        al.registered = true
        added = added + 1
      end
    end
  end
  if added > 0 then self.lex.spell = self.lex:build_spell(self.base.spell) end
  return added
end

---------------------------------------------------------------- public API
-- opts: { dataset = id, version, label = {year=}, format, name, mapping }
function K:ingest(text, opts)
  opts = opts or {}
  local did = opts.dataset or "dataset"
  local ds = self.datasets[did]
  if not ds then
    ds = Dataset.new({ id = did, version = opts.version, label = opts.label })
    self.datasets[did] = ds
    self.dataset_order[#self.dataset_order + 1] = did
  end
  local report = ds:ingest(text, opts)
  local n_assert, n_flag = 0, 0
  -- what the records ARE comes first (field names, speaker labels, persona / style statements, examples), then they are read accordingly
  local profile = self.profiles[did]
  if not profile then profile = Profile.new(); self.profiles[did] = profile end
  local fresh = {}
  for _, rec in ipairs(report.records or {}) do
    if self.datasets[did].records[rec.id] == rec then
      if profile.recs[rec.id] then Profile.remove_record(profile, rec.id) end
      fresh[#fresh + 1] = rec
    end
  end
  Profile.add_records(profile, fresh, { lex = self.base })
  for _, rec in ipairs(report.records or {}) do
    if self.datasets[did].records[rec.id] == rec then
      local an = self:index_record(rec)
      n_assert = n_assert + #an.assertions
      n_flag = n_flag + #an.reader_directed
    end
  end
  self.revision = self.revision + 1
  report.assertions = n_assert
  report.reader_directed = n_flag
  report.overlay_added = self:refresh_overlay()
  report.records = nil   -- the per-record table stays inside the dataset
  local kind, shares = Profile.kind(profile)
  report.dataset_kind = kind
  report.roles = Profile.summary(profile).roles
  return report
end

-- the user's reading of a dataset changed ("treat the examples as facts"): the derived state (index, overlay, vocabulary) is rebuilt from the records
-- policy: one reading for every dataset (what the user said applies to "the dataset"), or nil to go back to the structure the data itself shows
function K:set_policy(did, policy)
  self.policy[did] = policy
  return self:rebuild()
end

local function policy_key(p) return p and U.json_encode(p, { sort = true }) or "" end
function K:set_policy_all(policy)
  local changed = false
  for _, did in ipairs(self.dataset_order) do
    if policy_key(self.policy[did]) ~= policy_key(policy) then self.policy[did] = policy; changed = true end
  end
  if changed then self:rebuild() end
  return changed
end

function K:rebuild()
  self.lex = Lexicon.new(self.base)
  self.lex.spell = self.lex:build_spell(self.base.spell)
  self.index = Index.new()
  self.vocab, self.aliases, self.alias_keys, self.rel_induced = {}, {}, {}, {}
  self.reader_directed, self.qa_report = {}, {}
  self.qa_interpreter = nil
  for _, did in ipairs(self.dataset_order) do
    local ds = self.datasets[did]
    local recs = {}
    for _, id in ipairs(ds.order) do
      local rec = ds.records[id]
      if rec then recs[#recs + 1] = rec end
    end
    -- the profile is derived again from the records, then the user's statements about what a record IS are applied to it
    local pr = Profile.new()
    Profile.add_records(pr, recs, { lex = self.base })
    self.profiles[did] = pr
    local pol = self:effective_policy(did)
    for id, action in pairs(pol.records) do
      if action == "style_example" then Profile.force_role(pr, self:record(id), "style_example") end
    end
    for _, rec in ipairs(recs) do self:index_record(rec) end
  end
  self.revision = self.revision + 1
  return self:refresh_overlay()
end

function K:remove(record_id)
  local did = record_id:match("^([^:]+):")
  local ds = did and self.datasets[did]
  if not ds then return false end
  ds:remove(record_id)
  self.index:remove(record_id)
  if self.profiles[did] then Profile.remove_record(self.profiles[did], record_id) end
  self.revision = self.revision + 1
  return true
end

-- every key under which the data may refer to the same thing (canonical key + evidence-backed aliases)
function K:variants(key)
  local out = { key }
  for _, k in ipairs(self.alias_keys[key] or {}) do out[#out + 1] = k end
  return out
end

function K:canonical(key)
  local e = self.lex:get_entity(key)
  if e and e.alias_of then return e.alias_of end
  if key:sub(1, 8) == "mention:" then
    local al = self.aliases[key:sub(9)]
    if al and not al.conflict then return al.key end
  end
  return key
end

-- a stable key for caches: changes whenever any dataset record, the overlay, or the schema version changes
function K:digest()
  local parts = { K.SCHEMA }
  for _, did in ipairs(self.dataset_order) do parts[#parts + 1] = self.datasets[did]:digest() end
  parts[#parts + 1] = tostring(self.index.revision)
  for _, did in ipairs(self.dataset_order) do
    local pol = self.policy[did]
    if pol then parts[#parts + 1] = did .. "=" .. U.json_encode(pol, { sort = true }) end
  end
  return U.sha256(table.concat(parts, "|"))
end

function K:record(id)
  local did = id:match("^([^:]+):")
  return did and self.datasets[did] and self.datasets[did].records[id]
end

-- is `ds` the dataset a constraint such as "the 2020 dataset" refers to?
function K:dataset_label_of(rec)
  local ds = self.datasets[rec.dataset]
  return ds and ds.label or nil
end

-- terminology report: unfamiliar terms in the supplied data, what the data says about them, and whether their meaning is ambiguous
function K:terminology(limit)
  local out = {}
  for key, v in pairs(self.vocab) do
    local entry = { key = key, text = v.text, mentions = v.count, records = #v.records, kind = "entity" }
    entry.types = {}
    for t, n in pairs(v.class_votes) do entry.types[#entry.types + 1] = { type = t, evidence = "classification", n = n } end
    for t, n in pairs(v.types) do entry.types[#entry.types + 1] = { type = t, evidence = "mention", n = n } end
    table.sort(entry.types, function(a, b) if a.n ~= b.n then return a.n > b.n end return a.type < b.type end)
    entry.ambiguous = (best_vote(v.class_votes) ~= nil) and (function() local c = 0; for _ in pairs(v.class_votes) do c = c + 1 end return c > 1 end)() or nil
    local defs = {}
    for _, a in ipairs(self.index:classifications(key)) do defs[#defs + 1] = { class = a.class_text, record = a.record, text = a.text } end
    entry.definitions = defs
    out[#out + 1] = entry
  end
  table.sort(out, function(a, b) if a.mentions ~= b.mentions then return a.mentions > b.mentions end return a.key < b.key end)
  if limit and #out > limit then for i = #out, limit + 1, -1 do out[i] = nil end end
  return out
end

function K:stats()
  local s = self.index:stats()
  s.datasets = #self.dataset_order
  s.vocabulary = (function() local c = 0; for _ in pairs(self.vocab) do c = c + 1 end return c end)()
  s.induced_relations = (function() local c = 0; for _ in pairs(self.rel_induced) do c = c + 1 end return c end)()
  s.reader_directed_records = (function() local c = 0; for _ in pairs(self.reader_directed) do c = c + 1 end return c end)()
  s.digest = self:digest()
  return s
end

return K

end

package.preload["asi.nlu.lattice"] = function(...)
-- asi.nlu.lattice: phrase + entity recognition as a LATTICE of competing spans over the lexer's units.
-- Nothing is committed here: every attested reading of every span is kept, and a k-best dynamic program
-- proposes alternative non-overlapping covers (segmentations) for the semantic stage to compete over.
local U = require("asi.nlu.util")
local UC = require("asi.nlu.unicode")

local Lattice = {}

local NAME_CONNECTORS = U.set({ "of", "de", "van", "von", "der", "la", "le", "du", "di", "da", "del", "for", "the", "&", "den", "al", "bin" })
local TITLE_VERBS = U.set({ "wrote", "write", "writes", "written", "directed", "direct", "directs", "painted", "paint", "composed", "compose", "authored", "published", "read", "reading",
  "watched", "watch", "starred", "starring", "entitled", "titled", "called", "named", "about", "reviewed", "review", "adapted" })
local TITLE_NOUNS = U.set({ "novel", "book", "film", "movie", "song", "album", "play", "poem", "series", "show", "game", "painting", "opera", "musical", "story", "article", "paper" })
local TITLE_PREFIX = U.set({ "dr", "mr", "mrs", "ms", "prof", "sir", "lady", "lord", "president", "senator", "gen", "col", "capt", "rev" })

local function span_key(i, j) return i .. ":" .. j end

-- words of the dramatic register (interjections, intensifiers, hyperbole, praise ...): in SHOUTED text they are ordinary words, never name candidates
local STYLE_KNOWN
local function style_known(form)
  if not STYLE_KNOWN then
    STYLE_KNOWN = {}
    local L = require("asi.nlu.data.style_lex")
    for _, list in ipairs({ L.interjections, L.intensifiers, L.hyperbole, L.positive, L.hedges, L.formal_markers, L.informal_markers, L.polite_markers }) do
      for _, p in ipairs(list) do for w in p:lower():gmatch("[%a']+") do STYLE_KNOWN[w] = true end end
    end
    for _, ws in pairs(L.voice_markers) do for _, p in ipairs(ws) do for w in p:lower():gmatch("[%a']+") do STYLE_KNOWN[w] = true end end end
  end
  return STYLE_KNOWN[form] == true
end

-- a word the lexicon knows as an ordinary word (function word, verb, adjective, relational/type noun) -- not a name
local function is_common(lex, u)
  local f = u.form
  if lex:cats(f) then return true end
  for _, r in ipairs(lex:readings(f)) do if r.pos == "verb" or r.pos == "adj" then return true end end
  local has_entity, has_word = false, false
  for _, m in ipairs(lex:match_at({ u }, 1)) do
    if m.j == 1 then
      for _, e in ipairs(m.entries) do
        if e.kind == "entity" then has_entity = true else has_word = true end
      end
    end
  end
  return has_word and not has_entity
end

local function joined_forms(units, i, j)
  local t = {}
  for k = i, j do t[#t + 1] = units[k].form end
  return table.concat(t, " ")
end

local function joined_raw(units, i, j)
  local t = {}
  for k = i, j do t[#t + 1] = units[k].raw end
  return table.concat(t, " ")
end

-- does the surface text honour the entry's case sensitivity? (US vs us)
local function cs_ok(units, i, j, entry)
  if not entry.cs then return true end
  local want = entry.name:gsub("%.", ""):gsub("%s+", "")
  local have = joined_raw(units, i, j):gsub("%.", ""):gsub("%s+", "")
  return want == have
end

local function case_exact(units, i, j, entry)
  return joined_raw(units, i, j):gsub("%.", "") == entry.name:gsub("%.", "")
end

---------------------------------------------------------------- build
function Lattice.build(an, lex, opts)
  opts = opts or {}
  local units = an.units
  local n = #units
  local spans, by_ext = {}, {}
  local meter = opts.meter

  local function add(i, j, reading, kind, score)
    local key = span_key(i, j)
    local sp = by_ext[key]
    if not sp then
      sp = { i = i, j = j, readings = {}, kind = kind, score = score, text = an.original:sub(units[i].s, units[j].e) }
      by_ext[key] = sp
      spans[#spans + 1] = sp
    end
    -- one reading per entity id (several names of one entity may match the same extent): keep the best-matching one
    if reading.kind == "entity" then
      for idx, r in ipairs(sp.readings) do
        if r.kind == "entity" and r.entry.id == reading.entry.id and not r.fuzzy == not reading.fuzzy then
          if reading.exact_case and not r.exact_case then sp.readings[idx] = reading end
          return sp
        end
      end
    end
    sp.readings[#sp.readings + 1] = reading
    if score > sp.score then sp.score = score; sp.kind = kind end
    return sp
  end

  -- 1. attested spans from the phrase trie (core lexicon + dataset overlay)
  for i = 1, n do
    if meter and not meter:tick("lattice_match", 1) then break end
    for _, m in ipairs(lex:match_at(units, i)) do
      local len = m.j - i + 1
      for _, e in ipairs(m.entries) do
        if e.kind == "entity" then
          if cs_ok(units, i, m.j, e) then
            local exact = case_exact(units, i, m.j, e)
            add(i, m.j, { kind = "entity", entry = e, exact_case = exact }, "entity", 2.0 + 0.5 * (len - 1) + (exact and 0.2 or 0))
          end
        elseif e.kind == "sense" then
          local sc = (len > 1) and (1.8 + 0.5 * (len - 1)) or 0.4
          local sp = add(i, m.j, { kind = "sense", sense = e.sense, num = e.num }, len > 1 and "mwe" or "word_sense", sc)
        elseif e.kind == "relnoun" then
          add(i, m.j, { kind = "relnoun", entry = e }, len > 1 and "mwe" or "word_sense", (len > 1) and (1.6 + 0.4 * (len - 1)) or 0.6)
        elseif e.kind == "relverb" then
          add(i, m.j, { kind = "relverb", entry = e }, len > 1 and "mwe" or "word_sense", (len > 1) and (1.6 + 0.4 * (len - 1)) or 0.5)
        elseif e.kind == "actverb" then
          add(i, m.j, { kind = "actverb", entry = e }, "mwe", 1.6 + 0.4 * (len - 1))
        end
      end
    end
  end

  -- 2. temporal expressions and numbers (typed spans keep dates from being split into words)
  for _, t in ipairs(an.temporal or {}) do
    if t.u1 and t.u2 and t.kind ~= "weekday" then
      add(t.u1, t.u2, { kind = "temporal", expr = t }, "temporal", 1.0 + 0.3 * (t.u2 - t.u1))
    end
  end
  for _, nm in ipairs(an.numbers or {}) do
    if nm.kind ~= "digit" or nm.u2 > nm.u1 then
      add(nm.u1, nm.u2, { kind = "number", num = nm }, "number", 0.9 + 0.2 * (nm.u2 - nm.u1))
    end
  end

  -- 3. atomic literals: identifiers, URLs, paths, handles, versions
  for i = 1, n do
    local u = units[i]
    if u.case_sensitive and not u.hy then
      add(i, i, { kind = "literal", unit = u }, "literal", 1.5)
    end
  end

  -- 4. quoted strings (titles, exact phrases)
  do
    local toks = an.tokens
    local tok2unit = {}
    for ui, u in ipairs(units) do tok2unit[u.tok] = tok2unit[u.tok] or ui end
    local k = 1
    while k <= #toks do
      local t = toks[k]
      if t.kind == "punct" and (t.role == "open_quote" or t.role == "quote") and not t.single then
        local close
        for z = k + 1, math.min(#toks, k + 14) do
          local c = toks[z]
          if c.kind == "punct" and (c.role == "close_quote" or c.role == "quote") and not c.single then close = z break end
          if c.kind == "punct" and c.role == "sent_end" then break end
        end
        if close and close > k + 1 then
          local a, b
          for z = k + 1, close - 1 do
            if tok2unit[toks[z].i] then a = a or tok2unit[toks[z].i]; b = tok2unit[toks[z].i] end
          end
          if a and b then
            local ub = b
            while units[ub + 1] and units[ub + 1].tok == units[b].tok do ub = ub + 1 end
            add(a, ub, { kind = "quote", text = an.original:sub(units[a].s, units[ub].e) }, "quote", 1.4 + 0.1 * (ub - a))
          end
          k = close
        end
      end
      k = k + 1
    end
  end

  -- 5. unseen proper names (open-set): capitalised runs typed by head words
  local function sentence_initial(u) return u.i == 1 or units[u.i - 1].sent ~= u.sent end
  local i = 1
  while i <= n do
    local u = units[i]
    local sent = an.sentences[u.sent or 0]
    local shout = sent and sent.shout
    -- a brand written with an inner capital ("iPhone", "eBay", "iPad") is as name-like as a capitalised word
    local capital = (u.cap or u.mixed_case) and not shout and (u.kind == "word" or u.kind == "abbrev" or u.kind == "acronym" or u.kind == "initial") and not u.case_sensitive
    -- an ALL-CAPS word inside a sentence that is not shouted is emphasis when it is an ordinary word ("the MOST FASCINATING question EVER"), not a name
    if capital and u.allcaps and u.kind == "word" and not u.acr_known and (#u.form >= 7 or is_common(lex, u)) then capital = false end
    local initial = capital and sentence_initial(u)
    local common = capital and is_common(lex, u)
    -- "Compare", "Did", "Is" ... are capitalised only by position: they must not swallow the names that follow them
    if capital and not (initial and common) then
      local j = i
      -- connectors ("of", "for", ...) join a name only after an organisation/place head word ("University of X", "Bank of X"),
      -- never after an ordinary common word ("CEO of Acme": CEO is a relational noun, not the start of a name)
      local connect_ok = lex:headcue(u.form) ~= nil or not common
      -- a title ("Pride and Prejudice", "Harry Potter and the Chamber of Secrets") follows a verb / noun that introduces a work
      local merge_alts = {}
      local title_ctx = false
      do
        local p1, p2 = units[i - 1], units[i - 2]
        if p1 and p1.sent == u.sent and not u.pre and (TITLE_VERBS[p1.form] or (p2 and p2.sent == u.sent and TITLE_NOUNS[p1.form] == nil and TITLE_NOUNS[p2.form] and (p1.form == "titled" or p1.form == "called" or p1.form == "named" or p1.form == "entitled")) or TITLE_NOUNS[p1.form]) then title_ctx = true end
      end
      -- extend over capitalised units and name connectors ("and" only in a title or inside an organisation name that ends in a head word)
      while true do
        local nx = units[j + 1]
        if not nx or nx.pre or nx.sent ~= u.sent then break end
        if (nx.form == "and" or nx.form == "&") and not nx.cap then
          -- look ahead over the capitalised tail
          local t, head_found, tail_ok = j + 2, false, false
          if units[t] and units[t].form == "the" and title_ctx then t = t + 1 end
          local last_cap
          while units[t] and not units[t].pre and units[t].sent == u.sent and (units[t].cap or (title_ctx and (units[t].form == "of" or units[t].form == "the" or units[t].form == "in" or units[t].form == "and" or units[t].form == "for" or units[t].form == "to" or units[t].form == "a"))) do
            if units[t].cap then last_cap = t; tail_ok = true; if lex:headcue(units[t].form) then head_found = true end end
            t = t + 1
          end
          -- "Company A and Company B": two organisations; "Pellucid Freight and Logistics Holdings": one name whose HEAD WORD comes last
          local first_has_head = false
          for q = i, j do if lex:headcue(units[q].form) then first_has_head = true end end
          if first_has_head and not title_ctx then head_found = false end
          if head_found and last_cap and not lex:headcue(units[last_cap].form) then head_found = false end
          local known_entity = false
          for q = i, last_cap or i do
            if units[q].cap then
              for _, m in ipairs(lex:match_at(units, q)) do
                for _, e in ipairs(m.entries) do if e.kind == "entity" then known_entity = true end end
              end
            end
          end
          if tail_ok and last_cap and not known_entity and title_ctx then j = last_cap
          elseif tail_ok and last_cap and not known_entity and head_found then
            -- "Pellucid Freight AND Logistics Holdings": one name or two ("Harrow Dynamics and Vireo Labs")?  Both readings compete as alternative covers.
            merge_alts[#merge_alts + 1] = last_cap
            break
          else break end
        elseif nx.form == "the" and title_ctx and not nx.cap and units[j + 2] and units[j + 2].cap and not units[j + 2].pre then j = j + 2
        elseif nx.form == "of" and title_ctx and units[j + 2] and not units[j + 2].pre then
          local t = j + 2
          if units[t].form == "the" and units[t + 1] and units[t + 1].cap then t = t + 1 end
          if units[t].cap then j = t else break end
        elseif nx.cap and not shout and (nx.kind == "word" or nx.kind == "abbrev" or nx.kind == "acronym" or nx.kind == "initial" or nx.kind == "number") then j = j + 1
        -- "Area 51", "Apollo 11", "Windows 11": a small whole number right after a capitalised name belongs to it (a year or a larger number does not)
        elseif nx.kind == "number" and nx.numval and nx.numval == math.floor(nx.numval) and nx.numval >= 1 and nx.numval <= 999 and j == i and not nx.unit and not (units[j + 2] and units[j + 2].kind == "word" and not units[j + 2].cap and not units[j + 2].pre and lex:resource(units[j + 2].form)) then j = j + 1
        elseif NAME_CONNECTORS[nx.form] and not nx.cap and connect_ok then
          local nn = units[j + 2]
          if nn and not nn.pre and nn.cap and nn.sent == u.sent then j = j + 2 else break end
        else break end
      end
      local multi = j > i
      local last = units[j]
      local type_guess = lex:headcue(last.form) or lex:headcue(u.form) or (TITLE_PREFIX[u.form] and "person") or nil
      -- a final token that mixes letters and digits ("X2", "A380", "RTX4090") is a model code: the name denotes a product
      if not type_guess and (last.form:match("^%a+%d+%a*$") or last.form:match("^%d+%a+$")) and #last.form <= 8 and last.kind ~= "number" then type_guess = "product" end
      local sc = 0.8 + 0.3 * (j - i)
      -- "West Germany", "Northern Ireland": a capitalised modifier + an attested entity is a DIFFERENT, open-set entity of the attested one's type
      local extends
      if multi and not type_guess and not TITLE_PREFIX[u.form] then
        for _, m in ipairs(lex:match_at(units, j)) do
          for _, e in ipairs(m.entries) do
            if e.kind == "entity" and m.j == j then extends = e end
          end
        end
        if extends then type_guess = extends.etype; sc = sc + 1.7 end
      end
      local ok = true
      if initial and not multi and not type_guess and not u.hy then
        -- sentence-initial single unknown word: weak name guess only if the lexicon has never seen the word
        if is_common(lex, u) then ok = false else sc = 0.45 end
      end
      if common and not multi and not initial and u.form ~= "i" then
        -- a known common word capitalised mid-sentence ("Apple" is handled by the gazetteer; "Is" after a colon is not a name)
        sc = 0.55
      end
      if u.form == "i" then ok = false end
      if ok then
        -- capitalisation is the ONLY evidence for a sentence-initial single word: flagged so memory does not treat it as an established entity
        local weak = (initial and not multi and not type_guess) or nil
        add(i, j, { kind = "name", type_guess = type_guess, text = an.original:sub(units[i].s, units[j].e), multiword = multi, weak = weak,
          head_cue = (lex:headcue(last.form) or lex:headcue(u.form)) and true or nil }, "name_guess", sc)
        for _, aj in ipairs(merge_alts) do
          local al = units[aj]
          add(i, aj, { kind = "name", type_guess = lex:headcue(al.form) or type_guess, text = an.original:sub(units[i].s, units[aj].e), multiword = true, head_cue = true },
            "name_guess", 0.8 + 0.3 * (aj - i) - 0.2)
        end
      end
      i = j + 1
    else
      i = i + 1
    end
  end

  -- 5b. case-less text ("who founded acme robotics"): capitalisation carries no information, so a run of words unknown to the lexicon that ends in an
  --     organisation / place HEAD WORD (robotics, labs, industries, university, ...) is a name guess typed by that head word.  Weak by construction.
  do
    local nocase = {}
    for _, u in ipairs(units) do
      if u.sent then
        if nocase[u.sent] == nil then nocase[u.sent] = true end
        if u.cap then nocase[u.sent] = false end
      end
    end
    local k = 1
    while k <= n do
      local u = units[k]
      if nocase[u.sent] and u.kind == "word" and not u.cap and not is_common(lex, u) and #u.form >= 3 then
        local j = k
        while true do
          local nx = units[j + 1]
          if nx and not nx.pre and nx.sent == u.sent and nx.kind == "word" and (lex:headcue(nx.form) or (not is_common(lex, nx) and #nx.form >= 3)) then j = j + 1 else break end
        end
        local head = j > k and lex:headcue(units[j].form) or nil
        if head then
          add(k, j, { kind = "name", type_guess = head, text = an.original:sub(units[k].s, units[j].e), multiword = true, weak = true, head_cue = true }, "name_guess", 0.7 + 0.3 * (j - k))
        end
        k = j + 1
      else k = k + 1 end
    end
  end

  -- 5c. SHOUTED sentences: capitals say nothing about names, so a run of up to three ALL-CAPS words that neither the lexicon nor the dramatic register knows
  --     is a weak name guess (typed by a head word such as CORP / LABS when there is one).  Weak by construction: never an established entity.
  do
    local k = 1
    while k <= n do
      local u = units[k]
      local sent = an.sentences[u.sent or 0]
      if sent and sent.shout and u.kind == "word" and u.allcaps and #u.form >= 3 and not u.alts and not is_common(lex, u) and not style_known(u.form) then
        local known_entity = false
        for _, m in ipairs(lex:match_at(units, k)) do
          for _, e in ipairs(m.entries) do if e.kind == "entity" then known_entity = true end end
        end
        if not known_entity then
          local j = k
          while j - k < 2 do
            local nx = units[j + 1]
            if nx and not nx.pre and nx.sent == u.sent and nx.kind == "word" and nx.allcaps and #nx.form >= 3 and (lex:headcue(nx.form) or (not is_common(lex, nx) and not style_known(nx.form))) then j = j + 1 else break end
          end
          local type_guess = lex:headcue(units[j].form) or lex:headcue(u.form)
          add(k, j, { kind = "name", type_guess = type_guess, text = an.original:sub(units[k].s, units[j].e), multiword = j > k, weak = true, shouted = true,
            head_cue = type_guess and true or nil }, "name_guess", 0.5 + 0.2 * (j - k))
          k = j + 1
        else k = k + 1 end
      else k = k + 1 end
    end
  end

  -- 6. fuzzy readings for UNKNOWN words (typos): proposals only, flagged and down-weighted. Known words are never reinterpreted.
  --    4-letter words are too short to trust. Entities need a capitalised surface (or a strong match); relation words / senses any case.
  for ui, u in ipairs(units) do
    if u.alts and #u.alts > 0 and #u.form >= 5 then
      for _, a in ipairs(u.alts) do
        if a.conf >= 0.45 then
          local fake = { { form = a.form } }
          for _, m in ipairs(lex:match_at(fake, 1)) do
            for _, e in ipairs(m.entries) do
              -- a fuzzy span ties with a plain word in the cover search (0.1): the literal reading is never displaced by a guess;
              -- hypotheses decide, and a fuzzy lexeme earns no attestation credit and pays a penalty
              if e.kind == "entity" and not e.cs and a.kind == "entity" and (u.cap or a.conf >= 0.7) then
                add(ui, ui, { kind = "entity", entry = e, fuzzy = a.conf, fuzzy_from = u.raw, fuzzy_to = a.form }, "entity", 0.1)
              elseif e.kind == "relnoun" or e.kind == "relverb" then
                local ec = U.shallow(e); ec.fuzzy = a.conf
                add(ui, ui, { kind = e.kind, entry = ec, fuzzy = a.conf, fuzzy_from = u.raw }, "word_sense", 0.1)
              elseif e.kind == "sense" and not u.cap then
                add(ui, ui, { kind = "sense", sense = e.sense, num = e.num, fuzzy = a.conf, fuzzy_from = u.raw }, "word_sense", 0.1)
              end
            end
          end
        end
      end
    end
  end

  -- 7. compositional kind readings: an attested multiword concept "<kind> <relational noun>" ("financial capital") is ALSO read
  --    as the relation with a kind modifier, so the relation reading is not lost to the lexicalised concept.
  for _, sp in ipairs(spans) do
    if sp.j > sp.i then
      local last = by_ext[span_key(sp.j, sp.j)]
      if last then
        local prefix = joined_forms(units, sp.i, sp.j - 1)
        for _, r in ipairs(last.readings) do
          if r.kind == "relnoun" then
            local rel = lex:get_rel(r.entry.rel)
            if rel and rel.kinds and rel.kinds[prefix] then
              local ec = U.shallow(r.entry); ec.kind_prefix = prefix
              add(sp.i, sp.j, { kind = "relnoun", entry = ec }, sp.kind, sp.score)
            end
          end
        end
      end
    end
  end

  -- index
  local by_start = {}
  for _, sp in ipairs(spans) do
    by_start[sp.i] = by_start[sp.i] or {}
    table.insert(by_start[sp.i], sp)
  end
  for _, list in pairs(by_start) do table.sort(list, function(a, b) return (a.j - a.i) > (b.j - b.i) end) end

  local lat = { an = an, units = units, spans = spans, by_start = by_start, n = n }

  -- k-best covers: choose non-overlapping spans maximising total score; unit not in a span costs a small word score
  -- covers(k [, a, b]): k-best covers of unit range [a, b] (default: everything); spans must lie inside the range
  function lat:covers(k, a, b)
    k = k or 4
    a, b = a or 1, b or n
    local W = 0.1
    -- best[p] = list of {score, span|nil, next_rank} for suffix starting at p, size <= k
    local best = { [b + 1] = { { score = 0 } } }
    for p = b, a, -1 do
      local cand = {}
      for rank, bb in ipairs(best[p + 1]) do cand[#cand + 1] = { score = bb.score + W, span = nil, nxt = p + 1, rank = rank } end
      for _, sp in ipairs(by_start[p] or {}) do
        if sp.j <= b then
          for rank, bb in ipairs(best[sp.j + 1]) do
            cand[#cand + 1] = { score = bb.score + sp.score, span = sp, nxt = sp.j + 1, rank = rank }
          end
        end
      end
      table.sort(cand, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        local la = a.span and (a.span.j - a.span.i) or -1
        local lb = b.span and (b.span.j - b.span.i) or -1
        return la > lb
      end)
      -- k-best with distinct extents so alternatives are real segmentations, not duplicates
      local keep, seen = {}, {}
      for _, c in ipairs(cand) do
        local sig = (c.span and (c.span.j .. "") or "w") .. ":" .. c.nxt .. ":" .. c.rank
        if not seen[sig] then seen[sig] = true; keep[#keep + 1] = c end
        if #keep >= k then break end
      end
      best[p] = keep
    end
    local out = {}
    for rank = 1, #best[a] do
      local chosen, p, r = {}, a, rank
      local total = best[a][rank].score
      while p <= b do
        local c = best[p][r]
        chosen[#chosen + 1] = c.span or { i = p, j = p, kind = "word", readings = {}, score = W, text = an.original:sub(units[p].s, units[p].e) }
        p, r = c.nxt, c.rank
      end
      out[#out + 1] = { score = total, spans = chosen }
    end
    -- drop covers identical in extents to an earlier one
    local uniq, seen = {}, {}
    for _, c in ipairs(out) do
      local sig = {}
      for _, sp in ipairs(c.spans) do sig[#sig + 1] = sp.i .. "-" .. sp.j .. sp.kind end
      sig = table.concat(sig, ",")
      if not seen[sig] then seen[sig] = true; uniq[#uniq + 1] = c end
    end
    return uniq
  end

  -- segmentation confidence: margin between the best and runner-up cover (raw, uncalibrated)
  function lat:segmentation_margin()
    local cv = self:covers(2)
    if #cv < 2 then return 1.0, cv end
    local a, b = cv[1].score, cv[2].score
    return U.clamp((a - b) / math.max(a, 1e-6), 0, 1), cv
  end

  if meter then meter:tick("lattice_spans", #spans) end
  return lat
end

return Lattice

end

package.preload["asi.nlu.lex"] = function(...)
-- asi.nlu.lex: lexical front end.
--   * original text is NEVER modified; every token/unit carries exact byte (s,e) and code point (cs,ce) offsets
--     (1-based, inclusive:  original:sub(tok.s, tok.e) == tok.text).
--   * tokens = surface segmentation; units = comparison-level "match words" (hyphen parts, contraction
--     expansions) that still point back to their token.
--   * comparison forms (fold) are separate fields; case-sensitive kinds (identifiers, URLs, ...) keep raw case.
local U = require("asi.nlu.util")
local UC = require("asi.nlu.unicode")

local Lex = { SCHEMA = "nlu.lex/1" }

local S = U.set
local ABBR = S({ "mr", "mrs", "ms", "dr", "prof", "sr", "jr", "st", "mt", "vs", "etc", "inc", "ltd", "co", "corp", "dept",
  "univ", "gen", "col", "lt", "sgt", "capt", "cmdr", "rev", "hon", "gov", "sen", "rep", "pres", "fig", "eq", "vol", "pp",
  "approx", "est", "ave", "blvd", "rd", "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep", "sept", "oct", "nov", "dec",
  "mon", "tue", "wed", "thu", "fri", "sat", "sun", "cf", "al", "ed", "eds", "assn", "bros", "no", "ca", "approx", "incl",
  "excl", "esp", "ref", "resp", "dept", "div", "ft", "oz", "lb", "lbs", "mfg", "min", "max", "avg", "sec" })
local TITLE_ABBR = S({ "mr", "mrs", "ms", "dr", "prof", "sr", "jr", "st", "mt", "gen", "col", "lt", "sgt", "capt", "cmdr", "rev",
  "hon", "gov", "sen", "rep", "pres", "no", "fig", "eq", "vol", "pp", "vs", "cf", "al" })
local SENT_STARTERS = S({ "the", "a", "an", "it", "he", "she", "they", "we", "i", "in", "on", "at", "this", "that", "these",
  "those", "if", "when", "as", "but", "and", "so", "then", "there", "here", "what", "who", "how", "why", "where", "which",
  "after", "before", "however", "also", "for", "my", "our", "his", "her", "their", "its", "you", "your" })
local EXT_OR_TLD = S({ "com", "org", "net", "edu", "gov", "io", "ai", "dev", "app", "co", "us", "uk", "de", "fr", "js", "py",
  "lua", "rs", "go", "c", "h", "cpp", "java", "json", "txt", "md", "csv", "html", "css", "xml", "yaml", "yml", "toml", "sh",
  "ts", "jsx", "tsx", "php", "rb", "sql", "pdf", "doc", "docx", "xls", "xlsx", "png", "jpg", "gif", "zip", "tar", "gz", "log",
  "ini", "cfg", "conf", "exe", "dll", "so", "bin", "info", "biz", "me", "tv", "cc", "ru", "cn", "jp", "in", "ca", "au", "eu" })
local CONTRACT_NEG_STEMS = S({ "do", "does", "did", "is", "are", "was", "were", "has", "have", "had", "would", "could", "should",
  "might", "must", "need", "ought", "dare", "ai", "ca", "wo", "sha", "may", "mustn" })
local IRREG_STEM = { ca = "can", wo = "will", sha = "shall", ai = "be" }
local CLITIC_NORM = { s = "'s", re = "are", ve = "have", ll = "will", d = "would", m = "am" }
local EXPAND = { gonna = { "going", "to" }, wanna = { "want", "to" }, gotta = { "got", "to" }, gimme = { "give", "me" },
  lemme = { "let", "me" }, dunno = { "do", "not", "know" }, kinda = { "kind", "of" }, sorta = { "sort", "of" },
  outta = { "out", "of" }, lotta = { "lot", "of" }, hafta = { "have", "to" }, oughta = { "ought", "to" },
  -- contractions typed without the apostrophe ("whats", "dont"): expanded for matching, the surface text is untouched
  whats = { "what", "is" }, thats = { "that", "is" }, whos = { "who", "is" }, hows = { "how", "is" }, wheres = { "where", "is" }, theres = { "there", "is" },
  heres = { "here", "is" }, dont = { "do", "not" }, doesnt = { "does", "not" }, didnt = { "did", "not" }, isnt = { "is", "not" }, arent = { "are", "not" },
  wasnt = { "was", "not" }, werent = { "were", "not" }, cant = { "can", "not" }, wont = { "will", "not" }, wouldnt = { "would", "not" },
  shouldnt = { "should", "not" }, couldnt = { "could", "not" }, hasnt = { "has", "not" }, havent = { "have", "not" }, hadnt = { "had", "not" },
  im = { "i", "am" }, ive = { "i", "have" }, youre = { "you", "are" }, theyre = { "they", "are" }, weve = { "we", "have" }, youve = { "you", "have" },
  theyve = { "they", "have" },
  -- free-relative wh-words read as the plain wh-word when they open a question-like clause ("the name of whoever is CEO at X")
  whoever = { "who" }, whomever = { "whom" }, whichever = { "which" } }
local EXPAND_LOWER_ONLY = S({ "im", "ive" })   -- "IM" / "IVE" are initialisms, not contractions
local UNIT_SUFFIX = S({ "km", "kg", "m", "cm", "mm", "mg", "g", "ml", "l", "ms", "h", "hr", "hrs", "min", "gb", "mb", "kb", "tb",
  "hz", "khz", "mhz", "ghz", "mph", "kph", "kmh", "px", "pt", "usd", "eur", "gbp", "k", "bn", "mn", "x", "mi", "ft", "in", "lb",
  "lbs", "oz", "yr", "yrs", "wk", "mo", "w", "kw", "mw", "v", "a", "db", "pct" })
local MAGNITUDE = { k = 1e3, m = 1e6, mn = 1e6, mm = 1e6, b = 1e9, bn = 1e9, t = 1e12, tn = 1e12 }

---------------------------------------------------------------- scanner
local function new_analysis(text)
  return { schema = Lex.SCHEMA, original = text, tokens = {}, units = {}, sentences = {}, notes = {},
    utf8 = { valid = true, invalid = {}, bom = false, zero_width = 0, controls = 0, nbsp = 0 },
    cues = { negation = {}, comparative = {}, superlative = {}, conditional = {}, quantifier = {} },
    capabilities = UC.capabilities, status = "ok" }
end

local function shape_of(s)
  local out, last = {}, nil
  for _, c in utf8.codes(s, true) do
    local ch
    if UC.is_upper(c) then ch = "X" elseif UC.is_lower(c) then ch = "x" elseif UC.digit_value(c) then ch = "d"
    else ch = utf8.char(c) end
    if ch ~= last then out[#out + 1] = ch; last = ch end
  end
  return table.concat(out)
end

local function trim_trailing(core)
  while #core > 1 do
    local c = core:sub(-1)
    if c:find("[%.,;:!%?'\">]") then core = core:sub(1, -2)
    elseif c == ")" or c == "]" or c == "}" then
      local open = c == ")" and "%(" or (c == "]" and "%[" or "{")
      local _, no = core:gsub(open, "")
      local _, nc = core:gsub(c == ")" and "%)" or (c == "]" and "%]" or "}"), "")
      if nc > no then core = core:sub(1, -2) else break end
    else break end
  end
  return core
end

-- structured, high-precision whole-run patterns (ASCII). Returns kind, core
local function structured(run)
  if #run < 3 then return nil end
  local core = trim_trailing(run)
  local f = core:sub(1, 1)
  if core:find("^%a[%w+.-]*://[^%s<>\"]+$") or core:find("^[wW][wW][wW]%.[%w-]+%.%a[%w.-]*$") then
    return "url", core
  end
  if core:find("^[%w._%%+-]+@[%w-]+%.[%w.-]*%a%a$") then return "email", core end
  if core:find("^10%.%d%d%d%d+/%S+$") then return "doi", core end
  if core:find("^[aA]r[xX]iv:%d%d%d%d%.%d%d%d%d%d?v?%d*$") then return "ref", core end
  if core:find("^%d%d%d%d%-%d%d%-%d%d$") or core:find("^%d%d%d%d%-%d%d%-%d%dT[%d:.]+Z?$") then return "isodate", core end
  if core:find("^%d%d?/%d%d?/%d%d%d?%d?$") or core:find("^%d%d%d%d/%d%d?/%d%d?$") then return "slashdate", core end
  if core:find("^%d%d?%.%d%d?%.%d%d%d%d$") then return "dotdate", core end
  if core:find("^%d%d?:%d%d:?%d*%.?%d*$") and not core:find(":$") then return "time", core end
  if core:find("^%d%d?:%d%d[aApP][mM]$") or core:find("^%d%d?:%d%d:%d%d[aApP][mM]$") or core:find("^%d%d?[aApP][mM]$") then
    local h = tonumber(core:match("^(%d%d?)"))
    if h >= 1 and h <= 12 then return "time", core end
  end
  local a, b, c, d = core:match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
  if a and tonumber(a) <= 255 and tonumber(b) <= 255 and tonumber(c) <= 255 and tonumber(d) <= 255 then return "ip", core end
  if core:find("^[vV]%d+%.%d+[%w.+-]*$") or core:find("^%d+%.%d+%.%d+[%w.+-]*$") then return "version", core end
  if core:find("^~?/[%w._%-]+/[%w._/%-]*$") or core:find("^%.%.?/[%w._/%-]+$") or core:find("^%a:\\[^%s]+$") or core:find("^~/[%w._/%-]+$") then
    return "path", core
  end
  if core:find("^@[%w_]+$") and #core > 2 then return "handle", core end
  if core:find("^#%d+$") then return "ref", core end
  if core:find("^#%a[%w_]*$") and #core > 2 then return "hashtag", core end
  if core:find("^[%a_][%w_]*%(%)$") or core:find("^[%a_][%w_.]*%([^%s()]*%)$") then return "ident", core end
  if core:find("^[%a_][%w_]*::[%w_:]+$") then return "ident", core end
  if core:find("^%a[%w_]*%.%a[%w_]*%.[%w_.]+$") then
    -- a.b.c : module path / hostname. Require lowercase-led parts to avoid "U.S.A" / "e.g.i" style initialisms.
    local ok = true
    for part in core:gmatch("[^.]+") do if #part < 2 and part:find("^%a$") then ok = false end end
    if ok and core:find("^[%l_][%w_.]*$") then return "ident", core end
  end
  local stem, ext = core:match("^([%w_%-]+)%.(%a[%w]*)$")
  if stem and ext and EXT_OR_TLD[ext:lower()] and #stem >= 1 and not stem:find("^%u%l+$") then return "ident", core end
  if core:find("^[%a][%w]*[_][%w_]+$") or core:find("^_[%w_]+$") or core:find("^[%a][%w]*_$") then
    if core:find("[%a%d]_[%a%d]") or core:find("^_%a") then return "ident", core end
  end
  if core:find("^%x%x%x%x%x%x%x+$") and #core <= 64 and core:find("%d") and core:find("%a") and #core >= 7 and not core:find("^%d+$") then
    return "hash", core
  end
  if f == "`" then return nil end
  return nil
end

local function camel_humps(w)
  local n = 0
  local prev_lower = false
  for _, c in utf8.codes(w, true) do
    if UC.is_upper(c) then if prev_lower then n = n + 1 end; prev_lower = false
    else prev_lower = UC.is_lower(c) or (UC.digit_value(c) ~= nil and prev_lower) end
  end
  return n
end

function Lex.analyze(text, opts)
  opts = opts or {}
  local an = new_analysis(text)
  if type(text) ~= "string" then
    an.status, an.error, an.original = "rejected", "input must be a string", ""
    return an
  end
  local meter = opts.meter
  local max_bytes = opts.max_bytes or 1048576
  local work_text = text
  if #text > max_bytes then
    local cut = max_bytes
    while cut > 0 and (text:byte(cut + 1) or 0) & 0xC0 == 0x80 do cut = cut - 1 end -- back up to a character boundary
    work_text = text:sub(1, cut)
    an.status = "limited"
    an.analyzed_bytes = cut
    an.notes[#an.notes + 1] = string.format("input is %d bytes; only the first %d were analysed (limit), original retained in full", #text, cut)
  end
  an.n_bytes = #text

  local D = UC.decode(work_text)
  local cp, bs, be, n = D.cp, D.bs, D.be, D.n
  an.n_chars = n
  an.utf8.n_invalid = #D.invalid
  an.utf8.valid = (#D.invalid == 0)
  for _, k in ipairs(D.invalid) do an.utf8.invalid[#an.utf8.invalid + 1] = { cs = k, s = bs[k], e = be[k] } end
  if not an.utf8.valid then an.notes[#an.notes + 1] = "input contains invalid UTF-8; invalid bytes preserved in 'original' and reported in utf8.invalid" end
  if meter then meter:tick("lex_chars", n) end

  local invalid_at = {}
  for _, k in ipairs(D.invalid) do invalid_at[k] = true end

  local toks = an.tokens
  local cls_t = {}
  local function cls(k)
    local v = cls_t[k]
    if v == nil then
      local c = cp[k]
      v = UC.class(c)
      cls_t[k] = v
    end
    return v
  end
  local function ignorable(c)
    return (c >= 0x200B and c <= 0x200F) or (c >= 0x2060 and c <= 0x206F) or c == 0xFEFF or c == 0xAD or (c >= 0x202A and c <= 0x202E)
  end
  local function is_ws(k) return cls(k) == "Z" end
  local function is_alnum(k)
    if invalid_at[k] then return false end
    local c = cls(k)
    return c == "L" or c == "N" or c == "O" or c == "M"
  end
  local function is_letter(k)
    if invalid_at[k] then return false end
    local c = cls(k)
    return c == "L" or c == "O" or c == "M"
  end
  local function is_digit(k) return k <= n and UC.digit_value(cp[k]) ~= nil and not invalid_at[k] end

  local function mk(kind, i, j, extra)
    local t = { kind = kind, cs = i, ce = j, s = bs[i], e = be[j] }
    t.text = work_text:sub(t.s, t.e)
    if extra then for k, v in pairs(extra) do t[k] = v end end
    toks[#toks + 1] = t
    t.i = #toks
    if meter then meter:tick("lex_tokens", 1) end
    return t
  end

  local function finalize_word(t)
    local d = { cp = {}, bs = {}, be = {}, n = 0 }
    -- comparison forms
    local fold, lower, first_letter, caps, letters = {}, {}, nil, 0, 0
    local has_zw = false
    for k = t.cs, t.ce do
      local c = cp[k]
      if ignorable(c) then has_zw = true end
      fold[#fold + 1] = UC.fold_cp(c)
      lower[#lower + 1] = utf8.char(UC.lower_cp(c))
      if cls(k) == "L" then
        letters = letters + 1
        if not first_letter then first_letter = c end
        if UC.is_upper(c) then caps = caps + 1 end
      end
    end
    t.fold = table.concat(fold)
    t.lower = table.concat(lower)
    t.cap = first_letter ~= nil and UC.is_upper(first_letter) or false
    t.allcaps = letters >= 2 and caps == letters
    t.letters = letters
    if has_zw then t.has_zw = true; an.utf8.zero_width = an.utf8.zero_width + 1 end
    local sc = first_letter and UC.script(first_letter) or UC.script(cp[t.cs])
    t.script = sc
    if UC.unsegmented[sc] then t.unsegmented = true end
    t.shape = shape_of(t.text)
    for k = t.cs, t.ce do if invalid_at[k] then t.invalid = true break end end
    return t
  end

  ------------------------------------------------ number scanning
  local function scan_number(i, glued_sign)
    -- i points at first digit (sign/currency already consumed by caller and passed via glued_sign)
    local j = i
    local digits = {}
    local function take_digits()
      local st = j
      while j <= n and is_digit(j) do digits[#digits + 1] = tostring(UC.digit_value(cp[j])); j = j + 1 end
      return j > st
    end
    take_digits()
    -- thousands groups: ,ddd (not followed by another digit) or _ddd
    while j + 3 <= n and (cp[j] == 44 or cp[j] == 95) and is_digit(j + 1) and is_digit(j + 2) and is_digit(j + 3) and not is_digit(j + 4) do
      for q = 1, 3 do digits[#digits + 1] = tostring(UC.digit_value(cp[j + q])) end
      j = j + 4
    end
    local is_int = true
    if j + 1 <= n and cp[j] == 46 and is_digit(j + 1) then
      digits[#digits + 1] = "."
      j = j + 1
      take_digits()
      is_int = false
    end
    -- exponent
    if j <= n and (cp[j] == 101 or cp[j] == 69) then
      local q = j + 1
      if q <= n and (cp[q] == 43 or cp[q] == 45) then q = q + 1 end
      if is_digit(q) and not (q + 1 <= n and is_letter(q + 1)) then
        digits[#digits + 1] = "e" .. (cp[j + 1] == 45 and "-" or "")
        j = q
        while j <= n and is_digit(j) do digits[#digits + 1] = tostring(UC.digit_value(cp[j])); j = j + 1 end
        is_int = false
      end
    end
    return j - 1, table.concat(digits), is_int
  end

  local function number_token(i, first_digit, sign, cur_sym, ws_before)
    local last, digs, is_int = scan_number(first_digit)
    local value = tonumber(digs)
    if value and is_int then value = math.tointeger(value) or value end
    local extra = { numtext = digs, value = value, subkind = is_int and "integer" or "decimal" }
    if sign then extra.signed = sign end
    if sign == "-" and value then extra.value = -value end
    if cur_sym then extra.currency_symbol = cur_sym; extra.unit = "currency" end
    -- suffix: %, ordinal, magnitude, unit, alnum-run
    local nxt = last + 1
    if nxt <= n and cp[nxt] == 37 then -- %
      last = nxt; extra.unit = "percent"
    elseif nxt <= n and is_letter(nxt) then
      local q, letters = nxt, {}
      while q <= n and is_letter(q) and cp[q] < 128 do letters[#letters + 1] = string.char(cp[q]); q = q + 1 end
      local suf = table.concat(letters)
      local low = suf:lower()
      local after_alnum = q <= n and is_alnum(q) -- letters continue (non-ASCII) or digits follow -> alnum word
      if after_alnum or cp[nxt] >= 128 then
        extra = nil -- alphanumeric identifier, handled by caller as word
      elseif is_int and low == "s" and (#digs == 4 or #digs == 2) and digs:sub(-1) == "0" then
        -- decade: 1990s / 90s (century of the 2-digit form is unknown and stays unresolved)
        last = q - 1
        extra.kind_override = "decade"
        if #digs == 4 then extra.decade = extra.value else extra.decade2 = extra.value end
      elseif is_int and (low == "st" or low == "nd" or low == "rd" or low == "th") then
        last = q - 1
        extra.kind_override = "ordinal"
        extra.ordinal = extra.value
        local v = math.tointeger(extra.value) or 0
        local want = "th"
        if v % 100 < 11 or v % 100 > 13 then want = ({ [1] = "st", [2] = "nd", [3] = "rd" })[v % 10] or "th" end
        if want ~= low then extra.irregular_suffix = true end
      elseif cur_sym and MAGNITUDE[low] then
        last = q - 1
        extra.magnitude = low
        extra.value = (extra.value or 0) * MAGNITUDE[low]
      elseif UNIT_SUFFIX[low] then
        last = q - 1
        extra.unit_text = suf
        extra.unit = low
        if MAGNITUDE[low] and not cur_sym and (low == "k" or low == "bn") then extra.magnitude = low; extra.value = (extra.value or 0) * MAGNITUDE[low] end
      else
        extra = nil
      end
    end
    if not extra then return nil end
    local kind = extra.kind_override or "number"
    extra.kind_override = nil
    local t = mk(kind, i, last, extra)
    finalize_word(t)
    t.numeric = true
    return t, last
  end

  ------------------------------------------------ main loop
  local i = 1
  local nl_count, ws_flag = 0, false
  local line_start = true
  local open_sq = 0
  if n >= 1 and cp[1] == 0xFEFF then an.utf8.bom = true; i = 2 end

  local function ctx_flags(t)
    t.ws_before = ws_flag
    t.nl_before = nl_count
    if line_start then t.line_start = true end
    ws_flag, nl_count, line_start = false, 0, false
  end

  local progress_guard = 0
  while i <= n do
    -- forward-progress invariant: every iteration must consume at least one code point
    if i == progress_guard then
      local t = mk("symbol", i, i, { role = "symbol", forced_progress = true })
      ctx_flags(t)
      t.fold, t.lower, t.shape, t.script = t.text, t.text, "?", "common"
      an.notes[#an.notes + 1] = "scanner made no progress at byte " .. bs[i] .. "; emitted a symbol token"
      i = i + 1
    end
    progress_guard = i
    if i > n then break end
    if meter and meter.over then
      an.status = "limited"
      an.notes[#an.notes + 1] = "work budget exhausted during tokenisation; remaining input not analysed"
      an.analyzed_bytes = bs[i] - 1
      break
    end
    local c, k = cp[i], cls(i)
    if invalid_at[i] then
      local j = i
      while j + 1 <= n and invalid_at[j + 1] do j = j + 1 end
      local t = mk("invalid", i, j, { invalid = true })
      ctx_flags(t)
      t.fold, t.lower, t.shape = "", "", "?"
      i = j + 1
    elseif k == "Z" then
      ws_flag = true
      if c == 10 or c == 0x85 or c == 0x2028 or c == 0x2029 then nl_count = nl_count + 1; line_start = true
      elseif c == 13 then
        if not (i + 1 <= n and cp[i + 1] == 10) then nl_count = nl_count + 1; line_start = true end
      end
      if c == 0xA0 or c == 0x202F then an.utf8.nbsp = an.utf8.nbsp + 1 end
      i = i + 1
    elseif k == "C" then
      if ignorable(c) then an.utf8.zero_width = an.utf8.zero_width + 1; i = i + 1
      else
        an.utf8.controls = an.utf8.controls + 1
        local t = mk("control", i, i, {})
        ctx_flags(t)
        t.fold, t.lower, t.shape = "", "", "^"
        i = i + 1
      end
    else
      -- run (non-space) for structured detection
      local j = i
      local ascii_run = true
      while j + 1 <= n and cls(j + 1) ~= "Z" and not invalid_at[j + 1] do j = j + 1 end
      local done = false
      local maybe_struct = false
      -- cheap gate: only attempt structured patterns when the run contains characters that can be structural
      do
        local first = c
        if (first >= 48 and first <= 57) or first == 126 or first == 47 or first == 64 or first == 35 or first == 46
          or (first >= 65 and first <= 90) or (first >= 97 and first <= 122) or first == 95 or first == 92 then
          maybe_struct = true
        end
      end
      if maybe_struct and (j - i) >= 2 then
        local run = work_text:sub(bs[i], be[j])
        if run:find("[/:@#%.\\_%(]") or run:find("^%d") then
          local kind, core = structured(run)
          if kind then
            local last = i
            while last < n and be[last] < bs[i] + #core - 1 do last = last + 1 end
            local t = mk(kind, i, last, { atomic = true })
            ctx_flags(t)
            finalize_word(t)
            if kind ~= "time" and kind ~= "isodate" and kind ~= "slashdate" and kind ~= "dotdate" then t.fold = t.text; t.case_sensitive = true end
            i = last + 1
            done = true
          end
        end
      end
      if done then
        -- nothing
      elseif k == "N" or ((c == 43 or c == 45 or c == 0x2212) and is_digit(i + 1) and (ws_flag or i == 1 or (#toks > 0 and toks[#toks].kind == "punct" and toks[#toks].role ~= "sent_end"))
          and not (#toks > 0 and not ws_flag and (toks[#toks].numeric or toks[#toks].kind == "word")))
        or (UC.currency[c] and is_digit(i + 1))
        or (c == 46 and is_digit(i + 1) and (ws_flag or i == 1)) then
        local sign, cur_sym, first = nil, nil, i
        if c == 43 or c == 45 or c == 0x2212 then sign = (c == 43) and "+" or "-"; first = i + 1
        elseif UC.currency[c] then cur_sym = utf8.char(c); first = i + 1 end
        local t, last
        if c == 46 then
          -- ".5": treat as decimal with implicit leading zero
          local l2, digs = scan_number(first + 1)
          t = mk("number", i, l2, { numtext = "0." .. digs, value = tonumber("0." .. digs), subkind = "decimal" })
          finalize_word(t); t.numeric = true
          last = l2
        else
          t, last = number_token(i, first, sign, cur_sym)
        end
        if t then
          ctx_flags(t)
          i = last + 1
        else
          -- alphanumeric identifier starting with a digit (e.g. 4K, 3D, 24h-ish): scan as a word
          local q = first
          while q <= n and is_alnum(q) do q = q + 1 end
          local t2 = mk("word", i, q - 1, { alnum = true })
          ctx_flags(t2); finalize_word(t2)
          i = q
        end
      elseif is_letter(i) or (c == 95 and i + 1 <= n and (is_alnum(i + 1) or cp[i + 1] == 95)) then
        -- word scan with internal apostrophes, hyphens, underscores, initialism dots
        local q = i
        local parts, part_start = {}, i
        local has_apos, compound, seg_len, dotted, seg_letters = false, false, 0, false, 0
        local underscore = false
        while q <= n do
          local cq = cp[q]
          if is_alnum(q) or ignorable(cq) then
            q = q + 1
          elseif cq == 95 and q + 1 <= n and (is_alnum(q + 1) or cp[q + 1] == 95) then
            underscore = true; q = q + 1
          elseif UC.apostrophe[cq] and q > i and is_letter(q - 1) and q + 1 <= n and is_letter(q + 1) then
            has_apos = true; q = q + 1
          elseif UC.hyphen[cq] and q > i and is_alnum(q - 1) and q + 1 <= n and is_alnum(q + 1) then
            parts[#parts + 1] = { cs = part_start, ce = q - 1 }
            compound = true; q = q + 1; part_start = q
          elseif cq == 46 and q > i and is_letter(q - 1) and q + 1 <= n and is_letter(q + 1) then
            -- initialism dot: all dotted segments after the first must be <= 2 letters (U.S.A, e.g, Ph.D)
            local r = q + 1
            while r <= n and is_letter(r) do r = r + 1 end
            local first_seg = 0
            do local f = q - 1; while f >= i and is_letter(f) do first_seg = first_seg + 1; f = f - 1 end end
            if (r - (q + 1)) <= 2 and first_seg <= 2 then dotted = true; q = q + 1 else break end
          else break end
        end
        local last = q - 1
        parts[#parts + 1] = { cs = part_start, ce = last }
        -- trailing period of a dotted initialism ("U.S.", "e.g.") or an abbreviation ("Dr.", "Inc.")
        local word_txt = work_text:sub(bs[i], be[last])
        local low_txt = UC.lower(word_txt)
        local trailing_dot = false
        if last + 1 <= n and cp[last + 1] == 46 then
          if dotted and (last - i) >= 2 then trailing_dot = true
          elseif ABBR[low_txt] and not compound and not has_apos then
            -- "No." followed by a digit is an abbreviation; otherwise only keep period for non-sentence-final-looking abbrevs
            if low_txt == "no" then
              local r = last + 2
              while r <= n and is_ws(r) do r = r + 1 end
              trailing_dot = is_digit(r)
            else trailing_dot = true end
          elseif (last == i) and UC.is_upper(cp[i]) then
            -- single capital initial ("J. R. R. Tolkien"): keep the dot if followed by space + uppercase letter
            local r = last + 2
            while r <= n and is_ws(r) do r = r + 1 end
            if r > last + 2 and r <= n and UC.is_upper(cp[r]) then
              -- "J. R. R. Tolkien" continues a name; "Company A. Who founded it?" does not (a sentence starter follows)
              local q = r
              while q <= n and is_letter(q) do q = q + 1 end
              local nxtw = UC.lower(work_text:sub(bs[r], be[math.max(r, q - 1)]))
              if not SENT_STARTERS[nxtw] then trailing_dot = true end
            end
          end
        end
        local tk = "word"
        local extra = {}
        if trailing_dot then last = last + 1; extra.has_period = true end
        if dotted then tk = "acronym"
        elseif trailing_dot and ABBR[low_txt] then tk = "abbrev"
        elseif trailing_dot and last - i == 1 then tk = "initial" end
        local t = mk(tk, i, last, extra)
        ctx_flags(t)
        finalize_word(t)
        if underscore then t.kind = "ident"; t.case_sensitive = true; t.fold = t.text end
        if compound and #parts > 1 and not dotted then
          t.compound = true
          t.parts = {}
          for _, p in ipairs(parts) do
            local fp = {}
            for z = p.cs, p.ce do fp[#fp + 1] = UC.fold_cp(cp[z]) end
            t.parts[#t.parts + 1] = { cs = p.cs, ce = p.ce, s = bs[p.cs], e = be[p.ce], text = work_text:sub(bs[p.cs], be[p.ce]),
              fold = table.concat(fp) }
          end
        end
        if t.kind == "word" and not compound and t.letters >= 4 and not has_apos then
          local humps = camel_humps(t.text)
          if humps >= 2 or (humps == 1 and not t.cap and t.text:find("^%l%l+%u")) then
            t.kind = "ident"; t.case_sensitive = true; t.fold = t.text; t.camel = true
          elseif humps == 1 then t.mixed_case = true end
        end
        if has_apos then t.has_apostrophe = true end
        i = last + 1
        -- C++ / C# / F# / .NET style suffixes
        if t.kind == "word" and t.letters == 1 and i <= n and (cp[i] == 43 or cp[i] == 35) then
          local p = i
          if cp[i] == 43 and i + 1 <= n and cp[i + 1] == 43 then p = i + 1 elseif cp[i] == 35 then p = i end
          if p == i + (cp[i] == 43 and 1 or 0) and (i + (cp[i] == 43 and 1 or 0)) <= n and (p + 1 > n or not is_alnum(p + 1)) then
            local lw = t.lower
            if lw == "c" or lw == "f" then
              toks[#toks] = nil
              local t2 = mk("ident", t.cs, p, { atomic = true, case_sensitive = true })
              t2.ws_before, t2.nl_before, t2.line_start = t.ws_before, t.nl_before, t.line_start
              finalize_word(t2); t2.fold = t2.text
              i = p + 1
            end
          end
        end
      else
        -- punctuation / symbol / quotes / brackets
        local t
        if UC.sent_end[c] or c == 46 then
          local j2 = i
          while j2 + 1 <= n and (UC.sent_end[cp[j2 + 1]] or cp[j2 + 1] == 46) do j2 = j2 + 1 end
          t = mk("punct", i, j2, { role = "sent_end" })
          if t.text:find("^%.%.+$") or t.text == "…" or t.text:find("^…+$") then t.ellipsis = true end
          if t.text:find("%?") then t.question = true end
          i = j2 + 1
        elseif UC.clause_punct[c] then
          t = mk("punct", i, i, { role = (c == 44 or c == 0xFF0C or c == 0x3001) and "comma" or (c == 59 or c == 0xFF1B) and "semi" or "colon" })
          i = i + 1
        elseif UC.open_bracket[c] then t = mk("punct", i, i, { role = "open_bracket" }); i = i + 1
        elseif UC.close_bracket[c] then t = mk("punct", i, i, { role = "close_bracket" }); i = i + 1
        elseif c == 34 or c == 39 or UC.open_quote[c] or UC.close_quote[c] then
          local prev_ws = (i == 1) or cls(i - 1) == "Z" or UC.open_bracket[cp[i - 1]] or UC.dash[cp[i - 1]] or UC.open_quote[cp[i - 1]]
          local next_ws = (i == n) or cls(i + 1) == "Z" or UC.close_bracket[cp[i + 1]] or UC.clause_punct[cp[i + 1]] or UC.sent_end[cp[i + 1]]
          local role
          if UC.open_quote[c] and not UC.close_quote[c] then role = "open_quote"
          elseif UC.close_quote[c] and not UC.open_quote[c] then role = "close_quote"
          elseif prev_ws and not next_ws then role = "open_quote"
          elseif next_ws and not prev_ws then role = "close_quote"
          else role = "quote" end
          if (c == 39 or c == 0x2018 or c == 0x2019) then
            -- apostrophe-led elision: 'twas, '90s
            if prev_ws and not next_ws and i + 1 <= n and (is_digit(i + 1)) then
              local q = i + 1
              while q <= n and is_alnum(q) do q = q + 1 end
              local body = work_text:sub(bs[i + 1], be[q - 1])
              if body:find("^%d%d0?s$") and #body == 3 then
                t = mk("decade", i, q - 1, { elided = true, decade2 = tonumber(body:sub(1, 2)), numeric = true })
              else
                t = mk("word", i, q - 1, { elided = true })
              end
              ctx_flags(t); finalize_word(t)
              i = q
            end
            if not t then
              if role == "open_quote" then open_sq = open_sq + 1 elseif role == "close_quote" and open_sq > 0 then open_sq = open_sq - 1 end
              t = mk("punct", i, i, { role = role, single = true }); i = i + 1
            end
          else
            t = mk("punct", i, i, { role = role }); i = i + 1
          end
          if t.elided then t = nil end -- already finalised above
        elseif UC.dash[c] then
          local j2 = i
          while j2 + 1 <= n and UC.dash[cp[j2 + 1]] do j2 = j2 + 1 end
          t = mk("punct", i, j2, { role = "dash" }); i = j2 + 1
        elseif c >= 0x1F000 or (c >= 0x2600 and c <= 0x27BF) then
          local j2 = i
          while j2 + 1 <= n and (cp[j2 + 1] >= 0x1F000 or cp[j2 + 1] == 0xFE0F or cp[j2 + 1] == 0x200D or (cp[j2 + 1] >= 0x2600 and cp[j2 + 1] <= 0x27BF)) do j2 = j2 + 1 end
          t = mk("emoji", i, j2, {}); i = j2 + 1
        elseif k == "M" then
          t = mk("symbol", i, i, { stray_mark = true }); i = i + 1
        elseif k == "S" then
          t = mk("symbol", i, i, { role = UC.currency[c] and "currency" or "symbol" }); i = i + 1
        else
          t = mk("punct", i, i, { role = "other" }); i = i + 1
        end
        if t then
          ctx_flags(t)
          if t.kind == "punct" or t.kind == "symbol" or t.kind == "emoji" then
            t.fold, t.lower, t.shape = t.text, t.text, t.text
            t.script = "common"
          end
        end
      end
    end
  end

  Lex.split_clitics(an, work_text, cp, bs, be)
  Lex.segment_sentences(an)
  Lex.build_units(an, opts)
  Lex.mark_cues(an, opts)
  if opts.temporal ~= false then
    local ok, T = pcall(require, "asi.nlu.temporal")
    if ok then T.annotate(an, opts) end
  end
  if meter then meter:tick("lex_units", #an.units) end
  return an
end

---------------------------------------------------------------- contractions (surface-exact splitting)
function Lex.split_clitics(an, text, cp, bs, be)
  local old, new = an.tokens, {}
  local function push(t) new[#new + 1] = t; t.i = #new end
  local function piece(src, cs, ce, extra)
    local t = { kind = "word", cs = cs, ce = ce, s = bs[cs], e = be[ce] }
    t.text = text:sub(t.s, t.e)
    t.fold = UC.fold(t.text); t.lower = UC.lower(t.text)
    t.cap = src.cap and cs == src.cs; t.allcaps = false; t.script = src.script
    t.shape = shape_of(t.text); t.letters = 0
    for _, c in utf8.codes(t.text, true) do if UC.class(c) == "L" then t.letters = t.letters + 1 end end
    t.ws_before = (cs == src.cs) and src.ws_before or false
    t.nl_before = (cs == src.cs) and src.nl_before or 0
    t.line_start = (cs == src.cs) and src.line_start or nil
    for k, v in pairs(extra or {}) do t[k] = v end
    return t
  end
  for _, t in ipairs(old) do
    local handled = false
    if t.kind == "word" and not t.compound and t.letters and t.letters >= 2 then
      local lw = t.lower
      -- "cannot"
      if lw == "cannot" then
        push(piece(t, t.cs, t.cs + 2, { norm = "can" }))
        push(piece(t, t.cs + 3, t.ce, { norm = "not", neg_clitic = true, split_from = t.text }))
        handled = true
      elseif t.has_apostrophe then
        local n_chars = t.ce - t.cs + 1
        -- n't
        local stem = lw:match("^(.-)n[’']t$")
        if stem and CONTRACT_NEG_STEMS[stem] then
          local stem_len = utf8.len(stem)
          push(piece(t, t.cs, t.cs + stem_len - 1, { norm = IRREG_STEM[stem] or stem, split_from = t.text }))
          push(piece(t, t.cs + stem_len, t.ce, { norm = "not", clitic = "neg", neg_clitic = true }))
          handled = true
        else
          local host, suf = lw:match("^(.-)[’']([a-z]+)$")
          if host and #host > 0 and CLITIC_NORM[suf] and not host:find("[’']$") then
            local hlen = utf8.len(host)
            local reading = (suf == "s") and { "is", "has", "poss", "us" } or nil
            push(piece(t, t.cs, t.cs + hlen - 1, { split_from = t.text }))
            push(piece(t, t.cs + hlen, t.ce, { norm = CLITIC_NORM[suf], clitic = suf, readings = reading, aux_alt = (suf == "d") and "had" or nil }))
            handled = true
          end
        end
      end
    end
    -- plural possessive: "students'" (apostrophe directly after a word-final s, no pending open single quote)
    if not handled and t.kind == "word" and not t.compound and t.letters and t.letters >= 2 and t.lower:find("s$") then
      local nxt = old[t.i + 1]
      if nxt and nxt.kind == "punct" and nxt.single and nxt.cs == t.ce + 1 and (nxt.role == "close_quote" or nxt.role == "quote") then
        local after = old[t.i + 2]
        -- treat as possessive only when no opening single quote precedes in this sentence span
        local opened = false
        for z = t.i - 1, math.max(1, t.i - 40), -1 do
          local p = old[z]
          if p.kind == "punct" and p.single and p.role == "open_quote" then opened = true break end
          if p.kind == "punct" and p.role == "sent_end" then break end
        end
        if not opened then
          t.poss_plural = true
          nxt.kind = "word"; nxt.role = nil; nxt.clitic = "poss_pl"; nxt.norm = "'s"; nxt.readings = { "poss" }
          nxt.fold, nxt.lower, nxt.shape, nxt.letters, nxt.script, nxt.single = "'", "'", "'", 0, "common", nil
        end
      end
    end
    if not handled then push(t) end
  end
  an.tokens = new
end

---------------------------------------------------------------- sentence segmentation
function Lex.segment_sentences(an)
  local toks = an.tokens
  local sents, first = {}, 1
  local para = 1
  local function close(last, terminal)
    if last < first then return end
    local a, b = toks[first], toks[last]
    local s = { id = #sents + 1, first_tok = first, last_tok = last, s = a.s, e = b.e, cs = a.cs, ce = b.ce, para = para, terminal = terminal }
    if terminal and terminal:find("%?") then s.question_mark = true end
    -- shouting: most cased tokens all-caps
    local cased, up = 0, 0
    for z = first, last do
      local t = toks[z]
      if t.letters and t.letters >= 2 then cased = cased + 1; if t.allcaps then up = up + 1 end end
    end
    s.shout = cased >= 4 and up / cased >= 0.7
    sents[#sents + 1] = s
    for z = first, last do toks[z].sent = s.id end
    first = last + 1
  end
  local function starts_upper_or_open(t)
    if not t then return true end
    if t.kind == "punct" then return t.role == "open_quote" or t.role == "open_bracket" or t.role == "quote" end
    if t.letters and t.letters > 0 then return t.cap or t.script ~= "latin" and t.script ~= "greek" and t.script ~= "cyrillic" end
    return t.numeric or t.kind == "ident" or t.kind == "url" or t.kind == "ref" or t.kind == "handle" or t.kind == "emoji" or true
  end
  local t = 1
  while t <= #toks do
    local tk = toks[t]
    if tk.nl_before and tk.nl_before >= 2 and t > first then
      close(t - 1, nil); para = para + 1
    elseif tk.line_start and tk.nl_before and tk.nl_before == 1 and t > first and (tk.bullet_hint or false) then
      close(t - 1, nil)
    end
    -- bullets / list markers at line start
    if tk.line_start and (tk.kind == "punct" and (tk.text == "-" or tk.text == "*" or tk.text == "•" or tk.text == "–"))
      and toks[t + 1] and toks[t + 1].ws_before then
      tk.bullet = true
      if t > first then close(t - 1, nil) end
    elseif tk.line_start and tk.numeric and toks[t + 1] and toks[t + 1].kind == "punct" and (toks[t + 1].text == "." or toks[t + 1].text == ")")
      and toks[t + 2] and toks[t + 2].ws_before and tk.value and tk.value < 100 then
      tk.bullet = true
      if t > first then close(t - 1, nil) end
    end
    if tk.kind == "punct" and tk.role == "sent_end" then
      local last = t
      -- absorb closing quotes / brackets that belong to the terminal
      local absorbed_quote = false
      while toks[last + 1] and toks[last + 1].kind == "punct" and (toks[last + 1].role == "close_quote" or toks[last + 1].role == "close_bracket"
        or (toks[last + 1].role == "quote" and toks[last + 1].cs == toks[last].ce + 1)) and not toks[last + 1].ws_before do
        absorbed_quote = absorbed_quote or toks[last + 1].role == "close_quote" or toks[last + 1].role == "quote"
        last = last + 1
      end
      local nxt = toks[last + 1]
      local boundary
      local txt = tk.text
      if not nxt then boundary = true
      elseif nxt.nl_before and nxt.nl_before >= 1 then boundary = true
      elseif txt:find("[!?]") and not tk.ellipsis then
        boundary = not (absorbed_quote and nxt.letters and nxt.letters > 0 and not nxt.cap)
      elseif tk.ellipsis then
        boundary = nxt.cap == true and (nxt.ws_before or false)
      else -- a single period
        local prev = toks[t - 1]
        if prev and not tk.ws_before and nxt and not nxt.ws_before and nxt.cap and prev.letters and prev.letters >= 3 and not prev.cap then
          boundary = true; an.notes[#an.notes + 1] = "missing space after sentence-final period near byte " .. tk.s
        elseif nxt.letters and nxt.letters > 0 then
          boundary = nxt.cap == true or (nxt.script ~= "latin" and nxt.script ~= "greek" and nxt.script ~= "cyrillic")
        else
          boundary = starts_upper_or_open(nxt) and (nxt.numeric or nxt.kind == "punct" or nxt.kind == "ident") and true or false
          if nxt.numeric and not nxt.ws_before then boundary = false end
        end
      end
      if boundary then close(last, txt) end
      t = last + 1
    else
      -- period-ending abbreviation at a sentence end
      if tk.kind == "abbrev" and tk.has_period then
        local nxt = toks[t + 1]
        local low = tk.lower:gsub("%.$", "")
        if (not nxt) or (nxt.nl_before and nxt.nl_before >= 1) then
          close(t, ".");
        elseif not TITLE_ABBR[low] and nxt.cap and nxt.lower and SENT_STARTERS[nxt.lower] then
          close(t, ".")
        end
      elseif tk.kind == "acronym" and tk.has_period then
        local nxt = toks[t + 1]
        if (not nxt) or (nxt.nl_before and nxt.nl_before >= 1) or (nxt.cap and nxt.lower and SENT_STARTERS[nxt.lower]) then close(t, ".") end
      end
      t = t + 1
    end
  end
  if first <= #toks then close(#toks, nil) end
  an.sentences = sents
  -- Shouting is a property of a stretch of text, not of one sentence: "OH. MY. GOODNESS!!!" is three one-word sentences, and a short all-caps exclamation
  -- ("SO COOL!!!") beside shouted text is shouted too.  Capitalisation is then no evidence that a word is a name.
  local para_stats = {}
  local own = {}
  for _, s in ipairs(sents) do
    local c, u = 0, 0
    for z = s.first_tok, s.last_tok do
      local tk2 = toks[z]
      if tk2.letters and tk2.letters >= 2 then c = c + 1; if tk2.allcaps then u = u + 1 end end
    end
    own[s] = { c = c, u = u }
    local ps = para_stats[s.para]
    if not ps then ps = { cased = 0, up = 0 }; para_stats[s.para] = ps end
    ps.cased, ps.up = ps.cased + c, ps.up + u
  end
  for _, s in ipairs(sents) do
    if not s.shout then
      local o, ps = own[s], para_stats[s.para]
      if o.c >= 1 and o.u == o.c and ps.cased >= 3 and ps.up / ps.cased >= 0.7 then s.shout = true
      elseif o.c >= 2 and o.u == o.c and s.terminal and s.terminal:find("!", 1, true) then s.shout = true end
    end
  end
end

---------------------------------------------------------------- elongation ("whaaat", "peruuu", "sooo", "goood")
-- Every run of three or more equal letters is shortened to one or two letters (the more natural length first); the first candidate the caller knows as a word or
-- name wins.  Nothing is guessed beyond that: an elongated word that collapses to nothing known stays as written.
local function deelongate(form, known)
  if not known or type(form) ~= "string" or not form:find("(%a)%1%1") then return nil end
  local parts, runs, pos = {}, {}, 1
  while pos <= #form do
    local c = form:sub(pos, pos)
    local e = pos
    while form:sub(e + 1, e + 1) == c do e = e + 1 end
    if e - pos + 1 >= 3 and c:match("%a") then
      runs[#runs + 1] = #parts + 1
      parts[#parts + 1] = { c = c, n = e - pos + 1, run = true }
    else parts[#parts + 1] = { s = form:sub(pos, e) } end
    pos = e + 1
  end
  if #runs == 0 or #runs > 4 then return nil end
  local combos = {}
  for mask = 0, (1 << #runs) - 1 do
    local bits = 0
    for b = 0, #runs - 1 do if mask & (1 << b) ~= 0 then bits = bits + 1 end end
    combos[#combos + 1] = { mask = mask, bits = bits }
  end
  table.sort(combos, function(a, b) if a.bits ~= b.bits then return a.bits < b.bits end return a.mask < b.mask end)
  for _, cb in ipairs(combos) do
    local out, ri = {}, 0
    for _, p in ipairs(parts) do
      if p.run then
        ri = ri + 1
        local first = (p.n == 3) and 2 or 1
        local pick = (cb.mask & (1 << (ri - 1)) ~= 0) and (3 - first) or first
        out[#out + 1] = p.c:rep(pick)
      else out[#out + 1] = p.s end
    end
    local cand = table.concat(out)
    if cand ~= form and known(cand) then return cand end
  end
  return nil
end

---------------------------------------------------------------- units
local CASE_SENSITIVE_KINDS = S({ "ident", "url", "email", "path", "version", "ref", "doi", "handle", "hashtag", "hash", "ip" })
local ROLE_BARRIER = { comma = "comma", semi = "semi", colon = "colon", sent_end = "sent", open_bracket = "paren_open",
  close_bracket = "paren_close", open_quote = "quote_open", close_quote = "quote_close", quote = "quote", dash = "dash", other = "other" }

function Lex.build_units(an, opts)
  local units, toks = an.units, an.tokens
  local pending = {}
  local spell = opts and opts.spell
  local known = opts and (opts.known or (spell and function(f) return spell:known(f) end)) or nil
  local function push(u)
    u.i = #units + 1
    if #pending > 0 then u.pre = table.concat(pending, ","); pending = {} end
    units[#units + 1] = u
    return u
  end
  for _, t in ipairs(toks) do
    local barrier = nil
    if t.kind == "punct" then barrier = ROLE_BARRIER[t.role or "other"] or "other"
    elseif t.kind == "control" or t.kind == "invalid" or t.kind == "emoji" or t.kind == "symbol" then barrier = t.kind end
    if barrier then
      pending[#pending + 1] = barrier
      if barrier == "sent" and #units > 0 then units[#units].post = (units[#units].post and (units[#units].post .. ",") or "") .. "sent" end
    else
      local base = { tok = t.i, sent = t.sent, kind = t.kind, ws_before = t.ws_before, cap = t.cap, allcaps = t.allcaps, script = t.script,
        numval = t.value, unit = t.unit, ordinal = t.ordinal, mixed_case = t.mixed_case, line_start = t.line_start, has_zw = t.has_zw,
        decade = t.decade, decade2 = t.decade2, signed = t.signed, numtext = t.numtext, currency_symbol = t.currency_symbol }
      local function with(extra) local u = U.shallow(base); for k, v in pairs(extra) do u[k] = v end; return u end
      if t.compound and t.parts then
        for pi, p in ipairs(t.parts) do
          local u = with({ part = pi, raw = p.text, form = p.fold, lower = UC.lower(p.text), s = p.s, e = p.e, cs = p.cs, ce = p.ce,
            hy = true, hy_first = pi == 1, hy_last = pi == #t.parts })
          local c1 = utf8.codepoint(p.text, 1)
          u.cap = UC.is_upper(c1)
          push(u)
        end
      elseif EXPAND[t.lower] and t.kind == "word" and not t.compound and not (EXPAND_LOWER_ONLY[t.lower] and t.text == t.text:upper()) then
        for pi, w in ipairs(EXPAND[t.lower]) do
          push(with({ part = pi, raw = t.text, form = w, lower = w, s = t.s, e = t.e, cs = t.cs, ce = t.ce, expanded = true, neg_clitic = (w == "not") or nil }))
        end
      elseif t.neg_clitic or t.clitic then
        push(with({ raw = t.text, form = t.norm or t.fold, lower = t.norm or t.lower, s = t.s, e = t.e, cs = t.cs, ce = t.ce,
          clitic = t.clitic, readings = t.readings, aux_alt = t.aux_alt, neg_clitic = t.neg_clitic }))
      elseif t.norm then
        push(with({ raw = t.text, form = t.norm, lower = t.norm, s = t.s, e = t.e, cs = t.cs, ce = t.ce, surface_form = t.fold }))
      elseif t.numeric then
        local form = t.numtext and (t.signed == "-" and ("-" .. t.numtext) or t.numtext) or t.fold
        push(with({ raw = t.text, form = form, lower = form, s = t.s, e = t.e, cs = t.cs, ce = t.ce }))
      else
        local form = CASE_SENSITIVE_KINDS[t.kind] and t.text or t.fold
        -- match forms drop the abbreviation/initialism dots ("Dr." -> "dr", "U.S.A." -> "usa"); `raw` keeps them
        if t.kind == "abbrev" or t.kind == "initial" then form = form:gsub("%.$", "")
        elseif t.kind == "acronym" then form = form:gsub("%.", "") end
        -- elongation: "whaaat" / "peruuu" read as the known word they stretch
        local stretched = (t.kind == "word" and not t.alnum) and deelongate(form, known) or nil
        local surface
        if stretched then surface, form = form, stretched end
        local u = push(with({ raw = t.text, form = form, lower = stretched or t.lower, s = t.s, e = t.e, cs = t.cs, ce = t.ce,
          case_sensitive = CASE_SENSITIVE_KINDS[t.kind] or nil, atomic = t.atomic, elongated = stretched and true or nil, surface_form = surface,
          acr = (t.kind == "acronym" or (t.allcaps and t.letters <= 6)) or nil }))
        if spell and t.kind == "word" and t.letters and t.letters >= 4 and not t.alnum and not t.invalid and not u.hy then
          u.unknown = not spell:known(form)
          if u.unknown then u.alts = spell:suggest(form, { cap = t.cap }) end
        end
      end
    end
  end
  an.stats = { tokens = #toks, units = #units, sentences = #an.sentences }
end

---------------------------------------------------------------- cue flags (closed-class, lexicon-independent defaults)
local NEG_FORMS = S({ "not", "no", "never", "none", "nobody", "nothing", "nowhere", "neither", "nor", "without", "exclude",
  "excluding", "excluded", "excludes", "exclusion", "except", "excepting", "minus", "unless", "lacking", "absent", "cannot" })
local COND_FORMS = S({ "if", "unless", "provided", "assuming", "otherwise", "whether", "whenever", "once" })
local QUANT_FORMS = S({ "all", "every", "each", "some", "any", "many", "few", "several", "most", "both", "either", "only", "enough", "no" })
local COMP_IRREG = S({ "more", "less", "fewer", "better", "worse", "than", "versus", "vs", "compare", "compared", "comparison", "differ",
  "difference", "differences", "between", "older", "newer", "larger", "smaller", "bigger", "higher", "lower", "longer", "shorter",
  "younger", "earlier", "later", "faster", "slower", "cheaper", "stronger", "weaker", "greater" })
local SUP_IRREG = S({ "most", "least", "fewest", "best", "worst", "oldest", "newest", "largest", "smallest", "biggest", "highest",
  "lowest", "longest", "shortest", "youngest", "earliest", "latest", "fastest", "slowest", "cheapest", "strongest", "greatest", "top",
  "first", "last" })
local ADJ_BASE = S({ "old", "new", "big", "large", "small", "high", "low", "long", "short", "young", "early", "late", "fast", "slow",
  "cheap", "rich", "poor", "strong", "weak", "near", "far", "wide", "narrow", "deep", "tall", "heavy", "light", "hot", "cold", "good",
  "bad", "great", "recent", "popular", "common", "rare", "close", "safe", "simple", "easy", "hard", "large", "major", "minor" })

function Lex.mark_cues(an, opts)
  local cues = an.cues
  for _, u in ipairs(an.units) do
    local f = u.form
    if u.neg_clitic then cues.negation[#cues.negation + 1] = { u = u.i, form = "not", clitic = true } end
    if not u.case_sensitive then
      if NEG_FORMS[f] and not u.neg_clitic then cues.negation[#cues.negation + 1] = { u = u.i, form = f } end
      if COND_FORMS[f] then cues.conditional[#cues.conditional + 1] = { u = u.i, form = f } end
      if QUANT_FORMS[f] then cues.quantifier[#cues.quantifier + 1] = { u = u.i, form = f } end
      if COMP_IRREG[f] then cues.comparative[#cues.comparative + 1] = { u = u.i, form = f } end
      if SUP_IRREG[f] then cues.superlative[#cues.superlative + 1] = { u = u.i, form = f } end
      if u.kind == "word" and #f >= 5 then
        local b = f:match("^(.+)er$")
        if b and (ADJ_BASE[b] or ADJ_BASE[b:gsub("(.)%1$", "%1")] or ADJ_BASE[b .. "e"] or ADJ_BASE[b:gsub("i$", "y")]) then
          cues.comparative[#cues.comparative + 1] = { u = u.i, form = f, base = b }
        end
        b = f:match("^(.+)est$")
        if b and (ADJ_BASE[b] or ADJ_BASE[b:gsub("(.)%1$", "%1")] or ADJ_BASE[b .. "e"] or ADJ_BASE[b:gsub("i$", "y")]) then
          cues.superlative[#cues.superlative + 1] = { u = u.i, form = f, base = b }
        end
      end
    end
  end
end

---------------------------------------------------------------- accessors
function Lex.slice(an, t) return an.original:sub(t.s, t.e) end

function Lex.describe(an)
  local out = {}
  for _, t in ipairs(an.tokens) do
    out[#out + 1] = string.format("%s:%s[%d-%d]", t.kind, t.text, t.s, t.e)
  end
  return table.concat(out, " ")
end

function Lex.capabilities() return UC.capabilities end

return Lex

end

package.preload["asi.nlu.lexicon"] = function(...)
-- asi.nlu.lexicon: data-driven linguistic resources, loaded from a line-oriented DSL (data, never executed).
--
--   type <name> < <parent>[, <parent>]
--   class <cat>: w1 w2 ...                               closed-class word lists
--   pron <form>: person=3 number=sg gender=n animate=0   pronoun features
--   rel <id>: from=<type> to=<type> | event=1 (a one-off event or permanent fact: tense never makes it "past") | noun=a; b | noun_from=a; b | verb=lemma/subj=to; ... | prep=of; for | kinds=mod:rel_id; ...
--             | when=<rel> | where=<rel> | label=<text> | derived=<rel> | weight=<n>
--   sense <head>: <id> | pos=n|v|adj | type=<type> | domain=a; b | gloss=... | prior=0.5 | rel=<rel> | cs=1
--   entity <id>: <type> | names=A; B | cs=A; B | domain=a; b | prior=0.5 | attr.k=v
--   entities <type>: A; B; C                              bulk entities, ids derived from names
--   alias <entity-id>: A; B                               extra names (short all-caps aliases are case-sensitive)
--   verb <lemma>: act=retrieve|inform|compare|task|constraint|exclude|include
--   adj <lemma>: dim=age                                  gradable adjectives (comparative/superlative generated)
--   dim <name>: rels=a,b | order=...
--   cue <name>: a; b; c                                   discourse cues (negation, correction, persistence, ...)
--   domain <name>: w1 w2 ...                              domain cue words used for sense priming
--   headcue <type>: inc corp ...                          trailing words that type an unseen proper name
--   resource <name>: a; b                                 resource nouns (dataset/version/file/...), synonym groups
--   wrap <name>: pattern                                   politeness/request wrappers (closed class)
-- Lines starting with '#' are comments. Errors are collected with line numbers; a bad line never aborts a load.
local U = require("asi.nlu.util")
local Lex = require("asi.nlu.lex")
local Morph = require("asi.nlu.morph")

local L = {}
L.__index = L

local KID_SEP = "\1"

---------------------------------------------------------------- construction
function L.new(parent)
  local self = setmetatable({}, L)
  self.parent = parent
  self.types = {}       -- name -> {name, parents={}, anc={set incl. self}}
  self.classes = {}     -- form -> set of cats
  self.class_words = {} -- cat -> set of forms
  self.pron = {}        -- form -> feature table
  self.rels = {}        -- id -> relation
  self.rel_order = {}
  self.senses = {}      -- id -> sense
  self.sense_by_head = {} -- folded head -> list of senses
  self.entities = {}    -- id -> entity
  self.verbs = {}       -- lemma -> {lemma, act}
  self.adjs = {}        -- lemma -> {dim}
  self.adj_forms = {}   -- form -> {lemma, feat}
  self.dims = {}
  self.cues = {}        -- name -> set of folded phrases
  self.cue_phrases = {} -- name -> list of {forms...}
  self.cue_first = {}   -- name -> first form -> list of {forms...}  (cue_at looks up by first word instead of scanning every phrase)
  self.domain_words = {} -- form -> {domain -> 1}
  self.headcues = {}    -- folded last word -> type
  self.resources = {}   -- folded phrase -> canonical resource name
  self.refnouns = {}    -- form -> artifact class (solution | version | correction | ...)
  self.wraps = {}
  self.forms = {}       -- surface form -> list of readings {pos, lemma, feat, ref}
  self.trie = { kids = {} }
  self.errors = {}
  self.sources = {}     -- source name -> {sha256, n_lines}
  self.revision = 0
  return self
end

local function trim(s) return U.trim(s) end

local function split_fields(s)
  local fields, flags = {}, {}
  for part in (s .. "|"):gmatch("(.-)|") do
    part = trim(part)
    if part ~= "" then
      local k, v = part:match("^([%w_%.]+)%s*=%s*(.*)$")
      if k then fields[k] = v else flags[#flags + 1] = part end
    end
  end
  return fields, flags
end

local function list(v, sep)
  local out = {}
  if not v then return out end
  sep = sep or ";"
  for item in (v .. sep):gmatch("(.-)" .. (sep == "|" and "%|" or sep)) do
    item = trim(item)
    if item ~= "" then out[#out + 1] = item end
  end
  return out
end

---------------------------------------------------------------- phrase keys + trie
-- unit-form key sequence of a phrase, tokenised by the SAME lexer as queries (consistent segmentation)
function L.keys_of(phrase)
  local an = Lex.analyze(phrase, { temporal = false })
  local keys, raws = {}, {}
  for _, u in ipairs(an.units) do
    keys[#keys + 1] = { form = u.form, pre = u.pre, raw = u.raw }
  end
  return keys, an
end

local function kid_key(form, pre) if pre then return form .. KID_SEP .. pre end return form end

function L:trie_insert(phrase, entry)
  local keys = L.keys_of(phrase)
  if #keys == 0 then return false end
  local node = self.trie
  for idx, k in ipairs(keys) do
    local kk = kid_key(k.form, idx > 1 and k.pre or nil)
    local nxt = node.kids[kk]
    if not nxt then nxt = { kids = {} }; node.kids[kk] = nxt end
    node = nxt
  end
  entry.nwords = #keys
  node.entries = node.entries or {}
  node.entries[#node.entries + 1] = entry
  return true
end

local HARD = U.set({ "sent", "comma", "semi", "colon", "paren_open", "paren_close", "quote_open", "quote_close", "quote", "dash", "other",
  "control", "invalid", "symbol", "emoji" })

-- all trie matches starting at unit i (this lexicon and its parents): {j=last_unit, entries={...}}
function L:match_at(units, i)
  local out = {}
  local lex = self
  while lex do
    local node = lex.trie
    for k = i, #units do
      local u = units[k]
      local kk
      if k == i then kk = u.form
      else
        if u.pre then
          -- punctuation barrier: only phrases that literally contain this barrier may continue
          kk = u.form .. KID_SEP .. u.pre
        else kk = u.form end
      end
      local nxt = node.kids[kk]
      if not nxt then break end
      node = nxt
      if node.entries then out[#out + 1] = { j = k, entries = node.entries, lex = lex } end
    end
    lex = lex.parent
  end
  return out
end

---------------------------------------------------------------- types
function L:type_info(name)
  local t = self.types[name]
  if t then return t end
  if self.parent then return self.parent:type_info(name) end
end

function L:has_type(name) return self:type_info(name) ~= nil end

function L:isa(t, anc)
  if t == anc then return true end
  local info = self:type_info(t)
  return info ~= nil and info.anc[anc] == true
end

-- graded compatibility of a (possibly unknown) type with an expectation, in [-1, 1]
--   1.0 subtype/equal | 0.55 expectation is a subtype of the known type (known is vaguer)
--   0.25 unknown | -0.45 distinct siblings under a shared non-root ancestor | -1 disjoint branches
function L:compat(t, expected)
  if not expected then return 0.25 end
  if not t then return 0.25 end
  if expected:find("|", 1, true) then -- union expectation: best alternative
    local best = -1
    for alt in expected:gmatch("[^|]+") do best = math.max(best, self:compat(t, alt)) end
    return best
  end
  if t:find("|", 1, true) then
    local best = -1
    for alt in t:gmatch("[^|]+") do best = math.max(best, self:compat(alt, expected)) end
    return best
  end
  if t == expected then return 1.0 end
  if self:isa(t, expected) then return 0.95 end
  if self:isa(expected, t) then return 0.55 end
  local a, b = self:type_info(t), self:type_info(expected)
  if not a or not b then return 0.2 end
  for anc in pairs(a.anc) do
    if anc ~= "entity" and anc ~= t and b.anc[anc] then return -0.45 end
  end
  return -1.0
end

function L:ancestors(t)
  local info = self:type_info(t)
  local out = {}
  if info then for a in pairs(info.anc) do out[#out + 1] = a end end
  table.sort(out)
  return out
end

---------------------------------------------------------------- loading
local function add_err(self, source, ln, msg)
  self.errors[#self.errors + 1] = string.format("%s:%d: %s", source, ln, msg)
end

function L:add_type(name, parents)
  local info = self.types[name]
  if not info then info = { name = name, parents = {}, anc = { [name] = true } }; self.types[name] = info end
  for _, p in ipairs(parents or {}) do
    info.parents[#info.parents + 1] = p
    info.anc[p] = true
    local pi = self:type_info(p)
    if pi then for a in pairs(pi.anc) do info.anc[a] = true end end
  end
end

function L:add_form(form, reading)
  local list_ = self.forms[form]
  if not list_ then list_ = {}; self.forms[form] = list_ end
  list_[#list_ + 1] = reading
end

function L:add_rel(r)
  local ex = self.rels[r.id]
  if not ex then self.rel_order[#self.rel_order + 1] = r.id end
  self.rels[r.id] = r
  self.revision = self.revision + 1
  -- relational nouns (with plural forms) and verbs -> trie
  local function noun_entries(noun, role, rolesuffix)
    for _, f in ipairs(Morph.noun_forms(noun)) do
      self:trie_insert(f.form, { kind = "relnoun", rel = r.id, role = role, num = f.feat, lemma = noun, rolesuffix = rolesuffix })
    end
  end
  for _, n in ipairs(r.nouns_to) do noun_entries(n, "to") end
  -- "CEO position", "prime minister role": the post a person holds, named after the role noun (see the `rolesuffix=1` field of person-valued relations)
  for _, n in ipairs(r.role_nouns or {}) do noun_entries(n, "to", true) end
  for _, n in ipairs(r.nouns_from) do noun_entries(n, "from") end
  for _, v in ipairs(r.verbs) do
    for _, f in ipairs(Morph.verb_forms(v.lemma)) do
      self:trie_insert(f.form, { kind = "relverb", rel = r.id, subj = v.subj, vform = f.feat, lemma = v.lemma, prep = v.prep, support = v.support, as_only = v.as_only, np_only = v.np_only })
    end
  end
end

local function words_of(s) local t = {}; for w in s:gmatch("%S+") do t[#t + 1] = w end; return t end

function L:load(text, source)
  source = source or "inline"
  local n_dir = 0
  local ln = 0
  for line in (text .. "\n"):gmatch("(.-)\r?\n") do
    ln = ln + 1
    local l = trim(line)
    if l ~= "" and l:sub(1, 1) ~= "#" then
      local dir, rest = l:match("^(%a+)%s+(.*)$")
      if not dir then add_err(self, source, ln, "unparseable line")
      else
        local ok, err = pcall(self.directive, self, dir, rest, source, ln)
        if not ok then add_err(self, source, ln, tostring(err)) else n_dir = n_dir + 1 end
      end
    end
  end
  self.sources[source] = { sha256 = U.sha256(text), lines = ln }
  self.revision = self.revision + 1
  return n_dir, self.errors
end

local function split_head(rest)
  local head, tail = rest:match("^(.-)%s*:%s*(.*)$")
  if not head then error("missing ':'") end
  return trim(head), tail
end

local DIRECTIVES = {}

function DIRECTIVES.type(self, rest)
  local name, parents = rest:match("^([%w_]+)%s*<%s*(.+)$")
  if not name then name = rest:match("^([%w_]+)$"); parents = "" end
  if not name then error("bad type line") end
  local ps = {}
  for p in parents:gmatch("[%w_]+") do ps[#ps + 1] = p end
  for _, p in ipairs(ps) do if not self:has_type(p) then error("unknown parent type " .. p) end end
  self:add_type(name, ps)
end

function DIRECTIVES.class(self, rest)
  local cat, tail = split_head(rest)
  self.class_words[cat] = self.class_words[cat] or {}
  for _, w in ipairs(words_of(tail)) do
    local f = w:lower()
    self.classes[f] = self.classes[f] or {}
    self.classes[f][cat] = true
    self.class_words[cat][f] = true
  end
end

function DIRECTIVES.pron(self, rest)
  local form, tail = split_head(rest)
  local feats = {}
  for k, v in tail:gmatch("(%w+)=(%S+)") do feats[k] = v end
  self.pron[form:lower()] = feats
end

function DIRECTIVES.rel(self, rest)
  local id, tail = split_head(rest)
  tail = tail:gsub("^%s*from=(%S+)%s+to=(%S+)", "from=%1 | to=%2") -- signature shares one field: "from=A to=B"
  local f = split_fields(tail)
  if not f.from or not f.to then error("rel needs from= and to=") end
  f.from, f.to = f.from:gsub(",", "|"), f.to:gsub(",", "|") -- union types are written a,b in the DSL ('|' separates fields)
  f.from = f.from:gsub("%s+", ""); f.to = f.to:gsub("%s+", "")
  for _, t in ipairs({ f.from, f.to }) do
    for alt in t:gmatch("[%w_]+") do if not self:has_type(alt) then error("unknown type " .. alt .. " in rel " .. id) end end
  end
  local r = { id = id, from = f.from, to = f.to, label = f.label or id:gsub("_", " "), nouns_to = list(f.noun), nouns_from = list(f.noun_from),
    verbs = {}, preps = list(f.prep), kinds = {}, when = f.when, where = f.where, how_many = f.how_many, derived = f.derived,
    weight = tonumber(f.weight) or 1.0, source = f.source or "seed", symmetric = f.symmetric == "1", attr = f.attr == "1", event = f.event == "1",
    locus = f.locus == "1", isa = f.isa, support = {} }
  -- "How many PEOPLE LIVE IN X?" counts the relation's value without naming the relation: count_noun lists the countable nouns, count_verb the verbs
  -- (lemma[/prep=P]) whose subject is counted; howmuch=1 marks the relation "How much is X?" asks for when X is a product-like thing
  r.count_nouns = list(f.count_noun)
  r.count_verbs = {}
  for _, v in ipairs(list(f.count_verb)) do
    local lemma, attrs = v:match("^([^/]+)/?(.*)$")
    local ent = { lemma = trim(lemma) }
    for k, val in (attrs or ""):gmatch("(%a+)=([%w_]+)") do ent[k] = val end
    r.count_verbs[#r.count_verbs + 1] = ent
  end
  r.howmuch = f.howmuch == "1"
  -- derived event nouns ("the FOUNDING of X", "the ACQUISITION of Y"): the noun names the event whose agent fills the role of the relation's verbs
  r.deverbals = list(f.deverbal)
  if f.rolesuffix == "1" then
    r.role_nouns = {}
    for _, n in ipairs(r.nouns_to) do
      for _, sfx in ipairs({ "position", "role", "post", "job", "seat", "title", "office" }) do r.role_nouns[#r.role_nouns + 1] = n .. " " .. sfx end
    end
  end
  -- verb entries:  lemma/subj=to|from[/prep=in]   (prep => stative "X is VERB-ed PREP Y": X fills subj role, Y the other)
  for _, v in ipairs(list(f.verb)) do
    local lemma, attrs = v:match("^([^/]+)/(.*)$")
    if not lemma then error("verb entry needs /subj=to|from : " .. v) end
    local ent = { lemma = trim(lemma) }
    for k, val in attrs:gmatch("(%a+)=([%w_]+)") do ent[k] = val end
    if ent.subj ~= "to" and ent.subj ~= "from" then error("verb entry needs subj=to|from : " .. v) end
    r.verbs[#r.verbs + 1] = ent
  end
  -- support verbs ("Sweden USES the krona", "Acme KEEPS its headquarters in Oslo"): verbs that carry the relation with the holder as subject.
  -- `have` is an auxiliary and is handled by the support-construction frames, so it is recorded but not entered as a relation verb.
  for _, sv in ipairs(list(f.support)) do
    local lemma = trim(sv)
    r.support[#r.support + 1] = lemma
    if lemma == "have" then r.support_have = true else r.verbs[#r.verbs + 1] = { lemma = lemma, subj = "from", support = true } end
  end
  -- support verbs that only work with a possessed relational noun ("Acme ESTABLISHED its headquarters in Oslo"); "Acme established Brennick" says nothing about this relation
  for _, sv in ipairs(list(f.support_np)) do
    local lemma = trim(sv)
    r.support[#r.support + 1] = lemma
    r.verbs[#r.verbs + 1] = { lemma = lemma, subj = "from", support = true, np_only = true }
  end
  -- "as" verbs ("Acme APPOINTED Jane Doe as CEO", "France RECOGNIZES Paris as its capital"): the verb names the relation only together with "as <relational
  -- noun>"; on its own ("Acme employs Jane Doe", "voters elected X") it says nothing about this relation, so these entries never drive a plain verb frame
  r.as_verbs = {}
  for _, sv in ipairs(list(f.as)) do
    local lemma = trim(sv)
    r.as_verbs[#r.as_verbs + 1] = lemma
    r.verbs[#r.verbs + 1] = { lemma = lemma, subj = "from", support = true, as_only = true }
  end
  for _, k in ipairs(list(f.kinds)) do
    local mod, rid = k:match("^(.-):(.+)$")
    if mod then r.kinds[trim(mod):lower()] = trim(rid) end
  end
  self:add_rel(r)
end

function DIRECTIVES.sense(self, rest)
  local head, tail = split_head(rest)
  local id, after = tail:match("^([^|]+)(.*)$")
  id = trim(id)
  local f, flags = split_fields((after or ""):gsub("^|", ""))
  local s = { id = id, head = head, pos = f.pos or "n", type = f.type, gloss = f.gloss, prior = tonumber(f.prior) or 0.5,
    rel = f.rel, cs = f.cs == "1", domain = {}, source = f.source or "seed", kind = f.kind }
  for _, d in ipairs(list(f.domain)) do s.domain[d] = true end
  if s.type and not self:has_type(s.type) then error("unknown type " .. s.type) end
  self.senses[id] = s
  local key = table.concat(U.map((L.keys_of(head)), function(k) return k.form end), " ")
  s.key = key
  self.sense_by_head[key] = self.sense_by_head[key] or {}
  table.insert(self.sense_by_head[key], s)
  -- trie: single words get noun inflections; multiword heads are inserted as written (+ plural of last word)
  local variants = Morph.noun_forms(head)
  if s.pos == "adj" then variants = { { form = head, feat = "base" } } end
  for _, v in ipairs(variants) do
    self:trie_insert(v.form, { kind = "sense", sense = s, num = v.feat })
  end
  self.revision = self.revision + 1
end

local function is_short_caps(name) return name:find("^%u[%u%.]*$") ~= nil and #name:gsub("%.", "") <= 4 and #name:gsub("%.", "") >= 2 end

function L:add_entity(e)
  e.domain = e.domain or {}
  self.entities[e.id] = e
  for i, n in ipairs(e.names) do
    local nm = type(n) == "table" and n or { text = n, cs = false }
    if type(n) == "string" then
      nm = { text = n, cs = is_short_caps(n) }
      e.names[i] = nm
    end
    self:trie_insert(nm.text, { kind = "entity", id = e.id, name = nm.text, cs = nm.cs, primary = i == 1, etype = e.type })
  end
  self.revision = self.revision + 1
end

local function slug(s) return (s:lower():gsub("[^%w]+", "_"):gsub("^_+", ""):gsub("_+$", "")) end

function DIRECTIVES.entity(self, rest)
  local id, tail = split_head(rest)
  local etype, after = tail:match("^([%w_]+)(.*)$")
  if not etype or not self:has_type(etype) then error("unknown entity type " .. tostring(etype)) end
  local f = split_fields((after or ""):gsub("^%s*|", ""))
  local e = { id = id, type = etype, names = {}, domain = {}, prior = tonumber(f.prior) or 0.5, attr = {}, source = f.source or "seed" }
  local cs = {}
  for _, c in ipairs(list(f.cs)) do cs[c] = true end
  for _, n in ipairs(list(f.names)) do e.names[#e.names + 1] = { text = n, cs = cs[n] or is_short_caps(n) } end
  if #e.names == 0 then error("entity without names") end
  for _, d in ipairs(list(f.domain)) do e.domain[d] = true end
  for k, v in pairs(f) do local a = k:match("^attr%.(.+)$"); if a then e.attr[a] = v end end
  self:add_entity(e)
end

-- bulk entities get the default domains of their type, so bulk and hand-written entries compete on equal terms
local TYPE_DOMAINS = { country = { "geography", "politics" }, subnational = { "geography", "politics" }, city = { "geography" },
  continent = { "geography" }, ocean = { "geography" } }

function DIRECTIVES.entities(self, rest)
  local etype, tail = split_head(rest)
  if not self:has_type(etype) then error("unknown entity type " .. etype) end
  for _, n in ipairs(list(tail)) do
    local dom = {}
    for _, d in ipairs(TYPE_DOMAINS[etype] or {}) do dom[d] = true end
    self:add_entity({ id = etype .. "." .. slug(n), type = etype, names = { { text = n, cs = is_short_caps(n) } }, domain = dom, prior = 0.5,
      attr = {}, source = "seed" })
  end
end

function DIRECTIVES.alias(self, rest)
  local id, tail = split_head(rest)
  local e = self.entities[id]
  if not e then error("alias for unknown entity " .. id) end
  for _, n in ipairs(list(tail)) do
    local nm = { text = n, cs = is_short_caps(n) }
    e.names[#e.names + 1] = nm
    self:trie_insert(nm.text, { kind = "entity", id = e.id, name = nm.text, cs = nm.cs, primary = false, etype = e.type })
  end
end

function DIRECTIVES.verb(self, rest)
  local lemma, tail = split_head(rest)
  local f = split_fields(tail)
  local v = { lemma = lemma, act = f.act }
  self.verbs[lemma] = v
  for _, fm in ipairs(Morph.verb_forms(lemma)) do
    self:add_form(fm.form, { pos = "verb", lemma = lemma, feat = fm.feat, act = f.act })
    -- a multiword verb ("track down", "take a look at") is one span in the lattice
    if lemma:find(" ", 1, true) then self:trie_insert(fm.form, { kind = "actverb", lemma = lemma, feat = fm.feat, act = f.act }) end
  end
end

function DIRECTIVES.adj(self, rest)
  local lemma, tail = split_head(rest)
  local f = split_fields(tail)
  self.adjs[lemma] = { lemma = lemma, dim = f.dim }
  for _, fm in ipairs(Morph.adj_forms(lemma)) do
    self:add_form(fm.form, { pos = "adj", lemma = lemma, feat = fm.feat, dim = f.dim })
  end
end

function DIRECTIVES.dim(self, rest)
  local name, tail = split_head(rest)
  local f = split_fields(tail)
  self.dims[name] = { name = name, rels = list(f.rels, ","), order = f.order }
end

function DIRECTIVES.cue(self, rest)
  local name, tail = split_head(rest)
  self.cues[name] = self.cues[name] or {}
  self.cue_phrases[name] = self.cue_phrases[name] or {}
  for _, p in ipairs(list(tail)) do
    local keys = L.keys_of(p)
    local forms = U.map(keys, function(k) return k.form end)
    self.cues[name][table.concat(forms, " ")] = true
    self.cue_phrases[name][#self.cue_phrases[name] + 1] = forms
    self.cue_first[name] = self.cue_first[name] or {}
    local bucket = self.cue_first[name][forms[1]]
    if not bucket then bucket = {}; self.cue_first[name][forms[1]] = bucket end
    bucket[#bucket + 1] = forms
  end
end

function DIRECTIVES.domain(self, rest)
  local name, tail = split_head(rest)
  for _, w in ipairs(words_of(tail)) do
    local f = w:lower()
    -- cue words apply to their inflected forms too ("university" cues "universities")
    local forms = { f }
    if not f:find("[^%a]") then for _, nf in ipairs(Morph.noun_forms(f)) do forms[#forms + 1] = nf.form end end
    for _, form in ipairs(forms) do
      self.domain_words[form] = self.domain_words[form] or {}
      self.domain_words[form][name] = true
    end
  end
end

function DIRECTIVES.headcue(self, rest)
  local t, tail = split_head(rest)
  if not self:has_type(t) then error("unknown type " .. t) end
  for _, w in ipairs(words_of(tail)) do self.headcues[w:lower()] = t end
end

function DIRECTIVES.resource(self, rest)
  local name, tail = split_head(rest)
  for _, p in ipairs(list(tail)) do
    local keys = L.keys_of(p)
    self.resources[table.concat(U.map(keys, function(k) return k.form end), " ")] = name
  end
  self.resources[name] = name
end

-- nouns that denote conversational artifacts ("the second solution", "the revised version", "my earlier correction")
function DIRECTIVES.refnoun(self, rest)
  local class, tail = split_head(rest)
  for _, w in ipairs(list(tail)) do
    local f = w:lower()
    local forms = { f }
    for _, nf in ipairs(Morph.noun_forms(f)) do forms[#forms + 1] = nf.form end
    for _, form in ipairs(forms) do
      self.refnouns[form] = self.refnouns[form] or {}
      self.refnouns[form][class] = true
    end
  end
end

function DIRECTIVES.wrap(self, rest)
  local name, tail = split_head(rest)
  local f, _ = split_fields(tail)
  local pat = {}
  for tok in (f.pattern or tail):gmatch("%S+") do pat[#pat + 1] = tok end
  self.wraps[#self.wraps + 1] = { name = name, pattern = pat, mode = f.mode }
end

function L:directive(dir, rest, source, ln)
  local fn = DIRECTIVES[dir]
  if not fn then error("unknown directive '" .. dir .. "'") end
  fn(self, rest, source, ln)
end

---------------------------------------------------------------- queries
-- An OPEN relation stands for a relation word the lexicon does not know ("paint", "mascot"): it is represented faithfully under its own name
-- ("open:paint") instead of being mapped onto a familiar relation.  Created on demand, never listed among the lexicon's relations.
L.OPEN_PREFIX = "open:"
function L:open_relation(lemma)
  lemma = lemma:gsub("e$", "")   -- "dance" / "danc(ed)" name the same open relation
  local root = self
  while root.parent do root = root.parent end
  root.open_rels = root.open_rels or {}
  local id = L.OPEN_PREFIX .. lemma
  local r = root.open_rels[id]
  if not r then
    r = { id = id, from = "entity", to = "entity", label = lemma .. " (open relation)", nouns_to = {}, nouns_from = {}, verbs = {}, preps = {}, kinds = {}, weight = 0.5,
      source = "open", open = true }
    root.open_rels[id] = r
  end
  return r
end

function L:get_rel(id)
  local r = self.rels[id]
  if r then return r end
  if self.parent then
    r = self.parent:get_rel(id)
    if r then return r end
  end
  local lemma = id:match("^open:(.+)$")
  if lemma then return self:open_relation(lemma) end
end

-- relations that are specialisations of `id` (declared `isa=id`): evidence for them also answers a question about the general relation
function L:specializations(id)
  local out = {}
  local lex = self
  while lex do
    for _, rid in ipairs(lex.rel_order) do
      local r = lex.rels[rid]
      if r.isa == id then out[#out + 1] = rid end
    end
    lex = lex.parent
  end
  return out
end

-- a relation designated by a dataset column / predicate string: id, label or one of its nouns ("Capital", "capital of", "CEO", "has_capital")
function L:rel_by_name(name)
  local key = name:lower():gsub("[%s%-]+", "_"):gsub("[^%w_]", "")
  local r = self:get_rel(key)
  if r then return r end
  local plain = name:lower():gsub("[_%-]+", " "):gsub("^%s*has%s+", ""):gsub("%s+of%s*$", ""):gsub("%s+by%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
  -- passive-style column names ("founded_by", "acquired_by"): the relation whose verb has the subject in the `to` role
  local pv = key:match("^(.-)_by$")
  if pv then
    local cands = { pv, (pv:gsub("ed$", "")), (pv:gsub("d$", "")), (pv:gsub("ied$", "y")) }
    local lex = self
    while lex do
      for _, id in ipairs(lex.rel_order) do
        local rel = lex.rels[id]
        for _, v in ipairs(rel.verbs or {}) do
          if v.subj == "to" and not v.prep then for _, c in ipairs(cands) do if v.lemma == c then return rel end end end
        end
      end
      lex = lex.parent
    end
  end
  local lex = self
  while lex do
    for _, id in ipairs(lex.rel_order) do
      local rel = lex.rels[id]
      local label = (rel.label or ""):lower()
      if label == plain then return rel end
      for _, n in ipairs(rel.nouns_to or {}) do if n:lower() == plain then return rel end end
      for _, n in ipairs(rel.nouns_from or {}) do if n:lower() == plain then return rel end end
    end
    lex = lex.parent
  end
  return nil
end

function L:get_entity(id)
  local e = self.entities[id]
  if e then return e end
  if self.parent then return self.parent:get_entity(id) end
end

function L:get_sense(id)
  local s = self.senses[id]
  if s then return s end
  if self.parent then return self.parent:get_sense(id) end
end

function L:cats(form)
  local c = self.classes[form]
  if c then return c end
  if self.parent then return self.parent:cats(form) end
  return nil
end

function L:is_cat(form, cat)
  local c = self:cats(form)
  return c ~= nil and c[cat] == true
end

function L:pron_feats(form)
  return self.pron[form] or (self.parent and self.parent:pron_feats(form))
end

function L:readings(form)
  local out = {}
  local lex = self
  while lex do
    for _, r in ipairs(lex.forms[form] or {}) do out[#out + 1] = r end
    lex = lex.parent
  end
  return out
end

function L:has_cue(name, phrase_key)
  local lex = self
  while lex do
    if lex.cues[name] and lex.cues[name][phrase_key] then return true end
    lex = lex.parent
  end
  return false
end

function L:cue_list(name)
  local out = {}
  local lex = self
  while lex do
    for _, forms in ipairs(lex.cue_phrases[name] or {}) do out[#out + 1] = forms end
    lex = lex.parent
  end
  return out
end

-- does the unit sequence starting at i begin with any cue phrase of this kind? returns length matched
function L:cue_at(name, units, i)
  local u0 = units[i]
  if not u0 then return nil end
  local best
  local lex = self
  while lex do
    local first = lex.cue_first[name]
    local bucket = first and first[u0.form]
    if bucket then
      for _, forms in ipairs(bucket) do
        local ok = true
        for k = 2, #forms do
          local u = units[i + k - 1]
          if not u or u.form ~= forms[k] then ok = false break end
        end
        if ok and (not best or #forms > best) then best = #forms end
      end
    end
    lex = lex.parent
  end
  return best
end

function L:domains_of(form)
  local lex, out = self, {}
  while lex do
    local d = lex.domain_words[form]
    if d then for k in pairs(d) do out[k] = true end end
    lex = lex.parent
  end
  return out
end

-- is `phrase` (folded) listed under the cue kind `name` in this lexicon or an ancestor?
function L:is_cue(name, phrase)
  local lex = self
  while lex do
    if lex.cues[name] and lex.cues[name][phrase] then return true end
    lex = lex.parent
  end
  return false
end

-- artifact classes a noun can denote (set), merged along the overlay chain
function L:refclasses(form)
  local out, lex = {}, self
  while lex do
    for c in pairs(lex.refnouns[form] or {}) do out[c] = true end
    lex = lex.parent
  end
  return out
end

function L:headcue(form)
  return self.headcues[form] or (self.parent and self.parent:headcue(form))
end

function L:resource(key)
  local r = self.resources[key] or (self.parent and self.parent:resource(key))
  if r or type(key) ~= "string" then return r end
  -- plural forms of a resource noun ("datasets", "versions", "files", "analyses" are not resources, "libraries" is not either)
  if #key > 3 and key:sub(-1) == "s" and key:sub(-2) ~= "ss" then
    local stem = key:sub(1, -2)
    r = self.resources[stem] or (self.parent and self.parent:resource(stem))
    if r then return r end
    if key:sub(-2) == "es" then
      stem = key:sub(1, -3)
      r = self.resources[stem] or (self.parent and self.parent:resource(stem))
    end
  end
  return r
end

function L:adj_reading(form)
  for _, r in ipairs(self:readings(form)) do if r.pos == "adj" then return r end end
end

function L:dim(name) return self.dims[name] or (self.parent and self.parent:dim(name)) end

function L:all_rels()
  local out, seen = {}, {}
  local lex = self
  local chain = {}
  while lex do table.insert(chain, 1, lex); lex = lex.parent end
  for _, x in ipairs(chain) do
    for _, id in ipairs(x.rel_order) do if not seen[id] then seen[id] = true; out[#out + 1] = x.rels[id] end end
  end
  return out
end

---------------------------------------------------------------- typo vocabulary derived from the loaded resources
-- Every word the lexicon knows (class words, verb/adjective forms, every unit of every phrase) feeds a symmetric-delete index.
-- Entity-name words are tagged kind="entity" so unknown capitalised words prefer entity neighbours.
function L:build_spell(parent_spell)
  local Spell = require("asi.nlu.spell")
  local sp = Spell.new()
  if parent_spell then sp:chain(parent_spell) end
  for form in pairs(self.classes) do if not form:find("%s") and not form:find("'") then sp:add(form, 5, "lex") end end
  for form in pairs(self.forms) do if not form:find("%s") then sp:add(form, 3, "lex") end end
  local function walk(node)
    for key, kid in pairs(node.kids) do
      local form = key:match("^([^\1]*)")
      local kind = "lex"
      if kid.entries then for _, e in ipairs(kid.entries) do if e.kind == "entity" then kind = "entity" end end end
      if #form >= 3 and not form:find("[%d']") then sp:add(form, kind == "entity" and 4 or 3, kind) end
      walk(kid)
    end
  end
  walk(self.trie)
  self.spell = sp
  return sp
end

-- closed-class words (wh-words, auxiliaries, determiners, prepositions, pronouns, conjunctions): the words whose misspelling destroys syntax.  Kept in a
-- separate index so that a typo is read as a function word only through the explicit, penalised repair pass (asi.nlu.parse repair_cover).
local FUNCTION_CLASSES = { "wh", "aux_do", "aux_be", "aux_have", "modal", "det", "prep", "pron", "pron_poss", "conj", "polite" }
function L:function_spell()
  local root = self
  while root.parent do root = root.parent end
  if root._fn_spell and root._fn_spell_rev == root.revision then return root._fn_spell end
  local Spell = require("asi.nlu.spell")
  local sp = Spell.new()
  for _, cls in ipairs(FUNCTION_CLASSES) do
    local words = {}
    for form in pairs(root.class_words[cls] or {}) do words[#words + 1] = form end
    table.sort(words)
    for _, form in ipairs(words) do if #form >= 3 and not form:find("[%s']") then sp:add(form, 5, cls) end end
  end
  root._fn_spell, root._fn_spell_rev = sp, root.revision
  return sp
end

---------------------------------------------------------------- relation induction from dataset schema names
-- "founded_by" -> passive verb (found, subj=to); "ceo_of" -> noun "ceo"; "headquarters_location" -> noun; "has_capital" -> noun "capital"
function L:induce_relation(name, spec)
  spec = spec or {}
  local rid = spec.id or name
  if self.rels[rid] and not spec.force then return self.rels[rid], false end
  if not spec.id and self:get_rel(name) and not spec.force then return self:get_rel(name), false end
  local parts = {}
  for p in name:gsub("(%l)(%u)", "%1_%2"):lower():gmatch("[%a%d]+") do parts[#parts + 1] = p end
  local drop = { has = true, is = true, was = true, have = true, a = true, the = true }
  while #parts > 1 and drop[parts[1]] do table.remove(parts, 1) end
  local preps = { of = true, by = true, in_ = true, to = true, for_ = true, at = true, from = true, with = true }
  local r = { id = rid, from = spec.from or "entity", to = spec.to or "entity", label = (name:gsub("_", " ")), nouns_to = {}, nouns_from = {},
    verbs = {}, preps = {}, kinds = {}, weight = 0.7, source = "induced" }
  local last = parts[#parts]
  if #parts >= 2 and (last == "by") then
    local v = parts[#parts - 1]
    local base = v:gsub("ed$", ""):gsub("ied$", "y")
    local cands = { v:gsub("ed$", ""), v:gsub("d$", ""), (v:gsub("ied$", "y")) }
    local lemma = cands[1]
    if v:find("ed$") then
      if self.verbs[cands[2]] or self:readings(cands[2])[1] then lemma = cands[2] end
      if #v > 5 and v:sub(-3, -3) == v:sub(-4, -4) then lemma = v:sub(1, -4) end
    end
    r.verbs[#r.verbs + 1] = { lemma = lemma, subj = "to" }
    r.nouns_to[#r.nouns_to + 1] = (v:gsub("ed$", "er"):gsub("eder$", "er"))
  elseif #parts >= 2 and preps[last] then
    r.nouns_to[#r.nouns_to + 1] = table.concat(parts, " ", 1, #parts - 1)
  else
    r.nouns_to[#r.nouns_to + 1] = table.concat(parts, " ")
    if #parts >= 2 then r.nouns_to[#r.nouns_to + 1] = parts[#parts] end
  end
  for k, v in pairs(spec) do if k ~= "force" and k ~= "id" and r[k] == nil then r[k] = v end end
  if spec.nouns then for _, n in ipairs(spec.nouns) do r.nouns_to[#r.nouns_to + 1] = n end end
  if spec.verbs then for _, v in ipairs(spec.verbs) do r.verbs[#r.verbs + 1] = v end end
  self:add_rel(r)
  return r, true
end

return L

end

package.preload["asi.nlu.longctx"] = function(...)
-- asi.nlu.longctx: deterministic long-conversation generator + scorer for the memory / coreference layer.
-- Every scenario plants the information the final request needs at the beginning, middle or end of N distractor turns and records exactly
-- which planted items are relevant, so memory precision / recall / false-memory rate are measured against ground truth, not impressions.
-- The distractor vocabulary is deliberately disjoint from the wording of the dev/val/test case files.
local U = require("asi.nlu.util")

local LC = {}

local TOPIC_SENTENCES = {
  weather = { "The weather in %s was grey and windy all week.", "It rained on the %s ferry again yesterday.", "A cold front is crossing %s tonight." },
  food = { "I tried a new %s recipe over the weekend.", "The %s at the corner cafe sold out by noon.", "We ordered far too much %s for the party." },
  travel = { "Our train to %s was delayed by forty minutes.", "I booked a hostel near the %s station.", "The flight to %s leaves before sunrise." },
  hobby = { "I finally repaired my %s after months of procrastinating.", "The %s club meets on Thursdays.", "My neighbour lent me a %s for the weekend." },
  chatter = { "Anyway, that was a long day.", "Thanks, that makes sense.", "Okay, noted.", "Let me think about that for a moment.", "Interesting, I did not know that.",
    "Never mind the noise outside.", "The meeting ran over again." },
  -- adversarial distractors: they contain instruction-looking or dataset-looking words but are not instructions to the system
  lookalike = { "My friend said to use the %s dataset in her statistics class.", "The %s report was lovely but I lost the file.",
    "Someone asked whether universities should be excluded from the survey.", "She told me to switch to the %s edition of the textbook." },
}
local FILL = {
  weather = { "Springfield", "Dunmore", "Larchford", "Pellham", "Ostrava" },
  food = { "lentil", "mushroom", "quince", "barley", "sesame" },
  travel = { "Lisbon", "Bergen", "Tallinn", "Kraków", "Valencia" },
  hobby = { "bicycle", "telescope", "kayak", "accordion", "loom" },
  lookalike = { "2019", "2021", "2022", "revised", "third" },
}
local TOPICS = { "weather", "food", "travel", "hobby", "chatter", "lookalike" }

local ORGS = { "Zenvo Dynamics", "Quillon Labs", "Marrow Systems", "Tessaly Robotics", "Brindle Analytics", "Oakhaven Partners", "Pyrrhic Software", "Lumora Networks" }
local SIMILAR = { { "Zenvo Dynamics", "Zenvo Dynamix", "Zenvo Dynamics Labs" }, { "Quillon Labs", "Quillion Labs", "Quillon Labs Europe" } }

-- Wordings of every planted / final turn live in a template table so that an INDEPENDENTLY authored set can be swapped in (LC.use).  The defaults below are
-- the development wordings.  Placeholders: %ORG% %THING% %DB% %WHAT% %NEW% %OLD% %SIM1% %SIM2%.
local DEFAULT_T = {
  plant_entity = { "I'm looking at %ORG%, a small robotics business." },
  final_acquirer = { "Which company acquired the business I mentioned earlier?" },
  final_ceo = { "Who is the CEO of the company I mentioned earlier?" },
  plant_old_dataset = { "Use the %OLD% dataset." },
  plant_correction = { "Actually, use the %NEW% dataset from now on." },
  final_analyze = { "Analyze the figures." },
  plant_exclusion = { "Do not include %WHAT%." },
  plant_exclusion_embedded = { "Please do not include %WHAT%." },
  final_search = { "Find organizations in Germany." },
  plant_similar = { "I'm looking at %ORG%, a small robotics business." },
  assistant_similar = { "Related names include %SIM1% and %SIM2%." },
  final_ceo_similar = { "Who is the CEO of the company I mentioned earlier?" },
  plant_decision = { "We decided to use %DB% for the %THING% service." },
  final_decision = { "What did we decide about the %THING% service?" },
  plant_research = { "I'm researching %ORG%." },
  plant_other = { "Tell me about %ORG%." },
  final_pronoun = { "Who founded it?" },
  orgs = ORGS, things = { "inventory", "billing", "telemetry" }, dbs = { "PostgreSQL", "SQLite", "MariaDB" },
  whats = { "universities", "reposts", "retailers", "agencies" }, years_old = { "2019", "2020", "2021" }, years_new = { "2024", "2025", "2026" },
}
local T = DEFAULT_T
local EXTERNAL   -- set by LC.use: external distractor / look-alike pools

-- swap in an externally authored template set (same keys; missing keys fall back to the defaults); returns the previous set
function LC.use(t)
  local prev = { T = T, EXTERNAL = EXTERNAL }
  if not t then T, EXTERNAL = DEFAULT_T, nil; return prev end
  local merged = {}
  for k, v in pairs(DEFAULT_T) do merged[k] = v end
  for k, v in pairs(t) do merged[k] = v end
  if t.years then merged.years_old, merged.years_new = t.years, t.years end
  T = merged
  EXTERNAL = (t.distractors and #t.distractors > 0) and { distractors = t.distractors, lookalikes = t.lookalikes or {} } or nil
  return prev
end

local function fill(tmpl, vars)
  return (tmpl:gsub("%%(%u+%d?)%%", function(k) return vars[k] or ("%" .. k .. "%") end))
end

function LC.load_templates(path)
  local f = assert(io.open(path, "rb"))
  local raw = f:read("a")
  f:close()
  local obj = assert(U.json_decode(raw))
  return obj, U.sha256(raw)
end

function LC.distractor(rng)
  if EXTERNAL then
    local lookalike = #EXTERNAL.lookalikes > 0 and rng:int(1, 6) == 1
    local pool = lookalike and EXTERNAL.lookalikes or EXTERNAL.distractors
    return rng:pick(pool), lookalike and "lookalike" or "chatter"
  end
  local topic = rng:pick(TOPICS)
  local pool = TOPIC_SENTENCES[topic]
  local t = rng:pick(pool)
  if t:find("%%s") then t = t:format(rng:pick(FILL[topic])) end
  return t, topic
end

-- position p in {"begin","middle","end"} -> index among N distractor slots (needed turn is inserted AFTER that many distractors)
local function slot(p, n)
  if p == "begin" then return 0 elseif p == "middle" then return n // 2 end
  return n
end

-- ---------------------------------------------------------------------------------------------------------------- scenario builders
local B = {}

-- an entity introduced by the user is referred to much later by a definite description with a discourse-linked relative clause
function B.backref_entity(rng, n, pos)
  local org = rng:pick(T.orgs)
  local turns, planted = {}, {}
  local at = slot(pos, n)
  for i = 0, n do
    if i == at then
      turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_entity), { ORG = org }), planted = "entity" }
      planted[#planted + 1] = #turns
    end
    if i < n then local t, tp = LC.distractor(rng); turns[#turns + 1] = { speaker = "user", text = t, topic = tp } end
  end
  return { turns = turns, final = rng:pick(T.final_acquirer), planted = planted,
    expect = { ref = T == DEFAULT_T and "the business I mentioned earlier" or nil, ref_any = true, antecedent = org, relation = "acquirer" } }
end

-- instruction early, correction later; the superseded value must not be active or retrieved
function B.correction(rng, n, pos)
  local a, b = rng:pick(T.years_old), rng:pick(T.years_new)
  while b == a do b = rng:pick(T.years_new) end
  local turns, planted = {}, {}
  local first = slot(pos, n) // 2
  local second = slot(pos, n)
  if second <= first then second = first + 1 end
  for i = 0, n do
    if i == first then turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_old_dataset), { OLD = a }), planted = "old" } end
    if i == second then
      turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_correction), { NEW = b }), planted = "correction" }
      planted[#planted + 1] = #turns
    end
    if i < n then local t, tp = LC.distractor(rng); turns[#turns + 1] = { speaker = "user", text = t, topic = tp } end
  end
  return { turns = turns, final = rng:pick(T.final_analyze), planted = planted, expect = { slot = "dataset", value = b, stale = a } }
end

-- standing exclusion given once
function B.exclusion(rng, n, pos)
  local what = rng:pick(T.whats)
  local turns, planted = {}, {}
  local at = slot(pos, n)
  for i = 0, n do
    if i == at then
      turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_exclusion), { WHAT = what }), planted = "exclusion" }
      planted[#planted + 1] = #turns
    end
    if i < n then local t, tp = LC.distractor(rng); turns[#turns + 1] = { speaker = "user", text = t, topic = tp } end
  end
  return { turns = turns, final = rng:pick(T.final_search), planted = planted, expect = { prohibition = what } }
end

-- a negation buried inside ONE long message
function B.buried_negation(rng, n, pos)
  local what = rng:pick(T.whats)
  local parts = {}
  local at = slot(pos, n)
  for i = 0, n do
    if i == at then parts[#parts + 1] = fill(rng:pick(T.plant_exclusion_embedded), { WHAT = what }) end
    if i < n then local t = LC.distractor(rng); parts[#parts + 1] = t end
  end
  local text = table.concat(parts, " ")
  return { turns = { { speaker = "user", text = text, planted = "exclusion" } }, final = rng:pick(T.final_search), planted = { 1 },
    expect = { prohibition = what } }
end

-- several look-alike names: the one the USER introduced is the referent of "the company I mentioned earlier"
function B.similar_names(rng, n, pos)
  local set
  if T == DEFAULT_T then set = rng:pick(SIMILAR)
  else local org = rng:pick(T.orgs); set = { org, (org:gsub(".$", "x")), org .. " Europe" } end
  local turns, planted = {}, {}
  local at = slot(pos, n)
  for i = 0, n do
    if i == at then
      turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_similar), { ORG = set[1] }), planted = "entity" }
      planted[#planted + 1] = #turns
      turns[#turns + 1] = { speaker = "assistant", text = fill(rng:pick(T.assistant_similar), { SIM1 = set[2], SIM2 = set[3] }), planted = "similar" }
    end
    if i < n then local t, tp = LC.distractor(rng); turns[#turns + 1] = { speaker = "user", text = t, topic = tp } end
  end
  local final = rng:pick(T.final_ceo_similar)
  return { turns = turns, final = final, planted = planted,
    expect = { ref = T == DEFAULT_T and "the company I mentioned earlier" or nil, ref_any = true, antecedent = set[1], relation = "ceo" } }
end

-- a decision referred to later without repeating its wording
function B.decision(rng, n, pos)
  local db = rng:pick(T.dbs)
  local thing = rng:pick(T.things)
  local turns, planted = {}, {}
  local at = slot(pos, n)
  for i = 0, n do
    if i == at then
      turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_decision), { DB = db, THING = thing }), planted = "decision" }
      planted[#planted + 1] = #turns
    end
    if i < n then local t, tp = LC.distractor(rng); turns[#turns + 1] = { speaker = "user", text = t, topic = tp } end
  end
  return { turns = turns, final = fill(rng:pick(T.final_decision), { THING = thing }), planted = planted, expect = { fragment = db } }
end

-- the pronoun case: after distractors the antecedent has decayed; the system must either resolve correctly or say it cannot -- never resolve wrongly
function B.pronoun_gap(rng, n, pos)
  local org = rng:pick(T.orgs)
  local other = rng:pick(T.orgs)
  while other == org do other = rng:pick(T.orgs) end
  local turns, planted = {}, {}
  local at = slot(pos, n)
  for i = 0, n do
    if i == at then
      turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_research), { ORG = org }), planted = "entity" }
      planted[#planted + 1] = #turns
    end
    if i < n then local t, tp = LC.distractor(rng); turns[#turns + 1] = { speaker = "user", text = t, topic = tp } end
  end
  turns[#turns + 1] = { speaker = "user", text = fill(rng:pick(T.plant_other), { ORG = other }), planted = "other" }
  -- "it" now most plausibly refers to the most recent organisation (other); referring to the old one would be WRONG
  return { turns = turns, final = rng:pick(T.final_pronoun), planted = planted, expect = { pronoun = "it", wrong = org, right = other, relation = "founder" } }
end

LC.KINDS = { "backref_entity", "correction", "exclusion", "buried_negation", "similar_names", "decision", "pronoun_gap" }
LC.BUILD = B

-- ---------------------------------------------------------------------------------------------------------------- scoring
local function norm(s) return (s or ""):lower():gsub("%s+", " ") end

local function selected_text(m)
  local out = {}
  for _, it in ipairs(m.context and m.context.memory and m.context.memory.selected or {}) do out[#out + 1] = it.text or "" end
  return out
end

-- returns { ok = bool, checks = { name = bool }, selected = {...}, false_memory = n, relevant_selected = n }
function LC.score(sc, m, lex)
  local r = { ok = true, checks = {} }
  local function chk(name, ok) r.checks[name] = ok and true or false; if not ok then r.ok = false end end
  local ex = sc.expect
  if not m then chk("interpretation", false); return r end
  local texts = selected_text(m)
  local planted_text = {}
  for _, idx in ipairs(sc.planted) do planted_text[#planted_text + 1] = norm(sc.turns[idx].text) end
  -- memory precision / recall against planted items
  local rel_sel, false_sel, recent = 0, 0, 0
  for _, it in ipairs(m.context and m.context.memory and m.context.memory.selected or {}) do
    local t = it.text or ""
    local hit = false
    for _, p in ipairs(planted_text) do if norm(t):find(p:sub(1, 40), 1, true) or p:find(norm(t):sub(1, 40), 1, true) then hit = true end end
    if hit then rel_sel = rel_sel + 1
    elseif it.factors and it.factors.recent_window then recent = recent + 1 -- "essential recent conversation" by policy for pronoun requests: not a false memory
    else false_sel = false_sel + 1 end
  end
  r.relevant_selected, r.false_memory, r.n_selected, r.recent_window = rel_sel, false_sel, #texts, recent
  r.planted_total = #planted_text
  if ex.ref or ex.ref_any then
    local found
    local refs = m.context and m.context.references or {}
    if ex.ref then
      for _, ref in ipairs(refs) do if norm(ref.mention) == norm(ex.ref) then found = ref end end
    else
      -- externally authored final wording: the back-reference is whichever reference the interpreter resolved to the planted entity (or, failing that, any reference)
      for _, ref in ipairs(refs) do
        if ref.status == "resolved" and ref.antecedent and norm(ref.antecedent.text) == norm(ex.antecedent) then found = ref end
      end
      found = found or refs[1]
    end
    chk("reference_found", found ~= nil)
    chk("entity_recovered", found ~= nil and found.status == "resolved" and found.antecedent and norm(found.antecedent.text) == norm(ex.antecedent))
    -- "Who LEADS / is the HEAD of the company I mentioned?" asks for the leader, of which the CEO is a kind (ceo isa leader): when the wording does not say CEO,
    -- the parent relation is the correct reading of the question.  A wording that names the CEO must produce ceo.
    local rel_ok = m.relation and m.relation.id == ex.relation
    if not rel_ok and m.relation and lex and not (sc.final or ""):lower():find("ceo", 1, true) and not (sc.final or ""):lower():find("chief executive", 1, true) then
      local want = lex:get_rel(ex.relation)
      rel_ok = want ~= nil and want.isa == m.relation.id
    end
    chk("relation", rel_ok)
  elseif ex.slot then
    local act = {}
    for _, c in ipairs(m.context and m.context.active_constraints or {}) do if c.slot then act[c.slot] = tostring(c.value) end end
    chk("correction_active", act[ex.slot] == ex.value)
    -- the corrected value must be among the retrieved memory items of the slot and the superseded one must not be (the wording around the value is the
    -- user's own: "the 2021 dataset", "dataset 2021", "dataset named 2021", ...; the item records slot and value, so the check does not depend on wording)
    local got_new, got_stale = false, false
    for _, it in ipairs(m.context and m.context.memory and m.context.memory.selected or {}) do
      if it.slot == ex.slot and tostring(it.value) == tostring(ex.value) then got_new = true end
      if it.slot == ex.slot and tostring(it.value) == tostring(ex.stale) then got_stale = true end
    end
    chk("correction_retrieved", got_new)
    chk("stale_not_retrieved", not got_stale)
  elseif ex.prohibition then
    local found = false
    for _, c in ipairs(m.context and m.context.active_constraints or {}) do
      if c.kind == "prohibition" and norm(c.text):find(ex.prohibition, 1, true) then found = true end
    end
    chk("constraint_retained", found)
  elseif ex.fragment then
    local joined = table.concat(texts, "\n")
    chk("decision_retrieved", joined:find(ex.fragment, 1, true) ~= nil)
  elseif ex.pronoun then
    local found
    for _, ref in ipairs(m.context and m.context.references or {}) do if norm(ref.mention) == ex.pronoun then found = ref end end
    -- externally authored final wordings refer to the company in other ways ("them", "they", "that company", "this company"): any anaphoric reference counts
    if not found and T ~= DEFAULT_T then
      for _, ref in ipairs(m.context and m.context.references or {}) do
        if ref.kind == "pronoun" or ref.kind == "entity_backref" then found = found or ref end
      end
    end
    chk("pronoun_found", found ~= nil)
    -- correct = resolves to the right entity, or honestly reports ambiguity / no antecedent.  WRONG = resolves to the stale one.
    local wrong = found and found.status == "resolved" and found.antecedent and norm(found.antecedent.text) == norm(ex.wrong)
    chk("no_false_resolution", not wrong)
    r.pronoun_status = found and found.status or "none"
    r.pronoun_correct = found and found.status == "resolved" and found.antecedent and norm(found.antecedent.text) == norm(ex.right) or false
  end
  return r
end

-- run one scenario through an interpreter facade; returns score table plus cost counters
function LC.run(interp, Memory, sc, opts)
  opts = opts or {}
  local mem = Memory.new({ ns = { user = "lc", project = "lc", conversation = "lc" } })
  local work, t0 = 0, os.clock()
  local last
  for _, t in ipairs(sc.turns) do
    local r = interp:interpret(t.text, { memory = mem, speaker = t.speaker, light = (t.speaker ~= "user") })
    work = work + (r.work and r.work.total or 0)
  end
  local fin = interp:interpret(sc.final, { memory = mem, speaker = "user" })
  last = fin.main
  local score = LC.score(sc, last, interp.lex)
  score.work_final = fin.work and fin.work.total or 0
  score.work_total = work + score.work_final
  score.wall = os.clock() - t0
  score.items = mem.index.n
  score.n_candidates = (last and last.context and last.context.memory) and last.context.memory.n_selected or 0
  return score, mem, last
end

return LC

end

package.preload["asi.nlu.memory"] = function(...)
-- asi.nlu.memory: layered, namespaced, auditable conversation memory.
--   working   = the current request + recent turns + active standing constraints        (derived at selection time)
--   episodic  = every utterance / decision / correction with turn + exact source text
--   semantic  = facts asserted in conversation (triples) WITH provenance, hedges kept as speculative
--   task      = standing instructions, prohibitions, preferences, focus (slot-keyed, supersedable, revocable)
--   retrieval = inverted index over items (+ entity postings)  -> references, never a dump of history
--   persistent= canonical-JSON serialisation with schema version and checksum (only when save()/load() are called)
-- No cross-namespace reads exist in the API: every item carries its namespace and every query is scoped to one namespace.
local U = require("asi.nlu.util")

local M = {}
M.__index = M
M.SCHEMA = "nlu.memory/1"

local PROTECTED_KINDS = U.set({ "instruction", "prohibition", "correction", "preference", "decision", "focus" })
local STOP = U.set({ "the", "a", "an", "of", "and", "or", "to", "in", "on", "at", "by", "for", "with", "is", "are", "was", "were", "be", "it", "its",
  "as", "that", "this", "which", "what", "who", "how", "do", "does", "did", "i", "you", "we", "me", "my", "your", "please", "can", "could" })

-- words of the recall frame itself ("what did I SAY ...", "remind me what we DISCUSSED"): they name the act of recalling, not what is recalled
local RECALL_FRAME = {}
for _, w in ipairs({ "say", "said", "says", "tell", "told", "mention", "mentioned", "ask", "asked", "remember", "recall", "remind", "earlier", "before", "previously",
  "discuss", "discussed", "talk", "talked", "state", "stated", "specify", "specified", "about", "tell", "wrote", "write", "typed", "just", "again" }) do
  RECALL_FRAME[require("asi.nlu.textutil").stem(w)] = true
end

-- which slots apply to which kinds of request (everything else is "any")
local SLOT_SCOPE = { dataset = "evidence", source = "evidence", version = "evidence", year = "evidence", file = "evidence", statement = "evidence",
  figures = "evidence", model = "any", format = "style", language = "style", tone = "style", persona = "style", dataset_role = "style" }
-- slots whose instructions ACCUMULATE ("use a calmer tone", then "no caps"): a newer one does not replace the older ones, an explicit reset inside the instruction does
local ADDITIVE_SLOTS = { tone = true, persona = true, dataset_role = true }
M.ADDITIVE_SLOTS = ADDITIVE_SLOTS

---------------------------------------------------------------- construction
function M.new(opts)
  opts = opts or {}
  local self = setmetatable({}, M)
  self.schema = M.SCHEMA
  self.ns = opts.ns or { user = "anonymous", project = "default", conversation = "c0" }
  self.transient = opts.transient or false
  self.max_items = opts.max_items or 20000
  self.decay = opts.decay or 0.85
  self.turn, self.revision, self.next_id, self.seq = 0, 0, 1, 0
  self.items, self.order = {}, {}
  self.entities = {}
  self.slots = {}
  self.focus = nil
  self.comparison = nil
  self.artifacts = {}
  self.index = { terms = {}, df = {}, len = {}, n = 0, total_len = 0 }
  self.by_entity = {}   -- entity key -> item ids (identity postings; relevance never rests on shared words alone)
  self.standing = {}    -- id -> true for active instructions / prohibitions / preferences / corrections
  self.facts_by = {}    -- "rel|from" -> item ids (conflict detection without scanning history)
  self.evictions = {}
  return self
end

function M:ns_key() return table.concat({ self.ns.user, self.ns.project, self.ns.conversation }, "|") end

---------------------------------------------------------------- items + index
local TU = require("asi.nlu.textutil")
local stem = TU.stem
M.stem = stem

local function tokens_of(text)
  local out = {}
  for _, t in ipairs(TU.tokens(text)) do if not STOP[t.w] then out[#out + 1] = t.t end end
  return out
end

function M:begin_turn(speaker)
  self.turn = self.turn + 1
  self.turn_entities = {}
  self.speaker = speaker or "user"
  self.revision = self.revision + 1
  return self.turn
end

local DEFAULT_RELIABILITY = { user = 1.0, system = 1.0, assistant = 0.6, doc = 0.5 }

function M:add(item)
  item.id = "m" .. self.next_id
  self.next_id = self.next_id + 1
  item.ns = item.ns or self:ns_key()
  item.turn = item.turn or self.turn
  item.speaker = item.speaker or self.speaker or "user"
  item.status = item.status or "active"
  item.reliability = item.reliability or DEFAULT_RELIABILITY[item.speaker] or 0.5
  item.provenance = item.provenance or { turn = item.turn, speaker = item.speaker }
  item.entities = item.entities or {}
  self.items[item.id] = item
  self.order[#self.order + 1] = item.id
  self.revision = self.revision + 1
  -- retrieval index
  local toks = tokens_of(item.text or "")
  local tf = {}
  for _, t in ipairs(toks) do tf[t] = (tf[t] or 0) + 1 end
  item._tf = tf
  for t, c in pairs(tf) do
    local post = self.index.terms[t]
    if not post then post = {}; self.index.terms[t] = post end
    post[item.id] = c
    self.index.df[t] = (self.index.df[t] or 0) + 1
  end
  for _, k in ipairs(item.entities) do
    local l = self.by_entity[k]
    if not l then l = {}; self.by_entity[k] = l end
    l[#l + 1] = item.id
    if #l > 400 then table.remove(l, 1) end
  end
  if PROTECTED_KINDS[item.kind] and item.kind ~= "decision" and item.kind ~= "focus" and item.status == "active" then self.standing[item.id] = true end
  self.index.len[item.id] = #toks
  self.index.n = self.index.n + 1
  self.index.total_len = self.index.total_len + #toks
  self:enforce_capacity()
  return item
end

-- BM25 of a query (term list) against one item
function M:bm25(terms, item)
  local ix = self.index
  if ix.n == 0 or not item._tf then return 0 end
  local avg = ix.total_len / math.max(1, ix.n)
  local k1, b = 1.2, 0.75
  local s = 0
  for _, t in ipairs(terms) do
    local f = item._tf[t]
    if f then
      local df = ix.df[t] or 0
      local idf = math.log(1 + (ix.n - df + 0.5) / (df + 0.5))
      s = s + idf * (f * (k1 + 1)) / (f + k1 * (1 - b + b * (ix.len[item.id] or 1) / avg))
    end
  end
  return s
end

function M:enforce_capacity()
  if #self.order <= self.max_items then return end
  -- evict the oldest unprotected, non-active-standing items first; never silently drop protected ones
  local keep = {}
  local excess = #self.order - self.max_items
  for _, id in ipairs(self.order) do
    local it = self.items[id]
    if excess > 0 and it and not PROTECTED_KINDS[it.kind] and it.kind ~= "artifact" then
      self:drop(id, "capacity")
      excess = excess - 1
    else keep[#keep + 1] = id end
  end
  self.order = keep
end

function M:drop(id, reason)
  local it = self.items[id]
  if not it then return end
  for t in pairs(it._tf or {}) do
    if self.index.terms[t] then self.index.terms[t][id] = nil end
    self.index.df[t] = math.max(0, (self.index.df[t] or 1) - 1)
  end
  self.standing[id] = nil
  self.index.total_len = self.index.total_len - (self.index.len[id] or 0)
  self.index.n = self.index.n - 1
  self.index.len[id] = nil
  self.items[id] = nil
  self.evictions[#self.evictions + 1] = { id = id, turn = it.turn, kind = it.kind, reason = reason }
end

---------------------------------------------------------------- entities and focus
local function ref_key(r)
  if not r or r.deictic then return nil end
  if r.antecedent and r.antecedent.key then return r.antecedent.key end
  if r.resolved_id and (r.status == "resolved" or r.status == "unseen" or r.status == nil) then return r.resolved_id end
  return nil
end
M.ref_key = ref_key

-- the key under which a fact stores an argument: entities by key, the speaker ("I", "my") as "speaker:<who>"
local function fact_key(r, speaker)
  if r and r.deictic == "speaker" then return "speaker:" .. (speaker or "user") end
  return ref_key(r)
end
M.fact_key = fact_key

function M:mention(key, info)
  if not key then return end
  local e = self.entities[key]
  if not e then
    e = { key = key, names = {}, type = info.type, mentions = {}, first_turn = self.turn, by_user = false }
    self.entities[key] = e
  end
  if info.loc then e.loc = true end          -- first met after a locative preposition: evidence of a place
  if info.exact then e.exact = true end      -- the speaker stressed that THIS is the intended name ("exactly X, no lookalikes")
  if info.type and not e.type then e.type = info.type end
  if info.itype and not e.type and not e.itype then e.itype = info.itype end
  if info.pname and not e.type then e.pname = true end
  if info.name and not e.names[info.name:lower()] then e.names[info.name:lower()] = info.name end
  if info.speaker == "user" then e.by_user = true end
  if info.speaker then e.by_speaker = e.by_speaker or {}; e.by_speaker[info.speaker] = true end
  if info.plural then e.plural = true end
  -- an entity is "weak" while its only evidence is a sentence-initial capital; any stronger mention clears the flag
  if e.weak == nil then e.weak = info.weak or false elseif not info.weak then e.weak = false end
  self.seq = self.seq + 1
  e.last_turn, e.last_seq = self.turn, self.seq
  if self.turn_entities then self.turn_entities[key] = true end
  local ms = e.mentions
  ms[#ms + 1] = { turn = self.turn, seq = self.seq, w = info.w or 0.25, role = info.role, speaker = info.speaker, sent = info.sent, text = info.name }
  if #ms > 40 then table.remove(ms, 1) end
  return e
end

-- classifying nouns the discourse attached to an entity ("Brindle Analytics, a small robotics business" -> business)
function M:describe(key, head, text, speaker)
  local e = self.entities[key]
  if not e or not head then return end
  e.descriptors = e.descriptors or {}
  local st = stem(head)
  if not e.descriptors[st] then e.descriptors[st] = { head = head, text = text, turn = self.turn, speaker = speaker } end
end

-- salience = sum of mention weights decayed by turn distance (and a small sentence-order tie-break)
function M:salience(e, now_turn)
  now_turn = now_turn or self.turn
  local s = 0
  for _, m in ipairs(e.mentions) do s = s + m.w * (self.decay ^ math.max(0, now_turn - m.turn)) end
  return s
end

---------------------------------------------------------------- artifacts (solutions, versions, options ...)
local ARTIFACT_NOUN = { solution = "solution", approach = "solution", option = "solution", method = "solution", attempt = "solution", proposal = "solution",
  candidate = "solution", plan = "solution", version = "version", edition = "version", draft = "version", revision = "version", iteration = "version",
  variant = "version" }
local ORDINAL_WORD = { one = 1, two = 2, three = 3, four = 4, five = 5, six = 6, seven = 7, eight = 8, nine = 9, ten = 10,
  first = 1, second = 2, third = 3, fourth = 4, fifth = 5 }

-- artifact classes a noun denotes (set).  The interpreter installs the lexicon's `refnoun` data as self.refclasses; the built-in map is the fallback.
function M:classes_of(word)
  word = word:lower()
  local cands = { word }
  if word:sub(-3) == "ies" then cands[#cands + 1] = word:sub(1, -4) .. "y" end
  if word:sub(-2) == "es" then cands[#cands + 1] = word:sub(1, -3) end
  if word:sub(-1) == "s" then cands[#cands + 1] = word:sub(1, -2) end
  for _, w in ipairs(cands) do
    local out
    if self.refclasses then out = self.refclasses(w) else out = ARTIFACT_NOUN[w] and { [ARTIFACT_NOUN[w]] = true } or {} end
    out = U.copy(out)
    out.correction = nil -- corrections are memory items, not enumerable artifacts
    out.message = nil
    if next(out) then return out end
  end
  return {}
end

function M:register_artifact(class, ordinal, label, text, item)
  local list = self.artifacts[class]
  if not list then list = {}; self.artifacts[class] = list end
  list[#list + 1] = { class = class, ordinal = ordinal, label = label, text = text, item = item and item.id, turn = self.turn, speaker = self.speaker }
end

-- find labelled or numbered alternatives in assistant/user text:  "Solution 2: ...",  "Option B - ...",  "Here are two approaches:\n1. ...\n2. ..."
function M:extract_artifacts(text, item)
  local n = 0
  local current_class
  for line in (text .. "\n"):gmatch("(.-)\r?\n") do
    local noun, label = line:match("^%s*[%*#%-]*%s*(%a+)%s+(%w+)%s*[:%.%)%-—]")
    local classes = noun and self:classes_of(noun) or {}
    if next(classes) and label then
      local ord = tonumber(label) or ORDINAL_WORD[label:lower()] or (label:match("^%u$") and (label:byte() - 64)) or nil
      if ord then
        for cls in pairs(classes) do self:register_artifact(cls, ord, noun .. " " .. label, line, item); n = n + 1 end
      end
    else
      local num, rest = line:match("^%s*(%d+)[%.%)]%s+(.*)$")
      if num and current_class then
        for cls in pairs(current_class) do self:register_artifact(cls, tonumber(num), cls .. " " .. num, rest, item); n = n + 1 end
      else
        local lower = line:lower()
        if lower:match(":%s*$") then
          current_class = nil
          for w in lower:gmatch("%a+") do
            local c = self:classes_of(w)
            if next(c) then current_class = c end
          end
        end
      end
    end
  end
  return n
end

-- An enumeration of entities in a turn: "1. Oslo 2. Stockholm 3. Helsinki", "Tallinn, Riga and Klaipeda", "Marie Curie and Albert Einstein".
-- items = { {key=, text=, type=, s=, e=}, ... } (entity mentions of the turn with byte offsets); returns the members of the list, or nil
function M.detect_enumeration(text, items)
  if #items < 2 then return nil end
  table.sort(items, function(a, b) return a.s < b.s end)
  -- (1) numbered items: markers 1. 2. 3. ... each followed by one item
  local nums = {}
  for pos, num in text:gmatch("()%f[%d](%d+)[%.%)]%s") do nums[#nums + 1] = { pos = pos, n = tonumber(num) } end
  if #nums >= 2 then
    local ok = true
    for i, x in ipairs(nums) do if x.n ~= i then ok = false end end
    if ok then
      local out = {}
      for i, x in ipairs(nums) do
        local hi = nums[i + 1] and nums[i + 1].pos or (#text + 1)
        for _, it in ipairs(items) do if it.s >= x.pos and it.s < hi then out[#out + 1] = it; break end end
      end
      if #out >= 2 then return out end
    end
  end
  -- (2) a run of items separated only by commas / "and" / "or" that makes up most of the message
  local lead = text:match("^[^:]*:%s*()") or 1
  local body = text:sub(lead):gsub("[%.%!%?%s]+$", "")
  local best
  local run = { items[1] }
  local function close()
    if #run >= 2 and (not best or #run > #best) then
      local span = run[#run].e - run[1].s + 1
      if span >= 0.5 * #body then best = run end
    end
  end
  for i = 2, #items do
    local a, b = items[i - 1], items[i]
    local between = text:sub(a.e + 1, b.s - 1):lower()
    if between:match("^[%s,;&]*$") and between:find("[,;&]") or between:match("^[%s,]*and[%s,]*$") or between:match("^[%s,]*or[%s,]*$") or between:match("^[%s,]*as well as[%s,]*$") then
      run[#run + 1] = b
    else close(); run = { b } end
  end
  close()
  return best
end

function M:note_enumeration(members)
  for i, m in ipairs(members) do
    local list = self.artifacts["entity"]
    if not list then list = {}; self.artifacts["entity"] = list end
    list[#list + 1] = { class = "entity", ordinal = i, label = m.text, text = m.text, turn = self.turn, speaker = self.speaker, key = m.key, etype = m.type, size = #members }
  end
end

-- the member of the latest entity enumeration an ordinal ("second", 2) or "last" / "first" refers to
function M:find_entity_ordinal(ordinal)
  local list = self.artifacts["entity"] or {}
  local latest = -1
  for _, a in ipairs(list) do if a.turn > latest then latest = a.turn end end
  local members = {}
  for _, a in ipairs(list) do if a.turn == latest then members[#members + 1] = a end end
  table.sort(members, function(x, y) return x.ordinal < y.ordinal end)
  if #members == 0 then return nil, 0 end
  if ordinal == "last" then return members[#members], #members end
  return members[tonumber(ordinal)], #members
end

function M:find_artifact(class, ordinal, label_word)
  local list = self.artifacts[class] or {}
  if ordinal then
    -- the latest enumeration wins: take artifacts from the most recent turn that produced this class
    local best
    for i = #list, 1, -1 do
      if list[i].ordinal == ordinal and (not best or list[i].turn >= best.turn) then best = list[i]; break end
    end
    return best
  end
  if label_word then
    for i = #list, 1, -1 do if (list[i].text or ""):lower():find(label_word, 1, true) then return list[i] end end
  end
  return nil
end

---------------------------------------------------------------- slots: supersession, revocation
function M:slot_state(slot)
  local s = self.slots[slot]
  if not s then s = { active = nil, history = {} }; self.slots[slot] = s end
  return s
end

-- The slot of the most recent standing user instruction whose value is of the given kind ("year" / "word") within the last few turns: a bare
-- corrected value ("Sorry, I meant 2023.") replaces the value of that slot.
function M:recent_slot(value_kind, max_turns)
  for i = #self.order, 1, -1 do
    local it = self.items[self.order[i]]
    if it and it.slot and it.speaker == "user" and (it.kind == "instruction" or it.kind == "correction") and it.status == "active" then
      if it.turn < (self.turn or 0) - (max_turns or 4) then return nil end
      if it.value_kind == value_kind then return it.slot end
    end
  end
  return nil
end

function M:supersede(old_id, by, reason)
  local old = self.items[old_id]
  if not old or old.status ~= "active" then return end
  old.status, old.superseded_by, old.superseded_reason, old.superseded_turn = "superseded", by.id, reason, self.turn
  self.standing[old_id] = nil
  by.supersedes = by.supersedes or {}
  table.insert(by.supersedes, old_id)
  self.revision = self.revision + 1
end

function M:revoke(id, by_turn_text)
  local it = self.items[id]
  if it and it.status == "active" then
    it.status, it.revoked_turn, it.revoked_by = "revoked", self.turn, by_turn_text
    self.standing[id] = nil
    local s = it.slot and self.slots[it.slot]
    if s and s.active == id then s.active = nil end
    self.revision = self.revision + 1
    return it
  end
end

function M:active_items(kind)
  local out = {}
  for _, id in ipairs(self.order) do
    local it = self.items[id]
    if it and it.status == "active" and (not kind or it.kind == kind) then out[#out + 1] = it end
  end
  return out
end

---------------------------------------------------------------- observation
local function value_of(ins)
  if not ins or not ins.value then return nil end
  return ins.value.year or ins.value.word or ins.value.label
end

local function collect_refs(interp)
  local out = {}
  local function add(ref, role, w)
    if ref and not ref.deictic then out[#out + 1] = { ref = ref, role = role, w = w } end
  end
  for role, r in pairs(interp.roles or {}) do if not r.asked then add(r, "arg:" .. role, 0.5) end end
  add(interp.subject, "subject", 0.5)
  add(interp.concept, "concept", 0.4)
  add(interp.target, "target", 0.3)
  add(interp.focus, "focus", 1.0)
  add(interp.object, "object", 0.4)
  for _, it in ipairs(interp.items or {}) do add(it, "item", 0.7) end
  if interp.statement then add(interp.statement.subject, "stmt_subject", 0.7); add(interp.statement.object, "stmt_object", 0.4) end
  if interp.clause then add(interp.clause.subject, "clause_subject", 0.4); add(interp.clause.object, "clause_object", 0.3) end
  for _, st in ipairs((interp.query and interp.query.steps) or {}) do add(st.known, "chain_arg", 0.4) end
  return out
end

-- record one interpreted sentence. meta: {speaker, sent_text, hedged, additive, scoped, revoke_cue}
function M:observe_sentence(interp, meta)
  meta = meta or {}
  local speaker = meta.speaker or self.speaker or "user"
  if interp.status ~= "ok" then return nil end
  local text = interp.sentence and interp.sentence.text or ""
  local keys = {}
  for _, e in ipairs(collect_refs(interp)) do
    local r = e.ref
    local key = ref_key(r)
    local w = e.w
    if r.antecedent and r.antecedent.key then w = 0.35 end -- re-mention through a pronoun
    if key then
      local en = self:mention(key, { type = r.type or (r.antecedent and r.antecedent.type), itype = r.itype, pname = r.pname, name = (r.antecedent and r.antecedent.text) or r.text, w = w,
        role = e.role, speaker = speaker, plural = r.plural, sent = meta.sent, weak = r.weak_name })
      keys[#keys + 1] = key
      if e.role == "focus" then self.focus = { key = key, turn = self.turn, text = r.text } end
    end
  end
  -- topic shift: the entity a request is about (description subject, looked-up entity) becomes the discourse focus
  if not self.focus or self.focus.turn <= self.turn then
    local topic, ttext
    if interp.focus then topic, ttext = ref_key(interp.focus), interp.focus.text
    elseif interp.intent == "entity_description" and interp.subject then topic, ttext = ref_key(interp.subject), interp.subject.text
    elseif interp.intent == "factual_lookup" and interp.query and interp.roles then
      local kr = interp.roles[interp.query.known_role or "from"]
      topic, ttext = ref_key(kr), kr and kr.text
    end
    -- a name whose only evidence is a sentence-initial capital ("Let me think ...") never becomes the focus of the conversation
    local ten = topic and self.entities[topic]
    if topic and speaker == "user" and not (ten and ten.weak) then self.focus = { key = topic, turn = self.turn, text = ttext } end
  end
  -- the last relational question the user asked: elliptical follow-ups ("What about Jupiter?", "Same question for Y", "Sorry, I meant Z") re-ask it about another argument
  if speaker == "user" and interp.intent == "factual_lookup" and interp.relation and interp.query and interp.query.known_role and interp.query.ask
    and (interp.speech_act == "question" or interp.speech_act == "request") and not meta.hedged then
    self.last_query = { rel = interp.relation.id, known_role = interp.query.known_role, ask = interp.query.ask, answer_type = interp.query.answer_type, turn = self.turn, text = text }
  end
  if interp.intent == "comparison" and interp.items then
    local ks = {}
    for _, it in ipairs(interp.items) do local k = ref_key(it); if k then ks[#ks + 1] = k end end
    if #ks >= 2 then self.comparison = { keys = ks, turn = self.turn, dimension = interp.dimension, rel = interp.relation and interp.relation.id } end
  end
  local created
  -- standing instructions / prohibitions / preferences ----------------------------------------------------------------
  if speaker == "user" and (interp.speech_act == "instruction" or interp.intent == "instruction_update" or interp.intent == "correction") then
    local ins = interp.instruction or {}
    local cons = interp.constraints or {}
    if ins.act == "exclude" or (ins.kind == "exclusion") or (#(cons.negative or {}) > 0 and not ins.slot) then
      created = self:add({ layer = "task", kind = "prohibition", text = text, entities = keys, speaker = speaker,
        target = (cons.negative[1] and cons.negative[1].target) or nil, standing = true, polarity = "negative" })
    elseif ins.kind == "preference" or (#(cons.preferences or {}) > 0 and not ins.slot) then
      created = self:add({ layer = "task", kind = "preference", text = text, entities = keys, speaker = speaker, standing = true,
        target = (cons.preferences[1] and cons.preferences[1].target) or nil })
    elseif ins.slot then
      local value = value_of(ins)
      local item = { layer = "task", kind = ins.correction and "correction" or "instruction", text = text, entities = keys, speaker = speaker, slot = ins.slot,
        value = value, value_label = ins.value and ins.value.label, value_kind = ADDITIVE_SLOTS[ins.slot] and "voice" or (ins.value and ((ins.value.year and "year") or (ins.value.word and "word") or nil)),
        standing = not meta.scoped, persist = ins.persist, correction = ins.correction, verb = ins.verb }
      created = self:add(item)
      local st = self:slot_state(ins.slot)
      if st.active and self.items[st.active] and not meta.additive and not ADDITIVE_SLOTS[ins.slot] then
        self:supersede(st.active, created, ins.correction and "explicit correction" or "newer instruction for the same slot")
      end
      st.active = created.id
      st.history[#st.history + 1] = created.id
    end
  end
  -- revocation ("never mind the dataset instruction", "scratch that") -- only with an identifiable target ---------------------------------
  if meta.revoke and speaker == "user" then
    local rv, target = meta.revoke, nil
    if rv.slot then
      local st = self.slots[rv.slot]
      target = st and st.active
      -- an accumulating slot is withdrawn as a whole ("never mind the tone instructions")
      if st and ADDITIVE_SLOTS[rv.slot] then
        for _, hid in ipairs(st.history) do if hid ~= st.active and not (created and hid == created.id) then self:revoke(hid, text) end end
      end
    elseif rv.class or rv.bare then
      -- the most recent standing user item; a bare "never mind" can only refer to the immediately preceding turn
      local best_key
      for id in pairs(self.standing) do
        local it = self.items[id]
        if it and it.status == "active" and it.speaker == "user" and it.turn < self.turn and (rv.class or it.turn == self.turn - 1) then
          local k = it.turn * 1000000 + (tonumber(id:sub(2)) or 0)
          if not best_key or k > best_key then best_key, target = k, id end
        end
      end
    end
    if target and created and target == created.id then target = nil end   -- "Disregard what I said, and go with X": the new instruction survives its own retraction
    if target then self:revoke(target, text) end
  end
  -- semantic memory: relational assertions, hedges kept speculative ---------------------------------------------------------
  if interp.intent == "statement" and interp.relation and interp.roles and (interp.roles.from or interp.roles.to) then
    created = self:add({ layer = "semantic", kind = "fact", text = text, entities = keys, speaker = speaker, rel = interp.relation.id,
      from = fact_key(interp.roles.from, speaker), to = fact_key(interp.roles.to, speaker), polarity = interp.polarity,
      status = meta.hedged and "speculative" or "active", reliability = (meta.hedged and 0.3 or nil) })
    local fk = tostring(created.rel) .. "|" .. tostring(created.from)
    if not meta.hedged and created.from then
      for _, id in ipairs(self.facts_by[fk] or {}) do
        local o = self.items[id]
        if o and o.kind == "fact" and o.status == "active" and o.to ~= created.to then
          created.conflicts = created.conflicts or {}; table.insert(created.conflicts, o.id)
          o.conflicts = o.conflicts or {}; table.insert(o.conflicts, created.id)
        end
      end
    end
    self.facts_by[fk] = self.facts_by[fk] or {}
    table.insert(self.facts_by[fk], created.id)
  end
  return created
end

-- a stated decision (protected: never evicted, retrievable without repeating its wording)
function M:note_decision(text, meta)
  meta = meta or {}
  return self:add({ layer = "task", kind = "decision", text = text, speaker = meta.speaker or self.speaker or "user", entities = meta.entities or {}, standing = false })
end

-- store the raw utterance (episodic layer) and its artifacts
function M:note_utterance(text, speaker, meta)
  speaker = speaker or self.speaker or "user"
  local ents = {}
  for k in pairs(self.turn_entities or {}) do ents[#ents + 1] = k end
  table.sort(ents)
  local item = self:add({ layer = "episodic", kind = "utterance", text = text, speaker = speaker, entities = ents })
  item.n_bytes = #text
  self:extract_artifacts(text, item)
  return item
end

---------------------------------------------------------------- relevance-ranked selection (auditable)
local function applicable_scope(interp)
  local scopes = { any = true }
  if interp.requires_external_evidence or interp.intent == "task" or interp.intent == "search" or interp.intent == "comparison" then scopes.evidence = true end
  if interp.status == "ok" and interp.intent ~= "instruction_update" and interp.intent ~= "statement" then scopes.style = true end
  return scopes
end

function M:slot_applicable(slot, interp)
  local scopes = applicable_scope(interp)
  local sc = SLOT_SCOPE[slot] or "any"
  return scopes[sc] == true
end

-- query terms from the interpretation (entity names, relation words, concept text) -- never the raw string alone
local function query_terms(interp)
  local terms, seen = {}, {}
  local function add(s)
    for _, t in ipairs(tokens_of(s or "")) do if not seen[t] then seen[t] = true; terms[#terms + 1] = t end end
  end
  for _, e in ipairs(collect_refs(interp)) do
    add(e.ref.text)
    if e.ref.antecedent then add(e.ref.antecedent.text) end
  end
  if interp.relation then add(interp.relation.label) end
  -- no semantic reading (or none that names anything): the content words of the sentence itself are the only evidence of what it is about
  if (#terms == 0 or interp.status ~= "ok") and interp.sentence and interp.sentence.text then add(interp.sentence.text) end
  return terms
end

-- Candidate generation is index-driven (standing constraints + entity-identity postings + informative-term postings + a short
-- recency window), never a scan of the whole history; every candidate is then scored by named factors.
function M:select(interp, opts)
  opts = opts or {}
  local max_items, min_score = opts.max_items or 12, opts.min_score or 1.0
  local keys = {}
  for _, e in ipairs(collect_refs(interp)) do
    local k = ref_key(e.ref)
    if k then keys[k] = true end
    if e.ref.antecedent and e.ref.antecedent.key then keys[e.ref.antecedent.key] = true end
  end
  local terms = query_terms(interp)
  -- the request's own content words are a (capped) lexical signal; they can rank candidates but never select one alone
  local seen_t = {}
  for _, t in ipairs(terms) do seen_t[t] = true end
  for _, t in ipairs(tokens_of(interp.sentence and interp.sentence.text or "")) do if not seen_t[t] then seen_t[t] = true; terms[#terms + 1] = t end end
  local cand, n_cand = {}, 0
  local function want(id) if not cand[id] and self.items[id] then cand[id] = true; n_cand = n_cand + 1 end end
  for id in pairs(self.standing) do want(id) end
  for k in pairs(keys) do for _, id in ipairs(self.by_entity[k] or {}) do want(id) end end
  for _, t in ipairs(terms) do
    local df = self.index.df[t] or 0
    if df > 0 and df <= 200 then for id in pairs(self.index.terms[t]) do want(id) end end
  end
  for i = math.max(1, #self.order - 5), #self.order do want(self.order[i]) end
  -- superseded / revoked items of the slots in play stay visible in the audit (why the older value is not used)
  local excluded = {}
  for slot, st in pairs(self.slots) do
    for _, id in ipairs(st.history) do
      local it = self.items[id]
      if it and (it.status == "superseded" or it.status == "revoked") then
        excluded[#excluded + 1] = { item = it, reason = it.status .. (it.superseded_by and (" by " .. it.superseded_by) or "") .. " (slot '" .. slot .. "')" }
      end
    end
  end
  local cands = {}
  for id in pairs(cand) do
    local it = self.items[id]
    if it.ns ~= self:ns_key() then
      excluded[#excluded + 1] = { item = it, reason = "different namespace" }
    elseif it.status == "superseded" or it.status == "revoked" then
      -- already reported through the slot history when applicable
      if not it.slot then excluded[#excluded + 1] = { item = it, reason = it.status .. (it.superseded_by and (" by " .. it.superseded_by) or "") } end
    elseif it.turn >= self.turn and it.kind == "utterance" then
      -- the current turn is the request itself, not memory
    else
      local st, so, f = 0, 0, {}   -- structural evidence (identity, standing constraints, typed references) vs soft evidence (recency, words)
      if it.kind == "decision" and opts.decision_ref then st = st + 1.5; f.decision_reference = true end
      -- a question that shares at least two content words with a recorded decision is asking about what that decision settled ("what is the billing service running on?")
      if it.kind == "decision" and not f.decision_reference and (interp.speech_act == "question" or interp.speech_act == "request") then
        local shared_t = 0
        for _, t in ipairs(terms) do if (self.index.terms[t] or {})[it.id] then shared_t = shared_t + 1 end end
        if shared_t >= 2 then st = st + 1.0; f.decision_subject_overlap = shared_t end
      end
      -- "What did I say my dog was called?": a request to recall an earlier statement is linked to the statement that repeats at least two of its content words
      if interp.intent == "conversation_recall" and it.turn < self.turn and (it.kind == "utterance" or it.kind == "fact" or it.kind == "decision") then
        local shared_t = 0
        for _, t in ipairs(terms) do if not RECALL_FRAME[t] and (self.index.terms[t] or {})[it.id] then shared_t = shared_t + 1 end end
        if shared_t >= 2 then st = st + 1.0; f.recall_overlap = shared_t end
      end
      if it.kind == "instruction" or it.kind == "correction" or it.kind == "preference" then
        if self:slot_applicable(it.slot or "any", interp) or (not it.slot and it.kind == "preference") then
          st = st + (it.standing and 3.0 or 2.0); f.standing_constraint = true
        end
      elseif it.kind == "prohibition" then
        if interp.intent ~= "instruction_update" and interp.intent ~= "statement" then st = st + 2.5; f.standing_prohibition = true end
      end
      local shared = 0
      for _, k in ipairs(it.entities or {}) do if keys[k] then shared = shared + 1 end end
      if shared > 0 then st = st + 2.0 * math.min(shared, 2); f.entity_identity = shared end
      if shared > 0 and it.rel and interp.relation and it.rel == interp.relation.id then st = st + 1.0; f.relation_match = true end
      local dependent = #(interp.dependencies or {}) > 0
      local recent_dep = false -- pronoun / comparison-set requests lean on the last couple of turns; back-references reach further and say so
      for _, d in ipairs(interp.dependencies or {}) do if d.kind == "pronoun" or d.kind == "comparison_set" then recent_dep = true end end
      if self.focus and it.entities and dependent then
        for _, k in ipairs(it.entities) do if k == self.focus.key then st = st + 0.8; f.focus_continuity = true break end end
      end
      if recent_dep and it.turn >= self.turn - 2 and (it.kind == "utterance" or it.kind == "fact") then st = st + 1.2; f.recent_window = true end
      if it.kind == "utterance" or it.kind == "fact" or it.kind == "decision" then
        local rec = 0.6 * (self.decay ^ (self.turn - it.turn))
        if rec > 0.05 then so = so + rec; f.recency = U.round(rec, 3) end
      end
      local lex = self:bm25(terms, it)
      if lex > 0 then local nl = math.min(1, lex / 6) * 0.6; so = so + nl; f.lexical = U.round(nl, 3) end
      so = so + 0.3 * (it.reliability or 0.5)
      if it.status == "speculative" then so = so - 0.7; f.speculative = true end
      local s = st + so
      f.structural = U.round(st, 3)
      cands[#cands + 1] = { item = it, score = s, factors = f }
    end
  end
  table.sort(cands, function(a, b) if a.score ~= b.score then return a.score > b.score end return a.item.turn > b.item.turn end)
  local selected = {}
  for _, c in ipairs(cands) do
    local structural = c.factors.structural or 0
    if structural >= 0.8 and c.score >= min_score and #selected < max_items then selected[#selected + 1] = c
    else
      local why = structural < 0.8 and string.format("no structural link to the request (identity / standing constraint / typed reference); soft score %.2f", c.score)
        or (c.score < min_score and string.format("relevance %.2f below threshold %.2f", c.score, min_score) or "over item budget")
      excluded[#excluded + 1] = { item = c.item, reason = why, score = c.score }
    end
  end
  return { selected = selected, excluded = excluded, n_candidates = n_cand, n_items = self.index.n }
end

-- the standing constraints that are in force for this request (slot-keyed values, exclusions, preferences), with provenance
function M:active_constraints(interp, opts)
  local out = {}
  for slot, st in pairs(self.slots) do
    local it = st.active and self.items[st.active]
    if it and it.status == "active" and ((opts and opts.all) or self:slot_applicable(slot, interp)) then
      out[#out + 1] = { kind = it.kind, slot = slot, value = it.value, label = it.value_label, item = it.id, turn = it.turn, text = it.text, standing = it.standing or false,
        supersedes = it.supersedes, correction = it.correction or false }
    end
  end
  for id in pairs(self.standing) do
    local it = self.items[id]
    if it and it.status == "active" and (it.kind == "prohibition" or (it.kind == "preference" and not it.slot)) then
      out[#out + 1] = { kind = it.kind, item = it.id, turn = it.turn, text = it.text, target = it.target, standing = true }
    end
  end
  table.sort(out, function(a, b) if a.turn ~= b.turn then return a.turn < b.turn end return a.item < b.item end)
  return out
end

---------------------------------------------------------------- context dependency classification
-- coref: result of Coref.resolve for the same interpretation (may be nil)
function M:classify_dependency(interp, coref)
  local classes, unresolved = {}, false
  local function add(c) classes[#classes + 1] = c end
  local covered = {}
  for _, r in ipairs((coref and coref.references) or {}) do
    covered[r.mention] = true
    if r.status == "resolved" then
      local d = r.distance_turns or 0
      if r.kind == "correction_ref" then add("user_correction")
      elseif d == 0 then add("self_contained")
      elseif d <= 2 then add("recent_message")
      else add("earlier_project_context") end
    else add("ambiguous_missing_context"); unresolved = true end
  end
  -- dependencies no resolver looked at (e.g. coreference switched off) stay unresolved rather than silently self-contained
  for _, d in ipairs(interp.dependencies or {}) do
    if d.kind == "previous_question" then
      if (self.turn - (d.turn or self.turn)) <= 2 then add("recent_message") else add("earlier_project_context") end
    elseif d.kind == "conversation_history" then
      if coref and coref.recall_found then add("earlier_project_context") else add("ambiguous_missing_context"); unresolved = true end
    elseif not covered[d.text] and d.kind ~= "comparison_set" then add("ambiguous_missing_context"); unresolved = true end
  end
  local has_dataset = false
  for _, s in ipairs((interp.constraints and interp.constraints.source) or {}) do if s.cue then has_dataset = true end end
  if has_dataset then add("external_dataset") end
  local seen, uniq = {}, {}
  for _, c in ipairs(classes) do if not seen[c] then seen[c] = true; uniq[#uniq + 1] = c end end
  if #uniq == 0 then uniq[1] = "self_contained" end
  local PREC = { ambiguous_missing_context = 6, user_correction = 5, earlier_project_context = 4, recent_message = 3, external_dataset = 2, self_contained = 1 }
  table.sort(uniq, function(a, b) return PREC[a] > PREC[b] end)
  return { primary = uniq[1], all = uniq, unresolved = unresolved }
end

---------------------------------------------------------------- summaries that keep protected content
-- digest of turns [from, to]: entities, facts, open tasks, EXACT exclusion/instruction text, corrections, dates, numbers, hedges, source refs.
function M:summarize(from_turn, to_turn)
  from_turn, to_turn = from_turn or 1, to_turn or self.turn
  local d = { from_turn = from_turn, to_turn = to_turn, entities = {}, facts = {}, exclusions = {}, instructions = {}, corrections = {}, hedged = {},
    numbers = {}, dates = {}, source_refs = {} }
  local raw = {}
  for _, id in ipairs(self.order) do
    local it = self.items[id]
    if it and it.turn >= from_turn and it.turn <= to_turn then
      raw[#raw + 1] = id .. ":" .. (it.text or "")
      local ref = { item = id, turn = it.turn }
      if it.kind == "prohibition" then d.exclusions[#d.exclusions + 1] = { text = it.text, status = it.status, ref = ref }
      elseif it.kind == "instruction" or it.kind == "preference" then d.instructions[#d.instructions + 1] = { text = it.text, slot = it.slot, value = it.value, status = it.status, superseded_by = it.superseded_by, ref = ref }
      elseif it.kind == "correction" then d.corrections[#d.corrections + 1] = { text = it.text, slot = it.slot, value = it.value, supersedes = it.supersedes, ref = ref }
      elseif it.kind == "fact" then
        local entry = { rel = it.rel, from = it.from, to = it.to, text = it.text, status = it.status, ref = ref }
        if it.status == "speculative" then d.hedged[#d.hedged + 1] = entry else d.facts[#d.facts + 1] = entry end
      end
      if it.kind == "utterance" then
        for n in (it.text or ""):gmatch("%d[%d,%.]*%d?") do d.numbers[#d.numbers + 1] = { value = n, ref = ref } end
        for y in (it.text or ""):gmatch("%f[%d]([12]%d%d%d)%f[%D]") do d.dates[#d.dates + 1] = { year = y, ref = ref } end
      end
      d.source_refs[#d.source_refs + 1] = ref
    end
  end
  for key, e in pairs(self.entities) do
    if e.last_turn and e.last_turn >= from_turn and e.first_turn <= to_turn then
      d.entities[#d.entities + 1] = { key = key, type = e.type, first_turn = e.first_turn, last_turn = e.last_turn, mentions = #e.mentions }
    end
  end
  table.sort(d.entities, function(a, b) return a.key < b.key end)
  d.raw_sha256 = U.sha256(table.concat(raw, "\n"))
  d.kind = "summary"
  d.note = "compressed evidence: summary entries cite source items; the original text remains retrievable via expand()"
  return d
end

-- audit that a summary lost none of the protected content found in the original turns
function M:loss_audit(summary)
  local missing = {}
  local function present(list, id) for _, e in ipairs(list) do if e.ref and e.ref.item == id then return true end end return false end
  for _, id in ipairs(self.order) do
    local it = self.items[id]
    if it and it.turn >= summary.from_turn and it.turn <= summary.to_turn then
      if it.kind == "prohibition" and not present(summary.exclusions, id) then missing[#missing + 1] = { id = id, why = "exclusion dropped" } end
      if (it.kind == "instruction" or it.kind == "preference") and not present(summary.instructions, id) then missing[#missing + 1] = { id = id, why = "instruction dropped" } end
      if it.kind == "correction" and not present(summary.corrections, id) then missing[#missing + 1] = { id = id, why = "correction dropped" } end
      if it.kind == "fact" and not (present(summary.facts, id) or present(summary.hedged, id)) then missing[#missing + 1] = { id = id, why = "fact dropped" } end
      if it.kind == "fact" and it.status == "speculative" and present(summary.facts, id) then missing[#missing + 1] = { id = id, why = "speculation promoted to fact" } end
    end
  end
  return missing
end

function M:expand(ref) local it = self.items[ref.item]; return it and it.text, it end

---------------------------------------------------------------- retention and deletion
-- forget{ item=id | kind= | entity= | before_turn= }  -- protected kinds need force=true
function M:forget(filter)
  local removed = 0
  for _, id in ipairs(U.copy(self.order)) do
    local it = self.items[id]
    if it then
      local hit = (filter.item and filter.item == id) or (filter.kind and filter.kind == it.kind) or (filter.before_turn and it.turn < filter.before_turn)
      if filter.entity then
        hit = false
        for _, k in ipairs(it.entities or {}) do if k == filter.entity then hit = true end end
      end
      if hit and (not PROTECTED_KINDS[it.kind] or filter.force) then self:drop(id, "forget"); removed = removed + 1 end
    end
  end
  local keep = {}
  for _, id in ipairs(self.order) do if self.items[id] then keep[#keep + 1] = id end end
  self.order = keep
  if filter.entity then self.entities[filter.entity] = nil end
  self.revision = self.revision + 1
  return removed
end

---------------------------------------------------------------- persistence (explicit, checksummed)
function M:serialize()
  local items = {}
  for _, id in ipairs(self.order) do
    local it = U.shallow(self.items[id])
    it._tf = nil
    items[#items + 1] = it
  end
  local body = { schema = M.SCHEMA, ns = self.ns, turn = self.turn, revision = self.revision, next_id = self.next_id, items = items,
    entities = self.entities, slots = self.slots, focus = self.focus, comparison = self.comparison, artifacts = self.artifacts, evictions = self.evictions,
    last_query = self.last_query }
  local json = U.json_encode(body, { nan_null = true })
  return U.json_encode({ meta = { schema = M.SCHEMA, sha256 = U.sha256(json), bytes = #json }, body = U.json_decode(json) })
end

function M.deserialize(s, opts)
  opts = opts or {}
  local doc, err = U.json_decode(s)
  if not doc then return nil, "memory: " .. tostring(err) end
  if type(doc) ~= "table" or not doc.meta or doc.meta.schema ~= M.SCHEMA or not doc.body then return nil, "memory: unknown schema" end
  local check = U.sha256(U.json_encode(doc.body, { nan_null = true }))
  if check ~= doc.meta.sha256 then return nil, "memory: checksum mismatch (file modified or corrupted)" end
  local b = doc.body
  if opts.ns and (b.ns.user ~= opts.ns.user) then return nil, "memory: namespace owner mismatch (refusing cross-user load)" end
  local self = M.new({ ns = b.ns })
  self.turn, self.revision, self.next_id = b.turn, b.revision, b.next_id
  self.entities, self.slots, self.focus, self.comparison = b.entities or {}, b.slots or {}, b.focus, b.comparison
  self.artifacts, self.evictions = b.artifacts or {}, b.evictions or {}
  self.last_query = b.last_query
  for _, it in ipairs(b.items or {}) do
    self.items[it.id] = it
    self.order[#self.order + 1] = it.id
    local toks = tokens_of(it.text or "")
    local tf = {}
    for _, t in ipairs(toks) do tf[t] = (tf[t] or 0) + 1 end
    it._tf = tf
    for t, c in pairs(tf) do self.index.terms[t] = self.index.terms[t] or {}; self.index.terms[t][it.id] = c end
    self.index.len[it.id] = #toks; self.index.n = self.index.n + 1; self.index.total_len = self.index.total_len + #toks
  end
  return self
end

function M:save(path)
  local f, err = io.open(path, "wb")
  if not f then return nil, err end
  f:write(self:serialize()); f:close()
  return true
end

function M.load(path, opts)
  local f = io.open(path, "rb")
  if not f then return nil, "cannot open " .. path end
  local s = f:read("*a"); f:close()
  return M.deserialize(s, opts)
end

---------------------------------------------------------------- store: namespace isolation + authorisation
local Store = {}
Store.__index = Store
function M.store() return setmetatable({ mems = {} }, Store) end

-- principal = {user=...}; a memory is only reachable by its owner (no similarity-based cross-user retrieval exists)
function Store:open(ns, principal)
  if not principal or principal.user ~= ns.user then return nil, "access denied: principal is not the namespace owner" end
  local key = table.concat({ ns.user, ns.project, ns.conversation }, "|")
  local m = self.mems[key]
  if not m then m = M.new({ ns = ns }); self.mems[key] = m end
  return m
end

return M

end

package.preload["asi.nlu.morph"] = function(...)
-- asi.nlu.morph: English inflection generation + conservative reverse guessing for UNKNOWN words.
