  local n, distinct, i = 0, {}, 1
  while i <= #words do
    local len, ph = match_at(idx, words, i)
    if len then n = n + 1; distinct[table.concat(ph, " ")] = true; i = i + len else i = i + 1 end
  end
  local d = 0
  for _ in pairs(distinct) do d = d + 1 end
  return n, d
end

